create temporary table import_summary (wikidata_id text primary key, summary text not null, source text not null);

insert into import_summary (wikidata_id, summary, source) values
  ('Q2501640', 'Justice League Task Force is a competitive fighting game for the Genesis and Super Nintendo Entertainment System in 1995. The Genesis version was developed by Condor (later known as Blizzard North) and the Super NES version was by Blizzard Entertainment.

It involves characters from DC Comics'' Justice League, including Superman, Batman, Wonder Woman, Green Arrow, The Flash, and Aquaman. Additional Justice League members Martian Manhunter and Fire, as well as the supervillain Shrapnel, were also planned to appear but had to be omitted due to memory limitations.', 'https://en.wikipedia.org/wiki/Justice_League_Task_Force_(video_game)'),
  ('Q2496494', 'Accele Brid is a shooter game released by Tomy in 1993 for the Super Famicom.', 'https://en.wikipedia.org/wiki/Accele_Brid'),
  ('Q2474014', 'Operation Europe: Path to Victory, released in Japan as Europa Sensen, is a combat strategy video game for multiple platforms where one or two players can compete in World War II action. The MS-DOS version of the game was only released to North America.', 'https://en.wikipedia.org/wiki/Operation_Europe:_Path_to_Victory'),
  ('Q2480473', 'The Itchy & Scratchy Game is a platform video game that was released for the Super NES and Game Gear. Based on the American animated television series The Simpsons, it stars the cat and mouse pair Itchy & Scratchy, and features the classic gory violence from the show. The main character is Itchy, who has to fight Scratchy. Reception of the game has been generally negative.

The game was also developed for the Genesis but it was never commercially released.', 'https://en.wikipedia.org/wiki/The_Itchy_%26_Scratchy_Game'),
  ('Q1871848', 'Kirby Super Star, released as Kirby''s Fun Pak in PAL regions, is a 1996 anthology platform game developed by HAL Laboratory and published by Nintendo for the Super Nintendo Entertainment System. It is part of the Kirby series of video games by HAL Laboratory. The game was advertised as a compilation featuring nine games: seven short subsections with the same basic gameplay, and two minigames. Games and minigames include: Spring Breeze, Dyna Blade, Gourmet Race, Milky Way Wishes, The Great Cave Offensive, The Arena, Revenge Of Meta Knight, Megaton Punch, and Samurai Kirby.

An enhanced remake titled Kirby Super Star Ultra was released for the Nintendo DS in 2008 and 2009 to commercial and critical success, selling just under 3 million copies. The original game has also been digitally rereleased multiple times.', 'https://en.wikipedia.org/wiki/Kirby_Super_Star'),
  ('Q2919165', 'Kendo Rage, known in Japan as Makeruna! Makendō, is an action video game for the Super Nintendo Entertainment System/Super Famicom by Datam Polystar. SETA published the English version.', 'https://en.wikipedia.org/wiki/Kendo_Rage'),
  ('Q941354', 'Sunset Riders is a 1991 run and gun video game developed and published by Konami for arcades. It was released in North America in October 1991 and Japan in November 1991. It is set in the American Old West, where the player(s) take control of bounty hunters who are seeking the rewards offered for various criminals.

The arcade version was released in two variants: a two-player version and a four-player version. Home console versions of Sunset Riders were released for the Mega Drive/Genesis in 1992 and for the Super Nintendo Entertainment System in 1993 to a positive reception. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in June 2020.', 'https://en.wikipedia.org/wiki/Sunset_Riders'),
  ('Q2913706', 'Super Street Fighter II: The New Challengers is a 1993 fighting game developed and published by Capcom for arcades. It is the fourth game in the Street Fighter II sub-series of Street Fighter games, following Street Fighter II Turbo (1992). It refines and balances the existing character roster from the previous versions, and introduces four new characters, including Fei Long, Cammy, T. Hawk, and Dee Jay. It is the first game on Capcom''s CP System II hardware, with more sophisticated graphics and audio over the original CP System hardware used in previous versions of Street Fighter II.

Super Street Fighter II was ported to the Super Nintendo and Sega Genesis home consoles in 1994, followed by a number of computer platforms later. Super Street Fighter II was followed in 1994 by Super Street Fighter II Turbo, a fifth version of Street Fighter II, which further balances the characters and adds features.', 'https://en.wikipedia.org/wiki/Super_Street_Fighter_II'),
  ('Q2922966', 'Boxing Legends of the Ring is a boxing video game for the Sega Genesis and Super NES consoles. The boxers are represented by 2D sprites seen from over the shoulder of one of the fighters. The title of the game refers to the famous boxing magazine, The Ring, which the game is licensed to associate itself with. The following famous middleweight boxers are represented in the game: Sugar Ray Leonard, Roberto Durán, Thomas Hearns, James Toney, Marvin Hagler, Jake LaMotta, Sugar Ray Robinson, and Rocky Graziano.

All of the fights in the game take place in the Las Vegas Hilton casino in the North American version. There are also advertising banners for HBO visible during fights that are not available in the Japanese version. In the Japanese version, the game takes place in a generic boxing ring using the publisher''s name in place of the HBO advertisements found in the North American version.', 'https://en.wikipedia.org/wiki/Boxing_Legends_of_the_Ring'),
  ('Q953963', 'Might and Magic II: Gates to Another World (also known as Might and Magic Book Two: Gates to Another World) is a role-playing video game developed and published by New World Computing in 1988. It is the sequel to Might and Magic Book One: The Secret of the Inner Sanctum.', 'https://en.wikipedia.org/wiki/Might_and_Magic_II:_Gates_to_Another_World'),
  ('Q958761', 'Secret of Evermore is an action role-playing game developed and published by Squaresoft for the Super Nintendo Entertainment System. It was released in North America on October 17, 1995, in Australia in February 1996, and in Europe in March 1996. A Japanese release was planned to follow the North American release by a few months but was ultimately cancelled.

The story of Secret of Evermore follows a boy and his shapeshifting pet dog as they are inadvertently transported to the fantasy world of Evermore. The player guides both characters through Evermore, a world composed of separate realms, each resembling a different period of real-world history: "Prehistoria" (prehistory), "Antiqua" (classical antiquity), "Gothica" (the Middle Ages), and "Omnitopia" (an imaginative future world). The gameplay shares many similarities with Secret of Mana, such as real-time battles, a ring-shaped menu system, weapons needing to ''charge'' in order to attack at full power after making an attack and the ability to switch control between the two characters. Despite similar game mechanics and a similar title, it is not an entry in the Mana series.', 'https://en.wikipedia.org/wiki/Secret_of_Evermore'),
  ('Q957870', 'Asterix & Obelix is a platform game released by Infogrames in 1995 for MS-DOS, Windows, Super NES, Game Boy, and Game Boy Color. The player can play as either Asterix or Obelix. The game also supports multiplayer through two players using the same keyboard.', 'https://en.wikipedia.org/wiki/Asterix_%26_Obelix_(video_game)'),
  ('Q956155', 'The Lawnmower Man is a video game based on the 1992 film of the same name. The game was published in Japan by Coconuts Japan under the title Virtual Wars, the name also given to the source material in said region.', 'https://en.wikipedia.org/wiki/The_Lawnmower_Man_(video_game)'),
  ('Q2924608', 'Brett Hull Hockey ''95 is an ice hockey sports video game video game released in December 1994 for Genesis, and then, January 1995 for the Super NES and MS-DOS. The game was developed by Radical Entertainment and published by Accolade. It is the sequel to the original Brett Hull Hockey. The gameplay options include Exhibition, Half Season, Full Season, Play-offs and All-Star. Al Michaels calls the play-by-play for every game.', 'https://en.wikipedia.org/wiki/Brett_Hull_Hockey_%2795'),
  ('Q953511', 'Clock Tower is a point-and-click survival horror video game developed and published by Human Entertainment for the Super Famicom in 1995. It is the first installment in the Clock Tower series. The story follows orphan Jennifer Simpson soon after she is adopted by the Barrows family along with other orphaned girls. Shortly after arriving at the Barrows family manor, one of the other children is killed by a stalker called Scissorman. Jennifer must then explore the Barrows Mansion to find a way to escape while evading Scissorman, leading to one of the game''s multiple endings. Clock Tower utilizes a point-and-click interface with the player controlling a cursor to direct Jennifer''s actions.', 'https://en.wikipedia.org/wiki/Clock_Tower_(1995_video_game)'),
  ('Q2909761', 'Bombuzal, known in America as Ka-Blooey, is a 1988 puzzle video game designed by Antony Crowther (credited as "Ratt" in the game) and David Bishop for Image Works. The game was initially released in 1988 for the Amiga, Atari ST and Commodore 64. It was later released in 1989 for MS-DOS. It was released for Nintendo Entertainment System consoles not long after — in December 1990 in Japan for the Super Famicom, and in August 1992 in North America (where it was named as Ka-Blooey).

The game has a sequel/remake available for the Nintendo 64 called Charlie Blast''s Territory. Among its notable features is the ability to play using either an overhead or isometric view.', 'https://en.wikipedia.org/wiki/Bombuzal'),
  ('Q2540072', 'Mario & Wario is a 1993 puzzle-platform game developed by Game Freak and published by Nintendo for the Super Famicom. The game requires the Super Famicom Mouse accessory to play. Despite being a Japanese-only release, the game is entirely in English.

The gameplay of Mario & Wario focuses on guiding Mario, who has various objects placed atop his head by his self-declared arch rival Wario, through a series of levels consisting of various obstacles and traps. Because Mario has been rendered sightless and is constantly in danger of walking into hazards, the player controls the fairy Wanda, who can protect Mario by changing the environment around him as he moves towards the levels'' end. The game offers a total of 100 levels and offers three playable characters.', 'https://en.wikipedia.org/wiki/Mario_%26_Wario'),
  ('Q3088033', 'Uniracers (released as Unirally in Europe) is a racing game developed by DMA Design and published by Nintendo for the Super Nintendo Entertainment System in North America in December 1994 and in the PAL territories on 27 April 1995. DMA Design and Nintendo stopped cartridge production of the game, and the game has not been rereleased since. It is frequently reported that the reason for this is due to a lawsuit from Pixar over copyright infringement.', 'https://en.wikipedia.org/wiki/Uniracers'),
  ('Q2962854', 'Chester Cheetah is a fictional character and the official mascot for Frito-Lay''s Cheetos brand snacks as well as Chester''s Snacks which consists of flavored fries, popcorn and puffcorn.', 'https://en.wikipedia.org/wiki/Chester_Cheetah'),
  ('Q2553382', 'Goof Troop is an action-adventure video game developed and published by Capcom for the Super Nintendo Entertainment System. It was originally released in North America in July 1993, in Europe on November 25, 1993, and in Japan on July 22, 1994, and based on the animated television series of the same name. The game can be played in both single-player and multiplayer mode, wherein one player controls Goofy and the other Max.

Goof Troop is one of the first games designed by Shinji Mikami, who would go on to be renowned for his work on the Resident Evil series.', 'https://en.wikipedia.org/wiki/Goof_Troop_(video_game)'),
  ('Q1058903', 'Super Mario All-Stars is a 1993 platform game compilation developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). It contains remakes of four Super Mario games released for the Nintendo Entertainment System (NES) and the Famicom Disk System: Super Mario Bros. (1985), Super Mario Bros.: The Lost Levels (1986; released as Super Mario Bros. 2 in Japan), Super Mario Bros. 2 (1988), and Super Mario Bros. 3 (1988). As in the original games, players control the Italian plumber Mario and his brother Luigi through themed worlds, collecting power-ups, avoiding obstacles, and finding secrets. The remakes feature updated graphics—including the addition of parallax scrolling—and music, modified game physics, a save feature, and bug fixes.', 'https://en.wikipedia.org/wiki/Super_Mario_All-Stars'),
  ('Q2549185', 'Top Gear 2 (released as Top Racer 2 in Japan) is a racing video game developed and published by Gremlin Interactive. A direct sequel to the 1992 game Top Gear, it was first released by Kemco for the SNES in North America in September 1993, and then the Super Famicom in Japan on December 22. It was later ported to the Amiga and Amiga CD32 in September 1994 by Gremlin Interactive, and to the Sega Genesis sometime the same year by Vic Tokai. While more realistic than its predecessor, Top Gear 2 maintained the arcade-style gameplay the series is known for.', 'https://en.wikipedia.org/wiki/Top_Gear_2'),
  ('Q1052174', 'Pac-Man 2: The New Adventures, known in Japan as Hello! Pac-Man, is a 1994 side-scrolling adventure game in the Pac-Man series developed and published by Namco. Instead of being a maze game like the majority of its predecessors, Pac-Man 2 incorporates light point-and-click adventure game elements. The game borrows its structure and certain elements from Pac-Land, and also appears to contain certain elements from the animated series, such as Pac-Man''s family and a main villain commanding the ghosts.

The game was released in 1994 for the Super Nintendo Entertainment System, and was released for the Sega Genesis exclusively in the US.', 'https://en.wikipedia.org/wiki/Pac-Man_2:_The_New_Adventures'),
  ('Q2933418', 'Cal Ripken Jr. Baseball is a sports video game released in 1992 by Mindscape for the Sega Genesis and Super Nintendo Entertainment System. It was a port of TV Sports: Baseball for home computers.', 'https://en.wikipedia.org/wiki/Cal_Ripken_Jr._Baseball'),
  ('Q1966569', 'Lamborghini American Challenge (originally released as Crazy Cars III) is a 1992 racing video game developed and published by Titus France for the Amiga, Amstrad CPC, Atari ST, Commodore 64, MS-DOS, Super NES, Amiga CD32, and Game Boy.

The game is essentially an upgrade from Titus''s previous entry in the Crazy Cars franchise, Crazy Cars III. It adds a two-player mode, a few more options, and a jazz fusion soundtrack. It also changes the scoring system and gives the player a possibility to save progress every 5 races (instead after Division Challenge only). The night goggles item is no longer available for purchase (except in the SNES version) and the car no longer bounces to the top of the screen after driving through slopes at high speeds. In Amiga version introduction was cut out and MS-DOS version does not support EGA anymore.', 'https://en.wikipedia.org/wiki/Lamborghini_American_Challenge'),
  ('Q2937649', 'Captain Novolin is a 1992 educational platform video game, developed by Sculptured Software and published by Raya Systems for the Super Nintendo Entertainment System. Starring the eponymous superhero with type 1 diabetes, the game sees the player control Captain Novolin on a quest to save the mayor of Pineville from the supervillain Blubberman. It is a part of educational video game series from Raya that also includes Rex Ronan: Experimental Surgeon, Packy and Marlon, and Bronkie the Bronchiasaurus.

Funding for the game came from Novo (makers of the Novolin brand of insulin) and the National Institutes of Health. To promote the game, Novo distributed 10,000 free copies to hospitals. During its initial release, the game was positively received by diabetes specialists, as well as children with the condition. But reception from both contemporary and retrospective video game critics has been poor, and it has been named as one of the worst video games of all time.', 'https://en.wikipedia.org/wiki/Captain_Novolin'),
  ('Q1052386', 'The Lost Vikings is a 1993 puzzle-platform game developed by Silicon & Synapse (now Blizzard Entertainment) and published by Interplay Productions. In the game, the player controls three separate vikings with different abilities. The three vikings must work together to finish each level and find their way back home.

The game was initially released for the Super NES, then subsequently released for the Amiga, Amiga CD32, MS-DOS, and Mega Drive/Genesis. A sequel, The Lost Vikings 2, was released in 1997.

Blizzard re-released The Lost Vikings for the Game Boy Advance in 2003 and for Battle.net in 2014. In 2021, the game was re-released for Nintendo Switch, PlayStation 4, Windows, and Xbox One as part of the Blizzard Arcade Collection.', 'https://en.wikipedia.org/wiki/The_Lost_Vikings'),
  ('Q2962853', 'Chester Cheetah is a fictional character and the official mascot for Frito-Lay''s Cheetos brand snacks as well as Chester''s Snacks which consists of flavored fries, popcorn and puffcorn.', 'https://en.wikipedia.org/wiki/Chester_Cheetah'),
  ('Q2521841', 'Ultima VI: The False Prophet, released by Origin Systems in 1990, is the sixth part in the role-playing video game series of Ultima. It is the third and final game in the "Age of Enlightenment" trilogy. Ultima VI sees the player return to Britannia, at war with a race of gargoyles from another land, struggling to stop a prophecy from ending their race. The player must help defend Britannia against these gargoyles, and ultimately discover the secrets about both lands and its peoples.

Ultima VI continues to advance the technology of the Ultima series. The game world is larger, with a 1024x1024 tile map seamlessly connected and to scale. World interactivity is further increased with object manipulation, movement, and crafting. Graphics and sound are likewise advanced with the use of new sound card technology and VGA graphics cards, and the user interface is streamlined with the use of point-and-click icons.', 'https://en.wikipedia.org/wiki/Ultima_VI:_The_False_Prophet'),
  ('Q973459', 'Killer Instinct is a 1994 fighting game developed by Rare and published by Nintendo for consoles. It was originally released for arcades by publisher Midway in October 1994, and ported to both the Super Nintendo Entertainment System and the Game Boy the following year. The game''s plot involves an all-powerful corporation organizing a fighting tournament. The story was adapted in a limited comic book series published under the short-lived Acclaim Comics imprint.

According to Ken Lobb, during his time at Namco Hometek, the groundwork for Killer Instinct started as a Namco''s fighting game project in the early planning stages, titled Melee (which itself later became WeaponLord). Aspects of Killer Instinct''s core gameplay were influenced from SNK fighting games, namely both the World Heroes and the Fatal Fury series, particularly the characters Kim Dragon and Kim Kaphwan.', 'https://en.wikipedia.org/wiki/Killer_Instinct_(1994_video_game)'),
  ('Q3098487', 'Garry Kitchen''s Super Battletank: War in the Gulf is a 1992 tank simulation single-player video game developed and published by Absolute Entertainment for the SNES. Taking place during Operation Desert Storm, the player controls an M1 Abrams main battle tank for the United Nations. A sequel, Super Battletank 2, was released for the SNES in 1994.', 'https://en.wikipedia.org/wiki/Super_Battletank'),
  ('Q1900111', 'Double Dragon V: The Shadow Falls is a fighting game developed by Leland Interactive Media and published by Tradewest for the Super Nintendo Entertainment System and Sega Genesis in 1994. A port for the Atari Jaguar developed by Telegames was released the following year. It is an American-produced sequel to the Double Dragon series by Technōs Japan, who had little to no credited involvement in the development of the game outside of licensing the IP to the publisher outside Japan.

Unlike previous games in the series, which were side-scrolling beat ''em ups, Double Dragon V: The Shadow Falls is a head-to-head fighting game based on the Double Dragon animated series. Technōs would eventually produce their own fighting game based on the 1994 live-action Double Dragon film for the Neo Geo the following year, simply titled Double Dragon.', 'https://en.wikipedia.org/wiki/Double_Dragon_V:_The_Shadow_Falls'),
  ('Q969899', 'Virtual Bart is a 1994 action video game developed by Sculptured Software and published by Acclaim Entertainment. It was released for the Super Nintendo Entertainment System (SNES) and Sega Genesis in September 1994. It is based on the American animated television series The Simpsons, and has players control Bart Simpson through a selection of six minigames based around various themes. It is the final Simpsons game to star Bart Simpson, as well as the final Simpsons game released for the Genesis.

Virtual Bart was conceived as a follow-up to The Simpsons: Bart''s Nightmare (1992), with Mark Flitman as producer. The game received generally mixed reviews from critics upon release. Reviewers criticized the game for its high difficulty, controls, and lack of polish, though praised the gameplay variety, graphics, and overall presentation. Retrospective reviews have been more critical, with it often being ranked as among the worst Simpsons games.', 'https://en.wikipedia.org/wiki/Virtual_Bart'),
  ('Q3129978', 'Super Bomberman 2 is a 1994 action maze video game developed by Produce! and published by Hudson Soft for the Super Nintendo Entertainment System. It is the second installment of the Super Bomberman series, part of the larger Bomberman franchise, and the only installment without a two-player story mode. The game was re-released in 2026 as part of the Super Bomberman Collection compilation.', 'https://en.wikipedia.org/wiki/Super_Bomberman_2'),
  ('Q2534891', 'Aero Fighters, known as Sonic Wings in Japan, is a vertically scrolling shooter developed by Video System and published as an arcade video game by Tecmo in 1992. It is the first installment of the Aero Fighters series. A Super Nintendo Entertainment System version was released in 1993 in Japan and 1994 in North America.', 'https://en.wikipedia.org/wiki/Aero_Fighters'),
  ('Q1965664', 'Zero the Kamikaze Squirrel, released years later in Japan as Zero: High Flying Squirrel, is a video game developed by Iguana Entertainment and published by Sunsoft. It is a spin-off/sequel of the Aero the Acro-Bat series. The game was released in 1994 for the Sega Genesis in October and Super NES in November, along with the release of Aero the Acro-Bat 2. A PAL region release for Mega Drive was in July 1995.

The main star is Zero, Aero''s rival from the previous games. A remake for the Game Boy Advance was planned in 2003, but it was cancelled. The game was re-released in October 2024 for Nintendo Switch, PlayStation 4, PlayStation 5, Xbox One and Xbox Series X/S by Ratalaika Games.', 'https://en.wikipedia.org/wiki/Zero_the_Kamikaze_Squirrel'),
  ('Q1055377', 'Art of Fighting 2 is a 1994 fighting game developed and published by SNK for the Neo Geo arcade and home platforms. It is a direct sequel to 1992''s Art of Fighting, involving both new and returning characters competing against each other in the King of Fighters tournament. The plot follows Ryo Sakazaki and his friends as they work together to take down the mafia host Geese Howard, whose forces manipulated them in the first Art of Fighting game. It retains most of the characters from the first game rather than just Ryo and Robert Garcia. The gameplay remains faithful to the original Art of Fighting, including Desperation Moves and taunts that are used strategically. This game was promoted with The King of Fighters ''94 released in the same year by the company. It was ported to the Neo Geo AES, Neo Geo CD, and Super Famicom. It would be later re-released, along with the rest of the Art of Fighting trilogy, for more consoles.', 'https://en.wikipedia.org/wiki/Art_of_Fighting_2'),
  ('Q2561280', 'Dragon Ball Z: Super Butōden, known as Dragon Ball Z in Europe, is a 1993 fighting video game developed by Tose and published by Bandai for the Super Nintendo Entertainment System. It is based upon Akira Toriyama''s Dragon Ball franchise, and was its first fighting game.

Due to the popularity of Street Fighter II: The World Warrior at the time, producer Toshihiro Suzuki chose to work on a fighting game when assigned to a new project due to it being his preferred genre. Its gameplay consists of one-on-one fights, with a main six-button configuration, featuring special moves, as well as three playable modes.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_Super_But%C5%8Dden'),
  ('Q1058736', 'Gokujō Parodius ～Kako no Eikō o Motomete～, translated as Gokujo Parodius – Pursuing the Past Glory and also known as Fantastic Journey, is a 1994 horizontally scrolling shooter arcade video game developed and published by Konami. It is the third entry in their Parodius series, itself a parody spin-off of their Gradius series.', 'https://en.wikipedia.org/wiki/Gokuj%C5%8D_Parodius'),
  ('Q1061560', 'Super Mario Kart is a 1992 kart racing game developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). The first game in the Mario Kart series, it was released in Japan on August 27, 1992, North America on September 1, 1992, and Europe on January 21, 1993. Selling 8.76 million copies worldwide, the game went on to become the fourth best-selling SNES game of all time. Super Mario Kart was re-released on the Wii''s Virtual Console in 2009, on the Wii U''s Virtual Console in 2013, and on the New Nintendo 3DS''s Virtual Console in 2016. Nintendo re-released Super Mario Kart in 2017 as part of the company''s Super NES Classic Edition.', 'https://en.wikipedia.org/wiki/Super_Mario_Kart'),
  ('Q3107876', 'World Cup USA ''94 is an association football video game developed by Tiertex and published by U.S. Gold in 1994. It was released for Genesis, Sega CD, Super NES, Master System, MS-DOS, Game Boy, Commodore Amiga and Game Gear. The game gives official groups, teams, and the fidelity schedule of the championship. The MS-DOS and Sega CD versions have digitized stadium photos. The Genesis version carries the PolyGram Video logo across the stadium advertisement boards in the game. The Genesis version was also the first console game to support a 16:9 widescreen mode.

This was the last official FIFA World Cup franchise game before Electronic Arts acquired the rights in 1996 for the FIFA Soccer series and the first official FIFA World Cup franchise game to feature non-qualified teams.', 'https://en.wikipedia.org/wiki/World_Cup_USA_%2794'),
  ('Q3108499', 'NHLPA Hockey ''93 is a 1992 ice hockey video game released by Electronic Arts for the Sega Genesis and Super Nintendo Entertainment System. It is the second installment of the NHL series, following NHL Hockey (1991), and the first to be released for the Super NES.

Although it is considered to be the second EA Sports NHL game, the game was not licensed by the NHL; however, it did receive licensing permission from the NHLPA. Because of this, all teams are referred to only by city (the New York Islanders were referred to as "Long Island") with no use of the team nickname itself. Additionally, no NHL team logos or NHL emblems are seen anywhere in the game.', 'https://en.wikipedia.org/wiki/NHLPA_Hockey_%2793'),
  ('Q2526874', 'Aerobiz is a business simulation video game for the Super NES and Mega Drive/Genesis game consoles, released in 1992 by Koei. It was also released for the FM Towns, PC-9801 and X68000 computer platforms in Japan.

As CEO of a budding international airline, the player has a limited amount of time to expand their business to become the industry leader against three other airlines (either AI-controlled or human opponents). The player has an amount of control over how their airline develops, such as the name, investments, what routes to fly, plane purchases, and other various aspects, while at the mercy of world events such as politics (for instance, choosing to run an airline out of Moscow will restrict the player to buying only Soviet planes, and will make negotiating with Western nations more difficult) and natural disasters. The player can also get the company involved in peripheral businesses such as hotels and shuttle services. Once Perestroika is initiated, then the Cold War restrictions no longer apply in the game.', 'https://en.wikipedia.org/wiki/Aerobiz'),
  ('Q2948683', 'Champions World Class Soccer is a football (soccer) video game released on the Sega Genesis and Super Nintendo Entertainment System in 1994, developed by Park Place Productions and published by Acclaim Entertainment.', 'https://en.wikipedia.org/wiki/Champions_World_Class_Soccer'),
  ('Q2928112', 'Bulls vs. Blazers and the NBA Playoffs is a basketball video game developed and published by Electronic Arts, first released for the Super Nintendo Entertainment System in 1992. The following year, it was released for the Sega Genesis. It was then later released for the Mega Drive, under the title NBA Playoffs: Bulls vs Blazers.

The game is the sequel to Bulls vs Lakers and the NBA Playoffs. Like its predecessor, the game''s title refers to the previous season''s NBA championship series, the 1992 NBA Finals match-up between the Chicago Bulls and Portland Trail Blazers.

It is the first EA basketball game to feature in-game advertisements with the company''s "EA Sports" logo.', 'https://en.wikipedia.org/wiki/Bulls_vs._Blazers_and_the_NBA_Playoffs'),
  ('Q2527040', 'Lemmings 2: The Tribes is a 1993 puzzle strategy video game developed by DMA Design and published by Psygnosis, and is the sequel to the 1991 video game Lemmings. Similar to the original title, the game sees the player guiding anthropomorphised lemmings through a number of levels, using various skills to help them reach the exit. Expanding on the mechanics of the original game, Lemmings 2 introduced an overarching narrative and featured a more open-ended series of levels based around different ''tribes'' of lemmings, also increasing the number of available skills and simplifying the requirements for clearing levels. Development of Lemmings 2 was more intensive, with Psygnosis having greater involvement in attempt to recreate the success of the original game. A focus on the production of the game was cross-development of a large number of ports, with the game released to consoles including the Mega Drive, Super NES and Game Boy. Lemmings 2 was a commercial success and received positive reviews from critics, with praise directed towards its additional gameplay mechanics and greater variety of levels and abilities.', 'https://en.wikipedia.org/wiki/Lemmings_2:_The_Tribes'),
  ('Q1047581', 'Undercover Cops is a 1992 beat ''em up video game developed and published by Irem for arcades. It was the company''s first attempt at the modern beat ''em up genre, which had been established with their previous game Kung-Fu Master (1984). Players control "city sweepers", a police agent-like group who fights crime by taking down thugs in New York City in the year 2043. The game was ported to the Super Famicom exclusively in Japan in 1995.', 'https://en.wikipedia.org/wiki/Undercover_Cops'),
  ('Q2927096', 'Brutal: Paws of Fury (Titled Paws of Fury in Germany) is a 1994 fighting game developed and published by GameTek. The game features a cast of various anthropomorphic animals as selectable fighters. It also features the ability to learn new attacks and save them via passwords. Originally a Sega CD exclusive, it was later ported to other game consoles.

Brutal: Paws of Fury was published in 1994 by GameTek in Europe, Cybersoft in North America, and Kemco in Japan. The game was released for the Sega CD, Amiga, CD32, Genesis, and Super Nintendo Entertainment System. An updated version, Brutal Unleashed: Above the Claw (also titled Brutal: Above the Claw), was released for the Sega 32X and MS-DOS compatible computers in 1995 with two new playable characters, new arenas, a remixed intro, and new music. The general content and gameplay mechanics remained constant throughout all incarnations. Reviews for the game were mixed, with praise for the graphics, soundtrack, and gameplay innovations, but criticism for the sluggish play and controls.', 'https://en.wikipedia.org/wiki/Brutal:_Paws_of_Fury'),
  ('Q2927402', 'Bubsy II is a platform video game, the sequel to Bubsy in Claws Encounters of the Furred Kind, and the second game in the Bubsy series. It was originally released by Accolade in 1994 for the Sega Genesis, Super NES, and Game Boy. The Super NES version was re-released for Windows as part of Bubsy Two-Fur on December 17, 2015, while all three versions were re-released as part of Bubsy in: The Purrfect Collection in 2025.', 'https://en.wikipedia.org/wiki/Bubsy_II'),
  ('Q2927741', 'Bugs Bunny Rabbit Rampage is an action video game developed by Viacom New Media (a then-sister company to Nickelodeon, who had broadcast Looney Tunes cartoons at the time of the game''s release) and published by Sunsoft released exclusively for the SNES in 1994. The player controls Bugs Bunny as he fights traditional Looney Tunes villains in order to confront the main villain of the story, animator Daffy Duck. The game''s title is derived from the 1955 animated short with the same name, which follows a similar plot of Bugs at the mercy of an antagonistic animator, revealed to be Elmer Fudd. The characters in the game were voiced by Greg Burson.', 'https://en.wikipedia.org/wiki/Bugs_Bunny_Rabbit_Rampage'),
  ('Q2980379', 'Clue: Parker Brothers'' Classic Detective Game is a North American-exclusive video game published for the Super Nintendo Entertainment System and Sega Genesis video game consoles. It is based on the popular board game of the same name.

The game was shown for preview at the Summer CES in May 1992 with plans of distribution for that fall at a MSRP US$49.99.', 'https://en.wikipedia.org/wiki/Clue_(1992_video_game)'),
  ('Q2527522', 'Batman Forever is a 1995 beat ''em up video game based on the film of the same name. Though released by the same publisher at roughly the same time, it is an entirely different game from Batman Forever: The Arcade Game. It was followed by Batman & Robin in 1998.', 'https://en.wikipedia.org/wiki/Batman_Forever_(video_game)'),
  ('Q1942269', 'Super Back to the Future II is a 2D side-scrolling platformer video game developed by Daft and published by Toshiba EMI in Japan exclusively on July 23, 1993 for the Super Famicom. It is based on the film Back to the Future Part II, featuring elements from it, including the plot of protagonist Marty McFly attempting to prevent antagonist Biff Tannen from getting rich using a sports almanac from the future. The gameplay involves Marty using a hoverboard at all times, spin attacking and bouncing off enemies with it.

Super Back to the Future II uses a super deformed art style, designed by Endorphin Konappy, which differs from the film''s realistic style. The soundtrack was based on the film''s and was composed by Hitoshi Sakimoto. It began as a role-playing video game with a design similar to The Legend of Zelda, but was changed to be a platforming game at some point during development.', 'https://en.wikipedia.org/wiki/Super_Back_to_the_Future_II'),
  ('Q93655', 'The Humans is a 1992 puzzle-platform game developed by Imagitec Design and published by Mirage Technologies for the Amiga. It was ported to other home computers and consoles. The goal of the game varies per level but usually revolves around bringing at least one of the player-controlled humans to the designated end area marked by a colored tile. Doing this requires players taking advantage of the tribe''s ability to build a ladder and use tools such as spears, torches, wheels, ropes and a witch doctor in later levels.

The Humans was conceived by Rodney Humble during his time working with Imagitec Design as a project for the Atari Lynx spawning a trilogy based upon the human evolution inspired by Psygnosis'' 1991 game Lemmings, creating and drawing his ideas before transferring the design work to Imagitec programmers in developing them further, serving as the first game to be published by MicroProse offshoot Mirage, while Atari Corporation liked the title and commissioned two additional conversions for their systems.', 'https://en.wikipedia.org/wiki/The_Humans_(video_game)'),
  ('Q100096', 'Mega Man X2 is a 1994 platform game developed and published by Capcom for the Super Nintendo Entertainment System (SNES). The game was released in Japan on December 16, 1994, and in North America and PAL regions in 1995. It is the direct sequel to Mega Man X, released one year prior. Mega Man X2 takes place in the near future in which humans try to peacefully coexist with intelligent robots called "Reploids", with some of the Reploids going "Maverick" and threatening daily life. The plot follows the android protagonist X, a "Maverick Hunter" who saved humanity from the evil Sigma six months earlier. A trio of Mavericks calling themselves the "X-Hunters" has arisen, intent on destroying X by luring him with body parts of his comrade Zero, who died in the conflict with Sigma''s right-hand robot Vile.', 'https://en.wikipedia.org/wiki/Mega_Man_X2'),
  ('Q3007953', 'Cutthroat Island is a platform game based on 1995 film of the same name that was developed by Software Creations and published by Acclaim Entertainment in 1995 for the Game Boy, Game Gear, Genesis, and Super Nintendo Entertainment System. When the game was first released, it featured a promotion by which players could find hidden treasure chests in the game and enter a contest to win real world prizes.', 'https://en.wikipedia.org/wiki/Cutthroat_Island_(video_game)'),
  ('Q3064872', 'Famicom Detective Club is an adventure game duology developed and published by Nintendo for the Family Computer Disk System. The first entry, The Missing Heir, was released in 1988, followed by a prequel released the next year titled The Girl Who Stands Behind. In both games, the player takes on the role of a young man solving murder mysteries in the Japanese countryside.

The duology was the first writing project for Yoshio Sakamoto, before he found greater success and recognition with Metroid. The games were inspired by Enix''s 1983 adventure game The Portopia Serial Murder Case, horror films by Italian director Dario Argento, and detective novels by Japanese writer Seishi Yokomizo. Both games were only released in Japan and received positive reception from critics.', 'https://en.wikipedia.org/wiki/Famicom_Detective_Club'),
  ('Q3020587', 'Power Athlete, known outside Japan for the Sega Genesis as Deadly Moves and for the Super Nintendo Entertainment System as Power Moves, is a 1992 fighting video game developed by System Vision and published by Kaneko.', 'https://en.wikipedia.org/wiki/Power_Athlete'),
  ('Q2580580', 'Pierre le Chef is... Out to Lunch is a video game that was released for the Game Boy and Super NES in 1993 by Mindscape. It is a side-scrolling platform game about a French chef trying to collect ingredients for his dishes by going to different countries to catch them as they have escaped. Ports for the Amiga and Amiga CD32 were released in 1994.', 'https://en.wikipedia.org/wiki/Out_to_Lunch_(video_game)'),
  ('Q3021810', 'Mickey''s Ultimate Challenge is a puzzle video game developed by Designer Software and published by Hi Tech Expressions for the Super NES, Game Boy, Sega Genesis, Master System, and Game Gear under license from Walt Disney Computer Software. The Master System version, released in Brazil by Tec Toy in 1998, was the last game released for that console. All other versions were released in 1994. Players move Mickey through the game by making him walk, jump, and go through doors. There are five major challenges, a segue, and a final challenge. It was met with mixed reviews from gaming magazines.', 'https://en.wikipedia.org/wiki/Mickey%27s_Ultimate_Challenge'),
  ('Q2986962', 'Kirby''s Avalanche, known in Europe as Kirby''s Ghost Trap, is a puzzle video game developed by Compile and HAL Laboratory and published by Nintendo for the Super Nintendo Entertainment System. It was released in North America and Europe in February 1995. It is a Western release of the Japanese Super Puyo Puyo featuring characters from the Kirby series. There was not a Japanese release, and the game remains the only Kirby title not released there. In Europe and Australia, the game was re-released on the Wii''s Virtual Console service on July 27, 2007, and in North America on September 24, 2007. The game was re-released for the Nintendo Classics service on July 21, 2022.', 'https://en.wikipedia.org/wiki/Kirby%27s_Avalanche'),
  ('Q2527906', 'The Death and Return of Superman is a side-scrolling beat ''em up video game released by Sunsoft for the Super NES and Genesis. It is based on "The Death of Superman" comic book storyline by DC Comics and features many characters from the comics, including Superman himself, Superboy, Steel, Cyborg Superman, the Eradicator, and Doomsday. All of the five Supermen are playable characters at some point.

Gameplay, and visually, the Genesis and Super NES versions are near identical, however, each version''s soundtracks are radically different from one another.', 'https://en.wikipedia.org/wiki/The_Death_and_Return_of_Superman'),
  ('Q162562', 'Soul Blazer, released in Japan as Soul Blader, is an action role-playing video game developed by Quintet and published by Enix for the Super Nintendo Entertainment System. It was released in 1992 in Japan and North America, but not released in Europe until 1994. It was not released in the United Kingdom.

It is an action role-playing game where the player takes the role of The Master''s servant, to destroy monsters and release the captured souls of a world''s inhabitants. The player must constantly switch between restored areas and corrupted zones to progress, effectively rebuilding the world piece by piece. The servant can be named by the player, but in a later game developed by Quintet, Illusion of Gaia, he is referred to as "Blazer".', 'https://en.wikipedia.org/wiki/Soul_Blazer'),
  ('Q172113', 'Fever Pitch Soccer, known as Head-On Soccer in North America, is a soccer video game originally developed and published by U.S. Gold for the Sega Genesis/Mega Drive in 1995.

Featuring an arcade-style approach to soccer compared to other titles that were released at the time, Fever Pitch Soccer allows players to have the choice of playing across any of the game modes available against with either CPU-controlled opponents or other players with the team of their choosing. Initially launched for the Genesis, it was then released on the Super Nintendo Entertainment System a few months after the original version and was later ported to the Atari Jaguar in December of the same year.', 'https://en.wikipedia.org/wiki/Fever_Pitch_Soccer'),
  ('Q3062978', 'F1 Pole Position 2, known in Japan as Human Grand Prix II, is the sequel to Human Grand Prix and the predecessor to Human Grand Prix III: F1 Triple Battle.', 'https://en.wikipedia.org/wiki/F1_Pole_Position_2'),
  ('Q3062976', 'F1 Pole Position is a 1992 racing video game for the SNES, developed by Human Entertainment and published by them in Japan, while the other versions were handled by Ubi Soft. It is the first game in the Human Grand Prix/F1 Pole Position series, which features Formula One licensing.', 'https://en.wikipedia.org/wiki/F1_Pole_Position_(video_game)'),
  ('Q3051587', 'Mega Man & Bass is a 1998 action game developed and published by Capcom. It is a spin-off game in the original Mega Man series, and was originally released in Japan for the Super Famicom on April 24, 1998. It was later ported to the Game Boy Advance in 2002, and released internationally the following year.

After defeating the evil Dr. Wily many times, the robot hero Mega Man is called into action once again when a powerful robot known as King steals the blueprints to the creations of Dr. Wily and Dr. Light in order to create an army for robotic dominance over humans. Having learned of the threat, Mega Man''s rival Bass decides to take matters into his own hands. Gameplay is similar to previous entries in the series, in which the player advances by completing stages and defeating bosses to acquire their signature weapons. Mega Man & Bass lets the player choose between either of its title characters, who play differently from each other.', 'https://en.wikipedia.org/wiki/Mega_Man_%26_Bass'),
  ('Q3019391', 'Daze Before Christmas is a platform video game developed by Norwegian company Funcom for the Mega Drive and published by Sunsoft in 1994 in Australia. It was ported to the Super Nintendo Entertainment System and released in Europe and Australia. A North American release was planned but got cancelled.', 'https://en.wikipedia.org/wiki/Daze_Before_Christmas'),
  ('Q2532658', 'Breath of Fire is a role-playing video game developed by Capcom originally for the Super Nintendo Entertainment System. Initially released in Japan in April 1993, the game was later made available in North America in August 1994 by Square Soft, who handled the title''s English localization and promotion. It is the first entry in the Breath of Fire series.

Recognized by Capcom as their first traditional role-playing video game, Breath of Fire would set the precedent for future entries in the series, and features character designs artist Keiji Inafune, as well as music by members of Capcom''s in-house sound team Alph Lyla. The game has been re-released multiple times, being released for the Game Boy Advance in 2001, the Wii U in 2015, the New Nintendo 3DS in 2016 and the Nintendo Switch on the SNES Nintendo Classics in 2019.', 'https://en.wikipedia.org/wiki/Breath_of_Fire_(video_game)'),
  ('Q3072796', 'Fire Emblem: Genealogy of the Holy War is a 1996 tactical role-playing game developed by Intelligent Systems and published by Nintendo for the Super Famicom. It is the fourth installment of the Fire Emblem series, and the second to be developed for the platform. Genealogy of the Holy War takes place on the continent of Jugdral, split between eight countries founded by the Twelve Crusaders, an ancient group of soldiers who ended the rule of the ancient dragon Loptous with divine aid. In the present, a cult working to revive Loptous stirs up war among the countries. The story is told over two generations—the first generation follows the Grannvalian prince Sigurd, while the second follows his son Seliph as he works to defeat the cult and avenge his father. Gameplay follows the traditional Fire Emblem system of tactical battles taking place on grid-based maps, while adding the Weapon Triangle and Support systems, which directly impacted both gameplay and story.', 'https://en.wikipedia.org/wiki/Fire_Emblem:_Genealogy_of_the_Holy_War'),
  ('Q2588801', 'Trials of Mana, also known by its Japanese title Seiken Densetsu 3, is a 1995 action role-playing game developed and published by Square for the Super Famicom. It is the sequel to the 1993 game Secret of Mana, and is the third installment in the Mana series. Set in a high fantasy world, the game follows three heroes as they attempt to claim the legendary Mana Sword and prevent the Benevodons from being unleashed and destroying the world. It features three main plotlines and six different possible main characters, each with their own storylines, and allows two players to play simultaneously. Trials of Mana builds on the gameplay of its predecessor with multiple enhancements, including the use of a time progression system with transitions from day to night and weekday to weekday in game time, and a wide range of character classes to choose from, which provides each character with an exclusive set of skills and status progression.', 'https://en.wikipedia.org/wiki/Trials_of_Mana'),
  ('Q3077148', 'Foreman For Real is a 1995 boxing video game for the Game Boy, Game Gear, Sega Genesis, and the Super Nintendo Entertainment System featuring George Foreman. It is the follow-up to Acclaim''s previous release, George Foreman''s KO Boxing. The game was met with negative reviews which criticized the simplistic and unexciting gameplay and low production values.', 'https://en.wikipedia.org/wiki/Foreman_For_Real'),
  ('Q3018106', 'Ultraman: Towards the Future, released in Japan as Ultraman, is a fighting video game developed by Nova and published by Bandai for the Super Nintendo Entertainment System. It is based on the TV series Ultraman, with the Japanese version being based on the 1966 series and the North American version being based on the contemporary Ultraman: Towards the Future series. This game has received mostly negative reviews due to its high difficulty and sub-par graphics.', 'https://en.wikipedia.org/wiki/Ultraman:_Towards_the_Future_(video_game)'),
  ('Q2529000', 'EarthBound, originally released in Japan as Mother 2: Gīgu no Gyakushū, is a 1994 role-playing video game developed by Ape Inc. (now Creatures Inc.) and HAL Laboratory and published by Nintendo for the Super Nintendo Entertainment System. The second entry in the Mother series, it follows a young boy named Ness and his party of Paula, Jeff and Poo, as they travel the world to collect melodies from eight Sanctuaries to defeat the universal cosmic destroyer Giygas.

EarthBound had a lengthy development period that spanned five years. Its returning staff from EarthBound Beginnings (1989) included writer/director Shigesato Itoi and lead programmer Satoru Iwata, as well as composers Keiichi Suzuki and Hirokazu Tanaka, who incorporated a diverse range of styles into the soundtrack, including salsa, reggae, and dub. Most of the other staff members had not worked on the original EarthBound Beginnings, and the game came under repeated threats of cancellation until Iwata joined the team. Originally scheduled for release in January 1993, the game was completed around May 1994 and first released in Japan in August 1994, and in North America in June 1995. A port for the Game Boy Advance developed by Pax Softnica, bundled with Mother, as Mother 1 + 2, was released only in Japan in 2003.', 'https://en.wikipedia.org/wiki/EarthBound'),
  ('Q2565615', 'Fire Emblem: Mystery of the Emblem, known in Japan as Fire Emblem: Monshō no Nazo, is a 1994 tactical role-playing video game developed by Intelligent Systems and published by Nintendo for the Super Famicom. It is the third installment of the Fire Emblem series, and the first to be developed for the Super Famicom. The story is divided into two parts: the first is a retelling of Fire Emblem: Shadow Dragon and the Blade of Light, while the second is an original story acting as a sequel to the first game. After defeating the sorcerer Gharnef and the Dark Dragon Medeus, peace is restored to Archanea and Marth restores his kingdom. His ally Hardin ascends to the throne of Archanea, but begins hostile military expansion across the continent, forcing Marth to confront his old friend and the force driving him. Gameplay follows the traditional Fire Emblem system of tactical battles taking place on grid-based maps.', 'https://en.wikipedia.org/wiki/Fire_Emblem:_Mystery_of_the_Emblem'),
  ('Q3181985', 'John Madden Football, released as John Madden American Football in Europe, is an American football video game released by Electronic Arts. Loosely based on the 1988 video game of the same title, it was the first entry in what eventually became the yearly Madden NFL series on home consoles, initially released for the Sega Genesis in 1990. It is sometimes called Madden ''90 or Madden ''91 to distinguish it from subsequent entries in the series.

A Super NES version was released in 1991, which incorporated new content that was also featured in the second Genesis installment released during the same year (John Madden Football ''92), followed by a reworked Amiga version in 1992.', 'https://en.wikipedia.org/wiki/John_Madden_Football_(1990_video_game)'),
  ('Q3171670', 'Radical Rex is a 1994 platform video game developed by Beam Software for the Super Nintendo Entertainment System (SNES), Sega Genesis, and Sega CD. It is a remake of the 1993 Game Boy game Baby T-Rex.

A Microsoft Windows port of the SNES version published by Piko Interactive was released on March 7, 2019. Piko also released the game as part of the Piko Interactive Collection 1 for the Evercade on June 8, 2020.', 'https://en.wikipedia.org/wiki/Radical_Rex'),
  ('Q3155973', 'Itoi Shigesato no Bass Tsuri No. 1 is a fishing video game developed and released only in Japan for the Super Famicom on February 21, 1997 and updated for broadcast as eight different episodes on the Satellaview subsystem between April and November 1997. On March 31, 2000, the latest version of the game was released for the Nintendo 64 as the Definitive Edition. The game allows the player to play as the creator of the game, Shigesato Itoi, and includes a host of animal characters who occasionally appear in the game. The SA-1 was used in the Super Famicom version.', 'https://en.wikipedia.org/wiki/Itoi_Shigesato_no_Bass_Tsuri_No._1'),
  ('Q1063119', 'Super Mario RPG: Legend of the Seven Stars is a 1996 role-playing video game developed by Square and published by Nintendo for the Super Nintendo Entertainment System (SNES). It was the final Mario game for the SNES, and was directed by Chihiro Fujioka and Yoshihiko Maekawa, produced by Shigeru Miyamoto, and scored by Yoko Shimomura.

Super Mario RPG''s story focuses on Mario and his friends as they seek to defeat the Smithy Gang, who have crashed into their world and scattered the seven star pieces of Star Road. It is the first RPG in the Mario franchise, drawing from major elements of Square''s RPG franchises such as Final Fantasy. The main form of fighting enemies is turn-based combat with a party of up to three characters. It is also the first game in the Mario franchise to have gameplay within an isometric 3D environment, allowing for a new variety of the exploration and platforming elements reminiscent of the Super Mario series. The game features many new characters, such as Mallow and Geno.', 'https://en.wikipedia.org/wiki/Super_Mario_RPG'),
  ('Q3036891', 'Mutant Chronicles: Doom Troopers is a video game released in 1995 by Adrenalin Entertainment for the Sega Genesis and Super NES gaming systems.', 'https://en.wikipedia.org/wiki/Doom_Troopers'),
  ('Q1028503', 'Cameltry is a 1990 maze video game developed and published by Taito for arcades. It was released in Japan in April 1990. It was ported to the FM Towns, Super Nintendo Entertainment System, and X68000. The Super NES version was published in North America and Europe as On the Ball.', 'https://en.wikipedia.org/wiki/Cameltry'),
  ('Q2604921', 'Bahamut Lagoon is a 1996 tactical role-playing game developed and published by Square for the Super Famicom. Bahamut Lagoon was released on the Virtual Console in Japan on September 29, 2009 for the Wii and on February 5, 2014 for the Wii U.', 'https://en.wikipedia.org/wiki/Bahamut_Lagoon'),
  ('Q1992329', 'The Combatribes is a 1990 beat ''em up video game developed and published by Technōs Japan for arcades. A home version of the Super Nintendo Entertainment System was also released in 1992. The game centers on three vigilantes (identified as cyborgs in the SNES port) who must fight against numerous street gangs in futuristic New York City. The SNES version was released for the Wii Virtual Console in North America on November 30, 2009.', 'https://en.wikipedia.org/wiki/The_Combatribes'),
  ('Q1045765', 'Super Mario World 2: Yoshi''s Island is a 1995 platform game developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). The player controls Yoshi dinosaurs on their quest to reunite baby Mario with his brother Luigi, who has been kidnapped by the wizard Kamek. Yoshi runs and jumps to reach the end of each level while solving puzzles and collecting items with Mario''s help.

Having introduced the character in the previous Super Mario game, Super Mario World (1990), Nintendo decided to develop a game starring Yoshi, with the aim of making it more accessible. Yoshi''s Island introduced his signature flutter jump and egg-spawning abilities. The marker-drawn art style was created by scanning hand-drawn pictures and approximating them pixel-by-pixel. Some special effects were powered by a new Super FX2 microchip.', 'https://en.wikipedia.org/wiki/Yoshi%27s_Island'),
  ('Q3176904', 'Jelly Boy is a platform game developed by Probe Software for the Super Nintendo Entertainment System and Game Boy. It was published in Europe in 1995 by Ocean Software.', 'https://en.wikipedia.org/wiki/Jelly_Boy'),
  ('Q3046155', 'ESPN National Hockey Night is a multiplatform traditional ice hockey simulation video game for the Super NES, Sega Genesis, Sega CD, and personal computers with MS-DOS capabilities.', 'https://en.wikipedia.org/wiki/ESPN_National_Hockey_Night_(video_game)'),
  ('Q3028391', 'Dino Dini''s Goal is a soccer video game released by Virgin Games in 1993. It is considered by many to be the "true" sequel to Kick Off 2 (in preference to Kick Off 3), as Kick Off''s creator Dino Dini had moved from Anco Software and was responsible for all Goal''s engineering and game design. Goal introduced improved dynamics and A.I. over Kick Off 2, as well as other innovative features, such as multiple camera views. The game shipped 60,000 units on the first day of release.', 'https://en.wikipedia.org/wiki/Dino_Dini%27s_Goal'),
  ('Q196255', 'Street Fighter II Turbo: Hyper Fighting, released as Street Fighter II Dash Turbo in Japan, is a 1992 fighting game developed and published by Capcom for arcades. It is the third arcade version of Street Fighter II, part of the Street Fighter franchise, following Street Fighter II: Champion Edition, and was initially released as an enhancement kit for that game. Released less than a year after the previous installment, Hyper Fighting introduced a faster playing speed and new special moves for certain characters, as well as further refinement to the character balance.

Hyper Fighting is the final arcade game in the Street Fighter II series to use the original CP System hardware. It was distributed as an upgrade kit designed to be installed into Champion Edition printed circuit boards. The next game, Super Street Fighter II, uses the CP System''s successor, the CP System II.', 'https://en.wikipedia.org/wiki/Street_Fighter_II_Turbo'),
  ('Q3046163', 'ESPN Sunday Night NFL is a sports video game that was released for the Super NES, Sega CD, and Sega Genesis in 1994.', 'https://en.wikipedia.org/wiki/ESPN_Sunday_Night_NFL'),
  ('Q3190155', 'Jurassic Park is an action-adventure video game for the Super Nintendo Entertainment System (SNES), based on the 1990 novel and 1993 film of the same name. It was developed and published by Ocean Software in 1993 in North America and PAL regions, and published by Jaleco in 1994 in Japan.

The player controls Dr. Alan Grant, a paleontologist who has become trapped at Jurassic Park, an island theme park and zoo populated by genetically engineered dinosaurs. The game''s exterior portion is viewed from a top-down perspective, but shifts to a first-person view during interior sections. The game garnered praise for these varied and three-dimensional perspectives, the usage of stereo sound, and the adventure gameplay. In 1994, Ocean released a sequel, Jurassic Park 2: The Chaos Continues, with gameplay which significantly differs from that of the original.', 'https://en.wikipedia.org/wiki/Jurassic_Park_(SNES_video_game)'),
  ('Q2607689', 'Castlevania: Dracula X, titled Castlevania: Vampire''s Kiss in Europe and Akumajou Dracula XX in Japan, is a 1995 platform game developed and published by Konami for the Super Nintendo Entertainment System. It is the second Castlevania installment to be released for the Super NES. It is a remake of Castlevania: Rondo of Blood, which was previously released in Japan on the PC Engine Super CD-ROM2 in 1993. While the plot is similar to Rondo of Blood and it uses many of that game''s graphics, it features new levels and altered gameplay elements, rather than being a direct port because of the limits of the Super NES cartridge format and exclusivity agreements with PC Engine maker NEC. It was released on July 21, 1995 in Japan, in September 1995 in North America, February 22, 1996 in Europe, and on June 22, 1996, in Australia. The game received mixed reviews, with journalists considering it inferior to Rondo of Blood and criticizing its high difficulty.', 'https://en.wikipedia.org/wiki/Castlevania:_Dracula_X'),
  ('Q3043052', 'Star Ocean is a 1996 action role-playing game developed by tri-Ace and published by Enix for the Super Famicom. The first game in the Star Ocean series, it was released only in Japan in July 1996, and was the first game developed by tri-Ace, consisting of staff that had previously left Wolf Team due to being unhappy with the development process for Tales of Phantasia with Namco in 1995. The game used a special compression chip in its cartridge to compress and store all of the game''s data due to possessing graphics that pushed the limits of the Super Famicom. Additionally, the game had voice acting for the game''s intro and voice clips that played during the game''s battle gameplay, a rarity for games on the system.', 'https://en.wikipedia.org/wiki/Star_Ocean_(video_game)'),
  ('Q3130597', 'Marvel Super Heroes in War of the Gems is a 1996 beat-''em-up platform game developed by Capcom for the Super Nintendo Entertainment System, based on the events of Marvel Comics'' series The Infinity Gauntlet and The Infinity War. In the game''s plot, Adam Warlock calls upon Earth''s greatest superheroes to seek out the Infinity Gems before they fall into the wrong hands.

Although War of the Gems is based on a similar storyline as the Capcom arcade game Marvel Super Heroes, and each of the playable characters retains one of the special moves they had in that game, it is not a port; War of the Gems instead features gameplay similar to Final Fight and X-Men: Mutant Apocalypse. In 2020, the game was rereleased as part of a home arcade cabinet from Arcade1Up alongside X-Men vs. Street Fighter, Marvel Super Heroes vs. Street Fighter and Marvel vs. Capcom: Clash of Super Heroes.', 'https://en.wikipedia.org/wiki/Marvel_Super_Heroes_in_War_of_the_Gems'),
  ('Q1984081', 'First Samurai, alternatively titled The First Samurai, is a 1991 beat ''em up platform game developed by Vivid Image and published by Image Works. The First Samurai was originally released in September 1991 for the Amiga and Atari ST, and was later ported to the Commodore 64 (reduced graphics), MS-DOS (music during gameplay removed) and the Super Nintendo Entertainment System (significant level-design changes). It was followed by a sequel, Second Samurai, in 1994. In 2011, a port was released for iOS.', 'https://en.wikipedia.org/wiki/First_Samurai'),
  ('Q1970300', 'ESPN SpeedWorld is a Super NES and Sega Genesis video game that was released in 1994 exclusively for North America based on the television series of the same name. The title screen of the video game was partially inspired by the 1993 running of the First Union 400 racing event; which occurred on April 18, 1993. The real-life drivers from the mid-1990s are missing because the game only has an ESPN license and not an official NASCAR license.', 'https://en.wikipedia.org/wiki/ESPN_SpeedWorld_(video_game)'),
  ('Q3022202', 'Demolition Man is a pair of action video games based on the film of the same name. Acclaim Entertainment published the 16-bit version, which features run and gun gameplay, for the Super NES, Sega Genesis, and Sega CD. Virgin Interactive released a completely different game for the 3DO that combined several distinct gameplay styles. In both games, the player controls John Spartan, the main character from the film, as he attempts to find and defeat his nemesis, Simon Phoenix.', 'https://en.wikipedia.org/wiki/Demolition_Man_(video_game)'),
  ('Q1987042', '3 Ninjas Kick Back is a beat ''em up platform game for the Sega Genesis, Super Nintendo Entertainment System, and Sega CD. It was released in 1994 and was developed by Malibu Interactive. The Genesis version was published by Psygnosis while the SNES and Sega CD versions were published by Sony Imagesoft. The Sega CD version was released exclusively in a bundle pack with another game Hook and was not released separately.

The game is based on the film of the same name.', 'https://en.wikipedia.org/wiki/3_Ninjas_Kick_Back_(video_game)'),
  ('Q3138599', 'Hit the Ice is a 1990 ice hockey video game developed and published by Taito for arcades. It was released by Williams in North America. The game is a cartoonish representation of the sport with three players on each team: forward, defense, and goalie. There are few rules, as players are encouraged to trip, elbow and kick opponents.

Taito released ports of Hit the Ice for the PC Engine/TurboGrafx-16, Mega Drive/Genesis, Game Boy and Super NES. An NES version was developed but not released.', 'https://en.wikipedia.org/wiki/Hit_the_Ice'),
  ('Q1984719', 'Spider-Man and Venom: Maximum Carnage is a 1994 beat ''em up video game developed by Software Creations and published by Acclaim Entertainment and its subsidiary LJN for the Super Nintendo Entertainment System and Sega Genesis. The game, based on the comic book story arc of the same name, features numerous heroes, including Spider-Man, Venom, and their allies from the Marvel Comics fictional universe like Captain America, Black Cat, Iron Fist, Cloak and Dagger, Deathlok, Morbius and Firestar, all teaming up to battle an onslaught of villains led by Carnage, including Shriek, Doppelganger, Demogoblin and Carrion.', 'https://en.wikipedia.org/wiki/Spider-Man_and_Venom:_Maximum_Carnage'),
  ('Q1001925', 'Flashback, released as Flashback: The Quest for Identity in the United States, is a 1992 cinematic platformer developed by Delphine Software and published by U.S. Gold for the Amiga. It was directed, written, designed, and partially programmed by Paul Cuisset, who had previously created the adventure game Future Wars with Éric Chahi. Flashback was ported to the Mega Drive/Genesis, MS-DOS, Acorn Archimedes, and Super NES in 1993. CD-ROM versions for the Sega CD, 3DO, CD-i, MS-DOS, Macintosh, and FM Towns were released in 1994 and 1995, followed by a cartridge version for the Atari Jaguar in 1995. In 2017, the game was released worldwide on the Dreamcast, featuring graphic assets and cutscenes from the MS-DOS version and music from the Amiga version. An updated port titled Flashback: Remastered Edition was released for Nintendo Switch on 7 June 2018, for PlayStation 4 on 20 November 2018, and for Windows on 29 November 2018. The game was also released in October 2023 for the Evercade platforms as part of Delphine collection cartridge, and is based on the original Mega Drive/Genesis version.', 'https://en.wikipedia.org/wiki/Flashback_(1992_video_game)'),
  ('Q3190026', 'Jungle Strike is a video game developed and published by Electronic Arts in 1993 for the Sega Genesis. The game was later released for the Super NES and an enhanced version for MS-DOS. A 1994 Amiga version was developed by Ocean Software, the Super NES and MS-DOS versions developed by Gremlin Interactive, and portable console versions by Black Pearl Software. It is the direct sequel to Desert Strike (a best-seller released the previous year) and is the second installment in the Strike series. The game is a helicopter-based shoot ''em up, mixing action and strategy. The plot concerns two villains intent on destroying Washington, D.C. The player must use the helicopter and occasionally other vehicles to thwart their plans.', 'https://en.wikipedia.org/wiki/Jungle_Strike'),
  ('Q2618300', 'Super Godzilla is a video game for the Super Nintendo Entertainment System released in Japan on December 23, 1993, and in North America in July 1994. It is based on Toho''s Godzilla franchise and was developed by Advance Communication Company.', 'https://en.wikipedia.org/wiki/Super_Godzilla'),
  ('Q3038911', 'Drakkhen is a 1989 action role-playing video game developed and published by Infogrames for the Amiga and Atari ST. It was ported to MS-DOS, Super NES, PC-98, X68000, and FM Towns Marty. It was a very early game in the North American SNES library, and as such, received almost universal coverage in previews of the then-upcoming SNES in gaming magazines of 1990 and early 1991.

Drakkhen was among the first role-playing games with a three-dimensional playing field and an early example of the real-time tactics genre. It did not employ a fully 3D game engine, instead implementing a hybrid approach using vectors and bitmapped character-scaling algorithms. Drakkhen includes an animated day-night cycle and the ability to wander freely about the game world, both rarities for a game of its era. Kemco developed a follow-up Dragon View for the SNES.', 'https://en.wikipedia.org/wiki/Drakkhen'),
  ('Q1985746', 'The King of Dragons is a 1991 beat ''em up game developed and published by Capcom for arcades. It follows players as they control characters through the kingdom of Malus to defeat monsters led by the dragon Gildiss. It features a level advancement system, allowing character attributes to be upgraded as players progress through the game. The game''s music was composed by Yoko Shimomura.

The King of Dragons was ported to the Super NES in 1994. An emulated version of the game has been released in multiple Capcom compilations.', 'https://en.wikipedia.org/wiki/The_King_of_Dragons'),
  ('Q1026590', 'Mario''s Super Picross is a Super Famicom sequel to Mario''s Picross, and a part of Nintendo''s Picross video game franchise. The game is compatible with the Super Famicom Mouse. It is developed by Jupiter and Ape and published by Nintendo.', 'https://en.wikipedia.org/wiki/Mario%27s_Super_Picross'),
  ('Q2619370', 'Kirby''s Dream Course is a 1994 miniature golf video game developed by HAL Laboratory and Nintendo EAD and published by Nintendo for the Super Nintendo Entertainment System (SNES). A spin-off of the Kirby series and the first released for the SNES, players control the pink spherical character Kirby through a series of courses by launching him towards the goal hole at the end. Kirby can hit enemies to collect power-ups that grant him unique abilities, such as those that allow him to destroy certain obstacles or fly around the level.

HAL Laboratory originally designed Dream Course as a standalone game called Special Tee Shot. Though it was previewed in several magazines and displayed on the packaging for the console, HAL replaced the game''s original characters with those from the Kirby series following its popularity on the Game Boy. Special Tee Shot was later released for the Satellaview peripheral in Japan. Dream Course received favorable reviews, both at release and retrospectively, for its unique design and absurdity. Some were critical of its high difficulty level and controls. It has been re-released through the Wii and Wii U Virtual Console digital storefronts and the Super NES Classic Edition. A sequel for the Nintendo 64 was in development but later canceled.', 'https://en.wikipedia.org/wiki/Kirby%27s_Dream_Course'),
  ('Q1112940', 'Columns is a match-three puzzle video game designed and developed by Jay Geertsen and shared in 1989. Originally developed for the Motorola 68000-based HP 9000 running HP-UX, it was ported to Mac and MS-DOS before being released commercially by Sega, who ported it to arcades and then to several Sega consoles. The game was subsequently ported to other home computers, including the Atari ST.', 'https://en.wikipedia.org/wiki/Columns_(video_game)'),
  ('Q1141946', 'Final Fight is a 1989 beat ''em up game developed and published by Capcom for arcades. It is the seventh title released for the CP System hardware. Set in the fictional Metro City, the player controls one of three street fighters: former pro wrestler and city mayor Mike Haggar, expert brawler Cody Travers, and modern-day ninja Guy. The trio set out to rescue Jessica (Haggar''s daughter and Cody''s girlfriend) when she is kidnapped by the Mad Gear Gang.

The game began development as a sequel to the original Street Fighter released in 1987, under the working title Street Fighter ''89. However, its genre was switched from a fighting game to a beat ''em up, and the title was changed to Final Fight following the success of Technōs Japan''s Double Dragon. Final Fight was ported to various home computers and consoles, including the ZX Spectrum, Super NES and Sega CD.', 'https://en.wikipedia.org/wiki/Final_Fight_(video_game)'),
  ('Q3292201', 'NBA Live 95 is the follow-up to NBA Showdown and the first NBA Live title in the NBA Live video games series from EA Sports. It was published by EA Sports and released in October 1994. The cover features an action shot from the 1994 NBA Finals.

It introduced what would become standard elements in the series, including the isometric on-court perspective and the turbo button used to give players a temporary burst of speed. The game''s engine is a modified version of EA Sports'' FIFA International Soccer engine, using the same perspective. The game was re-released with NBA Live 06 as part of the EA Retro Series. Game Players gave the Super NES version its "best sports game award" in their Super NES division on the January 1995 issue of their magazine.', 'https://en.wikipedia.org/wiki/NBA_Live_95'),
  ('Q3298503', 'Math Blaster Episode I: In Search of Spot is an educational video game in the Blaster Learning System line created by Davidson & Associates. It is a remake of their earlier New Math Blaster Plus! from 1990. Versions of the game were released for the Super NES and Genesis, simply titled Math Blaster: Episode 1. The program was translated to Spanish and was published as Mates Blaster: En Busca de Positrón.

A sequel called Math Blaster Episode II: Secret of the Lost City was released in 1994 and a prequel for younger children called Math Blaster Jr. was released in 1996. The game Mega Math Blaster (also identified with subtitles "ages 6-9" or "3rd Grade") follows the structure of Math Blaster Episode I with a new story and art design.', 'https://en.wikipedia.org/wiki/Math_Blaster_Episode_I:_In_Search_of_Spot'),
  ('Q3296242', 'Mary Shelley''s Frankenstein is an action platformer video game based on the 1994 film of the same name, an adaptation of Mary Shelley''s 1818 novel Frankenstein; or, The Modern Prometheus.

A different game sharing the same name was developed by Psygnosis for the Sega CD, this version is instead a graphic adventure game with 2D fighting combat.', 'https://en.wikipedia.org/wiki/Mary_Shelley%27s_Frankenstein_(video_game)'),
  ('Q3198012', 'Knights of the Round is a 1991 beat ''em up game developed and published by Capcom for arcades. Based loosely on the legend of King Arthur and the Knights of the Round Table, the game features an action role-playing-like level advancement system, with fighters automatically being upgraded to new weapons and armor as they advance through the game. The arcade version of the game was included in the compilations Capcom Beat ''Em Up Bundle (2018) and Capcom Arcade 2nd Stadium (2022).', 'https://en.wikipedia.org/wiki/Knights_of_the_Round_(video_game)'),
  ('Q1194825', 'Super Metroid is a 1994 action-adventure game developed by Nintendo and Intelligent Systems and published by Nintendo for the Super Nintendo Entertainment System (SNES). It is the third Metroid game, following the Game Boy game Metroid II: Return of Samus (1991). The player controls bounty hunter Samus Aran, who travels to the planet Zebes to retrieve an infant Metroid creature stolen by the Space Pirate leader Ridley.

Like the previous two Metroid games, Super Metroid focuses on exploring a sprawling alien world to find power-ups used to reach previously inaccessible areas. New elements include an inventory screen, an automap, and the ability to fire in 8 directions. The development staff from previous Metroid games—including Yoshio Sakamoto, Makoto Kano, and Gunpei Yokoi—returned to develop Super Metroid over the course of two years.', 'https://en.wikipedia.org/wiki/Super_Metroid'),
  ('Q2632064', 'Fire Emblem: Thracia 776 is a tactical role-playing game developed by Intelligent Systems and published by Nintendo for the Super Famicom; it was originally released through the Nintendo Power flash cartridge in 1999, then on a ROM cartridge the following year. It is the fifth installment in the Fire Emblem series, the third and last title to be developed for the Super Famicom, and the last home console Fire Emblem until the release of Fire Emblem: Path of Radiance in 2005.

Thracia 776 takes place on the continent of Jugdral. Set in the generational gap within Fire Emblem: Genealogy of the Holy War, the story follows main protagonist Leif as he rallies a private army in an attempt to defeat the ruling Grannvale Empire and restore his lost kingdom of Thracia. Gameplay follows the traditional Fire Emblem system of tactical battles taking place on grid-based maps, but with added elements such as a fatigue system where characters lose energy with each performed action.', 'https://en.wikipedia.org/wiki/Fire_Emblem:_Thracia_776'),
  ('Q3190158', 'Jurassic Park 2: The Chaos Continues (also known as Jurassic Park Part 2: The Chaos Continues) is a 1994 run and gun video game developed and published by Ocean Software for the Super Nintendo Entertainment System (SNES). It is a sequel to the Super NES game Jurassic Park, and a non-canonical continuation of the Jurassic Park series.

Jurassic Park 2: The Chaos Continues was released in November or December 1994. A Game Boy version with a different storyline was released in February 1995. In 2023, Limited Run Games re-released both versions as part of Jurassic Park: Classic Games Collection for Nintendo Switch, PlayStation 4, PlayStation 5, and Xbox Series X/S, commemorating the 30th anniversary of the film Jurassic Park. The games were also available through re-issued Game Boy and SNES cartridges.', 'https://en.wikipedia.org/wiki/Jurassic_Park_2:_The_Chaos_Continues'),
  ('Q1240445', 'Pro Kishi Jinsei Simulation: Shōgi no Hanamichi is a shogi video game, developed by Access and published by Atlus, which was released exclusively in Japan in 1996.

This was the last game released for the Super Famicom by Atlus.', 'https://en.wikipedia.org/wiki/Pro_Kishi_Jinsei_Simulation:_Sh%C5%8Dgi_no_Hanamichi'),
  ('Q2628712', 'E.V.O.: Search for Eden is a 1992 action-adventure game developed by Almanic Corporation and published by Enix for the Super NES. Combining traditional platforming mechanics with experience and leveling mechanics originating from role playing games, E.V.O.: Search for Eden involves the player navigating a creature through a number of side-scrolling levels while undergoing bodily evolution to cope with ever-changing environments. It is heavily based on Almanic''s original title, 46 Okunen Monogatari ~The Shinka Ron~ ( 4.6 Billion Year Story: The Theory of Evolution), released in Japan in 1990 for the PC-9801.', 'https://en.wikipedia.org/wiki/E.V.O.:_Search_for_Eden'),
  ('Q1152450', 'Fatal Fury 2 is a 1992 fighting game developed and published by SNK for the Neo Geo arcade and home platforms. It is the second installment in the Fatal Fury franchise and the sequel to Fatal Fury: King of Fighters (1991). It was later ported to several home systems, including the Super Nintendo Entertainment System and Sega Genesis by Takara. Its updated version, Fatal Fury Special, was released in 1993.

The game introduced Kim Kaphwan, the first Taekwondo and the first Korean character in fighting games, and Mai Shiranui, one of SNK''s mascots, their primary sex symbol, and one of the most well-known female video game characters. Both of them went on to become mainstays in both Fatal Fury games as well as The King of Fighters series.', 'https://en.wikipedia.org/wiki/Fatal_Fury_2'),
  ('Q1305295', 'Pilotwings is a flight simulation video game developed and published by Nintendo for the Super Nintendo Entertainment System. The game was originally released in Japan in December 1990, shortly after the launch of the Super Famicom in the country. It was also released as a launch title for the SNES in August 1991 in North America, with a European release following in 1992.

In Pilotwings, the player attempts to earn pilot licenses through lessons in light plane flight, hang gliding, skydiving, and the use of a rocket belt. Bonus stages and levels involving an attack helicopter are also available. Each event offers unique controls and gameplay mechanics. To increase the realism of the game''s flight simulation, the developers extensively utilized the SNES''s Mode 7 capability, which mimics 3D graphics by rotating and scaling flat objects.', 'https://en.wikipedia.org/wiki/Pilotwings_(video_game)'),
  ('Q3194351', 'Kawasaki Superbike Challenge (known in Europe as Kawasaki Superbikes) is a multiplatform racing video game where the player takes the role of a Kawasaki factory team rider in an unnamed fictional racing series.', 'https://en.wikipedia.org/wiki/Kawasaki_Superbike_Challenge'),
  ('Q3195035', 'Ken Griffey Jr. Presents Major League Baseball is a 1994 baseball video game developed by Software Creations and published by Nintendo for the Super Nintendo Entertainment System. A Game Boy version was released in 1997. The game has a Major League Baseball (MLB) license but not a Major League Baseball Players Association (MLBPA) license, meaning that the game has real stadiums and real teams, but not real players (except Ken Griffey Jr.). The fictitious players have the same statistics as their real-world counterparts, and the game comes with a name-changing feature that allows players to change the athletes'' names. Nintendo released a portable version of the game in 1997 for the Game Boy with real players and stats from the 1996 season. The gameplay is similar to its predecessors, though it is sometimes sluggish due to hardware restrictions. The SNES version came with a promotional Griffey collector''s card packed inside. It is often rated by the public as one of the best baseball games of all time.', 'https://en.wikipedia.org/wiki/Ken_Griffey_Jr._Presents_Major_League_Baseball'),
  ('Q1105683', 'Kat''s Run: All Japan K-Car Championship is a racing video game, published by Atlus, which was released exclusively in Japan in 1995. As the title implies, the playable vehicles are all kei cars.

There are two playable modes: Street race and V.S. race, which has four selectable courses. The player can choose ten different characters/drivers and ten vehicles, respectively.', 'https://en.wikipedia.org/wiki/Kat%27s_Run:_All_Japan_K-Car_Championship'),
  ('Q1202713', 'Kirby''s Dream Land 3 is a 1997 platform game developed by HAL Laboratory and published by Nintendo for the Super Nintendo Entertainment System. Starring Kirby, it is the fifth installment in the Kirby series and the third game under the Kirby''s Dream Land name. Although the first game was largely unrelated, Dream Land 3 features many similar characters to Dream Land 2. Dream Land 3 was followed by Kirby 64: The Crystal Shards in 2000.

Kirby''s Dream Land 3 was the last SNES game published by Nintendo in North America. Problems with the game''s PAL conversion prevented it from being released in Europe and Australia for many years; it was eventually released for the Virtual Console in those regions in the form of an import from North America on July 24, 2009, for the Wii and on July 25, 2013, for the Wii U. The game was re-released on the Virtual Console in North America on January 5, 2009, for the Wii and on May 8, 2013, for the Wii U and in Japan on April 28, 2009, for the Wii and on May 8, 2013, for the Wii U. It was also included as part of the 2012 Wii compilation Kirby''s Dream Collection and the Nintendo Classics service.', 'https://en.wikipedia.org/wiki/Kirby%27s_Dream_Land_3'),
  ('Q2020530', 'Arcana is a role-playing video game released for the Super Nintendo Entertainment System by HAL Laboratory in 1992. The game represents all of its characters as cards, but plays like a dungeon-crawling role-playing game rather than a card-based game. In keeping with this metaphor, the death of a character results in a ''torn'' card, and the magical properties of some cards are used to explain abilities of the game''s characters.', 'https://en.wikipedia.org/wiki/Arcana_(video_game)'),
  ('Q2708224', 'Aero the Acro-Bat is a 1993 platform video game developed by Iguana Entertainment and published by Sunsoft for the Super Nintendo Entertainment System and Sega Genesis. Aero the Acro-Bat, a red anthropomorphic bat, was created by David Siller. In 2002, Metro 3D released a version of the game for the Game Boy Advance, with a battery back-up (which the original versions lacked). The GBA version was titled Aero The Acro-Bat - Rascal Rival Revenge in Europe and Acrobat Kid in Japan. The Super NES version of the game was released on the Wii''s Virtual Console in the PAL region and North America in July 2010. In 2024, the Super NES version was re-released in August for Nintendo Switch, PlayStation 4, PlayStation 5, Xbox One, and Xbox Series X/S, alongside a new localization in Japanese made by Shinyuden as Aero: Acrobat Kid for the Nintendo Switch users in Japan, while the GBA version was re-released for the same platforms in November.', 'https://en.wikipedia.org/wiki/Aero_the_Acro-Bat'),
  ('Q3275484', 'Madden NFL 95 is an American football video game released by EA Sports in 1994. In addition to the usual home console versions that were released on the Sega Genesis and Super NES, this edition was also released for the portable Game Gear and Game Boy systems (although the Game Boy was released without the NFL license as Madden ''95). It was the first version of the game that portrayed black NFL players as black, rather than all white as in previous versions, and the first in the Madden series to portray black athletes on the cover. It was also the first game in the series to have the official NFLPA license.', 'https://en.wikipedia.org/wiki/Madden_NFL_%2795'),
  ('Q2016892', 'Battletoads in Battlemaniacs is a beat ''em up platform game developed by Rare for the Super Nintendo Entertainment System. Part of the Battletoads series, the game was released in North America by Tradewest in June 1993, in Europe by Nintendo in October 1993 and in Japan by Masaya on January 7, 1994. It was also ported for the Master System and released exclusively in Brazil. It was released around the same time as Battletoads/Double Dragon, another installment in the series. The game received its first official re-release on the Nintendo Classics service on February 21, 2024, as it was not included in the Rare Replay collection for the Xbox One.', 'https://en.wikipedia.org/wiki/Battletoads_in_Battlemaniacs'),
  ('Q2016922', 'Barbie: Super Model is a one or two-player educational action video game that allows the player to play as Barbie. It was released for the Genesis, Super NES, and MS-DOS in 1993.', 'https://en.wikipedia.org/wiki/Barbie:_Super_Model'),
  ('Q2052338', 'Pocky & Rocky is a 1992 scrolling shooter video game developed by Natsume Co., Ltd. for the Super Nintendo Entertainment System (Super NES). It is the sequel to Taito''s 1986 arcade game KiKi KaiKai. Pocky & Rocky follows the adventures of a young Shinto shrine maiden, Pocky, and her new tanuki companion, Rocky, as they attempt to save a group of goblins from evil forces. Gameplay takes place from a top-down perspective and features both single-player and cooperative modes.

The game was generally well-received by critics. It was followed by Pocky & Rocky 2 (1994) and Pocky & Rocky with Becky (2001). A new entry, Pocky & Rocky Reshrined, released in 2022.', 'https://en.wikipedia.org/wiki/Pocky_%26_Rocky_(video_game)'),
  ('Q1074008', 'Fatal Fury: King of Fighters is a 1991 fighting game developed and published by SNK for the Neo Geo arcade. It was later ported to numerous home consoles, including the Super Nintendo Entertainment System in 1992 and Sega Genesis in 1993. Fatal Fury was SNK''s first fighting game for the Neo Geo system, and served as the first entry in their Fatal Fury series. The three playable characters are the Bogard brothers Terry and Andy alongside their friend Joe Higashi. In the story they oppose their nemesis Geese Howard, the host of "The King of Fighters" tournament where the player must use martial arts to defeat enemies until becoming the champion and reaching Geese.', 'https://en.wikipedia.org/wiki/Fatal_Fury:_King_of_Fighters'),
  ('Q2017312', 'Aaahh!!! Real Monsters is an action-adventure platform game developed by Realtime Associates and published by Viacom New Media in 1995 for the Sega Genesis and Super Nintendo Entertainment System. It is based on the animated series of the same name on Nickelodeon. The game was rereleased in 2026 as part of the Nickelodeon Splat Pack video game compilation.', 'https://en.wikipedia.org/wiki/Aaahh!!!_Real_Monsters_(video_game)'),
  ('Q2019441', 'Saturday Night Slam Masters, known in Japan as Muscle Bomber: The Body Explosion, is a 1993 pro wrestling fighting game developed and published by Capcom for arcades. The game features character designs by manga artist Tetsuo Hara, famous for Fist of the North Star.

The game was followed by an updated version titled Muscle Bomber Duo: Ultimate Team Battle in 1993, and a sequel called Ring of Destruction: Slam Masters II in 1994.', 'https://en.wikipedia.org/wiki/Saturday_Night_Slam_Masters'),
  ('Q2016787', 'Barkley Shut Up and Jam! is a basketball video game originally developed and published by Accolade for the Sega Genesis in March 1994. The game is the first entry in the Barkley Shut Up and Jam series, featuring former NBA MVP Charles Barkley prominently and as one of the playable characters.

Featuring arcade-style gameplay similar to Midway''s NBA Jam but closely following the rules seen in street basketball, players compete with either CPU-controlled opponents or against other players in matches across various cities of the United States. Originally known as Charles Barkley Basketball during development and initially released on the Genesis, it was later ported to the Super Nintendo Entertainment System and first released on North America in June 1994 and this version was released months later in both Japan and Europe on the same year by Den''Z and Sony Electronic Publishing respectively.', 'https://en.wikipedia.org/wiki/Barkley_Shut_Up_and_Jam!'),
  ('Q2634403', 'ClayFighter is a fighting game developed by Visual Concepts and published by Interplay Productions. It was released for the Super Nintendo Entertainment System in November 1993 and the Sega Genesis in 1994. The game is a parody of Street Fighter and Mortal Kombat. In 2009, the Genesis version was re-released on the Wii Virtual Console.

Most of the game features a circus theme focused more on humor. It features claymation-style graphics that were created by photographing and digitizing actual clay models. The game was one of the two clay-themed game franchises, the second being a platformer released for the SNES titled Claymates.', 'https://en.wikipedia.org/wiki/ClayFighter_(video_game)'),
  ('Q2662389', 'HardBall III is a baseball video game developed by MindSpan and published by Accolade between 1992 and 1994 for MS-DOS, Genesis, and the Super Nintendo Entertainment System. It is licensed by the Major League Baseball Players Association and is the sequel to HardBall II.', 'https://en.wikipedia.org/wiki/HardBall_III'),
  ('Q1239244', 'Populous is a video game developed by Bullfrog Productions and published by Electronic Arts for the Amiga in March 1989, then quickly the Atari ST and MS-DOS. Many conversions followed, including for the Genesis, Super NES, and PC Engine consoles. Populous is considered the first god game. With over four million copies sold, Populous is one of the best-selling PC games of all time.

The player assumes the role of a deity, who must lead followers through direction, manipulation, and divine intervention, with the goal of eliminating the followers led by the opposite deity. Played from an isometric perspective, the game consists of more than 500 levels, with each level being a piece of land which contains the player''s followers and the enemy''s followers. The player is tasked with defeating the enemy followers and increasing their own followers'' population using a series of divine powers before moving on to the next level. The game was designed by Peter Molyneux, and Bullfrog developed a gameplay prototype via a board game they invented using Lego.', 'https://en.wikipedia.org/wiki/Populous_(video_game)'),
  ('Q2634825', 'Troy Aikman NFL Football is an American football video game originally developed by Leland Interactive Media and published by Williams Entertainment (credited under the Tradewest name) for the Super Nintendo Entertainment System first in North America in August 1994. Officially licensed from the National Football League, it prominently features former NFL player Troy Aikman, who became the first member of the Dallas Cowboys to have his namesake in a game, followed by his teammate Emmitt Smith in Emmitt Smith Football.

In Troy Aikman NFL Football, players have the choice to compete in matches across any of the game modes available with either AI-controlled opponents or against other human players. Initially launched for the Super Nintendo, it was then released on the Sega Genesis a few months after the original version and was later ported to the Atari Jaguar in the following year.', 'https://en.wikipedia.org/wiki/Troy_Aikman_NFL_Football'),
  ('Q1276884', 'Daffy Duck: The Marvin Missions is a 1993 platform game for the Super NES. A different Game Boy game was released with the same title in North America, with the European Game Boy version known as Daffy Duck, and the Japanese Game Boy version is known as Looney Tunes Series: Daffy Duck.

The game involves Duck Dodgers in the 24th and a ½ Century, as told in the classic Looney Tunes stories created by Chuck Jones. When he is hit, Duck Dodgers says some of Daffy Duck''s lines from 1950s cartoons like "Mother", "Duck Dodgers!" and "Ho-hoo!", voiced by Greg Burson.', 'https://en.wikipedia.org/wiki/Daffy_Duck:_The_Marvin_Missions'),
  ('Q2020509', 'Adventures of Yogi Bear is a platform game published by Cybersoft on October 1, 1994, in North America and later in Japan and Europe. The game is called Yogi Bear in Japan, Yogi Bear''s: Cartoon Capers for the European Super NES version, and Yogi Bear Cartoon Capers for the Mega Drive version.', 'https://en.wikipedia.org/wiki/Adventures_of_Yogi_Bear'),
  ('Q3275483', 'Madden NFL ''94, released as NFL Pro Football ''94 in Japan, is a 1993 American football video game released by EA Sports for the Sega Genesis and Super NES. It is the fourth game in the Madden NFL series, and marked a significant step forward in the franchise, known for bringing realistic football gameplay to home consoles and laying the groundwork for modern football video games. As the first game in the Madden series with an official NFL team license, the introduction of official NFL teams and improved gameplay mechanics made it a standout title in the series and a nostalgic favorite for fans of retro sports games.', 'https://en.wikipedia.org/wiki/Madden_NFL_%2794'),
  ('Q2629633', 'Aero the Acro-Bat 2 is a platform game developed by Iguana Entertainment, and published by Sunsoft as the sequel of Aero the Acro-Bat. It was released for the Sega Genesis and Super Nintendo Entertainment System in November 1994. The game is dedicated to Brazilian racer Ayrton Senna, who died in a crash during a Grand Prix.

David Siller planned to port and remake the game for Game Boy Advance in 2002, but then cancelled it in favor of original titles. The Super NES version was re-released for the Wii Virtual Console in the PAL region on August 6, 2010, and in North America on September 20. Ratalaika Games re-released the game in September 2024 for Nintendo Switch, PlayStation 4, PlayStation 5, Xbox One, and Xbox Series X/S.', 'https://en.wikipedia.org/wiki/Aero_the_Acro-Bat_2'),
  ('Q2040884', 'Front Mission: Gun Hazard is a 1996 side-scrolling shooter game developed by Omiya Soft and published by Squaresoft for the Super Famicom. It was released only in Japan on February 23. Gun Hazard is the second entry in the Front Mission series and is a side-scrolling shooter with role-playing game elements. The game received an English language fan translation in 2004.', 'https://en.wikipedia.org/wiki/Front_Mission:_Gun_Hazard'),
  ('Q3196442', 'Imperium is a 1992 vertically scrolling shooter video game developed by Jorudan and published by Vic Tokai for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Imperium_(1992_video_game)'),
  ('Q2628325', 'Demon''s Crest, known in Japan as Demon''s Blazon, is a 1994 platform game developed and published by Capcom for the Super Nintendo Entertainment System. It is the third video game starring Firebrand (an enemy character from the Ghosts ''n Goblins series, known as "Red Arremer" in the Japanese version), following Gargoyle''s Quest (1990) and Gargoyle''s Quest II (1992).

The game was internally considered a commercial failure. For this reason, Capcom rejected a potential port to the Game Boy Advance by a studio that would later become Renegade Kid.', 'https://en.wikipedia.org/wiki/Demon%27s_Crest'),
  ('Q1241664', 'Donkey Kong Country 3: Dixie Kong''s Double Trouble!  is a 1996 platform game developed by Rare and published by Nintendo for the Super Nintendo Entertainment System (SNES). It is the third installment of the Donkey Kong Country series, and serves as a sequel to 1995''s Donkey Kong Country 2: Diddy''s Kong Quest. It was also re-released for the Game Boy Advance (GBA) in 2005. The game was made available to download on the Wii''s Virtual Console service in 2007, as well as for the Wii U''s Virtual Console in 2014.

The plot centers on Dixie Kong and her cousin, Kiddy Kong, in their attempts to save the captured Donkey Kong and Diddy Kong from the series'' villain King K. Rool. The game is set in the "Northern Kremisphere", a fictionalized version of northern Europe and Canada. Dixie Kong''s Double Trouble! utilises the same Silicon Graphics technology from its predecessors, which features the use of pre-rendered 3D imagery. The game received positive reviews upon release; critics praised the visuals and various aspects of gameplay, but noted a lack of innovation.', 'https://en.wikipedia.org/wiki/Donkey_Kong_Country_3'),
  ('Q3259253', 'Road Runner''s Death Valley Rally (known in Japan as Looney Tunes: Road Runner vs. Wile E. Coyote and in Europe as Looney Tunes: Road Runner) is a 1992 video game developed by ICOM Simulations and published by Sunsoft for the Super Nintendo Entertainment System. It is based on the Looney Tunes characters Wile E. Coyote and the Road Runner.', 'https://en.wikipedia.org/wiki/Road_Runner%27s_Death_Valley_Rally'),
  ('Q1249187', 'Final Fantasy Mystic Quest, released as Mystic Quest Legend in PAL regions and as Final Fantasy USA: Mystic Quest in Japan, is a 1992 role-playing video game developed and published by Square for the Super Nintendo Entertainment System. It is a spin-off of the broader Final Fantasy series. Final Fantasy Mystic Quest was first released in North America in 1992 and marketed as a "simplified role-playing game... designed for the entry-level player" in an attempt to broaden the genre''s appeal. The game''s presentation and battle system is broadly similar to that of the main series, but differs in its inclusion of action-adventure game elements. It was also the first Final Fantasy game to be released in Europe.', 'https://en.wikipedia.org/wiki/Final_Fantasy_Mystic_Quest'),
  ('Q3237821', 'Liberty or Death is a turn-based strategy video game for NEC PC-9801, MS-DOS, Super NES, and Sega Genesis released by Koei in 1993 and 1994 respectively. It is part of Koei''s Historical Simulation Series.', 'https://en.wikipedia.org/wiki/Liberty_or_Death_(video_game)'),
  ('Q1072051', 'Donkey Kong Country 2: Diddy''s Kong Quest  is a 1995 platform game developed by Rare and published by Nintendo for the Super Nintendo Entertainment System (SNES). It was released on 21 November 1995 in Japan, 4 December in North America, and 14 December in Europe. It is the second installment of the Donkey Kong Country series and the sequel to Donkey Kong Country (1994). It was re-released for the Game Boy Advance (GBA) in 2004. The game was made available for download on the Virtual Console for the Wii and Wii U in 2007 and 2015, respectively.

Players control Diddy Kong and his girlfriend Dixie Kong, who must rescue Donkey Kong after he is kidnapped by King K. Rool. The game is set on Crocodile Isle, with eight worlds of varying environments, totaling 52 levels. The game uses the same Silicon Graphics (SGI) technology from the original, which features the use of pre-rendered 3D imagery. Diddy''s Kong Quest received acclaim and is regarded as one of the greatest 2D platformers of all time. Praise was directed at its soundtrack, which is considered one of the greatest of all time, as well as its graphics and gameplay. It was the second best-selling game of 1995, and the sixth best-selling game on the SNES. It was followed by Donkey Kong Country 3: Dixie Kong''s Double Trouble! in 1996.', 'https://en.wikipedia.org/wiki/Donkey_Kong_Country_2'),
  ('Q2702756', 'Super Bomberman is a 1993 action maze video game developed by Produce! and published by Hudson Soft for the Super Nintendo Entertainment System. Part of the Bomberman series, it is the first game in the series to retain the Bomberman title in Europe, instead of being renamed to Dynablaster or Eric and the Floaters.

Super Bomberman spawned the Super Bomberman sub-series, of which seven more entries have been released: Super Bomberman 2 (1994), Super Bomberman 3 (1995), Super Bomberman 4 (1996), Super Bomberman 5 (1997), Super Bomberman R (2017), Super Bomberman R Online (2017), and Super Bomberman R 2 (2023). The game was re-released in 2026 as part of the Super Bomberman Collection compilation.', 'https://en.wikipedia.org/wiki/Super_Bomberman'),
  ('Q1198491', 'F-Zero is a 1990 racing game developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). It was released in Japan on November 21, 1990, in North America in August 1991, and in Europe in 1992. F-Zero is the first game in the F-Zero series and was a launch game for the SNES. F-Zero has been rereleased for the Virtual Console and Nintendo Classics services on various Nintendo platforms, and as part of the Super NES Classic Edition in 2017.

F-Zero takes place in 2560, when multi-billionaires have created a new entertainment based on Formula One races called "F-Zero". The player can choose between one of four characters, each with their own hovercar. The player can race against computer-controlled characters in 15 tracks divided into three leagues.', 'https://en.wikipedia.org/wiki/F-Zero_(video_game)'),
  ('Q2642154', 'Maui Mallard in Cold Shadow – originally released as Donald in Maui Mallard (Japanese: Donald Duck no Maui Mallard) – is a platforming video game developed and published by Disney Interactive. The game was released in Europe in November 1995, and in Brazil in spring 1997 for the Sega Mega Drive. It was also ported by Eurocom Entertainment Software to the Super NES and released in North America in January 1997, in Europe mostly in autumn 1996 (although the SNES version was released in Germany at the end of 1995), and in Japan on December 20, 1996. A Microsoft Windows port was released in North America in November 1996. It was ported one last time to the Game Boy by Bonsai Entertainment Corp., released in North America in August 1998.', 'https://en.wikipedia.org/wiki/Maui_Mallard_in_Cold_Shadow'),
  ('Q2015417', 'WWF Royal Rumble is a professional wrestling video game released in 1993 for the Super NES and Sega Genesis. Like its predecessor, WWF Super WrestleMania, it is based on the World Wrestling Federation (WWF). It features a variety of match types, including the newly added Royal Rumble match. The game''s roster consists of wrestlers who were top stars in the WWF at the time, and each version of the game has five exclusive playable characters.

The game boasts several new features, including an on-screen meter grappling meter and steel chairs that can be used as weapons. Royal Rumble also adds a variety of new moves, including illegal tactics such as choking and each wrestler''s signature finishing moves.', 'https://en.wikipedia.org/wiki/WWF_Royal_Rumble_(1993_video_game)'),
  ('Q3282634', 'Captain Tsubasa 5: Hasha no Shōgō Campione is the fifth and final installment of Tecmo''s Captain Tsubasa video game series. It is a sequel of Captain Tsubasa 4: Pro no Rival Tachi and was released exclusively in Japan for Nintendo''s Super Famicom on December 9, 1994.', 'https://en.wikipedia.org/wiki/Captain_Tsubasa_5:_Hasha_no_Sh%C5%8Dg%C5%8D_Campione'),
  ('Q3283937', 'Congo''s Caper is a 1992 platform video game developed and published by Data East for the Super Nintendo Entertainment System. A North American version was released in May 1993. It was later released on the Nintendo Switch via the Nintendo Classics service on May 26, 2022.

The game was included along with its predecessor and successor games in a compilation called Joe & Mac Retro Collection, released for modern consoles on October 29, 2026.', 'https://en.wikipedia.org/wiki/Congo%27s_Caper'),
  ('Q2712379', 'Cool Spot is a 1993 platform game developed by Virgin Games for the Sega Genesis, Super Nintendo Entertainment System, Master System, Game Gear, Game Boy, Amiga, and MS-DOS. The title character is Spot, a mascot for the soft drink brand 7 Up. Spot''s appearance in his own video game came at a time when other brand mascots (like Chester Cheetah and the Noid) were appearing in their own video games.', 'https://en.wikipedia.org/wiki/Cool_Spot'),
  ('Q2712722', 'Arkanoid: Doh It Again is a 1997 block breaker video game developed and published by Taito. It was first released in Japan for the Super Famicom and Windows, while Nintendo published the SNES version in Australia, North America and Europe. It is the third installment in the Arkanoid series after the original 1986 arcade game and its sequel Arkanoid: Revenge of Doh.', 'https://en.wikipedia.org/wiki/Arkanoid:_Doh_It_Again'),
  ('Q2709391', 'X-Men: Mutant Apocalypse is an action game developed and published by Capcom for the Super Nintendo Entertainment System in 1994. The game is based on the X-Men comic book franchise from Marvel Comics, being the first such game released by Capcom, a month before the fighting game X-Men: Children of the Atom.

In Mutant Apocalypse, players control five of the X-Men: Beast, Cyclops, Gambit, Psylocke, and Wolverine. After guiding each of them through their own dedicated levels, players can then select which level to complete next as well as the team member to complete it with. The end goal is to defeat Magneto on his Avalon space station. The game was well received by critics.', 'https://en.wikipedia.org/wiki/X-Men:_Mutant_Apocalypse'),
  ('Q220174', 'Zool: Ninja of the Nth Dimension is a platform video game developed and published by Gremlin Graphics. It was marketed as a rival to Sega''s Sonic the Hedgehog. Originally released for the Amiga home computer in October 1992, the game was subsequently ported to Sega Genesis, Super Nintendo Entertainment System, Master System, Game Boy and Game Gear, as well as other home computers. A sequel, Zool 2, was released in 1993. A remastered version of the original game, titled Zool Redimensioned, was developed by Sumo Digital Academy and published by

Secret Mode for Windows and PlayStation 4 in August 2021.', 'https://en.wikipedia.org/wiki/Zool'),
  ('Q3284282', 'Ghoul Patrol is a 1994 run and gun video game developed by LucasArts and published by JVC Musical Industries for the Super Nintendo Entertainment System. It is a sequel to Zombies Ate My Neighbors (1993). In 2021, both games were re-released as part of Lucasfilm Classic Games: Zombies Ate My Neighbors and Ghoul Patrol for Nintendo Switch, PlayStation 4, Xbox One and Windows by Disney Interactive.', 'https://en.wikipedia.org/wiki/Ghoul_Patrol'),
  ('Q3276911', 'Magical Drop II (sometimes known as Magical Drop 2) is a 1996 puzzle video game developed and published by Data East for the Neo Geo arcade and home platforms. It was later ported to Neo Geo CD, Super Famicom, and Sega Saturn. It is the second entry in the Magical Drop series. In the game, the player takes control of one of several characters, battling against computer-controlled opponents before facing the villainous Empress in a final encounter. Gameplay is similar to its predecessor Magical Drop (1995), albeit with improvements; the objective is to clear the screen of constantly advancing colored ''drops'' via a character placed at the bottom of the playfield, which can grab drops and make them disappear by putting them as a column of three or more drops of the same color. Two players can also participate in a competitive versus mode.', 'https://en.wikipedia.org/wiki/Magical_Drop_II'),
  ('Q2015441', 'WWF Super WrestleMania is a multiplatform wrestling video game based on the World Wrestling Federation (WWF), released in 1992 for the Super Nintendo Entertainment System and the Sega Genesis.

Two other 16-bit WWF games, WWF Royal Rumble and WWF Raw, were released which retained the "tug-of-war" style grappling system, where moves are performed by locking up and out-tapping the other player or the computer to execute a move.', 'https://en.wikipedia.org/wiki/WWF_Super_WrestleMania'),
  ('Q2002093', 'Super Punch-Out!! is a boxing video game developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). It was released on October 24, 1994, in North America, in the United Kingdom on February 10, 1995, and in Japan in 1998 for the Super Famicom through the Nintendo Power flash RAM cartridge series. The game is also included in the GameCube version of Fight Night Round 2 as an extra game due to the inclusion of Little Mac in the game. The game was released for the Wii''s Virtual Console in Europe on March 20, 2009, in North America on March 30, 2009, and in Japan on July 7, 2009. The game was also released on the New Nintendo 3DS eShop on May 5, 2016. Nintendo re-released Super Punch-Out!! in the United States in September 2017 as part of the company''s Super NES Classic Edition. It is the fourth game in the Punch-Out!! series, taking place after the Punch-Out!! game for the Nintendo Entertainment System (NES).', 'https://en.wikipedia.org/wiki/Super_Punch-Out!!'),
  ('Q2710813', 'Dragon Ball Z: Super Butōden 3 is a 1994 fighting video game developed by Tose and published by Bandai for the Super Nintendo Entertainment System. Based upon Akira Toriyama''s Dragon Ball franchise, it is the sequel to Dragon Ball Z: Super Butōden 2, which was released earlier in 1993 for SNES. Following the Majin Buu arc, its gameplay remains relatively the same as the previous two Super Butōden entries, consisting of one-on-one fights using a main six-button configuration, featuring special moves as well as two playable modes.

Dragon Ball Z: Super Butōden 3 was created by most of the same team who previously worked on the first two Super Butōden entries on Super Nintendo, with producer Toshihiro Suzuki returning to lead its production, with additional support from staff of both Toei Animation and V Jump magazine. Like its predecessors, Super Butōden 3 garnered positive reception from critics, however the lack of a story mode was heavily criticized by reviewers. Likely due to the game releasing in the middle of the Majin Buu Saga, rendering a faithful adaptation impossible.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_Super_But%C5%8Dden_3'),
  ('Q2016278', 'Beavis and Butt-Head (advertised as MTV''s Beavis and Butt-Head: The Game) are three tie-in video games based on the animated television series of the same name that were released by Viacom New Media in 1994 for the Super NES, Genesis/Mega Drive and Game Gear. The three versions differ from each other, sharing only the basic premise involving the titular characters searching for tickets to a Gwar concert. The games were advertised as featuring music by the band. A fourth version was later released for the Game Boy by GT Interactive in 1998 without the Gwar tie-in.', 'https://en.wikipedia.org/wiki/Beavis_and_Butt-Head_(video_game)'),
  ('Q3275487', 'Madden NFL ''96 is a football video game designed for the 1995 NFL season, licensed by the NFL. Publisher EA Sports intended for it to be the first licensed NFL game for the PlayStation, but the PlayStation version was delayed and ultimately cancelled, with the game being published only for previous-generation consoles, PCs, and handhelds. Compared to previous Madden NFL games, the AI has been boosted and can now hurry in two-minute drill situations, spike the ball, and cover the receivers with better efficiency. The handheld versions did not have NFL licensing, so the NFL was removed from the title, and they were released as Madden 96. In addition to the 16-bit console and portable versions, a DOS version was also released under the title of Madden NFL Football: Limited Edition in 1996.', 'https://en.wikipedia.org/wiki/Madden_NFL_%2796'),
  ('Q2709518', 'In 1994, Konami developed and published two different platform games of the same name, Animaniacs, based on the cartoon series of the same name: one for the Super Nintendo Entertainment System (SNES), and another for the Sega Mega Drive/Genesis. The latter was ported to the Game Boy by Factor 5 in 1995. The Game Boy version has a unique soundtrack if played on the Super Game Boy accessory, and is one of the few games to take full advantage of the accessory.', 'https://en.wikipedia.org/wiki/Animaniacs_(video_game)'),
  ('Q2709557', 'Dragon Ball Z: Super Butōden 2 is a 1993 fighting video game developed by Tose and published by Bandai for the Super Nintendo Entertainment System. Based upon Akira Toriyama''s Dragon Ball franchise, it is the sequel to Dragon Ball Z: Super Butōden, which was released earlier in 1993 for SNES. Following the Cell Games arc and a side-story about characters from the films Dragon Ball Z: Broly – The Legendary Super Saiyan and Dragon Ball Z: Bojack Unbound, its gameplay remains relatively the same as the original Super Butōden, consisting of one-on-one fights using a main six-button configuration, featuring special moves as well as three playable modes.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_Super_But%C5%8Dden_2'),
  ('Q1999554', 'King of the Monsters is a 1991 fighting game developed and published by SNK for the Neo Geo arcade and home platforms. The game features playable giant monsters that are reminiscent of characters from kaiju and tokusatsu films.

In 1992, a sequel titled King of the Monsters 2 was released for arcades. Months later, King of the Monsters was ported to the Super Nintendo Entertainment System. It would then be ported to the Sega Genesis in 1993. It was included in the compilation SNK Arcade Classics Vol. 1, which was released for the Wii, PlayStation 2 and PlayStation Portable in 2008.', 'https://en.wikipedia.org/wiki/King_of_the_Monsters_(video_game)'),
  ('Q3285270', 'Strike Gunner S.T.G is a 1991 vertically scrolling shooter video game developed by Athena and published by Tecmo. It was released in Japan and North America in April 1991.

A port was released for the Super Nintendo Entertainment System in 1992; apart from aspect-ratio changes, it also incorporated Mode 7 effects. The European version was released (by Activision) under the title Super Strike Gunner.

Hamster Corporation acquired the rights to the game alongside Athena''s catalogue, releasing the game as part of the Arcade Archives series for the Nintendo Switch and PlayStation 4 in September 2023.', 'https://en.wikipedia.org/wiki/Strike_Gunner_S.T.G'),
  ('Q1196400', 'Mega Man X is a 1993 platform game developed and published by Capcom for the Super Nintendo Entertainment System. It was the first Mega Man game for the 16-bit console and the first game in the Mega Man X series, a spin-off of the original Mega Man series that began on the Super NES''s predecessor, the Nintendo Entertainment System. The game takes place a century after the original Mega Man series, and is set in a futuristic world populated by both humans and "Reploids", robots capable of thinking, feeling, and growing like their human creators. Because of these complex attributes, many Reploids are prone to destructive, renegade activity and are thereafter referred to as "Mavericks". The plot of the game follows the protagonist X, the last creation of Dr. Light and an android member of a military task force called the "Maverick Hunters". With the help of his partner Zero, the last creation of Dr. Wily, X must stop Sigma, a powerful Maverick leader, from taking over Earth and committing genocide against humanity.', 'https://en.wikipedia.org/wiki/Mega_Man_X_(video_game)'),
  ('Q3282001', 'Pac-Attack, also known as Pac-Panic, is a 1993 tile-matching puzzle video game developed and published by Namco for the Super Nintendo Entertainment System. Versions for the Sega Genesis, Game Boy, Game Gear, and Philips CD-i were also released. The player is tasked with clearing out blocks and ghosts without them stacking to the top of the playfield — blocks can be cleared by matching them in horizontal rows, while ghosts can be cleared by placing down a Pac-Man piece that can eat them. It is the first Pac-Man game to be released exclusively for home platforms.

Pac-Attack is an adaptation of the 1992 game Cosmo Gang the Puzzle, which was released for arcades worldwide and for the Super Famicom in Japan. Music was composed by Hiromi Shibano, and the cover art was designed by Greg Martin. To promote the game''s release, a contest was held in GameFan magazine that awarded cash prizes to players who submitted their highest scores.', 'https://en.wikipedia.org/wiki/Pac-Attack'),
  ('Q1197149', 'Terranigma is a 1995 action role-playing game developed by Quintet for the Super Nintendo Entertainment System (SNES), with manga artist Kamui Fujiwara acting as the character designer. The game tells the story of the Earth''s resurrection by the hands of a boy named Ark, and its progress from the evolution of life to the present day. The game is the third entry in an unofficial trilogy of action role-playing games created by Quintet, including Soul Blazer (1992) and Illusion of Gaia (1993). The game has been met with critical acclaim for its presentation, gameplay, and story, while being criticized for its difficulty.', 'https://en.wikipedia.org/wiki/Terranigma'),
  ('Q219804', 'Zombies Ate My Neighbors is a 1993 run and gun video game developed by LucasArts and published by Konami for the Super Nintendo Entertainment System and Sega Genesis. The player controls the protagonists Zeke and Julie in order to rescue the titular neighbors from monsters often seen in horror films. Aiding them in this task are a variety of weapons and power-ups that can be used to battle the numerous enemies in each level. Various elements and aspects of horror movies are referenced in the game with some of its more violent content being censored in various territories such as Europe and Australia, where it is known only as Zombies.', 'https://en.wikipedia.org/wiki/Zombies_Ate_My_Neighbors'),
  ('Q2656776', 'Live A Live is a 1994 role-playing video game developed and published by Square for the Super Famicom. A remake was published by Square Enix in Japan and Nintendo worldwide, being released first for Nintendo Switch in 2022, and the following year for PlayStation 4, PlayStation 5, and Windows. The game follows seven distinct scenarios scattered across different time periods, with two more unlockable scenarios linking the narratives together through the recurring antagonist Odio. Gameplay is split between exploration with story-specific twists, and turn-based combat played out on a grid.

Production began in late 1993, and was the directorial debut of Takashi Tokita. Tokita wanted to tell multiple stories within a single game, with each section drawing inspiration from different sources. Character designs for the seven main scenarios were handled by different manga artists. The music was composed by Yoko Shimomura as her first large-scale project after joining Square.', 'https://en.wikipedia.org/wiki/Live_A_Live'),
  ('Q2637335', 'Lufia & the Fortress of Doom, known as Estpolis Denki in Japan, is a role-playing video game developed by Neverland and published by Taito in 1993, for the Super Nintendo Entertainment System. It is the first title in the Lufia series of video games and the only game from the series released under the Taito label in North America.

The game''s plot follows The Hero, Lufia, Aguro, and Jerin on a quest to prevent the resurrection of four superpowered beings called Sinistrals, and frequently delves into the political and personal lives of the subjects of kingdoms all around the world. Top-down exploration is mixed with traditional turn-based combat using 2D sprites. The game was generally well-received, and has spawned multiple sequels on the Super Nintendo as well as the Game Boy Color, Game Boy Advance and the Nintendo DS.', 'https://en.wikipedia.org/wiki/Lufia_%26_the_Fortress_of_Doom'),
  ('Q3285722', 'Super Strike Eagle is a 1993 combat flight simulation video game for the Super Nintendo Entertainment System. It was later released in Japan as F-15 Super Strike Eagle.

The game involves flying airplanes that tests the player''s Sidewinder missile and machine gun firing skills against various non-aligned nations that were historically notorious for housing extremist leaders during the Cold War. The game was released in North America, Europe, and Japan approximately simultaneously. In the Japanese version, real political flags are not used unlike the North American version.', 'https://en.wikipedia.org/wiki/Super_Strike_Eagle'),
  ('Q1197521', 'Puzzle Bobble, released internationally as Bust-A-Move, is a 1994 tile-matching puzzle video game developed and published by Taito for arcades. It is a spin-off of the 1986 arcade game Bubble Bobble, featuring characters and themes from that game. Its characteristically cute Japanese animation and music, along with its play mechanics and level designs, made it successful as an arcade title and spawned several sequels and ports to home systems.', 'https://en.wikipedia.org/wiki/Puzzle_Bobble'),
  ('Q1200598', 'Desert Strike: Return to the Gulf is a shoot ''em up video game released by Electronic Arts (EA) in 1992 for the Sega Genesis. The game was released on several other formats such as the Super Nintendo Entertainment System, including a much upgraded version for the Amiga home computer. The game was inspired by the Gulf War and depicts a conflict between an insane Middle Eastern dictator, General Kilbaba, and the United States. The player controls an Apache helicopter and attempts to destroy enemy weapons and installations, rescue hostages and capture enemy personnel, while managing supplies of fuel and ammunition.', 'https://en.wikipedia.org/wiki/Desert_Strike'),
  ('Q2062867', 'California Games II is a sports video game released by Epyx for MS-DOS in 1990. Versions were published for the Amiga, Atari ST, and Super Nintendo Entertainment System in 1992, then the Master System in 1993. This game is a sequel to California Games. An Atari Lynx version was announced and previewed in several magazines but was never released.', 'https://en.wikipedia.org/wiki/California_Games_II'),
  ('Q3280284', 'Super Bomberman 4 is an action-party video game developed by Produce and published by Hudson Soft. It was developed for the Super Famicom, released on April 26, 1996, in Japan. Part of the Bomberman franchise, it is the fourth installment of the Super Bomberman series.

The story begins at an unknown time after Super Bomberman 3. Bagular''s brain escaped the explosion of his flying saucer and has summoned the Four Bomber Kings and Great Bomber to get revenge on White and Black Bomber. The two, along with other fellow Bombermen, are sent hurtling back in time to fight through different eras and ultimately stop Bagular.', 'https://en.wikipedia.org/wiki/Super_Bomberman_4'),
  ('Q267368', 'U.N. Squadron, released in Japan as Area 88, is a 1989 side-scrolling shooter video game developed and published by Capcom for arcades. It was based on the manga series of the same name, though the North American release omits all references to the manga. Their mission is to stop a terrorist group known as Project 4. It was ported to multiple platforms including the Super Nintendo Entertainment System and was followed by a spiritual successor, Carrier Air Wing.', 'https://en.wikipedia.org/wiki/U.N._Squadron'),
  ('Q2081774', 'Super Baseball 2020 is a 1991 baseball video game developed by Pallas and published by SNK for the Neo Geo arcade and home platforms. It was ported to the Neo Geo AES console a month after its release, followed by ports for the Sega Genesis and Super Nintendo Entertainment System in 1993. The North American Genesis and European Mega Drive versions feature a package illustration by Electronic Arts artist Marc Ericksen.

The gameplay and rules build upon its predecessors Baseball Stars Professional and Baseball Stars with futuristic upgrades befitting of the year 2020 AD, including robot players and technological upgrades for the humans, including powerful armor, computer sensors, jet-packs.', 'https://en.wikipedia.org/wiki/Super_Baseball_2020'),
  ('Q3279162', 'Super Bomberman 5 is a 1997 action maze video game developed and published by Hudson Soft. It is the fifth installment of the Super Bomberman series and the final Bomberman game to be released on the Super Famicom. The game was released in two variations: a standard cartridge and a gold cartridge, which was sold through CoroCoro Comic. The gold cartridge included extra maps in battle mode.', 'https://en.wikipedia.org/wiki/Super_Bomberman_5'),
  ('Q3281949', 'WWF Raw is a professional wrestling video game based on the television show of the same name produced by the World Wrestling Federation (WWF), released for the SNES, 32X, Mega Drive/Genesis, Game Boy, and Game Gear in late 1994 and early 1995 by Acclaim Entertainment. It is the sequel to the WWF Royal Rumble game that was released in 1993, and is the final part of LJN''s 16-bit WWF trilogy. Players can play either One-on-One, Tag Team, Bedlam, Survivor Series, Royal Rumble, or a Raw Endurance Match. Unlike its predecessor, WWF RAW is multitap compatible.

WWF RAW introduces differences between the characters in that they not only have their own signature moves, but differing move sets altogether (including new over-the-top "mega moves"). The game adds many moves not seen in the previous games, such as a DDT, a fallaway slam, and various types of suplexes. Additionally, wrestlers differ in attributes of speed, strength, stamina, and weight.', 'https://en.wikipedia.org/wiki/WWF_Raw_(1994_video_game)'),
  ('Q1321249', 'Final Fight 2 is a 1993 beat ''em up game released by Capcom for the Super Nintendo Entertainment System. It is the direct sequel to the 1989 arcade game Final Fight, which was previously also released for the SNES. Final Fight 2 was developed by Capcom''s consumer division with no preceding coin-op version. The game was re-released onto Wii''s Virtual Console service in 2009 worldwide.

Unlike the SNES version of the first game, Final Fight 2 supports two-player simultaneous play and has a total of three playable characters. The only playable character from the first game to return is Mike Haggar. Two new player characters were introduced: Carlos Miyamoto and Maki Genryusai. In the game''s plot, the three battle the resurgent Mad Gear gang at various locations around Asia and Europe to rescue Maki''s sister and father, who are also the fiancée and teacher respectively of Guy from the first Final Fight.', 'https://en.wikipedia.org/wiki/Final_Fight_2'),
  ('Q257469', 'Another World is a cinematic platform action-adventure game designed by Éric Chahi and published by Delphine Software in November 1991. In North America it was published as Out of This World. The game tells the story of Lester, a young scientist who, as a result of an experiment gone wrong, finds himself on a dangerous alien world where he is forced to fight for his survival.

Another World was developed by Chahi alone over a period of about two years, with help with the soundtrack from Jean-François Freitas. Chahi developed his own game engine, creating all the game''s art and animations in vector form to reduce memory use, with some use of rotoscoping to help plan out character movements. Both narratively and gameplay-wise, he wanted the game to be told with little to no language or user-interface elements. The game was originally developed for the Amiga and Atari ST but has since been widely ported to other contemporary systems, including home and portable consoles and mobile devices. Chahi has since overseen release of various anniversary releases of the game.', 'https://en.wikipedia.org/wiki/Another_World_(video_game)'),
  ('Q2151598', 'Pit-Fighter is a 1990 fighting game developed and published by Atari Games for arcades. The Japanese release was published by Konami. Home versions were published by Tengen.

The game uses digitized live actors captured through a bluescreen process, where the various poses and moves were performed by actors in front of a video camera. The game''s on-screen character animation is replays of the actual footage, not a rotoscoped (redrawn) animation. Pit-Fighter is the second fighting game to use digitized sprites, after Home Data''s Reikai Dōshi: Chinese Exorcist.', 'https://en.wikipedia.org/wiki/Pit-Fighter'),
  ('Q2083777', 'Pitfall: The Mayan Adventure is a 1994 action-platform video game developed by Activision in conjunction with Kroyer Films. The fourth installment in the Pitfall! franchise, players assume the role of Pitfall Harry Jr. as he embarks on a journey through the Mayan jungles of Central America in an attempt to rescue Pitfall Harry, his father and the protagonist of previous entries in the series, from the evil Mayan warrior spirit Zakelua. Its gameplay mainly consists of action and platforming mixed with stage-based exploration using a main six-button configuration.

Pitfall: The Mayan Adventure began its development on the Super Nintendo Entertainment System and formed part in a string of planned franchise revivals by Activision along with other games from the Atari 2600 such as Kaboom! and River Raid. It featured sprite-based visuals before Kroyer Films was brought to assist in its creation by providing hand-drawn animations and graphics instead, while the lead platform transitioned from the Super NES to Sega Genesis. The Genesis and Super NES versions were both released during the 1994 holiday shopping season, and ports for the 32X, Atari Jaguar, PC, and Sega CD followed in 1995, with each one being developed by third-party developers and featuring several changes and additions compared to the original version. Years later it was re-released through download services such as Virtual Console and given a portable release on the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Pitfall:_The_Mayan_Adventure'),
  ('Q3280556', 'Power Rangers Zeo: Battle Racers is a Super NES racing video game released in 1996 by Bandai.

The game was based on the Zeo generation of Power Rangers. It features Mode 7 graphics. The game allows for two-player or single-player split screen racing or battle mode.', 'https://en.wikipedia.org/wiki/Power_Rangers_Zeo:_Battle_Racers'),
  ('Q3278677', 'Shaq Fu is a 1994 fighting game developed by Delphine Software International and published by Electronic Arts for the Sega Genesis and Super Nintendo Entertainment System. Versions for the Game Gear, Game Boy, and Amiga followed in 1995. Professional basketball player Shaquille O''Neal is the player character.

Shaq Fu was met with mixed responses from critics upon release, though it has since come to be considered one of the worst video games ever made. A sequel, Shaq Fu: A Legend Reborn, was released in 2018.', 'https://en.wikipedia.org/wiki/Shaq_Fu'),
  ('Q3281420', 'Mighty Morphin Power Rangers: The Fighting Edition is a 2D competitive fighting video game based on the Mighty Morphin Power Rangers television series that was released exclusively for the Super Nintendo Entertainment System developed by Natsume Co., Ltd. and published by Bandai in 1995. Unlike previous Power Rangers video games, which had the player controlling the titular heroes, the player controls their giant robots (known as Zords) in this title. A bootleg Genesis port is known to exist, though who actually made it is currently unknown.', 'https://en.wikipedia.org/wiki/Mighty_Morphin_Power_Rangers:_The_Fighting_Edition'),
  ('Q2169654', 'ActRaiser 2 is a side-scrolling platform game for the Super Nintendo Entertainment System developed by Quintet and published by Enix in 1993.

The game is a sequel to the original ActRaiser, but the storyline is not directly connected to its predecessor. Otherwise, the given story draws concepts from the famous religious epics Paradise Lost and the Divine Comedy.

Unlike the original game, which alternately combined platform game sequences and god game sequences, ActRaiser 2 is only a platform game.', 'https://en.wikipedia.org/wiki/ActRaiser_2'),
  ('Q1326889', 'Star Fox, known as Starwing in PAL regions, is a 1993 rail shooter game developed by Nintendo EAD and Argonaut Software, and published by Nintendo for the Super Nintendo Entertainment System (SNES). The first entry in the Star Fox series, the story follows pilot Fox McCloud and his elite squadron of mercenaries known as the Star Fox team defending their homeworld of Corneria against the invading forces of the malevolent mad scientist Andross.

It was the second 3D Nintendo game after X for the Game Boy in 1992, and the first Nintendo game to use polygonal graphics, achieved with the Super FX graphics chip included in the cartridge. At the time, the complex display of three-dimensional models using polygons was uncommon in console games.', 'https://en.wikipedia.org/wiki/Star_Fox_(1993_video_game)'),
  ('Q2186293', 'The Aquatic Games Starring James Pond and the Aquabats, also known as The Super Aquatic Games Starring the Aquabats on the Super NES, is a 1992 sports video game developed by Vectordean and published by Millennium Interactive. It featured pseudo-Olympic sports starring the video game character James Pond, better known for his series of side-scrolling platform games. It was the last game to be released for the Amiga A500. Though the next game (James Pond 3: Operation Starfish) also appeared on the Amiga, it was only compatible with the newer range of 32-bit Amigas (such as the A1200) which used the AGA chipset.', 'https://en.wikipedia.org/wiki/The_Aquatic_Games'),
  ('Q1313980', 'Ultimate Mortal Kombat 3 is a 1995 fighting game developed and published by Midway for arcades. Part of the Mortal Kombat series, it is a standalone update of 1995''s earlier Mortal Kombat 3 with an altered gameplay system and some new features, as well as additional characters like the returning favorites Reptile, Kitana, Jade, and Scorpion, who were missing from Mortal Kombat 3.

Several home port versions of the game were soon released after the arcade original. Although none were completely identical to the arcade version, the Nintendo DS port came closest. Other versions followed, with some released under different titles, such as Mortal Kombat Advance (2001) for the Game Boy Advance. An iOS version recreating the game using a 3D graphics engine was released by Electronic Arts in 2010.', 'https://en.wikipedia.org/wiki/Ultimate_Mortal_Kombat_3'),
  ('Q2158049', 'PGA Tour Golf is a golf video game and the first in the PGA Tour game series. It was developed by Sterling Silver Software and released in 1990 for MS-DOS. It was initially published by Electronic Arts, which subsequently released versions of the game for Sega Genesis and Amiga in 1991, followed by a version for the SNES in 1992. By 1994, Tengen had published versions for Sega''s Master System and Game Gear consoles. PGA Tour Golf received generally positive reviews for its realism, sound, and camera. Several critics considered the computer versions to be the best golf game available at the time of its release. It was followed by PGA Tour Golf II.', 'https://en.wikipedia.org/wiki/PGA_Tour_Golf'),
  ('Q254723', 'Cannon Fodder is a 1993 shoot ''em up video game developed by Sensible Software and published by Virgin Interactive Entertainment for the Amiga. Virgin later ported the game to MS-DOS, Atari ST, Acorn Archimedes, Atari Jaguar, Mega Drive, Super NES and 3DO. The game is military-themed and based on shooting action with squad-based tactics. The player directs troops through numerous missions, battling enemy infantry, vehicles, and installations.

Cannon Fodder has a darkly humorous tone which commentators variously praised and condemned. Its creators intended it to convey an anti-war message, which some reviewers recognised, but the Daily Star and a number of public figures derided the game. Other reviewers highly praised the game, which widely achieved scores of over 90% in Amiga magazines. Amiga Action awarded it an unprecedented score, calling it the best game of the year. It was followed by the sequel Cannon Fodder 2 in 1994.', 'https://en.wikipedia.org/wiki/Cannon_Fodder_(video_game)'),
  ('Q3281960', 'Super Famicom Wars is an enhanced remake of Famicom Wars developed by Intelligent Systems and released for the Super Famicom on May 1, 1998, exclusively via the Nintendo Power service in commemoration of the tenth anniversary of the original Family Computer version.', 'https://en.wikipedia.org/wiki/Super_Famicom_Wars'),
  ('Q2198073', 'Ultima: Runes of Virtue II is a 1993 video game developed by Origin Systems for the Game Boy and Super Nintendo Entertainment System and published by Pony Canyon and FCI. The game is the sequel to the 1991 Game Boy title of the same name and the second Ultima game to be released on a handheld console. Upon release, the game received average reviews, with critics praising the additions, including new animations, larger scope, and cutscenes, as an improvement to the previous game, but found the visual presentation of the game to be lacking.', 'https://en.wikipedia.org/wiki/Ultima:_Runes_of_Virtue_II');

insert into import_summary (wikidata_id, summary, source) values
  ('Q2741882', 'Addams Family Values is a 1995 action-adventure game based on the 1993 film of the same name, developed and published by Ocean Software for the Super NES (in North America and Europe) and Mega Drive (in Europe only).', 'https://en.wikipedia.org/wiki/Addams_Family_Values_(video_game)'),
  ('Q2297364', 'Teenage Mutant Ninja Turtles: Turtles in Time, released as Teenage Mutant Hero Turtles: Turtles in Time in Europe, is a 1991 beat ''em up game developed and published by Konami for arcades. A sequel to the original Teenage Mutant Ninja Turtles arcade game, it is a side-scrolling game based mainly on the 1987 TMNT animated series. Originally an arcade game, Turtles in Time was ported to the Super Nintendo Entertainment System in 1992 under the title Teenage Mutant Ninja Turtles IV: Turtles in Time, continuing the numbering from the earlier Turtles games released on the original NES. That same year, a game that borrowed many elements, Teenage Mutant Ninja Turtles: The Hyperstone Heist, was released for the Sega Genesis.', 'https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles:_Turtles_in_Time'),
  ('Q1511144', 'SimEarth: The Living Planet is a life simulation game, the second designed by Will Wright, published in 1990 by Maxis. In SimEarth, the player controls the development of a planet. English scientist James Lovelock served as an advisor and his Gaia hypothesis of planet evolution was incorporated into the game. Versions were made for the Macintosh, Atari ST, Amiga, IBM PC, Super Nintendo Entertainment System, Sega CD, and TurboGrafx-16. It was re-released for the Wii Virtual Console in 2009. In 1996, several of Maxis'' simulation games were re-released under the Maxis Collector Series with greater compatibility with Windows 95 and differing box art, including the addition of Classics beneath the title. SimEarth was re-released in 1997 under the Classics label.', 'https://en.wikipedia.org/wiki/SimEarth'),
  ('Q2743913', 'King of the Monsters 2 is a 1992 fighting game developed and published by SNK for the Neo Geo arcade and home platforms. It is a sequel to the 1991 game King of the Monsters. In this game, three of the previous game''s surviving monsters return and battle across the globe against giant alien monsters that threaten the Earth. The game was later ported to the Super NES and Sega Genesis by Takara.', 'https://en.wikipedia.org/wiki/King_of_the_Monsters_2'),
  ('Q1405093', 'Top Gear 3000, later released in Japan as The Planet''s Champ: TG3000, is a racing video game developed by Gremlin Interactive and published by Kemco for the Super Nintendo Entertainment System. It is the third game in the original Top Gear trilogy, and the last in the series to be developed by Gremlin. 3000 heavily resembles the previous Top Gear 2, but is set in the distant future.', 'https://en.wikipedia.org/wiki/Top_Gear_3000'),
  ('Q1442104', 'The Duel: Test Drive II is a 1989 racing video game developed by Distinctive Software and published by Accolade for Amiga, Amstrad CPC, Apple IIGS, Commodore 64, Macintosh, MS-DOS, MSX, ZX Spectrum, Atari ST, Sega Genesis and SNES.', 'https://en.wikipedia.org/wiki/The_Duel:_Test_Drive_II'),
  ('Q275122', 'Super Ghouls ''n Ghosts, known as Chō Makaimura in Japan, is a 1991 platform video game developed and published by Capcom for the Super Nintendo Entertainment System. The third installment in the Ghosts ''n Goblins series and the first not to be released for arcades, it again depicts knight Arthur saving Princess Guinevere and the kingdom from Emperor Sardius, who has cast a spell that has revived the Ghoul Realm.

The game has been included in multiple compilations of Capcom classics. A remake was released for the Game Boy Advance which features an additional game mode with new stages.', 'https://en.wikipedia.org/wiki/Super_Ghouls_%27n_Ghosts'),
  ('Q1557589', 'Mr. Do! is a 1982 maze video game developed and published by Universal Entertainment for arcades. It is the first arcade video game to be released as a conversion kit for other cabinets; Taito published the conversion kit in Japan. The game was inspired by Namco''s Dig Dug, released earlier in 1982. Mr. Do! was a commercial success in Japan and North America, selling 30,000 arcade units in the US, and it was followed by several arcade sequels.', 'https://en.wikipedia.org/wiki/Mr._Do!'),
  ('Q2736832', 'Lethal Enforcers is a 1992 light gun shooter video game developed and published by Konami for arcades. The graphics consist entirely of digitized photographs and digitized sprites. Home console versions were released for the Super NES, Sega Genesis, and Sega CD, and include a revolver-shaped light gun known as the Justifier.

The game was a critical and commercial success, becoming one of the top five highest-grossing dedicated arcade games of 1993 in the United States. However, it also caused controversy as it allowed players to shoot photorealistic representations of enemies. Lethal Enforcers was followed by Lethal Enforcers II: Gun Fighters. Both games would later be released in the two-in-one compilation Lethal Enforcers I & II (Lethal Enforcers Deluxe Pack in Japan) for the PlayStation. Years later, Konami released the Police 911 series as a Japan-themed sequel to the original plot. This was also followed by the arcade game Heroes of Justice, which was localized and renamed as Lethal Enforcers 3 for Western audiences.', 'https://en.wikipedia.org/wiki/Lethal_Enforcers'),
  ('Q284064', 'Stunt Race FX, known in Japan as Wild Trax, is a racing video game developed by Nintendo and Argonaut Software and published by Nintendo for the Super Nintendo Entertainment System. It is the second game to use the 3D-centric Super FX powered GSU-1.

Stunt Race FX was added to the Nintendo Classics service on September 5, 2019, its first re-release in more than two decades.', 'https://en.wikipedia.org/wiki/Stunt_Race_FX'),
  ('Q3334222', 'NBA All-Star Challenge is a video game for the Super NES, the Game Boy, and the Sega Genesis.', 'https://en.wikipedia.org/wiki/NBA_All-Star_Challenge'),
  ('Q2716211', 'Yoshi''s Safari is a 1993 light gun shooter developed and published by Nintendo for its Super Nintendo Entertainment System (SNES). It is the only Mario franchise game to feature first-person shooter gameplay and requires the SNES''s Super Scope, a light gun. As Mario and his pet dinosaur Yoshi, the player embarks on a quest to save the kingdom of Jewelry Land from Bowser and his Koopalings, who have kidnapped its rulers and stolen 12 gems. The game features 12 levels in which the player shoots enemies like Goombas and Koopas, and collects power-ups and coins. At the end of each level, the player engages in a boss fight with an enemy, a Koopaling, or Bowser. Nintendo commissioned its R&D1 department to develop Yoshi''s Safari in response to the waning popularity of the Super Scope. Yoshi''s Safari was the first Super Scope title to use the SNES''s Mode 7 graphics mode, and the future of the peripheral depended on the game''s performance.', 'https://en.wikipedia.org/wiki/Yoshi%27s_Safari'),
  ('Q2746048', 'E.D.F.: Earth Defense Force is a 1991 horizontally scrolling shooter video game developed and published by Jaleco for arcades. It was ported to the Super Nintendo Entertainment System as Super Earth Defense Force, dropping the two-player cooperative gaming mode while adding graphics and selectable weapons. The Super NES version was released in Japan on October 25, 1991, and in North America in January 1992. The Super NES version was eventually released on the Wii Virtual Console in Europe on October 29, 2010, and in 2011 for Japan on January 11, and North America on July 14. It was released on the Nintendo Classics service in September 2019.', 'https://en.wikipedia.org/wiki/Earth_Defense_Force_(video_game)'),
  ('Q3312139', 'Taz-Mania is the name of several video games based on the Taz-Mania cartoon series. A 2D side-scrolling platform/adventure video game developed by Recreational Brainware and published by Sega on the Sega Mega Drive/Genesis in 1992. Different games were also developed by NuFX and released on the Game Gear and by Technical Wave on the Master System. Other different Taz-Mania games were also published by Sunsoft in North America and by THQ in PAL territories and released on the SNES and 2 games on the Game Boy were made too. One from David A. Palmer Productions and published by Sunsoft and another one called Taz-Mania 2 from Beam Software and published by THQ.', 'https://en.wikipedia.org/wiki/Taz-Mania_(video_game)'),
  ('Q1385731', 'Eye of the Beholder is a role-playing video game for personal computers and video game consoles developed by Westwood Associates. It was published by Strategic Simulations, Inc. in 1991, for the MS-DOS operating system and later ported to the Amiga, the Sega CD and the Super NES. The Sega CD version features a soundtrack composed by Yuzo Koshiro and Motohiro Kawashima. A port to the Atari Lynx handheld was developed by NuFX in 1993, but was not released. In 2002, an adaptation of the same name was developed by Pronto Games for the Game Boy Advance.

The game has two sequels: the first was Eye of the Beholder II: The Legend of Darkmoon, which was also released in 1991; after Westwood Studios was acquired by Virgin Interactive in 1992, Eye of the Beholder III: Assault on Myth Drannor was released in 1993. The third game, however, was not developed by Westwood, who instead went on to create the Lands of Lore series.', 'https://en.wikipedia.org/wiki/Eye_of_the_Beholder_(video_game)'),
  ('Q2721899', 'Top Gear is a 1992 racing video game developed by Gremlin Graphics and published by Kemco for the Super Nintendo Entertainment System. The objective of the game is to become the fastest driver in the world by racing other drivers across several nations.

It marks the first game in the Top Gear racing game franchise, and it is one of the first racing games to be released on the SNES. This game and its next two sequels were created by the same developers as the similar Lotus series of games was released earlier on the Amiga and Mega Drive.', 'https://en.wikipedia.org/wiki/Top_Gear_(video_game)'),
  ('Q2273067', 'FIFA International Soccer (also known as FIFA 94) is a 1993 association football video game developed by EA Canada''s Extended Play Productions team and published by EA Sports. The game was released for the Sega Mega Drive/Genesis console in December 1993 and ported to numerous other systems in 1994. It is the first game in the FIFA series.

The game was positively received by critics upon release; critics lauded the detail and animation of the footballers in the game, the crowd sound effects, and the overall presentation. The speed the game ran at and issues with the response to the player''s input were seen as the game''s primary faults. The 3DO version added multiple camera views and more detailed graphics than other versions. The game sold well, with the Mega Drive version becoming the best-selling home video game of 1993 in the United Kingdom. It later served as a pack-in game for the Goldstar 3DO, and led to a sequel, FIFA Soccer 95.', 'https://en.wikipedia.org/wiki/FIFA_International_Soccer'),
  ('Q1408193', 'Ardy Lightfoot is a 2D side-scrolling platform game released on the Super Nintendo Entertainment System in 1993 in Japan and 1994 in the west. It was developed by ASCII and published by Titus France in North America and Europe.', 'https://en.wikipedia.org/wiki/Ardy_Lightfoot'),
  ('Q1486269', 'Gods is a platform game by The Bitmap Brothers released for the Amiga and Atari ST in 1991. The player is cast as Hercules in his quest to achieve immortality. It was ported to the Acorn Archimedes, Genesis/Mega Drive, PC98, Super Nintendo Entertainment System, and Atari Jaguar.', 'https://en.wikipedia.org/wiki/Gods_(video_game)'),
  ('Q2723021', 'Treasure of the Rudras is a Japanese role-playing game released by Square in 1996, and the company''s last developed game for the Super Famicom.

The plot incorporates elements from Indian religions, centrally the concept of the wheel of time - every 4000 years the world is destroyed and recreated by a Rudra - the name taken from an aspect of the Hindu god of destruction, Shiva. With several races of beings already eradicated and replaced, the story takes place during the final 15 days before humans are scheduled to be wiped out as well; this forces the four main characters who were chosen by fate - Sion, Surlent, Riza, and Dune - to go on a quest to avert the scenario whilst uncovering the source of it all.', 'https://en.wikipedia.org/wiki/Treasure_of_the_Rudras'),
  ('Q1527988', 'Darius Force, known as Super Nova in North America, is a horizontal scrolling shooter for the Super Famicom/SNES, released in 1993 and is part of the Darius series.', 'https://en.wikipedia.org/wiki/Darius_Force'),
  ('Q1587638', 'Dungeon Master is a role-playing video game featuring a pseudo-3D first-person perspective. It was developed and published by FTL Games for the Atari ST in 1987, almost identical Amiga and PC (DOS) ports following in 1988 and 1992.

Dungeon Master sold 40,000 copies in its year of release alone, and went on to become the ST''s best-selling game of all time. The game was an influential early example of the first-person party-based dungeon crawler genre, with later examples including Eye of the Beholder (1991).', 'https://en.wikipedia.org/wiki/Dungeon_Master_(video_game)'),
  ('Q2269596', 'Populous II: Trials of the Olympian Gods is a strategy video game and the sequel to the 1990 game Populous. It was developed by Bullfrog Productions for the Amiga, Atari ST, and MS-DOS and published by Electronic Arts in 1991. A Mega Drive version, converted by PanelComp, was published as Two Tribes: Populous II in 1993 by Virgin Games.

Like its predecessor, Populous II is a god game, where the player is guiding their people in battle against the followers of an enemy god. Whereas Populous only generally alluded to undefined deities, Populous II is specifically set under the backdrop of Greek mythology. The player is a demigod, one of Zeus''s countless children with mortal women, and has to battle one Greek deity at a time until finally facing his father. Zeus has promised to let the player into the Pantheon on Olympus if he can survive all the battles.', 'https://en.wikipedia.org/wiki/Populous_II:_Trials_of_the_Olympian_Gods'),
  ('Q3307249', 'Metal Warriors is a side-scrolling action-platform run and gun video game developed by LucasArts and published by Konami exclusively for the Super Nintendo Entertainment System in North America in April 1995. It is often confused by many to be a direct sequel to Cybernator, which was created by NCS Corporation and released earlier in 1992 on the console. Set in the year 2102 where dictator Venkar Amon has waged a war against the United Earth Government for three years, players assume the role of lieutenant Stone from the titular freedom-fighting group taking control of several mecha suits in a last-ditch effort to overthrow the Dark Axis military force on Earth. Its gameplay mainly consists of action and shooting mixed with mission-based exploration using a main seven-button configuration.', 'https://en.wikipedia.org/wiki/Metal_Warriors'),
  ('Q3308280', 'Michael Jordan: Chaos in the Windy City is a platform video game developed and published by Electronic Arts for the Super Nintendo Entertainment System. The game was released in North America in November 1994 and in Europe by Ocean Software in 1995. A Sega Genesis version was planned but never released.', 'https://en.wikipedia.org/wiki/Michael_Jordan:_Chaos_in_the_Windy_City'),
  ('Q3312023', 'Micro Machines 2: Turbo Tournament is a 1994 racing video game developed by Supersonic Software and published by Codemasters for the Sega Mega Drive. The sequel to Micro Machines, the game is themed around Galoob''s Micro Machines toys, and players race around environments in miniature toy vehicles. Micro Machines 2: Turbo Tournament adds new vehicles and game modes, and the Mega Drive version was released on J-Cart, enabling up to eight players without a multitap.

Development began after the release of the Mega Drive version of the original, and there was a focus on graphics and driving physics. Violet Berlin of Bad Influence! makes a cameo appearance as a new character. Codemasters did not develop the game because the programmer of the first Micro Machines was not available, though they did develop the Game Gear and Game Boy versions. Micro Machines 2: Turbo Tournament was ported to various systems, including the Game Gear and MS-DOS, the latter of which features a track editor. The MS-DOS version is the only version of the game released in North America, where it was published by GameTek. An update, Micro Machines Turbo Tournament ''96, was released for the Mega Drive in 1995, which added the track editor, new race tracks, and a new soundtrack.', 'https://en.wikipedia.org/wiki/Micro_Machines_2:_Turbo_Tournament'),
  ('Q1545458', 'Syndicate is an isometric real-time tactics and strategic game from Bullfrog Productions created in 1993, and initially released for MS-DOS and the Amiga. It is the first game in the Syndicate series. Set in a dystopian future in which corporations have replaced governments, Syndicate puts the player in control of a corporation vying for global dominance.

The game consists of a series of missions in which the player controls a team of cybernetically modified agents attempting to take control of a particular country. The agents must frequently overcome local police forces and heavily armed agents from rival syndicates to achieve mission objectives, which range from assassinations to capture or rescue of personnel. Agent armaments, cybernetic modifications and behavioral attributes can be controlled by the player to make them more suited for particular tasks.', 'https://en.wikipedia.org/wiki/Syndicate_(1993_video_game)'),
  ('Q3334265', 'NCAA Final Four Basketball is a sports video game developed by Bitmasters and published by Mindscape for the Sega Genesis and SNES.', 'https://en.wikipedia.org/wiki/NCAA_Final_Four_Basketball'),
  ('Q1445705', 'Dragon Ball Z: Hyper Dimension is a 1996 fighting video game developed by Tose and published by Bandai for the Super Nintendo Entertainment System. Based upon Akira Toriyama''s Dragon Ball franchise, it is the last fighting game in the series to be released for SNES. Following from the Frieza saga to the conclusion of the Majin Buu saga, its gameplay is similar to the earlier Butōden entries, consisting of one-on-one fights using a main six-button configuration, featuring special moves as well as multiple game modes.

Dragon Ball Z: Hyper Dimension was created over the course of 15 months by most of the same team who worked on the previous three Super Butōden entries for Super Nintendo, with producers Takeo Isogai and Toshihiro Suzuki returning to helm its production, alongside staff from both Toei Animation and V Jump magazine assisting with its development. Hyper Dimension garnered positive reception from critics, but the European version received criticism for its absence of a story mode. The game has never been officially released outside Japan and Europe, although fan translations exist.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_Hyper_Dimension'),
  ('Q3334247', 'NBA Showdown is a 1993 basketball video game developed by EA Creative Development and published by EA Sports for the Super Nintendo Entertainment System. The game is a sequel to Bulls vs. Blazers video game. The game was re-released for the Sega Genesis/Mega Drive as NBA Showdown ''94. It is the fifth and final game in the NBA Playoffs series of games, before the series was rebranded as NBA Live.', 'https://en.wikipedia.org/wiki/NBA_Showdown_(video_game)'),
  ('Q2748343', 'Spider-Man and the X-Men in Arcade''s Revenge is a video game released for the Super NES in 1992 by LJN. It was released for the Genesis and Game Gear (under the Flying Edge brand) as well as the Game Boy. The game features Marvel Comics characters Spider-Man and the X-Men as they battle their captor, the villainous Arcade, to escape his death trap, Murderworld.', 'https://en.wikipedia.org/wiki/Spider-Man_and_the_X-Men_in_Arcade%27s_Revenge'),
  ('Q2748421', 'Striker is a soccer video game series first released by Rage Software in 1992. The game was released for the Amiga, Amiga CD32, Atari ST, PC, Mega Drive, and Super Nintendo Entertainment System. It was bundled in one of the Amiga 1200 launch packs. It was one of the first soccer games to feature a 3D viewpoint, after Simulmondo''s I Play 3D Soccer.

In 1993 it was released in Japan by Coconuts Japan for the Super Famicom as World Soccer, while the French Super NES version of Striker is known as Eric Cantona Football Challenge, playing on the popularity of French forward Eric Cantona, while the North American Super NES release of Striker was known as World Soccer ''94: Road to Glory.', 'https://en.wikipedia.org/wiki/Striker_(video_game)'),
  ('Q369264', 'Super Bomberman 3 is a game released for the Super Nintendo Entertainment System in 1995. It is the third installment in the Super Bomberman series, and the third Bomberman game to be released for the system. Up to five players can play at the same time. The game was released in Japan and the PAL region, but not in North America due to the closure of Hudson Soft USA.', 'https://en.wikipedia.org/wiki/Super_Bomberman_3'),
  ('Q343033', 'ActRaiser is a 1990 video game developed by Quintet and published by Enix for the Super Nintendo Entertainment System. It combines traditional side-scrolling platforming and sections with city building elements. A sequel, ActRaiser 2, was released for the Super NES in 1993. In 2007, ActRaiser became available on the Wii''s Virtual Console download service in Europe, North America, and Japan. A version of the game was also released for European mobile phones in 2004. A remake, Actraiser Renaissance, was released for several platforms in 2021.', 'https://en.wikipedia.org/wiki/ActRaiser'),
  ('Q2751109', 'Kid Klown in Crazy Chase is a platform video game developed and published by Kemco for the Super Nintendo Entertainment System. It was released in North America in September 1994, Japan on October 21, 1994 and in Europe in 1995. The game features the Kid Klown, the player character who is tasked with rescuing the Princess Honey from the villain Black Jack. Players view gameplay from an isometric perspective as Kid Klown pursues a lit fuse in order to stop it from reaching a spade bomb. The game was re-released for the Game Boy Advance as Crazy Chase and features 11 new levels and four mini-games. The re-release was released in Europe and North America in October 2002, while a release in Japan was planned but ultimately canceled. It was met with mixed reception from critics, who found it to be inferior to other games of its type. The game has a Japan-exclusive sequel Kid Klown in Crazy Chase 2: Love Love Hani Soudatsusen released for the Sony PlayStation in 1996.', 'https://en.wikipedia.org/wiki/Kid_Klown_in_Crazy_Chase'),
  ('Q2140297', 'Rock n'' Roll Racing is a vehicular combat-based racing video game developed by Silicon & Synapse and published by Interplay Productions for the Super Nintendo Entertainment System in 1993 and the Mega Drive/Genesis in 1994. The game prominently features a number of popular heavy metal and rock songs in its soundtrack, hence the game''s title. After Silicon & Synapse rebranded into Blizzard Entertainment, a port to the Game Boy Advance was released in 2003. In celebration of the company''s 30th anniversary, a new version titled Definitive Edition alongside emulated re-releases of the original game were re-released for Nintendo Switch, PlayStation 4, Windows, and Xbox One as part of the Blizzard Arcade Collection in February 2021.', 'https://en.wikipedia.org/wiki/Rock_n%27_Roll_Racing'),
  ('Q2748662', 'Mighty Morphin Power Rangers: The Movie is the title of four different video game adaptations of the film of the same name which were released for the Super NES, Genesis, Game Boy, and Game Gear. While the games are ostensibly based on the film, they also feature characters and plot elements from the second season of the original TV series. Like the previous game versions of the original Mighty Morphin Power Rangers, none of the four versions of the movie game are ports of each other.', 'https://en.wikipedia.org/wiki/Mighty_Morphin_Power_Rangers:_The_Movie_(video_game)'),
  ('Q2116167', 'F1 ROC: Race of Champions, released in Japan and Europe as Exhaust Heat, is a 1992 racing video game developed by SETA Corporation for the Super Nintendo Entertainment System.

The following year, the game was followed up with F1 ROC II: Race of Champions.', 'https://en.wikipedia.org/wiki/F1_ROC:_Race_of_Champions'),
  ('Q1634991', 'Operation Thunderbolt is a 1988 light gun shooter video game developed and published by Taito for arcades. As the sequel to Operation Wolf, changes include two-player gameplay with two positional gun controllers mounted on the arcade cabinet, and a new forward-scrolling pseudo-3D perspective combined with side-scrolling sections.

The arcade game was a commercial success and was one of the top three highest-grossing dedicated arcade games of 1989 in both Japan and the United States. Versions were released for Amiga, Commodore 64, and Super Nintendo Entertainment System. The arcade-exclusive sequel Operation Wolf 3 was released in 1994.', 'https://en.wikipedia.org/wiki/Operation_Thunderbolt_(video_game)'),
  ('Q2112232', 'Judge Dredd is a side-view action video game released for the Super NES, Mega Drive/Genesis, Game Gear, and Game Boy, originally in 1995. An MS-DOS version was published in 1996. The game is based on the 1995 film Judge Dredd, which was itself an adaptation of the Judge Dredd strip from 2000AD.

The game was released on Steam and ZOOM Platform as Judge Dredd 95 by Throwback Entertainment. It was delisted by its publisher on January 1, 2023, a move that was criticized by ZOOM Platform.', 'https://en.wikipedia.org/wiki/Judge_Dredd_(1995_video_game)'),
  ('Q3334369', 'NFL Quarterback Club is an American football video game for multiple platforms that features quarterbacks from the NFL. It is the first game in Acclaim Entertainment''s NFL Quarterback Club series.

The first game to use the name was a Game Boy title developed by Beam Software and released under Acclaim''s LJN brand in 1993 that was a simulation of the NFL Quarterback Challenge. The following year, Acclaim and LJN released a new multiplatform title under the same name, adding options to play full team games under NFL rules, while retaining the Quarterback Challenge mode. The game was released for the Super NES, Genesis and Game Gear. A Game Boy version, called NFL Quarterback Club II and a 32X version were released in 1995. Both these versions omitted the Quarterback Challenge mode, a trend that would continue with NFL Quarterback Club 96.', 'https://en.wikipedia.org/wiki/NFL_Quarterback_Club_(video_game)'),
  ('Q2881443', 'Ballz 3D (originally subtitled Fighting at Its Ballziest in North America and The Battle of the Balls in Europe) is a 1994 fighting game developed by PF.Magic and published by Accolade for the Sega Genesis and Super Nintendo Entertainment System, with a 3DO version being released as a director''s cut in 1995. The game offers three difficulty levels over a total of 21 matches. Its distinguishing quality was that each of the characters were composed completely of spheres, giving the game a pseudo-3D look. Although the game was not a major success, it was generally well-received by critics, and PF.Magic reused its graphics technology in the Petz line of virtual pet titles (Dogz, Catz and Oddballz).', 'https://en.wikipedia.org/wiki/Ballz'),
  ('Q2757541', 'Mr. Nutz is a 2D side-scrolling platform game published by Ocean Software. It was released for the Super Nintendo Entertainment System in late 1993 in Europe and in North America and Japan in 1994. In 1994, it was released for the Mega Drive as Ocean''s first Sega game, and on the Game Boy. It was also released on the Sega Channel in 1995, the Game Boy Color in 1999, and remade for the Game Boy Advance in 2001.

The player controls the one player character, Mr. Nutz, an anthropomorphic red squirrel through six themed levels. The end goal is to stop Mr. Blizzard, a yeti, who is trying to take over the world by using his magic powers to turn it into a mass of ice. Ammunition, in the form of nuts, can be collected and thrown at enemies.', 'https://en.wikipedia.org/wiki/Mr._Nutz'),
  ('Q3342399', 'No Escape is a video game developed by Bits Studios and published by Psygnosis for the Sega Genesis and by Sony Imagesoft for the Super Nintendo Entertainment System, based on the 1994 film of the same name.', 'https://en.wikipedia.org/wiki/No_Escape_(video_game)'),
  ('Q430868', 'True Golf Classics: Wicked 18 is a golf video game originally released by T&E Soft in 1993 for the Super Famicom in Japan and by Bullet-Proof Software for the Super NES in North America. A version was later released for the 3DO Interactive Multiplayer and the Mega Drive. The game takes place on a very difficult otherworldly golf course. It is part of the True Golf Classics series, but unlike other games such as Pebble Beach and Waialae Country Club, which portray actual golf courses, Wicked 18 portrays an entirely fictitious golf course.', 'https://en.wikipedia.org/wiki/True_Golf_Classics:_Wicked_18'),
  ('Q2881009', 'Ball Bullet Gun is a 1995 tactical role-playing game released by I''MAX for the Super Famicom. It features airsoft battles with about 50 different weapons and seven different fields, including forests and offices.', 'https://en.wikipedia.org/wiki/Ball_Bullet_Gun'),
  ('Q2903390', 'Bill Walsh College Football is an American football video game released for the Super NES, Genesis, and Sega CD. It is one of the earliest video games to deal with the sport at a college level and is built around the fame of coach Bill Walsh. The game was followed by a sequel, Bill Walsh College Football ''95.', 'https://en.wikipedia.org/wiki/Bill_Walsh_College_Football'),
  ('Q2814018', 'The Mask is a 1995 side-scrolling action video game developed and published by THQ subsidiary Black Pearl Software for the Super Nintendo Entertainment System which is based on the film of the same name. The film, in turn, was loosely based on the Dark Horse comic book series of the same name.

The game received moderately positive reviews from critics, who were particularly pleased with its faithful recreation of the humor and visual style of the film, while criticizing the level design and difficulty.', 'https://en.wikipedia.org/wiki/The_Mask_(video_game)'),
  ('Q2789389', 'James Pond 3: Operation Starfish (stylized as Operation Starfi5h, after the fictional secret service F.I.5.H) is a 1993 video game for Mega Drive, Amiga and Amiga CD32, Super NES and Game Gear. It is the third and last game in the James Pond series. It is also the only one that was only released for AGA Amigas: the Amiga 1200, Amiga 4000 and CD32.

The game''s working title was James Pond 3: Splash Gordon, a play on Flash Gordon. Although it enjoyed good sales, it was not as well received as other games in the series.', 'https://en.wikipedia.org/wiki/James_Pond_3'),
  ('Q2906318', 'Sky Mission is a 1992 combat flight simulation video game developed by Malibu Interactive and published by Namco for the Super Nintendo Entertainment System. In North America, the game was rebranded as the sequel to the Commodore Amiga game Wings, which was developed by the developer''s predecessor Cinemaware, titled Wings 2: Aces High, while in Europe it was renamed to Blazing Skies. As the leader of a British plane squadron during World War I, the player is tasked with destroying enemy planes under the command of German emperor Kaiser Wilhelm II in France. Gameplay involves gunning down enemies and performing bombing runs on enemy bases. The game was produced by Ken Lobb, best known as the co-creator of the Killer Instinct fighting game series, with music composed by musician George Sanger. Sky Mission was met with a mixed reaction from critics — although it was disliked for its short length and lacking gameplay, it was praised for its realistic visuals, soundtrack and sense of thrill.', 'https://en.wikipedia.org/wiki/Sky_Mission'),
  ('Q3342057', 'Super Scope 6, known as Nintendo Scope 6 in Europe and Australia, is a shooter video game developed by Nintendo and Intelligent Systems and published by Nintendo for the Super Nintendo Entertainment System. The game was bundled with the Super Scope for the Super NES. As the name suggests, the cartridge contains six games that require the Super Scope to play.', 'https://en.wikipedia.org/wiki/Super_Scope_6'),
  ('Q389254', 'Super Castlevania IV is a 1991 platform game developed and published by Konami for the Super Nintendo Entertainment System. It has been re-released multiple times, including for the Super NES Classic Edition.

Super Castlevania IV features expanded play control, 16-bit graphics featuring Super NES''s Mode 7, and a soundtrack featuring new pieces and arrangements based on previous Castlevania music. Following the same story as Castlevania on the NES, the game takes place in 1691 Transylvania, where the vampire hunter Simon Belmont must defeat the vampire Dracula. The game received critical acclaim, with praise for its gameplay, soundtrack, and visual style, and has since been considered one of the greatest video games ever made.', 'https://en.wikipedia.org/wiki/Super_Castlevania_IV'),
  ('Q2887292', 'Bass Masters Classic is a 1995 fishing video game developed by Chicago-based studio Black Pearl Software. It was developed with the help of the Bass Anglers Sportsman Society.', 'https://en.wikipedia.org/wiki/Bass_Masters_Classic'),
  ('Q3334421', 'NHL 95 (also known as NHL Hockey 95) is an ice hockey video game published by EA Sports. It was released in 1994 for the Super Nintendo Entertainment System and the Sega Genesis. The team rosters and player attributes in the game reflect that of the 1994–95 NHL season.', 'https://en.wikipedia.org/wiki/NHL_95'),
  ('Q524267', 'Frogger is a 1981 action video game developed by Konami and published by Sega for arcades. It was released in North America by Sega/Gremlin. The object of the game is to direct five frogs to their homes by dodging traffic on a busy road, then crossing a river by jumping on floating logs, turtles, and alligators.

Frogger was positively received by critics upon its release, and is considered one of the greatest video games ever made. It was followed by numerous clones and several home-only sequels in the Frogger series. By 2005, 20 million copies of its various home video game incarnations had been sold worldwide.', 'https://en.wikipedia.org/wiki/Frogger'),
  ('Q3339129', 'Newman/Haas IndyCar featuring Nigel Mansell, released in Japan as Nigel Mansell Indy Car and in South America as Newman/Haas IndyCar Estrelando Nigel Mansell, is an IndyCar racing video game developed by Gremlin Graphics and published by Acclaim Entertainment, which was released in 1994 for the Super NES and Sega Genesis/Mega Drive.', 'https://en.wikipedia.org/wiki/Newman/Haas_IndyCar_featuring_Nigel_Mansell'),
  ('Q2887296', 'Bass Masters Classic: Pro Edition is an enhanced version of Bass Masters Classic, released for both the Super Nintendo Entertainment System and Sega Genesis. As a promotional tool, an introductory offer to join the Bass Anglers Sportsman Society for $14 (instead of the usual $20) was bundled with the game.', 'https://en.wikipedia.org/wiki/Bass_Masters_Classic:_Pro_Edition'),
  ('Q388247', 'Might and Magic III: Isles of Terra is the third game in the role-playing video game series Might and Magic. Released in 1991, it is the predecessor to Might and Magic IV: Clouds of Xeen and the sequel to Might and Magic II: Gates to Another World. A Sega Genesis version was developed, but never released.

This was the last installment in the series to be released for the Amiga, Mac OS, Sega CD, TurboGrafx-CD and Super NES.', 'https://en.wikipedia.org/wiki/Might_and_Magic_III:_Isles_of_Terra'),
  ('Q3334422', 'NHL 96 is a sports video game developed by EA Tiburon for the Super NES, High Score Entertainment for the Genesis, EA Canada for MS-DOS, and Probe Entertainment for the Game Boy. EA Sports published all versions of the game in 1995, except the Game Boy version, which was published by THQ. The game is based on the sport of ice hockey and puts the player in control of a hockey team in modes of play such as exhibitions, seasons and playoffs. It is the fifth installment in the NHL game series.

NHL 96 is the first entry in the series with real-time three-dimensional graphics through the MS-DOS version''s "Virtual Stadium" technology. The game also has improved and adjustable opponent artificial intelligence, a previously barred ability to engage in physical fights, new moves such as the spin-o-rama, and general enhancements to the visual animations and audio. NHL 96 was met with critical acclaim, with reviewers commending the game''s opponent AI, fluid graphics, and added gameplay features.', 'https://en.wikipedia.org/wiki/NHL_96'),
  ('Q2904717', 'Alien vs Predator is a 1993 beat ''em up video game for Super Nintendo Entertainment System, developed by Jorudan and published by Information Global Service in Japan and by Activision internationally. An arcade game of the same title was released by Capcom eight months later, but the two games are different and their storylines are unrelated to each other.', 'https://en.wikipedia.org/wiki/Alien_vs_Predator_(SNES_video_game)'),
  ('Q2756952', 'Super Tennis is a 1991 tennis video game developed by Tose and published by Tonkin House for the Super Nintendo Entertainment System. Nintendo localized the game and released it outside Japan. It utilizes mode 7 graphics.', 'https://en.wikipedia.org/wiki/Super_Tennis'),
  ('Q1807798', 'Plok! is a 1993 platform game developed by Software Creations and published by Nintendo for the Super Nintendo Entertainment System (SNES). The player controls the hood-headed titular protagonist, the king of the island Akrillic, who is defending it from fleas spawned by the Flea Queen, hidden beneath the island''s surface, as well as other bosses attempting to usurp Plok''s power. Plok''s versatility lies in his four detachable limbs, which can be used to attack targets and enemies, along with various power-ups scattered throughout the game''s colorful stages, referred to as "presents".

The history of Plok! began in the late 1980s as a self-funded coin-op project by Ste and John Pickford called Fleapit. They developed it while working at Zippo Games and programmed it for Rare''s ''Razz Board'' hardware. The project was canceled in 1990 following the closure of Zippo Games, but was later revived as an SNES game developed at Software Creations after the Pickfords were promoted to higher positions, with Ste becoming an art director and John a producer. Software Creations self-funded the game, with the Pickfords retaining ownership of its intellectual property rights. A port for the Mega Drive was planned, but was canceled for unknown reasons.', 'https://en.wikipedia.org/wiki/Plok!'),
  ('Q2841430', 'David Crane''s Amazing Tennis is a 1992 tennis video game published by Absolute Entertainment for the Super Nintendo Entertainment System and Sega Genesis consoles. The game was also made available for the Nintendo Super System. The SNES version got a worldwide release, while the Genesis version only saw a North American release.

The game was designed by an expert in the sport, as the titular David Crane was an avid tennis player. He had played tournaments as well as playing in doubles with Activision co-founder Alan Miller, but stated he never had interest in developing a tennis-themed game until then.', 'https://en.wikipedia.org/wiki/David_Crane%27s_Amazing_Tennis'),
  ('Q2846258', 'Andre Agassi Tennis is a tennis video game released in 1993, starring tennis legend Andre Agassi. The game was released for the Super Nintendo Entertainment System, Genesis, Master System, and Game Gear. It enjoyed a much belated release for mobile phones.', 'https://en.wikipedia.org/wiki/Andre_Agassi_Tennis'),
  ('Q2316943', 'Tetris Attack, also known as Panel de Pon in Japan, is a 1995 puzzle video game developed by Intelligent Systems and published by Nintendo for the Super Nintendo Entertainment System. A Game Boy version was released a year later. In the game, the player must arrange matching colored blocks in vertical or horizontal rows to clear them. The blocks steadily rise to the top of the playfield, with new blocks being added at the bottom. Several gameplay modes are present, including a time attack and multiplayer mode.

Tetris Attack was first released as Panel de Pon in Japan in October 1995, featuring fairies as the main characters with a mythical fantasy setting. The game was released outside Japan in 1996, with the original characters and settings replaced by those from Super Mario World 2: Yoshi''s Island. Though international releases have the name Tetris Attack, the game bears no relation to the Tetris video game series, leading Tetris Company co-founder Henk Rogers to regret giving Nintendo the license to use the name. Both Panel de Pon and Tetris Attack were later broadcast through the Japan-only Satellaview peripheral, the latter renamed to BS Yoshi''s Panepon.', 'https://en.wikipedia.org/wiki/Tetris_Attack'),
  ('Q1827675', 'Harley''s Humongous Adventure is a 1993 platform video game developed by Visual Concepts for the Super Nintendo Entertainment System. It was originally funded by publisher Electronic Arts, but eventually published by Hi Tech Expressions.', 'https://en.wikipedia.org/wiki/Harley%27s_Humongous_Adventure'),
  ('Q595860', 'The Incredible Hulk is a 1994 video game released for the Mega Drive, Master System, Game Gear, and SNES. Developed by Probe Software and published by U.S. Gold, the game is based on the Marvel Comics superhero Hulk and showcases him within the context of a side-scrolling action game with platforming and beat ''em up elements. The narrative involves the Hulk attempting to thwart the world domination bid of his nemesis, the Leader, while engaging in combat with other arch-rivals.

The gameplay incorporates a number of fighting moves for the Hulk to execute, and includes moments where his human alter-ego, Bruce Banner, must emerge to access areas that the Hulk is too large to reach. The scenario was created by two journalists from the magazine Mean Machines, and development took place over the course of 18 months. The game received mixed reviews upon release, with critics praising the visuals, music, and variety of moves while criticizing the controls and lack of enemy variety.', 'https://en.wikipedia.org/wiki/The_Incredible_Hulk_(1994_video_game)'),
  ('Q1785007', 'Push-Over is a puzzle-platform game developed by Red Rat Software and published by Ocean Software in 1992 for the Amiga, Atari ST, MS-DOS, and the Super Nintendo Entertainment System. The game was sponsored by Smiths'' British snack Quavers (now owned by Walkers), and the plot revolves around the then Quavers mascot Colin Curly losing his Quavers packets down a giant ant hill. The player is tasked with controlling G.I. Ant, a large soldier ant, to recover the Quavers by solving a series of puzzles. The Super NES version lacks the Quavers branding, and instead the aim is to recover bundles of cash dropped down the ant hill by Captain Rat.', 'https://en.wikipedia.org/wiki/Push-Over_(video_game)'),
  ('Q1853282', 'Jammit is a video game for the Sega Genesis, Super NES, 3DO, and MS-DOS. It was developed by GTE ImagiTrek Studios and published in 1994.', 'https://en.wikipedia.org/wiki/Jammit'),
  ('Q2876628', 'B.O.B. (known in Japan as Space Funky B.O.B.) is a run and gun video game for the Genesis and Super Nintendo Entertainment System. It was published by Electronic Arts in 1993. A sequel, B.O.B. II, was in development but never released.', 'https://en.wikipedia.org/wiki/B.O.B._(video_game)'),
  ('Q2860688', 'Arcus Odyssey is a 1991 action game developed by Wolf Team and released by Renovation Products for the Sega Genesis and X68000 and in 1993 for the Super Nintendo Entertainment System. The game features an isometric perspective and cooperative gameplay with hack and slash elements. It tells the story of four heroes trying to thwart the return of an evil sorceress.

Arcus Odyssey is part of the Arcus franchise, that also included Arcus in 1988, Arcus II: Silent Symphony in 1989, and Arcus III in 1991. A North American version for the SNES was planned, but it was cancelled following Sega''s acquisition of Renovation Products (American publisher for Wolf Team and Telenet games). It was released only in Japan with the title Arcus Spirits, and was also planned to be released in Europe by Loriciels.', 'https://en.wikipedia.org/wiki/Arcus_Odyssey'),
  ('Q2332991', 'Metal Max 2 is the second entry in the Metal Max series. It is a vehicle combat RPG published in Japan by Data East in 1993 for the Super Famicom. Ten years later, the game was ported to the Game Boy Advance with a few new bounties by Now Production under the title Metal Max 2 Kai. In December 2011, a full remake with upgraded graphics in the vein of Metal Max 3 and using its game engine was released in Japan for the Nintendo DS and titled Metal Max 2 Reloaded.', 'https://en.wikipedia.org/wiki/Metal_Max_2'),
  ('Q1851017', 'International Superstar Soccer is a 1994 football video game developed and published Konami for the Super Nintendo Entertainment System. It is the first title in the International Superstar Soccer (ISS) series of sports video games. It was initially released in Japan for the Super Famicom in 1994, and also in North America and Europe for the SNES in 1995. The game sold over 500,000 copies since its first week of release.', 'https://en.wikipedia.org/wiki/International_Superstar_Soccer_(video_game)'),
  ('Q1800173', 'Secret of Mana, originally released in Japan as Seiken Densetsu 2, is a 1993 action role-playing game developed and published by Square for the Super Nintendo Entertainment System. It is the sequel to the 1991 game Seiken Densetsu, released in North America as Final Fantasy Adventure and in Europe as Mystic Quest. Secret of Mana was the first Seiken Densetsu title to be marketed as part of the Mana series rather than the Final Fantasy series. Set in a high fantasy universe, the game follows three heroes as they attempt to prevent an empire from conquering the world with the power of an ancient flying fortress.', 'https://en.wikipedia.org/wiki/Secret_of_Mana'),
  ('Q1854477', 'Urban Strike (subtitled The Sequel to Jungle Strike) is a video game developed and published by Electronic Arts. It was initially released for the Sega Genesis in 1994, with ports handled by Black Pearl Software to the Super Nintendo Entertainment System and Game Gear in 1995 and to the Game Boy in 1996. It is the third game in the Strike series, after Desert Strike: Return to the Gulf and Jungle Strike.', 'https://en.wikipedia.org/wiki/Urban_Strike'),
  ('Q2857370', 'Pinkie is a 1994 platform video game developed by Data Design Interactive and originally published by Millennium Interactive for the Amiga. A Super Nintendo Entertainment System version was released by Piko Interactive in 2017. In the game, the player takes on the role of Pinkie, who is tasked with collecting eggs throughout the galaxy to prevent the extinction of the Pinkie dinosaur race. The player controls Pinkie and his "Pinkie Pod" vehicle across 50 levels featuring a variety of enemies and obstacles divided into five planets. The Pinkie Pod can perform various actions, and the player can obtain upgrades to augment its features.', 'https://en.wikipedia.org/wiki/Pinkie_(video_game)'),
  ('Q582662', 'Super Bonk (released in Europe as Super B.C. Kid and in Japan as Super Genjin) is a 1994 platform video game developed by A.I. Co, Ltd. and published by Hudson Soft for the Super Nintendo Entertainment System. It is the fourth game in the Bonk series.', 'https://en.wikipedia.org/wiki/Super_Bonk'),
  ('Q1848990', 'Shadowrun is a cyberpunk-fantasy action role-playing video game for the Super Nintendo Entertainment System, adapted from the tabletop role-playing game Shadowrun by FASA. The video game was developed by Australian company Beam Software and first released in 1993 by Data East.

The game is loosely based on the novel Never Deal with a Dragon by Shadowrun co-creator Robert N. Charrette and set in the year 2050. The player takes on the role of Jake Armitage, a man suffering from amnesia after having been critically wounded by assassins. The plot then follows Jake as he attempts to uncover his own identity and the identity of the mysterious figure who wants him dead, and eventually complete his mission. Harebrained Schemes'' 2013 Shadowrun Returns links the stories of this game and of Shadowrun for the Sega Genesis.', 'https://en.wikipedia.org/wiki/Shadowrun_(1993_video_game)'),
  ('Q1773728', 'Super Double Dragon is a beat ''em up video game developed and published by Technōs Japan for the Super Nintendo Entertainment System. It was released by Tradewest in North America the same year and the PAL region in 1993. Super Double Dragon is the fourth console game in the Double Dragon series developed by Technōs Japan, following Double Dragon III: The Sacred Stones for the NES. The game did not have an arcade release and was made specifically for the home market.

In 2018, a slightly enhanced Japanese version, Return of Double Dragon, was re-released by Tommo in Japan and under its Retroism brand in North America. Despite being officially licensed, this release is only guaranteed to work on third-party hardware.', 'https://en.wikipedia.org/wiki/Super_Double_Dragon'),
  ('Q1809250', 'Mario Paint is a 1992 art creation video game developed by Nintendo Research & Development 1 (R&D1) and Intelligent Systems and published by Nintendo for the Super Nintendo Entertainment System. Mario Paint consists of a raster graphics editor, an animation program, a music composer, and a point and click minigame, all of which are designed to be used with the Super NES Mouse peripheral, which the game was packaged and sold with. Per its name, the game is Mario-themed, and features sprites and sound effects that are taken from or in the vein of Super Mario World.

Mario Paint sold very well following its release and is one of the best-selling SNES games, with over 2.3 million copies sold. The game was released to fairly positive contemporaneous reviews; critics highlighted its accessibility, features, innovative design, and educational potential, but criticized limitations on creation that rendered it unviable for serious creation. Retrospective reviews have been more positive, praising the game as "memorable", "addictive", "unique", and "ingenious", and it has been deemed one of the best SNES games of all time. Mario Paint''s music composer in particular has been used to create original songs, covers, and remixes using the game''s sounds and limitations.', 'https://en.wikipedia.org/wiki/Mario_Paint'),
  ('Q2827341', 'Aguri Suzuki F-1 Super Driving, released as Redline F-1 Racer in North America, is a Formula One racing simulator game for the Super Nintendo Entertainment System and Game Boy. The game is named after and sponsored by the Japanese Formula 1 driver, Aguri Suzuki; his likeness and imagery were retained in the North American version despite the name change.', 'https://en.wikipedia.org/wiki/Aguri_Suzuki_F-1_Super_Driving'),
  ('Q607073', 'NHL ''94 is an ice hockey game by EA Sports released for the Genesis, Super NES. and MS-DOS in 1993, then the Sega CD in 1994. The MS-DOS version is titled NHL Hockey, without the "''94" in the title. It is the third game in the NHL series and the first in the series to be officially licensed by both the National Hockey League (NHL) and the NHL Players'' Association (NHLPA). NHL ''94 launched to critical acclaim. It is often considered among the greatest sports video games and is widely considered the greatest hockey game of all time.', 'https://en.wikipedia.org/wiki/NHL_%2794'),
  ('Q3388790', 'Disney''s Pinocchio is a platform puzzle adventure game created as a collaboration between Disney Interactive and Virgin Interactive Entertainment. It was released in 1996 for the Game Boy, Super NES, and Sega Genesis, and is based on the 1940 Disney animated film Pinocchio. The game was published by Capcom in Japan on the same year. A Sega 32X version of the game was made and completed, but was not released due to the add-on''s limited popularity.', 'https://en.wikipedia.org/wiki/Pinocchio_(video_game)'),
  ('Q3386242', 'Venom/Spider-Man: Separation Anxiety is a 1995 beat ''em up video game and a sequel to Spider-Man and Venom: Maximum Carnage, released for Mega Drive/Genesis and Super NES and then ported to PC. One or two players team up as Spider-Man and Venom to defeat the evil symbiote Carnage. The game boasts many thugs that the player has to defeat: heavily armed Jury and Venom''s symbiote children. There is also cameo assistance from Captain America, Ghost Rider, Hawkeye, and Daredevil.

The SNES and Genesis versions were re-released as part of the compilation Marvel MaXimum Collection in 2026.

The game received mediocre reviews, being criticized largely for its repetitiveness, unoriginality and lack of cutscenes.', 'https://en.wikipedia.org/wiki/Venom/Spider-Man:_Separation_Anxiety'),
  ('Q3496985', 'Star Trek: Deep Space Nine – Crossroads of Time is a 1995 action-adventure video game for the Genesis and Super NES platforms, based on the television series Star Trek: Deep Space Nine. Critics praised the game''s authentic recreation of the look and feel of the TV series, but often criticized its gameplay as repetitive and clunky.', 'https://en.wikipedia.org/wiki/Star_Trek:_Deep_Space_Nine_%E2%80%93_Crossroads_of_Time'),
  ('Q3525730', 'Whilst merchandise for The Railway Series books by Wilbert Awdry was produced alongside the books, since the original broadcast of its television adaptation Thomas & Friends in 1984 in the United Kingdom, much more merchandise was produced for the television series. Large numbers of manufacturers have sought to produce items based on the Thomas & Friends franchise after the original television series was broadcast in the United States and Japan.

The most popular and wide-ranging merchandise are models of the characters, some including accompanying railway systems. Other popular products include videos, books and magazines, computer and video games, audiobooks, annuals, colouring and activity books, jigsaw puzzles, board games, stationery, clothing, cutlery, household items such as curtains, duvet covers and lampshades and soft drinks.', 'https://en.wikipedia.org/wiki/The_Railway_Series_and_Thomas_%26_Friends_merchandise'),
  ('Q634300', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q3397941', 'Popful Mail: Magical Fantasy Adventure is a 1991 action-adventure platform video game developed and published by Nihon Falcom for the PC-8801. It was later ported to the PC-9801 and Super Famicom by Falcom, to the Sega CD by Sega and Sega Falcom, to the PC Engine Super CD-ROM² by NEC Home Electronics and HuneX, and to DoJa mobile phones by Bothtec.

Most versions of Popful Mail are for the most part similar to each other, but the Sega CD and Super Famicom versions differ significantly both from each other and from the other releases. The Sega CD version was going to be reworked even further to be part of Sega''s Sonic the Hedgehog series, but this did not end up happening. This version was localized by Working Designs and released in North America in early 1995, and was the only version available outside Japan prior to July 2024.', 'https://en.wikipedia.org/wiki/Popful_Mail'),
  ('Q619025', 'R-Type III: The Third Lightning is a 1993 side-scrolling shooter video game developed by Tamtex and first released in Japan by Irem in 1993 for the Super Famicom and in North America and Europe in 1994 for the SNES.', 'https://en.wikipedia.org/wiki/R-Type_III:_The_Third_Lightning'),
  ('Q3522153', 'The Pagemaster is a platform game developed by Probe Software and published by Fox Interactive for the Super Nintendo Entertainment System, Game Boy, and Sega Genesis in 1994. It was released in conjunction with the film of the same name.', 'https://en.wikipedia.org/wiki/The_Pagemaster_(video_game)'),
  ('Q2394252', 'PGA Tour is a series of golf video games developed and published by Electronic Arts - and later their EA Sports sub-label - since 1990. The series primarily features courses featured on the U.S. PGA Tour, and other notable courses (such as those that have hosted majors).

In 1998, EA began publishing their golf games with the endorsement of Tiger Woods. Following the Tiger Woods 99 PGA Tour Golf release, subsequent titles were named Tiger Woods PGA Tour and released yearly.

Although EA Sports developed most games in the series internally, some SKUs have come from outside developers including the first edition, Tiger Woods 99 PGA Tour Golf, which Adrenalin Entertainment developed in conjunction with EA for the PlayStation and Tiger Woods PGA Tour 2001 for the PlayStation, which was developed by Stormfront Studios. IOMO also produced versions of the game for mobile phones for the 2002, 2004, and 2005 editions.', 'https://en.wikipedia.org/wiki/PGA_Tour_(video_game_series)'),
  ('Q2425425', 'WildSnake is a puzzle video game inspired by Tetris. Snakes of varying colors and lengths fall from the top of the screen and slither to the bottom. The goal is to clear out the snakes by touching two of the same color. WildSnake was designed by Alexey Lysogorov and presented by Alexey Pajitnov. Game Gear and Sega Genesis versions were planned but never released.', 'https://en.wikipedia.org/wiki/WildSnake'),
  ('Q3528972', 'Timecop is a side-scrolling action video game produced by Cryo Interactive for the Super Nintendo Entertainment System in 1995. It is based on the 1994 film of the same title and takes place after the events of the film. Despite the use of digitized actors to portray the characters in the game, Jean-Claude Van Damme was not used to pose as protagonist Max Walker. Levels range from locales in the past (e.g., New York City during the 1920s, the European front of World War II), the present day, and a dystopian Los Angeles of the distant future.

Although the game was only released for the Super NES, a version was also developed for the Sega CD, with a short demo being distributed in May 1995 alongside the European Sega Pro magazine. Despite being fully completed by the developer, JVC pulled off the Sega CD version publishing and it remained unreleased. In 2007, a complete version of the game was eventually released on the Internet by the Sega CD version coder.', 'https://en.wikipedia.org/wiki/Timecop_(video_game)'),
  ('Q2387100', 'Obitus is an action-adventure game developed and released by Psygnosis in early 1991 for Amiga, Atari ST, and MS-DOS compatible operating systems. A version for the Super Nintendo Entertainment System was published in 1994 by Bullet-Proof Software. The game includes both first-person dungeon crawling and side-scrolling gameplay with action-oriented combat and an emphasis on item acquisition.', 'https://en.wikipedia.org/wiki/Obitus'),
  ('Q2406801', 'ESPN Baseball Tonight is a 1994 baseball video game for the MS-DOS, Sega CD, Sega Genesis, and Super Nintendo Entertainment System.

The cartridge versions was developed by Park Place Productions, while Sony Imagesoft''s internal development team handled development for the Sega CD version amidst troubles at Park Place.', 'https://en.wikipedia.org/wiki/ESPN_Baseball_Tonight'),
  ('Q2440904', 'Super Adventure Island is a 1992 platform game developed by Produce! and published by Hudson Soft for the Super Nintendo Entertainment System. It was the first Adventure Island game released for the SNES and came out between the releases of the NES games Adventure Island II and Adventure Island 3. It was later followed by Super Adventure Island II. The game''s soundtrack was composed by Yuzo Koshiro.

An unrelated game with the same name was released for mobile phones in 2004. This version of Super Adventure Island is a remake of Wonder Boy: Monster Land, which was previously ported to the PC Engine by Hudson as Bikkuriman World.', 'https://en.wikipedia.org/wiki/Super_Adventure_Island'),
  ('Q609155', 'Aerobiz Supersonic, known as Air Management II: Kōkū Ō wo Mezase in Japan, is a business simulation video game released for the Super Nintendo Entertainment System by Koei in North America in August 1994. It was later ported to the Genesis. It is a sequel to Koei''s previous airline simulation game, Aerobiz.', 'https://en.wikipedia.org/wiki/Aerobiz_Supersonic'),
  ('Q610749', 'Mega Man 7 is a 1995 action game developed and published by Capcom for the Super Nintendo Entertainment System (SNES). It is the seventh game in the original Mega Man series. The game was released in Japan on March 24, 1995 and was localized later in the year in North America and Europe.

Picking up 6 months after the events of Mega Man 6, the plot involves the protagonist Mega Man once again attempting to stop the evil Dr. Wily, who uses a new set of Robot Masters to free himself from captivity and begin wreaking havoc on the world. Along with some help from his old friends, Mega Man finds potential allies in the mysterious robot pair Bass and Treble, who are later revealed to be in league with Wily. In terms of gameplay, Mega Man 7 follows the same play style introduced in the 8-bit NES titles, but updates the graphics and sound of the series for the more powerful SNES.', 'https://en.wikipedia.org/wiki/Mega_Man_7'),
  ('Q3532345', 'Torneko''s Great Adventure: Mystery Dungeon is a 1993 role-playing video game by Chunsoft. The first entry in the Mystery Dungeon series, the game features Torneko, a merchant from Dragon Quest IV, and his adventures around the Mystery Dungeon in search of items. 33 years after its Japanese only release, the game received a worldwide release on modern platforms under a remake titled Dragon Quest Heroes: Torneko''s Mystery Dungeon -Classic HD-.

Torneko''s Great Adventure is the first spin-off game in the Dragon Quest franchise. The game was a success with over 800,000 copies sold, which led to Chunsoft turning it into a franchise with the release of a sequel, Mystery Dungeon 2: Shiren the Wanderer, in 1995. The unreleased English version of the game was to be called Mystery Dungeon: Taloon''s Great Adventure.', 'https://en.wikipedia.org/wiki/Torneko%27s_Great_Adventure'),
  ('Q3496990', 'Star Trek: Starfleet Academy – Starship Bridge Simulator is a video game for the Super Nintendo Entertainment System and 32X systems that was released in 1995 by Interplay, the same group that produced many later Star Trek starship games.', 'https://en.wikipedia.org/wiki/Star_Trek:_Starfleet_Academy_%E2%80%93_Starship_Bridge_Simulator'),
  ('Q3496991', 'Star Trek: The Next Generation (subtitled Future''s Past on SNES and Echoes from the Past on Sega Genesis) is a 1994 adventure game developed by Spectrum HoloByte. The game features strategy and puzzle-solving elements. The game was released for the Super Nintendo Entertainment System and Genesis. It takes place in the Star Trek universe, spanning Federation space and the Romulan Neutral Zone, and centers on the appearance of the IFD (Integrated Field Derandomizer), an artifact machine of unknown origin that, as its name suggests, allows its user to reshape matter and energy. It culminates in the IFD Trials, three tests undertaken by representatives of any races that are present when the Trials are held, and failure would mean the destruction of the Federation and the enslavement of countless worlds by the Federation''s enemies.', 'https://en.wikipedia.org/wiki/Star_Trek:_The_Next_Generation_(1994_video_game)'),
  ('Q610138', 'SimAnt: The Electronic Ant Colony is a 1991 life simulation video game by Maxis and the company''s third product, focusing on the lifecycle of ants. It was designed by Will Wright. In 1992, it was named "Best Simulation Game" at the Software Publishers Association''s Codie awards. SimAnt was re-released in 1993 as part of the SimClassics Volume 1 compilation alongside SimCity Classic and SimLife for MS-DOS, Mac and Amiga. In 1996, SimAnt, alongside several of Maxis'' simulation games were re-released under the Maxis Collector Series with greater compatibility with Windows 95 and differing box art, including the addition of Classics beneath the title.', 'https://en.wikipedia.org/wiki/SimAnt'),
  ('Q3529116', 'Tin Star is a 1994 rail shooter video game developed by Software Creations and published by Nintendo for the Super Nintendo Entertainment System (SNES). Starring anthropomorphic robot characters, it follows a seven-day adventure of the titular sheriff who fights the criminal Bad Oil Gang from taking over the town of East Driftwood.

It includes both third and first-person stages, and players can control the reticle either with a standard SNES controller, Super Scope, or the SNES Mouse. It is the third Software Creations game to be published by Nintendo, after Ken Griffey Jr. Presents Major League Baseball (1994) and (only in Europe) Plok! (1993). The game received positive reviews from critics, with praise for the presentation, especially the graphics and humor, but criticism of the monotonous gameplay and lack of challenge.', 'https://en.wikipedia.org/wiki/Tin_Star_(video_game)'),
  ('Q3529218', 'Tintin in Tibet (French: Tintin au Tibet, Spanish: Tintin en el Tibet) is a video game based on the storyline of the same title from the series The Adventures of Tintin, the comics series by Belgian cartoonist Hergé. It was one of a series of two games released, the other being Prisoners of the Sun. It was released for the Super NES in late 1995, followed by versions for the Mega Drive, Game Boy, Game Gear, MS-DOS, and Windows 95 in 1996, and for the Game Boy Color in 2001.', 'https://en.wikipedia.org/wiki/Tintin_in_Tibet_(video_game)'),
  ('Q1661310', 'Indiana Jones'' Greatest Adventures is a 1994 platform video game released for the Super Nintendo Entertainment System. It is a video game adaptation of the Indiana Jones films Raiders of the Lost Ark (1981), Indiana Jones and the Temple of Doom (1984), and Indiana Jones and the Last Crusade (1989). The game was developed by Factor 5 and published by JVC Musical Industries. The story is told through cutscenes and text and is mostly faithful to the movies. Its release coincided with that of Super Star Wars: Return of the Jedi, also released by JVC and LucasArts and in the same platform style as the Super Star Wars trilogy.', 'https://en.wikipedia.org/wiki/Indiana_Jones%27_Greatest_Adventures'),
  ('Q2376909', 'Ultima VII: The Black Gate is the seventh installment of the Ultima series of role-playing video games. It was published in April 1992 for MS-DOS by Origin Systems. The player returns as The Avatar, a would-be paragon of moral virtue who faces down many dangers and deceptions in order to cleanse the medieval fantasy world of Britannia of assorted plots and schemes, monster infestations, and the undermining of crown authority. A Super NES conversion was released in 1994.

The Black Gate was critically acclaimed and commercially successful, being widely lauded as a high point in the series and is also regarded as one of the best video games ever created. In an interview with GameSpot, Richard Garriott stated that Ultima VII "was the most masterfully executed of the Ultima series". He has also often stated that the game was, along with Ultima IV, his own favorite installment overall.', 'https://en.wikipedia.org/wiki/Ultima_VII:_The_Black_Gate'),
  ('Q1658920', 'Illusion of Gaia, known in PAL territories as Illusion of Time, is an action role-playing video game developed by Quintet for the Super Nintendo Entertainment System. The game was released in Japan by Enix in 1993, and in North America and PAL territories by Nintendo in 1994 and 1995. Set in a fantasy reimagining of Earth, the game''s plot centers on a boy named Will who is chosen to save the world from an impending disaster. Throughout the game, the player guides Will through levels inspired by the ancient ruins of real-world civilizations and Wonders of the World, including the Great Pyramid and the Great Wall of China.', 'https://en.wikipedia.org/wiki/Illusion_of_Gaia'),
  ('Q2362159', 'Outlander is an action driving video game with a post-apocalyptic theme. It was developed and published by Mindscape in 1993 for the Sega Genesis and Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Outlander_(video_game)'),
  ('Q3497781', 'Steel Talons is a combat flight simulator arcade video game released by Atari Games in 1991. The player pilots an "AT1196 Steel Talons combat helicopter. The 3D view is rendered with flat-shaded polygons using the TMS34010 combination CPU and programmable graphics processor. It was ported to the Genesis, Lynx, Atari Falcon, and Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Steel_Talons'),
  ('Q3373888', 'True Golf Classics: Pebble Beach Golf Links is a traditional golf simulation video game that was originally released in 1992 for the Super Nintendo Entertainment System. It was eventually released in 1993 to the Sega Genesis and the NEC PC-9801. It is part of T&E Soft''s True Golf series.

The game takes place at the prestigious Pebble Beach Golf Links in Pebble Beach, California.', 'https://en.wikipedia.org/wiki/True_Golf_Classics:_Pebble_Beach_Golf_Links'),
  ('Q2423838', 'Phantom 2040 is an action-adventure platform game published by Viacom New Media in 1995 for the Genesis, Super NES and Game Gear. The game is directly based upon the animated television series Phantom 2040 but follows a plotline not strictly taken by the show. The game has been classified as a metroidvania, and plays similarly to the Metroid and Castlevania series.', 'https://en.wikipedia.org/wiki/Phantom_2040_(video_game)'),
  ('Q2414296', 'Axelay is a 1992 scrolling shooter developed and published by Konami for the Super Nintendo Entertainment System. Set in the fictional solar system Illis where an alien empire known as "Armada of Annihilation" invades its planets including the Earth-like Corliss (Mother), players take control of the titular D117B space fighter craft as a last resort to stop the alien invasion by recovering its lost weaponry. The gameplay mainly consist of both vertical-scrolling and horizontal-scrolling stages in the same vein as Konami''s own Life Force, with players choosing three different weapon-types that increase in number as they progress through the game.', 'https://en.wikipedia.org/wiki/Axelay'),
  ('Q1724425', 'Super Soccer, known in Japanese as Super Formation Soccer, is a football (soccer) video game developed by Human Entertainment for the Super Nintendo Entertainment System (SNES) and published by Human Entertainment in Japan and Nintendo internationally. It was released in Japan in 1991 and in North America and Europe in 1992, being a launch title in Europe. It was included on the Nintendo Classic Mini: Super Famicom released in Japan in October 2017 and was initially re-released worldwide on the Nintendo Classics service in September 2019, but was removed worldwide on March 28, 2025.', 'https://en.wikipedia.org/wiki/Super_Soccer'),
  ('Q3497140', 'Stargate is a 1995 platform game by Acclaim Entertainment for the Super Nintendo Entertainment System and Genesis/Mega Drive. It follows the adventures of Colonel Jack O''Neill as he struggles to free the slaves of Abydos, defeat Ra, and get his mission team back home using the stargate device. The game is based on the 1994 film of the same name.', 'https://en.wikipedia.org/wiki/Stargate_(1995_console_video_game)'),
  ('Q3523014', 'The Tick is a side-scrolling beat ''em up video game developed by Software Creations and published by Fox Interactive for the Super NES and Sega Genesis systems in 1994. It was based on the comic book and Fox Kids animated series of the same name.', 'https://en.wikipedia.org/wiki/The_Tick_(video_game)'),
  ('Q2414743', 'Breath of Fire II is a role-playing video game developed and published by Capcom. First released in 1994, the game was licensed to Laguna for European release in 1996. It is the second entry in the Breath of Fire series. It was later ported to Game Boy Advance and re-released worldwide. The game was released on Wii''s Virtual Console in North America on August 27, 2007. Nintendo of Europe''s website mistakenly announced it for release on July 27, 2007, but it was in fact released two weeks later, on August 10, 2007. In 2013, it was released for the Wii U Virtual Console. In 2016, it was released for the New Nintendo 3DS Virtual Console. In 2019, it was released for the Nintendo Switch SNES games library.', 'https://en.wikipedia.org/wiki/Breath_of_Fire_II'),
  ('Q2440245', 'Shin Kidō Senki Gundam Wing: Endless Duel is a 1996 fighting video game developed by Natsume Co., Ltd. and published in Japan by Bandai for the Super Famicom. It is the first game to be based on the Mobile Suit Gundam Wing anime series. Set in the year After Colony 195, players take control of a pilot from the Colony Liberation Organization or the Organization of the Zodiac. Its gameplay consists of one-on-one fights, with a main four-button configuration, featuring special moves, as well as three playable modes.

Gundam Wing: Endless Duel was released during the boom of fighting games after the launch of Street Fighter II as one of the last titles to appear on the Super Famicom. The game was developed by Tengo Project, a team within Natsume Co., Ltd. who previously developed The Ninja Warriors (1994), Wild Guns and Mighty Morphin Power Rangers: The Fighting Edition (1995). The staff reused the same engine from Power Rangers: The Fighting Edition for Endless Duel but with some improvements.', 'https://en.wikipedia.org/wiki/Shin_Kid%C5%8D_Senki_Gundam_Wing:_Endless_Duel'),
  ('Q2404768', 'Winter Olympics, released in the United States as Winter Olympic Games, is the official video game of the XVII Olympic Winter Games in Lillehammer, Norway. All versions were published by U.S. Gold. It was released in North America in 1993 for the Amiga, Sega Genesis, and IBM PC compatibles. Ports to the Game Gear, Sega Genesis, Master System, and Super Nintendo Entertainment System followed. The game includes 10 winter sporting events. Players can represent countries from all over the world.', 'https://en.wikipedia.org/wiki/Winter_Olympics_(1993_video_game)'),
  ('Q3496959', 'Star Fox 2 is a shoot ''em up game developed by Nintendo and Argonaut Software for the Super Nintendo Entertainment System (SNES). It was completed in 1995, but was not released until 2017 on the Super NES Classic Edition. Like the original Star Fox (1993), the player controls the Star Fox team as they battle Emperor Andross, who survived his previous defeat and seeks to destroy the Lylat System. Star Fox 2 introduces semi-real-time gameplay, new ship types, new playable characters, and a more advanced 3D game engine.

The development began after Star Fox''s release, with Katsuya Eguchi, Shigeru Miyamoto, and Dylan Cuthbert returning as director, producer, and lead programmer. Like the original, Star Fox 2 pushed the SNES''s graphical capabilities with Argonaut''s Super FX chip. The team experimented more than they had with Star Fox and incorporated platforming and roguelike elements. Star Fox 2 was set for release in August 1995, but 3D technology was advancing quickly, with competition from the Sony PlayStation and Sega Saturn. Concerned that Star Fox 2''s 16-bit graphics would compare poorly against newer games, Nintendo canceled the release to prioritize its upcoming Nintendo 64 console.', 'https://en.wikipedia.org/wiki/Star_Fox_2'),
  ('Q3532667', 'Total Carnage is a twin-stick shooter arcade video game originally developed and published by Midway in North America in March 1992. Set in the fictional country of Kookistan during 1999, players assume the role of Captain Carnage and Major Mayhem from the Doomsday Squad in a last-ditch effort to overthrow dictator General Akhboob and his army of mutants from conquering the world, while also rescuing POWs held by his military force.

Total Carnage was created by most of the same team who previously worked on Williams'' 1990 arcade game Smash TV and shares many gameplay elements. Both use twin-stick shooter control schemes, but while Smash TV takes place in single-screen arenas, Total Carnage has large scrolling levels and bonus levels. Total Carnage adds bombs which can be collected and become active when dropped, exploding several seconds later.', 'https://en.wikipedia.org/wiki/Total_Carnage'),
  ('Q636246', 'Sparkster is a 1994 platform game developed and published by Konami for the Super Nintendo Entertainment System. It is the only game in the Rocket Knight series to be released on a Nintendo console, and was directed by Hideo Ueda. Sparkster is a sequel to the original Rocket Knight Adventures for the Sega Genesis, though it is a different game than the similarly titled Genesis sequel, Sparkster: Rocket Knight Adventures 2.', 'https://en.wikipedia.org/wiki/Sparkster'),
  ('Q3566321', 'Warlock (also stylized Beware the Ultimate Evil of Warlock) is a side-scrolling action video game based on the 1989 horror film series of the same title, more spefically the movie Warlock: The Armageddon. It was released on May 26, 1995 through Acclaim Entertainment for the Genesis and Super NES platforms. A version for the Atari Jaguar was planned by Trimark Interactive but never released.', 'https://en.wikipedia.org/wiki/Warlock_(video_game)'),
  ('Q3521126', 'Disney''s Magical Quest is a Disney platform game trilogy released by Capcom. The games star Mickey Mouse and (depending on the game version) either Minnie Mouse or Donald Duck, who must defeat Pete. The gameplay is similar amongst all games in the series: the player must move as in a typical platform game, defeating enemies either by jumping on them or by grabbing and throwing blocks at them.

One of the most notable gameplay features of the series is the ability to change characters'' outfits, which give characters different special abilities. Other gameplay elements in the series include the ability to expand the player''s health meter by collecting special hearts, and to shop for items using coins that are scattered throughout the game.', 'https://en.wikipedia.org/wiki/Disney%27s_Magical_Quest'),
  ('Q3541110', 'True Lies is a top-view run and gun video game based on the 1994 film of the same name. The game was developed by Beam Software and published by Acclaim Entertainment. Four different versions of the game were released for the Super Nintendo Entertainment System, Sega Genesis, Game Gear, and Game Boy. The home versions and portable versions are drastically different from each other, but have similar play mechanics.', 'https://en.wikipedia.org/wiki/True_Lies_(video_game)'),
  ('Q3516989', 'Tecmo Super NBA Basketball is a basketball video game developed by Sculptured Software for the Super NES. The game is the SNES equivalent of the original Tecmo NBA Basketball. It also came out a year later (with updated rosters) for the Sega Genesis.', 'https://en.wikipedia.org/wiki/Tecmo_Super_NBA_Basketball'),
  ('Q3504105', 'Super Battleship is a naval simulator video game released for the Super NES and Genesis. The game is strictly single-player and is primarily a strategy game with some real-time elements. It is based on the Battleship board game by the Milton Bradley Company.', 'https://en.wikipedia.org/wiki/Super_Battleship'),
  ('Q3511972', 'Terminator 2: Judgment Day or T2 is a 1991 light gun shooter video game based on the film of the same name, developed and published by Midway for arcades. Developed in tandem with the movie, several actors from the film reprise their roles for the game and are featured as part of the game''s photorealistic digitized graphics. The game''s plot largely follows that of the film, casting up to two players as the T-800 "terminator" cyborg, sent back in time to protect John Connor from assassination by the T-1000 terminator. A success in arcades, home conversions of the game were released by Acclaim Entertainment for various platforms under the title of T2: The Arcade Game to avoid confusion with the numerous tie-in games also based on the movie.', 'https://en.wikipedia.org/wiki/Terminator_2:_Judgment_Day_(arcade_game)'),
  ('Q2471838', 'Jimmy Connors Pro Tennis Tour is a video game developed by Blue Byte and published by Ubisoft and released in December 1992 for the Super Nintendo Entertainment System. It is the third game in the Pro Tennis Tour series developed by Blue Byte. It follows 1989''s Pro Tennis Tour and 1991''s Pro Tennis Tour 2. An 8-bit console version, Jimmy Connors Tennis, was developed by NMS Software and released in 1993.', 'https://en.wikipedia.org/wiki/Jimmy_Connors_Pro_Tennis_Tour'),
  ('Q3549559', 'Variable Geo, also known as V.G., is a Japanese 2D fighting game and eroge series developed and published by TGL for consoles and under their Giga brand for home computers. The series focuses on an all-female martial arts competition where participants are required to promote various family restaurants by acting as waitresses when not fighting. The original Variable Geo was released in 1993 for PC-9801; after this first game, the series continued on home computers as an adult-oriented eroge including visual novel spin-offs, while a separate rebooted sub-series was made for consoles called Advanced V.G. with a story mode and toned down (or removed) explicit content, more akin to a regular 2D fighter. The Advanced line had three titles, the last being Advanced V.G. 2 on PlayStation in 1998, while the main line continued until 2004''s V.G. NEO. Alongside the video games, OVA adaptations were also made based on the Variable Geo series.', 'https://en.wikipedia.org/wiki/Variable_Geo'),
  ('Q2420037', 'The Simpsons: Bart''s Nightmare is a 1992 platform video game based on the animated television series The Simpsons. Developed by Sculptured Software and published by Acclaim Entertainment, it was first released for the Super Nintendo Entertainment System in 1992, followed by the Sega Genesis in 1993. The first half of the game follows Bart Simpson as he tries to find his missing homework pages in order to escape a bizarre dream world, while the second half consists of minigames.', 'https://en.wikipedia.org/wiki/The_Simpsons:_Bart%27s_Nightmare'),
  ('Q3536083', 'Toys (also known as Toys: Let the Toy Wars Begin!) is an action video game for the Super NES and Sega Genesis released in 1993. The game is based on the 1992 film Toys starring Robin Williams. Chaos has been spread at a toy factory that must be stopped by the player.', 'https://en.wikipedia.org/wiki/Toys_(video_game)'),
  ('Q2414752', 'Toy Story is a 1995 platform game developed by Traveller''s Tales and published by Disney Interactive for the Sega Genesis, Super Nintendo Entertainment System, Game Boy, and Microsoft Windows. It is based on the 1995 computer-animated Pixar film of the same name.', 'https://en.wikipedia.org/wiki/Toy_Story_(video_game)'),
  ('Q3504196', 'Super High Impact is a sports video game published by Acclaim Entertainment for the Sega Genesis in 1992 and SNES in 1993. It is a console version of the 1991 arcade video game High Impact Football by Williams Electronics. Upon release, the game received average reviews, with critics praising the game''s visual presentation, animation and digitized voice, and faulting the game''s simple design, playbook and lack of features.', 'https://en.wikipedia.org/wiki/Super_High_Impact'),
  ('Q3516983', 'Tecmo Super Baseball is a professional baseball video game that was released in 1994 for the Super NES and Sega Genesis gaming systems. It features all 28 MLB teams that existed at the time. However, the only license the game has is the MLBPA license. This means that while the game does feature actual players, there are no team names or logos. The teams wear uniforms without logos and are only named by their city (the teams that share the cities of Chicago and New York are separated by having either an A or N after their name, denoting their league).

The main menu theme is a cover of "Take Me Out to the Ball Game".', 'https://en.wikipedia.org/wiki/Tecmo_Super_Baseball'),
  ('Q3519716', 'The Adventures of Mighty Max is a 1994 action-adventure platform game developed by the British studio WJS Design and published by the Ocean Software for the Sega Genesis and Super Nintendo Entertainment System. The game is based on the Mighty Max television series.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Mighty_Max'),
  ('Q3534834', 'Socks the Cat Rocks the Hill is a platform video game developed by Realtime Associates for the Super Nintendo Entertainment System. The game stars Socks, the real-life presidential pet cat of the Clinton family during Bill Clinton''s tenure in office. Originally scheduled for release in 1993, Socks the Cat experienced delays until it was ultimately cancelled due to the closure of publisher Kaneko''s U.S. branch. A prototype copy eventually entered the hands of private collectors; following a successful Kickstarter campaign, the ROM image was released to the public in 2018.

Set in Washington D.C., Socks the Cat Rocks the Hill follows the title character as he makes his way past spies, politicians, and the news media to warn the Clinton family of a stolen nuclear missile launch device. The game makes heavy use of political satire, including bosses designed as caricatures of former U.S. presidents and other political figures. Nintendo reportedly liked the game despite their censorship policies during the era which condemned games with political content. The political satire was also praised by contemporary critics, although the game was otherwise found to be average.', 'https://en.wikipedia.org/wiki/Socks_the_Cat_Rocks_the_Hill'),
  ('Q3539815', 'Troddlers is a 1992 Lemmings-inspired puzzle game developed by Atod that was originally released for the Amiga and was later remade on the Super NES. The remake was published by Seika. An MS-DOS port was also released.', 'https://en.wikipedia.org/wiki/Troddlers'),
  ('Q3566369', 'WarpSpeed is a 1992 space flight simulator video game developed and published by Accolade for the Super Nintendo Entertainment System and Sega Genesis.', 'https://en.wikipedia.org/wiki/WarpSpeed'),
  ('Q3504101', 'Super Adventure Island II is a platform video game released by Hudson Soft for the Super NES in 1994 in North America, with subsequent releases in Japan and Europe following in 1995. Unlike most of the previous games, it is a platformer with action-adventure elements that encourages exploration, similar to the later Wonder Boy games.', 'https://en.wikipedia.org/wiki/Super_Adventure_Island_II'),
  ('Q3564651', 'WCW SuperBrawl Wrestling is a professional wrestling video game published by FCI, Inc. for the Super Nintendo Entertainment System in 1994. The third World Championship Wrestling (WCW) video game, it is named after the pay-per-view SuperBrawl. It was the only WCW game to be released on the Super NES, and the last to be produced by FCI, Inc. A Sega Genesis version was planned but never released.', 'https://en.wikipedia.org/wiki/WCW_SuperBrawl_Wrestling'),
  ('Q644838', 'Rise of the Robots is a fighting game released by Time Warner Interactive in 1994. Originally developed for the Amiga and MS-DOS compatible operating systems by Mirage''s Instinct Design, it was ported to video game consoles, including the Super NES, Mega Drive, and 3DO. The game includes a single-player mode in which the player assumes the role of the ECO35-2 Cyborg as he attempts to stop the Supervisor, who has taken over Electrocorp''s facilities in Metropolis 4, and a two-player mode in which the second player controls a character chosen from among ECO35-2''s enemies.

Developed by a team of five people, including former Bitmap Brothers member Sean Griffiths, Rise of the Robots was intended to utilize a high level of artificial intelligence (AI) that had never been seen in other fighting games at the time. The game features music from Queen''s lead guitarist Brian May, although it only uses "The Dark" and "Resurrection", both tracks taken from his solo album Back to the Light, while the in-game music was composed by Richard Joseph.', 'https://en.wikipedia.org/wiki/Rise_of_the_Robots'),
  ('Q3493433', 'Spider-Man is a side-scrolling action game developed by Western Technologies and published by Acclaim and LJN in 1995, based on the 1994–98 animated series of the same name. The game was released for the Sega Genesis and the Super Nintendo Entertainment System (SNES). The two versions of the game have the same basic story but have gameplay, level, and enemy differences.', 'https://en.wikipedia.org/wiki/Spider-Man_(1995_video_game)'),
  ('Q2444666', 'RoboCop Versus The Terminator is a run and gun game released for the Sega Genesis, Super Nintendo Entertainment System, Master System, and Game Gear in 1993, with a port to the Game Boy in 1994. It is based on the 1992 four-issue comic book mini-series of the same name, which is a crossover between the RoboCop and Terminator franchises. Despite their likenesses being shown on packaging, the actors who portrayed the titular characters (Arnold Schwarzenegger in 1984''s The Terminator and Peter Weller in 1987''s RoboCop) did not reprise their roles in this game.

The Genesis version was developed by Virgin Games and uses an engine written by David Perry.', 'https://en.wikipedia.org/wiki/RoboCop_Versus_The_Terminator'),
  ('Q2444696', 'The 7th Saga is a 1993 role-playing video game developed by Produce! and published by Enix for the Super Nintendo Entertainment System. The game made innovative use of a radar system during gameplay. It featured seven playable characters of various types including humans, an elf, a dwarf, robots, a demon, and an alien. Each character has unique items, spells and level/stat progressions.

The game Mystic Ark was planned to be marketed as a sequel to The 7th Saga in North America, but the game was only ever released in Japan.', 'https://en.wikipedia.org/wiki/The_7th_Saga'),
  ('Q3476003', 'Scooby-Doo Mystery is the name of two video games released by Acclaim Entertainment in 1995 and produced by Sunsoft based on the Scooby-Doo franchise. One of the games was released for the Sega Genesis and features a more traditional adventure game-style interface. The other title, released for the Super Nintendo Entertainment System, is an adventure game with platforming elements. Both were released only in North America. In both games, players take control of Shaggy Rogers and Scooby-Doo, who help solve various mysteries with other members of Mystery Incorporated who serve minor roles during gameplay.', 'https://en.wikipedia.org/wiki/Scooby-Doo_Mystery'),
  ('Q682463', 'Wild Guns is a 1994 shooting gallery video game developed and published by Natsume Co., Ltd. for the Super Nintendo Entertainment System. Set in the Wild West with steampunk and sci-fi influences, the story follows Annie and her bounty hunter Clint, seeking revenge for the death of her family. The player controls either Annie or Clint sidestepping and jumping in the foreground while shooting down enemy robots in the background and dodging enemy bullets. These gameplay mechanics combine elements from third-person shooters and light gun games.

Development lasted five months on a small budget with a team of only three core members and two support staff. The team leads had previously worked together on The Ninja Warriors (1994) for the Super NES, and so chose to develop for that system. Wild Guns was heavily influenced in its gameplay and artistic design by arcade games such as Blood Bros. and Dynamite Duke. The game''s scenery, characters, and sound design drew ideas from the Western film genre and the science fiction manga Cobra, creating a space Western setting.', 'https://en.wikipedia.org/wiki/Wild_Guns'),
  ('Q683630', 'Pinball Dreams is a pinball simulation video game developed by Digital Illusions and originally released for the Amiga in 1992. It spawned several sequels, including Pinball Fantasies and Pinball Illusions. The MS-DOS port was digitally released by Rebellion Developments along with its sequel Pinball Dreams 2 and Pinball Mania on February 22, 2011 on GOG.com with support for Microsoft Windows. It received an OS X build on April 23, 2013; and a Linux build on August 19, 2014.', 'https://en.wikipedia.org/wiki/Pinball_Dreams'),
  ('Q2457059', 'Sengoku is a 1991 hack and slash beat ''em up video game developed and published by SNK for the Neo Geo arcade and home platforms. It was ported to several home consoles, including the Neo Geo AES, Neo Geo CD, Mega-CD and Super Famicom. The game was followed by the sequels Sengoku 2 in 1993 and Sengoku 3 in 2001.', 'https://en.wikipedia.org/wiki/Sengoku_(1991_video_game)'),
  ('Q2471373', 'Battle Clash is a 1992 light gun shooter video game developed by Intelligent Systems and published by Nintendo for the Super Nintendo Entertainment System. It is one of a small number of titles that requires the Super Scope, a light gun. Set in a futuristic post-apocalyptic Earth where battles are fought with mechs called Standing Tanks (STs), a man named Mike Anderson participates in the Battle Game to face the ruthless champion Anubis. The player acts as the gunner of the ST Falcon piloted by Anderson, taking on Anubis and his subordinate chiefs in one-on-one fights.

Battle Clash was created by Team Battle Clash, a group within Intelligent Systems that developed games for the Super Scope, made up of Nintendo R&D1 staff responsible for light gun shooters such as Duck Hunt and Hogan''s Alley. It was co-directed by Makoto Kano and Masao Yamamoto, and produced by Gunpei Yokoi. The soundtrack was scored by Yuka Tsujiyoko, best known for her work in the Fire Emblem and Paper Mario series. The game garnered average reception from critics; praise was given to the visuals, but other expressed mixed opinions regarding the sound and gameplay. Some reviewers also criticized its low difficulty. It was followed by Metal Combat: Falcon''s Revenge (1993), and Team Battle Clash would later work on Tetris Attack.', 'https://en.wikipedia.org/wiki/Battle_Clash'),
  ('Q739658', 'Sink or Swim is a puzzle video game that was released in 1993 for MS-DOS Developed by Odysseus Software and published by Zeppelin Games. It is similar in style to Lemmings. The game was ported to the Amiga and the Super Nintendo Entertainment System. Mega Drive and Game Gear versions were renamed to Man Overboard!.', 'https://en.wikipedia.org/wiki/Sink_or_Swim_(video_game)'),
  ('Q720440', 'Darius Twin is a 1991 horizontally scrolling shooter video game developed and published by Taito for the Super Nintendo Entertainment System. It is part of the Darius series. It was re-released for the Wii Virtual Console in Japan on April 13, 2010 and in North America on December 13, 2010.', 'https://en.wikipedia.org/wiki/Darius_Twin'),
  ('Q3476647', 'seaQuest DSV is an action/strategy video game depiction of the seaQuest DSV television series for developed by Sculptured Software. A Super Nintendo Entertainment System version was published in 1994 and a Sega Genesis port in 1995. The player captains the submarine seaQuest DSV 4600 to carry out a series of missions in a scrolling, underwater environment.

The seaQuest DSV game for the Game Boy is completely different from the console versions.', 'https://en.wikipedia.org/wiki/SeaQuest_DSV_(video_game)'),
  ('Q2450491', 'Ys V: Lost Kefin, Kingdom of Sand is a 1995 action role-playing game developed by Nihon Falcom. It is the fifth game in the Ys series of video games and was released for the Super Famicom in December 1995. A remake by Access and Taito was released for the PlayStation 2 in 2006.', 'https://en.wikipedia.org/wiki/Ys_V:_Lost_Kefin,_Kingdom_of_Sand'),
  ('Q681057', 'Powermonger is a real-time strategy video game developed by Bullfrog Productions and published by Electronic Arts. Originally released in 1990 for the Amiga and Atari ST, it was derived from the Populous engine but presented using a three-dimensional game map.', 'https://en.wikipedia.org/wiki/Powermonger'),
  ('Q743550', 'John Madden Football ''93 is a 1992 American football video game developed and published by Electronic Arts for the Super NES and Sega Genesis. The player controls a football team in modes such as tournament play and sudden death. Officially endorsed by John Madden, it was the third Madden game for the Genesis and the second for the SNES, being the first title in the series to receive a simultaneous release on both platforms.

The Genesis version was developed by LookingGlass Technologies, which was simultaneously creating Ultima Underworld: The Stygian Abyss. John Madden Football ''93 adds new animations and features, and allows players to play as and against famous teams such as the 1976 Oakland Raiders. Aside from Madden Football 64, the game was the last in the Madden franchise to lack the NFL license, which was featured in Madden NFL ''94 onward.', 'https://en.wikipedia.org/wiki/John_Madden_Football_%2793'),
  ('Q743523', 'Space Megaforce, known in Japan and Europe as Super Aleste, is a vertically scrolling shooter developed by Compile. It was published by Toho in 1992 for the Super Nintendo Entertainment System as part of the Aleste series. The player pilots a spacecraft through a variety of locales shooting enemy ships. The story in the Japanese version is different from the American and European one. Super Aleste also offers a "Short Game", with segments of the regular levels; the emphasis is on scoring as many points as possible.', 'https://en.wikipedia.org/wiki/Space_Megaforce'),
  ('Q744175', 'Lord Monarch is a real-time strategy war game by Nihon Falcom. The game is considered to be part of the Dragon Slayer series. It was originally released in 1991 for the NEC PC-9801, ported 1992 to the Super Famicom and 1994 to the Mega Drive. In 1997, it was remade for Windows as Lord Monarch Online and released for free in both Japanese, and for the first time, English.', 'https://en.wikipedia.org/wiki/Lord_Monarch'),
  ('Q3493594', 'Spirou is a platform game developed and published by Infogrames in 1995 for the Mega Drive and in 1996 for the Super NES, Game Boy, Microsoft Windows and MS-DOS. A Game Gear version was planned but canceled, although a fully completed prototype was leaked online.

The game is based on the Spirou et Fantasio comic book series. It follows Spirou on his adventure to rescue his kidnapped friend Count Champignac and stop his arch-enemy Cyanida from making robots rule the Earth. The game was noted for its strong graphics and for being faithful to the Spirou et Fantasio comic book series, but due to its relatively high difficulty, most reviewers recommended it only for true fans of the series.', 'https://en.wikipedia.org/wiki/Spirou_(video_game)'),
  ('Q3492971', 'Speedy Gonzales: Los Gatos Bandidos is a Super Nintendo Entertainment System video game published by Acclaim Entertainment and developed by Sunsoft in 1995.', 'https://en.wikipedia.org/wiki/Speedy_Gonzales:_Los_Gatos_Bandidos'),
  ('Q3461639', 'Sailor Moon is a side-scrolling beat ''em up video game originally developed and released by Angel in Japan on August 27, 1993 and later in France and Spain in November 1994 by Bandai for the Super Nintendo Entertainment System. It is the second game to be created by Angel based upon Naoko Takeuchi''s Sailor Moon shōjo manga and anime series, the first for the Super NES and one of the few Sailor Moon titles that had an official international release.

Following the first season of the anime series, which adapted the first arc of the manga, the players control one of the five original Inner Sailor Guardians and fight against enemies across several locations in order to protect Earth from the Dark Kingdom, a group of antagonists led by Queen Beryl who previously destroyed the ancient Moon Kingdom as they attempt to steal life energy from humans and the Silver Crystal to free Queen Metaria from her imprisonment. Due to the success of Sailor Moon for Game Boy in Japan, Angel wanted to develop a project for the Super NES with the aim to appeal towards fans of the series. The title was later ported to the Sega Mega Drive, featuring various changes compared to the original SNES version.', 'https://en.wikipedia.org/wiki/Sailor_Moon_(1993_video_game)'),
  ('Q3607174', 'Air Cavalry is a flight simulation video game developed by Synergistic Software. It was released by Cybersoft and GameTek for the Super NES in 1995.', 'https://en.wikipedia.org/wiki/Air_Cavalry'),
  ('Q3636049', 'Bassin''s Black Bass with Hank Parker, known in Japan as Super Black Bass 2 is a 1994 tournament-based fishing video game developed by Starfish (ja) and published by Hot B for the Super Nintendo Entertainment System. It is part of the Black Bass series. The player attempts to rise up from an amateur tournament to the bass fishing championship in both versions. In the North American version, the player must compete and win against Hank Parker for the championship.', 'https://en.wikipedia.org/wiki/Bassin%27s_Black_Bass_with_Hank_Parker'),
  ('Q3636838', 'Battle Blaze is a 1992 medieval fighting game released for the Super Nintendo Entertainment System by Sammy Studios. Players use swords, morningstars, knives, and other weapons to beat up their opponents. The player can either play in a colosseum or on a quest. The eventual goal is defeat the Dark Lord who lives in a castle in the sky.', 'https://en.wikipedia.org/wiki/Battle_Blaze'),
  ('Q3636845', 'Battle Grand Prix is a 1992 Formula One racing video game developed by KID. One or two players can pit themselves in three Grand Prix races. Each of the different team cars have different color schemes. The courses vary from blacktop to concrete, and rain is also included and is implemented in the game.', 'https://en.wikipedia.org/wiki/Battle_Grand_Prix'),
  ('Q3616386', 'The Firemen is an action video game developed and published by Human Entertainment for the Super Nintendo Entertainment System. It was first released in Japan in 1994, and then in Europe and Australia in 1995. In The Firemen, the player controls firemen who fight fires and save civilians. A sequel was released for the PlayStation in 1995 titled The Firemen 2: Pete & Danny.', 'https://en.wikipedia.org/wiki/The_Firemen'),
  ('Q3569675', 'Wolfchild is a platform game originally released for the Amiga and the Atari ST by Core Design in 1992. It was later released for the SNES, Mega Drive/Genesis, Sega CD, Master System, and Game Gear.

The plot revolves around biotechnology researcher Kal Morrow and his son Saul. When Kal is kidnapped by the evil Chimera organization, Saul uses one of his father''s inventions to turn himself into a wolf-human hybrid (similar to a werewolf) that may be capable of defeating Chimera.

Wolfchild was designed by Simon Phipps, also responsible for the earlier Switchblade 2, a rather similar game. The action is viewed from the side and scrolls in eight directions. The player must guide Saul through five levels, negotiating platforms and shooting various monsters, the result of Chimera experiments. Initially, the player character is Saul in his normal, human form. Only when enough energy has been collected does he turn into a wolf-human, giving him much better attack techniques.', 'https://en.wikipedia.org/wiki/Wolfchild'),
  ('Q3604232', 'Shijō Saikyō League Serie A: Ace Striker is a 1995 Japan-exclusive football video game for the Super Famicom.', 'https://en.wikipedia.org/wiki/Shij%C5%8D_Saiky%C5%8D_League_Serie_A:_Ace_Striker'),
  ('Q3569743', 'Wolverine: Adamantium Rage is a platform-action video game released for both the Super NES and the Sega Genesis in 1994. Both versions were developed by different London studios: the Genesis version developed by Teeny Weeny Games and the Super NES version by Bits Studios. Both versions of the title were developed separately and differed from one another in some key areas, but their opening storyline and gameplay remain similar. It is one of the first action video games to feature a recharging health system.', 'https://en.wikipedia.org/wiki/Wolverine:_Adamantium_Rage'),
  ('Q3566712', 'Several video games based on the 1995 film Waterworld have been released for the Super Nintendo Entertainment System, Genesis, Virtual Boy, MS-DOS, Microsoft Windows and Game Boy, along with unpublished versions for the Sega Saturn, Atari Jaguar, 3DO and PlayStation. These games were produced by Ocean Software. The SNES and Game Boy games were released only in Europe in 1995, the Virtual Boy game was released exclusively in North America in November 1995, and the Genesis version was only available via the Sega Channel service in March 1996. A strategy game for Windows was released in 1997.', 'https://en.wikipedia.org/wiki/Waterworld_video_games'),
  ('Q3614789', 'An American Tail: Fievel Goes West is a Super NES platform game released in 1994. It is the second game released based on the film of the same name; the other is an adventure game for MS-DOS, published by Capstone Software.', 'https://en.wikipedia.org/wiki/An_American_Tail:_Fievel_Goes_West_(video_game)'),
  ('Q3639833', 'Big Sky Trooper is a sci-fi action game produced by JVC Musical Industries and LucasArts for the Super NES in October 1995. The game runs on the Zombies Ate My Neighbors engine.', 'https://en.wikipedia.org/wiki/Big_Sky_Trooper'),
  ('Q3570039', 'Worlds of Ultima: The Savage Empire is a role-playing video game, part in the Ultima series, published in 1990. It is considered a Worlds of Ultima game, as its setting differs from that of the main series. It uses the same engine as Ultima VI: The False Prophet and Martian Dreams. On June 18, 2012, Electronic Arts released the game as freeware through GOG.com.', 'https://en.wikipedia.org/wiki/Worlds_of_Ultima:_The_Savage_Empire'),
  ('Q3639984', 'Future Basketball is a futuristic basketball video game released by Hewson Consultants for the Amiga and Atari ST in 1990. It was ported to the Super Nintendo Entertainment System (SNES) by Hudson Soft in 1991 as Bill Laimbeer''s Combat Basketball. It was the first basketball game released for the SNES. The game stars Bill Laimbeer, who played for the Detroit Pistons of the NBA during a time when the team was notorious for dirty, physical play. The Pistons during this time were also known as the "Bad Boys" for the amount of contact they would initiate. They would often hit or strike opponents in an attempt to intimidate and harm opponents.', 'https://en.wikipedia.org/wiki/Future_Basketball'),
  ('Q3600489', 'ABC Monday Night Football is an American football video game named after the television broadcast of the same name. It was published by Data East for MS-DOS (1989), Commodore 64 (1990), Amiga (1991), and Super NES (1993). The game was licensed by ABC Sports, but without NFL and NFLPA licenses, so the teams are fictional, such as the Indianapolis Rays and Miami Sharks. The team colors mimic their real-life counterparts.', 'https://en.wikipedia.org/wiki/ABC_Monday_Night_Football_(video_game)'),
  ('Q3566952', 'WeaponLord is a 1995 fighting game developed by Visual Concepts and published by Namco for the Super Nintendo Entertainment System and Sega Genesis. The game has players select a character and defeat a series of opponents. The game is a weapons-based fighter, with various gory moves and a deep counterattack system.

Project leads James Goddard and Dave Winstead aimed to design a title for enthusiasts of the fighting game genre. Unlike many other fighting games of the time, WeaponLord was designed specifically for home consoles and was one of the first fighting games optimized for online play. It has also been thought of as the basis for Namco''s Soul Edge/Calibur series.', 'https://en.wikipedia.org/wiki/WeaponLord'),
  ('Q3636839', 'Battle Cars is a 1993 racing video game developed by Malibu Interactive and published by Namco Hometek for the Super Nintendo Entertainment System. It is a futuristic racing game in which cars are equipped with multiple weapons which are used to eliminate opponents. It was only released in North America.', 'https://en.wikipedia.org/wiki/Battle_Cars'),
  ('Q3639893', 'Biker Mice From Mars is a racing video game released by Konami for the Super Nintendo Entertainment System. It is a tie-in to the animated series of the same title. The PAL version of the game features in-game product placement for Snickers candy bars.', 'https://en.wikipedia.org/wiki/Biker_Mice_from_Mars_(1994_video_game)'),
  ('Q3607557', 'Al Unser Jr.''s Road to the Top is a racing video game released for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Al_Unser_Jr.%27s_Road_to_the_Top'),
  ('Q3566834', 'Wayne Gretzky Hockey NHLPA All-Stars is an ice hockey video game featuring Wayne Gretzky and other NHLPA players. It was published by Time Warner Interactive for the Super NES, Mega Drive/Genesis, and MS-DOS.', 'https://en.wikipedia.org/wiki/Wayne_Gretzky_and_the_NHLPA_All-Stars'),
  ('Q3661053', 'Cyber Knight is a science fiction PC Engine and Super Famicom role-playing video game that combines sci-fi space exploration with strategic robot combat. This game is intended for experienced role-playing gamers only. The random encounters are high even for a Japanese role-playing game with a mid-to-late 1992 Super Famicom release date (e.g., Dragon Quest V: Hand of the Heavenly Bride) and the combat sequences (using melee attacks in addition to missiles and guns) are extremely slow. Two years later, a sequel was released for this game titled Cyber Knight II: Chikyū Teikoku no Yabō. The games were only released commercially in Japan, however there are a fan-translations from Japanese to English by Aeon Genesis.', 'https://en.wikipedia.org/wiki/Cyber_Knight'),
  ('Q3658043', 'Captain Tsubasa J: The Way to World Youth is a 1995 Japan-exclusive Captain Tsubasa video game developed and published by Bandai and was the final Captain Tsubasa game for the Super Famicom.', 'https://en.wikipedia.org/wiki/Captain_Tsubasa_J:_The_Way_to_World_Youth'),
  ('Q3658045', 'Captain Tsubasa 4: Professional Rivals is the third sequel and fourth installment in the Captain Tsubasa video game series by Tecmo. It''s a direct sequel of Captain Tsubasa 3: Koutei no Chousen and was released exclusively in Japan for Nintendo''s Super Famicom on April 3, 1993, with inferior graphics compared to its predecessor.', 'https://en.wikipedia.org/wiki/Captain_Tsubasa_4:_Pro_no_Rival_Tachi'),
  ('Q3647960', 'Bebe''s Kids is a side-scrolling beat ''em up video game developed by Radical Entertainment and published by Motown Games/Paramount Interactive for the Super Nintendo Entertainment System, released in 1994. It is based on the 1992 animated film of the same name and, like the film, received largely unfavorable critical reception.', 'https://en.wikipedia.org/wiki/Bebe%27s_Kids_(video_game)'),
  ('Q762130', 'The Chaos Engine is a top-down run and gun video game developed by The Bitmap Brothers and published by Renegade Software in March 1993. The game is set in a steampunk Victorian age in which one or two players must battle the hostile creations of the eponymous Chaos Engine across four landscapes and ultimately defeat it and its deranged inventor.

It was first released for the Amiga, with a version available for AGA Amigas, and later ported to MS-DOS, the Super Nintendo Entertainment System, Atari ST, Amiga CD32, RISC OS and Mega Drive. In the Super NES and Mega Drive versions, the Preacher character was renamed as the Scientist and redesigned to remove his clerical collar. The US versions of these two ports were retitled Soldiers of Fortune. A sequel to the game, The Chaos Engine 2, was released in 1996.', 'https://en.wikipedia.org/wiki/The_Chaos_Engine'),
  ('Q786464', 'Gon is a side-scrolling platform game for the Super Famicom published by Bandai in 1994. The game is an adaptation of the manga series Gon by Masashi Tanaka, about the daily life of a dinosaur named Gon.', 'https://en.wikipedia.org/wiki/Gon_(video_game)'),
  ('Q771109', 'MLBPA Baseball, known in Japan as Fighting Baseball (Fightingベースボール, Faitingu Bēsubōru; "Fighting Baseball"), is a baseball video game for the Super NES, Sega Genesis, and Game Gear.', 'https://en.wikipedia.org/wiki/MLBPA_Baseball'),
  ('Q3868738', 'Mutant Fighter, originally titled in Japan as, is a 1991 fighting game published and developed in-house by Data East for arcades. It was later ported to the FM Towns, Sharp X68000, and Super Nintendo Entertainment System. The SNES version was developed and published by I''Max. It is a sequel to Data East''s 1989 arcade title Hippodrome.', 'https://en.wikipedia.org/wiki/Mutant_Fighter_(arcade_game)'),
  ('Q3823700', 'Princess Minerva is a role-playing video game developed and published by Riverhillsoft for the NEC PC-9801 in 1992 in Japan only. An original video animation by Group TAC was originally released by Toho in May 1995 in Japan; it was later released also in the United States. The extended franchise also includes a manga series, an illustrated serial novel, and other media.', 'https://en.wikipedia.org/wiki/Princess_Minerva'),
  ('Q3928360', 'RPM Racing (short for Radical Psycho Machine Racing) is an isometric racing video game developed by Silicon & Synapse and published by Interplay Productions for the Super Nintendo Entertainment System (SNES). It was released in November 1991, as the first game from Silicon & Synapse, the company that became Blizzard Entertainment. It is one of the first American-developed games for the SNES.

RPM Racing is a remake of the 1985 Electronic Arts game Racing Destruction Set. The core logic engine and track editor were ported from the original game. Development was completed in approximately four to six months. A spiritual successor, Rock n'' Roll Racing, appeared in 1993. The game''s reviews were mixed, with critics noting its functional but uninspired gameplay and bland graphics, a result of using a high-resolution graphics mode that severely limited its color palette. In 2021, Blizzard Entertainment re-released RPM Racing as part of the Blizzard Arcade Collection for modern platforms.', 'https://en.wikipedia.org/wiki/RPM_Racing'),
  ('Q939924', 'A.S.P. Air Strike Patrol is an isometric scrolling shooter video game developed by Japanese studio Opus and published by SETA for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/A.S.P._Air_Strike_Patrol'),
  ('Q3744718', 'Fighter''s History is a 1993 fighting game developed and published by Data East for arcades. It is the first installment in the Fighter''s History series. The main unique feature of the Fighter''s History is its weak point system, which allows the player to temporarily stun an opponent by repeatedly hitting their weak point.

Fighter''s History was the subject of a lawsuit against Data East by Capcom, who claimed the game infringed on the copyright of its game Street Fighter II. The case was found in Data East''s favor, as the court found that the copied elements were scènes à faire, elements necessary for depicting the scenario. Fighter''s History was ported to the Super Nintendo Entertainment System in 1994, and followed by a sequel, Karnov''s Revenge, for the Neo Geo.', 'https://en.wikipedia.org/wiki/Fighter%27s_History_(video_game)'),
  ('Q865277', 'Hong Kong 97 (also referred to as Hong Kong 1997 on the floppy disk cover) is an unlicensed shoot ''em up video game developed and published by HappySoft, a doujin game developer, for the Super Famicom. It was released in Japan in 1995, being sold as floppy disks. Designed by the Japanese game journalist Kowloon Kurosawa, who stated the game was a satire of the video game industry, Hong Kong 97 was made in seven days with the help of his friend.

The game takes place in China in 1997, during the handover of Hong Kong from the United Kingdom. Facing an increased crime rate due to immigration from Mainland China, the Hong Kong government hires Chin, a relative of Bruce Lee, to massacre the population of China. Meanwhile, the Chinese government has been conducting a secret project in which the deceased Tong Shau Ping [sic] will be resurrected and transformed into an "ultimate weapon" to battle Chin. After defeating Tong Shau Ping, the game is repeated indefinitely until Chin dies. Hong Kong 97 sold around 30 copies due to its underground bootleg release. It has since gained a cult following for its notoriously poor quality, offensive content and absurd gameplay. In retrospect, it is considered by critics and journalists to be among the worst games ever made. A sequel, titled Hong Kong 2097, was released in February 2026 for Windows.', 'https://en.wikipedia.org/wiki/Hong_Kong_97'),
  ('Q3777241', 'Brawl Brothers, originally known in Japan as Rushing Beat Run and known as Rival Turf! 2 in PAL region, is a 1992 beat ''em up video game developed and published by Jaleco for the Super Nintendo Entertainment System. It is the second game in the Rushing Beat series, after Rival Turf!, and was followed by The Peace Keepers in 1993.', 'https://en.wikipedia.org/wiki/Brawl_Brothers'),
  ('Q837531', 'This list provides an index of video game titles in Banpresto''s Super Robot Wars franchise, known as Super Robot Taisen in Japan. Most of the games in the series are tactical role-playing games, but several games representing other genres were also released. List is divided by video game genre and ordered by initial release date. Only the original games, Neo Super Robot Wars and Super Robot Wars Compact, had final bosses that were not directly created by Banpresto.', 'https://en.wikipedia.org/wiki/List_of_Super_Robot_Wars_video_games'),
  ('Q3777687', 'Albert Odyssey is a tactical role-playing video game developed and published by Sunsoft and released for the Super Nintendo Entertainment System in Japan in March 1993. The game features strategy-based combat in addition to traditional role-playing game elements in two-dimensional environments. It is the first game in the Albert Odyssey series, and was followed by two sequels, Albert Odyssey 2: Jashin no Taidō in 1994, and Albert Odyssey: Legend of Eldean in 1996. Albert Odyssey was made available as a full game download on the Satellaview add-on as BS Albert Odyssey on June 12, 1996, and the original Albert Odyssey was re-released for Satellaview in March 1998 the Wii Virtual Console in October 2010, and the Wii U Virtual Console in July 2015.', 'https://en.wikipedia.org/wiki/Albert_Odyssey_(1993_video_game)'),
  ('Q863419', 'Romancing SaGa 2 is a 1993 role-playing video game developed and published by Square for the Super Famicom (Super Nintendo Entertainment System). Originally exclusive to Japan, a remaster was released worldwide on home consoles, mobile devices, and Windows from 2016 to 2017. The fifth entry in the SaGa series and second in the Romancing SaGa trilogy, the story follows the fate of Avalon, a nation that must fight against a group dubbed the Seven Heroes. Gameplay features nonlinear exploration and expansion of the game world and narrative, with the turn-based battles featuring group formations. As with other SaGa titles, there are no experience points; character attributes and skills are dependent on actions taken in battle. A key mechanic is choosing the next ruler of Avalon, who will inherit the abilities of the previous ruler.', 'https://en.wikipedia.org/wiki/Romancing_SaGa_2'),
  ('Q3782393', 'Hagane: The Final Conflict is a 1994 action-platform video game developed by CAProduction and Red Entertainment and published by Hudson Soft for the Super Nintendo Entertainment System. The player takes on the role of a ninja cyborg named Hagane on his path to take revenge on an opposing ninja faction. The game combines traditional Japanese ninja and samurai aesthetics with a futuristic setting. The player has a wide variety of weapons, moves, and attacks at their disposal to defeat enemies and progress through the game. Hagane released to positive reception, and was compared favorably to classic side-scrolling action games. Reviewers praised the controls, art design, and challenge but criticized the quality of the graphics and sound.', 'https://en.wikipedia.org/wiki/Hagane:_The_Final_Conflict'),
  ('Q846203', 'Super R-Type is a scrolling shooter video game developed and published by Irem for the Super Nintendo Entertainment System. It was released in Japan and North America in 1991, Europe in 1992, and Brazil in 1993 by Nintendo. It is a partial port of R-Type II, borrowing stages and enemies, but introducing several of its own. The game has been re-released on the Wii Virtual Console in 2008, and on the Nintendo Classics service in 2024.', 'https://en.wikipedia.org/wiki/Super_R-Type'),
  ('Q890852', 'The Adventures of Batman & Robin is a series of video game adaptations released between 1994 and 1995 featuring the DC Comics characters Batman and Robin, based on Batman: The Animated Series (which had been retitled The Adventures of Batman and Robin for its second season). The games were released for numerous platforms, with the Genesis, Game Gear, and Sega CD versions published by Sega, while the Super NES version was published by Konami (who also produced an earlier Game Boy video game based on the show).', 'https://en.wikipedia.org/wiki/The_Adventures_of_Batman_%26_Robin_(video_game)'),
  ('Q880945', 'Blackthorne (released as Blackhawk in some European countries) is a cinematic platform game developed by Blizzard Entertainment. It was released for the Super NES and MS-DOS in 1994. The cover art for the SNES version was drawn by Jim Lee. The following year, Blackthorne was released for the 32X with additional content. In 2013, Blizzard released the game for free on their Battle.net PC client. In celebration of the company''s 30th anniversary, Blackthorne was re-released for Nintendo Switch, PlayStation 4, Windows, and Xbox One as part of the Blizzard Arcade Collection in February 2021.', 'https://en.wikipedia.org/wiki/Blackthorne');

insert into import_summary (wikidata_id, summary, source) values
  ('Q906895', 'Prince of Persia 2: The Shadow and the Flame is a 1993 cinematic platform game released by Broderbund for MS-DOS, and later ported to Macintosh, Super NES, and FM Towns. It is the sequel to 1989''s Prince of Persia, and the second installment in the Prince of Persia series. Both games were designed by Jordan Mechner, but unlike the original, he did not program the sequel himself. In the game, players control the eponymous Prince as he attempts to return to medieval Persia and defeat the evil wizard Jaffar once and for all, who has assumed his appearance, seized the throne, and put his love interest, the Princess, under a death spell.', 'https://en.wikipedia.org/wiki/Prince_of_Persia_2:_The_Shadow_and_the_Flame'),
  ('Q3930130', 'Street Combat is a fighting video game developed by NCS Corporation for the Super Nintendo Entertainment System (SNES). The game centers around Steven, a scientist and Kung Fu expert who enters a martial arts tournament to thwart the plans of a terrorist organization. Gameplay consists of one-on-one battles where the player must defeat opponents in sets of rounds using both standard and special attacks. It also features bonus rounds and a two-player versus option.

The game was originally released in Japan in 1992 by the NCS label Masaya Games under the title Ranma ½: Chōnai Gekitōhen as an adaptation of the manga series Ranma ½ authored by Rumiko Takahashi. When Irem localized it as Street Combat for the western market in 1993, the game mechanics were unaltered. However, all connections to the manga were removed, most notably with its entire roster of characters being replaced with different sprites.', 'https://en.wikipedia.org/wiki/Street_Combat'),
  ('Q3930132', 'Ranma ½: Hard Battle, known as Ranma ½: Bakuretsu Rantōhen in Japan and as just Ranma ½ in Europe, is a 2-D fighting video game released by Masaya and DTMC for the Super Nintendo Entertainment System. It is based on the manga and anime series Ranma ½. Hard Battle is the second Ranma ½ game to be translated into English, this time keeping the original graphics, music, and names of the characters, though the voices were still dubbed into English. The game''s English translation (but not its English voice acting) was provided by Viz Media (who had begun releasing the English dub of Ranma 1/2 earlier that same year).', 'https://en.wikipedia.org/wiki/Ranma_%C2%BD:_Hard_Battle'),
  ('Q3942796', 'This is a list of video games of the Japanese media franchise Lupin the Third based on the manga written by Monkey Punch beginning in 1967.', 'https://en.wikipedia.org/wiki/List_of_Lupin_the_Third_video_games'),
  ('Q3944958', 'Bishōjo Senshi Sailor Moon: Another Story is a role-playing video game developed and published by Angel exclusively for the Super Famicom in Japan on 22 September 1995. Based upon Naoko Takeuchi''s Sailor Moon shōjo manga and anime series, the game takes place between the third season and fourth season of the anime series, which adapted the third and fourth arcs of the manga respectively, as players take control of either the five Inner Guardians or the four Outer Guardians in order to protect Crystal Tokyo by fighting against a group of rebels and several of their previously defeated enemies once again that were resurrected by the sorceress Apsu.', 'https://en.wikipedia.org/wiki/Bish%C5%8Djo_Senshi_Sailor_Moon:_Another_Story'),
  ('Q3944964', 'Bishōjo Senshi Sailor Moon S: Jōgai Rantō!? Shuyaku Sōdatsusen is a 1994 fighting video game developed by Arc System Works and published by Angel for the Super Famicom. It is based upon Naoko Takeuchi''s Sailor Moon manga and anime series and stars heroic teenage girls who represent the major celestial bodies of the Solar System. The player takes control of one of the girls who have decided to stage a fighting tournament to determine who should lead the group.

Sailor Moon S: Jōgai Rantō!? Shuyaku Sōdatsusen served as both the first full-fledge fighting game in the Sailor Moon franchise and the first fighting project created by Arc System Works. In 1996, an updated version titled Bishōjo Senshi Sailor Moon SuperS: Zenin Sanka!! Shuyaku Sōdatsusen was published by Angel for the Super Famicom and featured several additions not found in the original release. The game garnered mixed reception from critics upon its initial launch, though retrospective reviews have been more positive. It has been featured at the Evolution Championship Series tournament, among other fighting game events.', 'https://en.wikipedia.org/wiki/Bish%C5%8Djo_Senshi_Sailor_Moon_S:_J%C5%8Dgai_Rant%C5%8D!%3F_Shuyaku_S%C5%8Ddatsusen'),
  ('Q936565', 'Acme Animation Factory is an educational art and graphics video game released by Sunsoft in November 1994 for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Acme_Animation_Factory'),
  ('Q939597', 'Mega-Lo-Mania is a real-time strategy video game developed by Sensible Software. It was released for the Amiga in 1991 and ported to other systems. It was released as Tyrants: Fight Through Time in North America and Mega Lo Mania: Jikū Daisenryaku in Japan. The game was re-released on ZOOM-Platform.com via Electronic Arts on August 31, 2022.', 'https://en.wikipedia.org/wiki/Mega-Lo-Mania'),
  ('Q3977556', 'Chō Jikū Yōsai Macross: Scrambled Valkyrie is a 1993 shmup video game for the Super Famicom, developed by Winky Soft and published by Zamuse.

It is part of the "Parallel World" timeline based on Macross: Do You Remember Love, which also includes the video games Macross 2036 and Macross: Eien no Love Song, and the OVA Macross II. The events of Scrambled Valkyrie take place some time after Do You Remember Love (2010) but before the launch of the SDF-2 Megaroad-01 as depicted in Macross: Flash Back 2012 (2012).', 'https://en.wikipedia.org/wiki/Super_Dimension_Fortress_Macross:_Scrambled_Valkyrie'),
  ('Q3966420', 'Spectre is a video game for the Macintosh, developed in 1990 by Peninsula Gameworks and published in 1991 by Velocity Development. It is a 3D vector graphics tank battle reminiscent of the arcade game Battlezone. One sequel, Spectre VR, appeared on a number of lists of best video games.', 'https://en.wikipedia.org/wiki/Spectre_(1991_video_game)'),
  ('Q3983399', 'Tenchi Muyō! Game Hen, also known as Tenchi Muyō! RPG, is a Japanese role-playing strategy game developed by Banpresto for the Super Famicom, released on October 27, 1995. It was licensed by AIC and the now former Pioneer LDC. While Tenchi Muyō! Game Hen was never officially translated and released for international consoles, the latter dumped ROM image of the game was hacked and translated into English on two occasions. Lina`chan, Nuku-Nuku & Filia''s Translations, or LNF, released their functional iteration in 2000, albeit some bugs and textual imperfections.', 'https://en.wikipedia.org/wiki/Tenchi_Muy%C5%8D!_Game_Hen'),
  ('Q4009249', 'Vegas Stakes, known as Las Vegas Dream in Japan, is a 1993 gambling video game developed by HAL Laboratory and published by Nintendo for the Super Nintendo Entertainment System. It was released in North America in April 1993, in Europe the same year and in Japan by Imagineer in September 1993. A port for the Game Boy was released only in North America in December 1995. The Super NES version supports the Super NES Mouse, while the Game Boy version is compatible with the Super Game Boy, and features borders which use artwork from the Super NES version. It is the sequel to the NES game Vegas Dream.', 'https://en.wikipedia.org/wiki/Vegas_Stakes'),
  ('Q4006784', 'Utopia: The Creation of a Nation is a strategy video game developed by Celestial Software and published by Gremlin Graphics (later known as Gremlin Interactive) in 1991 for the Amiga, Atari ST and MS-DOS. It was later released for the Super NES in 1993, by Jaleco in the USA. This release made use of the Super NES Mouse peripheral.', 'https://en.wikipedia.org/wiki/Utopia:_The_Creation_of_a_Nation'),
  ('Q3967184', 'Sports Illustrated: Championship Football & Baseball (known in Europe as All-American Championship Football) is a multiplatform sports video game that is licensed by sports magazine Sports Illustrated which features both American football and baseball games.', 'https://en.wikipedia.org/wiki/Sports_Illustrated:_Championship_Football_%26_Baseball'),
  ('Q3977565', 'Super Formation Soccer ''95: della Serie A is an official licensed football video game that featured all clubs and footballers from the Italian Serie A (SEASON 1994-95) and was released exclusively in Japan in 1995. It was licensed by Italian Football League and AIC (Associazione Italiana Calciatori). The game is based on the original video game Super Formation Soccer.

In the same year, Formation Soccer ''95: della Serie A was released for the Turbo CD. The game structure differs from Super Formation Soccer ''95.', 'https://en.wikipedia.org/wiki/Super_Formation_Soccer_95:_della_Serie_A'),
  ('Q3977633', 'Super Turrican 2 is a run and gun video game developed by Factor 5 and published by Ocean Software in 1995 for the Super Nintendo Entertainment System. Part of the Turrican series, it is the sequel to Super Turrican for the same platform.

The game was released on the Virtual Console in North America on September 29, 2008. However, it was retired without any explanation in October 2013 in the same region. It was also re-released as an aftermarket cartridge for the original SNES console in 2022, also including a score attack level for Super Turrican.', 'https://en.wikipedia.org/wiki/Super_Turrican_2'),
  ('Q3978362', 'Sutte Hakkun is a 1997 action puzzle video game developed by Indieszero with Nintendo R&D2 and published by Nintendo. It was created for the Super Famicom''s add-on, the Satellaview, first datacasting the game on November 2, 1997. Three different updates involving new puzzles were released from 1998 to 1999. The game received its first re-release outside of Japan on the Nintendo Classics service on January 24, 2025.', 'https://en.wikipedia.org/wiki/Sutte_Hakkun'),
  ('Q4021021', 'Wrecking Crew is an action game developed and published by Nintendo. It was first released for arcades for the Nintendo VS. System in 1984, titled VS. Wrecking Crew with a simultaneous two-player mode. It was released as a single-player game for the Family Computer (Famicom) console in 1985, and as a launch game for the Nintendo Entertainment System (NES) later that year.

It was designed by Yoshio Sakamoto and Makoto Kanoh. It is a spin-off of Nintendo''s Mario franchise, featuring Mario (and, in two-player mode, Luigi) going through levels attempting to destroy certain objects. A sequel, Wrecking Crew ''98, was released only in Japan in 1998 for the Super Famicom, and the game''s legacy would continue beyond with appearances from its antagonist Spike in the Mario spin-off Mobile Golf (2001), the films The Super Mario Bros. Movie (2023) and The Super Mario Galaxy Movie (2026), and its Golden Hammer appearing as an item in the Super Smash Bros. series.', 'https://en.wikipedia.org/wiki/Wrecking_Crew_(video_game)'),
  ('Q4035116', 'BioMetal is a single-player horizontally scrolling shooter released on June 1, 1993, for the Super NES.

The game features six different weapons to combat the BioMetals, an extraterrestrial race determined to destroy the human race. The gameplay is very similar to that of the R-Type series, with the final boss even greatly resembling and behaving similarly to that series'' iconic boss enemy Dobkeratops.

The European and North American versions of BioMetal feature a soundtrack entirely created of four remixed songs of techno group 2 Unlimited from their 1991 album, Get Ready!. The Japanese version of the game features an entirely different soundtrack.', 'https://en.wikipedia.org/wiki/BioMetal_(video_game)'),
  ('Q4035407', 'Brett Hull Hockey is an ice hockey video game developed by Radical Entertainment and published by Accolade for the Super Nintendo Entertainment System in North America in January 1994. It features former Canadian-American NHL player Brett Hull and is officially licensed from the NHL Players'' Association.

Featuring the sports commentator Al Michaels as the play-by-play announcer, players have the choice to play across any of the game modes available against with either computer-controlled opponents or other players. Despite being licensed by the NHLPA, the game was not officially endorsed by the NHL and as such, all the teams are referred only by city with no use of the team name itself, in addition to not having either NHL team logos or NHL emblems to be seen anywhere in the title.', 'https://en.wikipedia.org/wiki/Brett_Hull_Hockey'),
  ('Q4047298', 'Power Piggs of the Dark Age is a 1997 hack and slash platform video game developed by Radical Entertainment and published by Titus France for the Super Nintendo Entertainment System. A Sega Mega Drive version was planned but never released.', 'https://en.wikipedia.org/wiki/Power_Piggs_of_the_Dark_Age'),
  ('Q4048363', 'Robotrek, known in Japan as Slapstick, is a role-playing video game (RPG) for the Super Nintendo Entertainment System (SNES). It was developed by Quintet and published by Enix in both Japan and North America in 1994. Set on the fictional planet Quintenix, the game puts the player in control of a budding robotics expert who is the son of a famous inventor.

As its Japanese name implies, Robotrek was intended as a humorous game. Designed to appeal to a younger audience, Robotrek''s main focus is on allowing the player to raise up to three robots which are built from spare parts that may be found, gained through battles, or generated by the player by means of the game''s item combination system.', 'https://en.wikipedia.org/wiki/Robotrek'),
  ('Q4043876', 'MechWarrior, known in Japan as BattleTech, is a first-person action video game for the Super NES set in the BattleTech universe. The SNES game was based upon the original PC MechWarrior, with updated graphics that utilized Mode 7 for the Battlemech mission sequences instead of the PC version''s flat-shaded 3D graphics.

The game was followed by a sequel, MechWarrior 3050, which is played from an isometric view.', 'https://en.wikipedia.org/wiki/MechWarrior_(1993_video_game)'),
  ('Q4051546', 'Todd McFarlane''s Spawn: The Video Game is a 1995 video game based on the Spawn comic book character. Developed by Ukiyotei and published by Acclaim Entertainment and Sony Electronic Publishing for the Super Nintendo Entertainment System in late 1995, it features Al Simmons, Spawn, trying to save the lives of thirteen children in a beat ''em up type of video game. The game received mixed reviews by critics; the graphics were praised while the unoriginality of the game was criticized.

When the video game was released, the Image Comics Spawn character was popular in the United States,[a] and this is the first video game based on the Spawn comic books.', 'https://en.wikipedia.org/wiki/Todd_McFarlane%27s_Spawn:_The_Video_Game'),
  ('Q4051081', 'The Flintstones: The Treasure of Sierra Madrock is a 1994 action-platform game developed and published by Taito for the Super Nintendo Entertainment System. The story of the game is generally based on the 1960s The Flintstones cartoon series. The title is a reference to the 1927 novel The Treasure of the Sierra Madre by B. Traven and its 1948 film adaptation.

In the opening story of the game, the Water Buffalos'' leader decides to retire. As his last decree as Great Poobah, he creates a contest in which whoever finds the Treasure of Sierra Madrock will be his successor. In the game, Fred Flintstone and Barney Rubble must find the treasure before any other Buffalo member (or even their wives, Wilma and Betty). The game features passwords to continue the game from the highest level reached.', 'https://en.wikipedia.org/wiki/The_Flintstones:_The_Treasure_of_Sierra_Madrock'),
  ('Q4051519', 'Tiny Toon Adventures: Buster Busts Loose! (released in Japan as Tiny Toon Adventures) is a video game for the Super NES console that is based on the animated TV series Tiny Toon Adventures. It was developed and published by Konami, released in 1992 in Japan and in 1993 in Europe and North America.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Buster_Busts_Loose!'),
  ('Q4051520', 'Tiny Toon Adventures: Wacky Sports Challenge is a sports video game. The game was released in 1994 for the Super Nintendo Entertainment System and developed and published by Konami. It is based on the American children’s television series, Tiny Toon Adventures. It is one of the few SNES games to feature an SNES Multitap as a useable controller.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Wacky_Sports_Challenge'),
  ('Q4048413', 'Romancing SaGa 3 is a 1995 role-playing video game developed and published by Square for the Super Famicom (Super Nintendo Entertainment System) as a Japanese exclusive. A remaster was released worldwide in 2019 by Square Enix for mobile platforms, consoles and Windows. The sixth entry in the SaGa series, it follows eight characters who are drawn into the search for the Child of Destiny, a figure who could bring either salvation or ruin to the world. Gameplay has the chosen character exploring the world, completing a variety of quests and with some characters engaging in campaign-specific mini-games. The turn-based combat carries over established SaGa mechanics including usage-based statistic growth and learning new moves based on a character''s weapons and combat actions.', 'https://en.wikipedia.org/wiki/Romancing_SaGa_3'),
  ('Q4353245', 'Alcahest is a 1993 action video game developed by HAL Laboratory and published by Square for the Super Famicom. The plot takes place in a world where an emperor leads his army towards conquest of the kingdom of Panakeia in the midst of the revival of the demon god Alcahest, who was previously defeated by a swordsman aided with the power of guardians. The player acts as the swordsman Alen, exploring and searching for items and power-ups, while fighting enemies and bosses. Throughout the journey, the player encounters guardians who help Alen with their power and allies who join his party to stop Alcahest.', 'https://en.wikipedia.org/wiki/Alcahest_(video_game)'),
  ('Q4384620', 'Mega Man Soccer is a soccer video game for the Super NES. The game is based on the original Mega Man series of action-platform games. Mega Man Soccer was released in Japan on March 25, 1994, and in North America in April of that same year.

Mega Man Soccer is a traditional soccer game with exhibition matches, tournaments, and leagues that can be played both single-player and multiplayer depending on the mode. The game features characters and Robot Masters from previous entries in the original Mega Man series. Each character has a unique special shot that will temporarily disable anyone that comes in contact with the ball. This aspect of Mega Man Soccer was met with critical praise, but overall reception has been average, particularly due to its controls and frame drops due to the sprites on screen.', 'https://en.wikipedia.org/wiki/Mega_Man_Soccer'),
  ('Q4675293', 'Acrobat Mission is a 1991 vertically scrolling shooter arcade video game developed by UPL and published by Taito. A port to the Super Famicom developed by Micronics was released in 1992.', 'https://en.wikipedia.org/wiki/Acrobat_Mission'),
  ('Q4415665', '4th Super Robot Wars is a tactical RPG for the Super Famicom developed by both Banpresto and Winky Soft and published by Banpresto. It is the 5th entry in the Super Robot Wars series and the last entry in the Classic Timeline. It was first released on March 17, 1995, and received mostly positive reception, with reviewers highly praising the improvements from the last game while criticizing the game''s increased difficulty. The game was ported to the Sony PlayStation and released on January 26, 1996, under the name 4th Super Robot Wars Scramble.', 'https://en.wikipedia.org/wiki/4th_Super_Robot_Wars'),
  ('Q4356532', 'Xak: The Art of Visual Stage is a 1989 role-playing video game developed and published by Microcabin. The first game in the Xak series, it was originally released for the PC-88 computer system, with subsequent versions being developed for the PC-98, X68000, MSX2, PC Engine, Super Famicom, and mobile phones. The first four versions were re-released for Windows on the online store Project EGG. An English translation of Xak: The Art of Visual Stage was also released in 2007 on the now-defunct retro gaming service WOOMB.net, and became available on Project EGG.', 'https://en.wikipedia.org/wiki/Xak:_The_Art_of_Visual_Stage'),
  ('Q4707360', 'The Legend of the Mystical Ninja is a 1991 action-adventure game released by Konami for the Super Nintendo Entertainment System. It was also ported to the Game Boy Advance along with Ganbare Goemon 2: Kiteretsu Shōgun McGuiness in 2005 only in Japan.

It is the first game in the Japanese video game series Ganbare Goemon to have a western release and the fifth mainline game overall. It has also been released for the Wii Virtual Console in 2007, the Wii U Virtual Console in 2013 (2014 in Europe and Australia), and the Nintendo 3DS Virtual Console in 2016. The game was re-released in 2026 via the Ganbare Goemon! Daishūgō compilation.', 'https://en.wikipedia.org/wiki/The_Legend_of_the_Mystical_Ninja'),
  ('Q4677160', 'Joe & Mac 2: Lost in the Tropics, known in PAL regions as Joe & Mac 3: Lost in the Tropics, is a 1994 platform video game developed and published by Data East for the Super Nintendo Entertainment System. It was initially released in Japan and North America in 1994, and in Europe by Elite Systems in 1995. It is a sequel to Joe & Mac and a follow-up to Congo''s Caper, the second game in the series.', 'https://en.wikipedia.org/wiki/Joe_%26_Mac_2:_Lost_in_the_Tropics'),
  ('Q4778649', 'Shoot! is a Japanese manga series written and illustrated by Tsukasa Ōshima. It was published in Kodansha''s Weekly Shōnen Magazine between 1990 and 2003. The story revolves around a boy named Toshihiko Tanaka, who had just started at Kakegawa High School in order to play association football with his idol, Yoshiharu Kubo. Toshi''s friends were not interested in playing football again until he convinces them to join the team and soon the team would enter the All-Japan High School Championship.

A 58-episode anime television series adaptation titled Aoki Densetsu Shoot! was produced by Toei Animation and broadcast between November 7, 1993, and December 25, 1994, on Fuji Television. A brand-new original anime television series by EMT Squared and Magic Bus titled Shoot! Goal to the Future aired from July 2 to September 24, 2022, on AT-X, Tokyo MX, TV Shizuoka, ytv, BS NTV, and BS Fuji. Noriyuki Nakamura directed the series alongside Junichi Kitamura serving as assistant director, Mitsutaka Hirota writing the scripts, and Yukiko Akiyama designing the characters. Crunchyroll streamed the series.', 'https://en.wikipedia.org/wiki/Shoot!_(manga)'),
  ('Q4726195', 'Epoch Company, Ltd. is a Japanese toy and computer games company founded in 1958 which is best known for manufacturing Barcode Battler and Doraemon video games, Aquabeads, and the Sylvanian Families series of toys. Its current Representative President is Michihiro Maeda.

They also made Japan''s first successful programmable console video game system, the Cassette Vision, in 1981.', 'https://en.wikipedia.org/wiki/Epoch_Co.'),
  ('Q4783378', 'Arabian Nights: Sabaku no Seirei-ō is a 1996 role-playing video game developed by Pandora Box and published by Takara for the Super Famicom.', 'https://en.wikipedia.org/wiki/Arabian_Nights:_Sabaku_no_Seirei-%C5%8D'),
  ('Q4789097', 'Aretha is a series of role-playing video games developed by Japan Art Media (JAM) and published by Yanoman Corporation to an exclusively Japanese market. It was originally released for the Game Boy in 1990. A sequel to the original trilogy named Aretha the Super Famicom was later released for the Super Famicom in 1993. Aretha was the first title in the game series of the same name. A collection of the Super Famicom trilogy is planned for release on July 30, 2026, for modern consoles exclusively for Japan.', 'https://en.wikipedia.org/wiki/Aretha_(video_game_series)'),
  ('Q4803477', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q4859481', 'Barbarossa is a 1992 Japan-exclusive Super Famicom strategy video game that revolves around Nazi Germany''s involvement in the World War II campaign called Operation Barbarossa.

The game was originally ported from the Japanese personal computer to the Super Famicom.', 'https://en.wikipedia.org/wiki/Barbarossa_(video_game)'),
  ('Q4870121', 'Battle Submarine is a submarine simulator video game, published by Pack-In-Video, which was released exclusively in Japan in 1995.', 'https://en.wikipedia.org/wiki/Battle_Submarine'),
  ('Q4870126', 'Battle Zeque Den is a Japan-exclusive video game for the Super Famicom.', 'https://en.wikipedia.org/wiki/Battle_Zeque_Den'),
  ('Q4870093', 'Compati Hero is a video game series published in Japan by Banpresto and Bandai Namco Entertainment that began in 1990 and features 16 crossover teams between Ultraman, Kamen Rider (also known as Masked Rider) and Gundam. Characters from other franchises have also been featured in some of the initial games, as well as in the Compati Sports series such as Mazinger, Getter Robo, Devilman and Godzilla.

It was the first video game series to involve a crossover between animated giant robots and live action tokusatsu heroes from different established franchises. The series makes this possible by using caricaturized versions of the characters (officially referred to as "SD" or "super deformed" characters), which allowed the different heroes and villains to co-exist and interact with each other without the need to reconcile their contrasting styles, settings, or sizes. This also made them appear cute. The first game in the series, SD Battle Ōzumō: Heisei Hero Basho for the Famicom, which mixed franchises that were originally licensed to Popy, was developed as a congratulatory present to Yukimasa Sugiura when he was promoted to president of Banpresto at the time, and was soon followed by series of spin-offs and related games featuring the same cast of characters that developed into the Compati Hero Series. The crossover was also possible due to Banpresto''s parent company Bandai holding the merchandising rights for all the properties associated with the series.', 'https://en.wikipedia.org/wiki/Compati_Hero'),
  ('Q4870115', 'Compati Hero is a video game series published in Japan by Banpresto and Bandai Namco Entertainment that began in 1990 and features 16 crossover teams between Ultraman, Kamen Rider (also known as Masked Rider) and Gundam. Characters from other franchises have also been featured in some of the initial games, as well as in the Compati Sports series such as Mazinger, Getter Robo, Devilman and Godzilla.

It was the first video game series to involve a crossover between animated giant robots and live action tokusatsu heroes from different established franchises. The series makes this possible by using caricaturized versions of the characters (officially referred to as "SD" or "super deformed" characters), which allowed the different heroes and villains to co-exist and interact with each other without the need to reconcile their contrasting styles, settings, or sizes. This also made them appear cute. The first game in the series, SD Battle Ōzumō: Heisei Hero Basho for the Famicom, which mixed franchises that were originally licensed to Popy, was developed as a congratulatory present to Yukimasa Sugiura when he was promoted to president of Banpresto at the time, and was soon followed by series of spin-offs and related games featuring the same cast of characters that developed into the Compati Hero Series. The crossover was also possible due to Banpresto''s parent company Bandai holding the merchandising rights for all the properties associated with the series.', 'https://en.wikipedia.org/wiki/Compati_Hero'),
  ('Q4870027', 'Battle Cross is an action racing video game published by Imagineer, which was released exclusively in Japan in 1994 for the Super Famicom.', 'https://en.wikipedia.org/wiki/Battle_Cross_(1994_video_game)'),
  ('Q4907338', 'Bike Daisuki! Hashiriya Kon - Rider''s Spirits is a 1994 video game for the Super Famicom. It is a racing game that allows players to race on motorcycles.', 'https://en.wikipedia.org/wiki/Bike_Daisuki!_Hashiriya_Kon_%E2%80%93_Rider%27s_Spirits'),
  ('Q4920000', 'BlaZeon is a horizontally scrolling shoot ''em up arcade game released by Atlus in 1992 and was ported to the Super Nintendo Entertainment System in the same year. The game''s most distinguishable feature is that players come equipped with a device that allows them to freeze and control certain robots.', 'https://en.wikipedia.org/wiki/BlaZeon'),
  ('Q4914116', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q4974003', 'Bronkie the Bronchiasaurus is an educational platform video game developed by American studio WaveQuest and published by Raya Systems for the Super Nintendo Entertainment System. It is a part of educational video game series from Raya that includes Captain Novolin, Rex Ronan: Experimental Surgeon and Packy and Marlon.', 'https://en.wikipedia.org/wiki/Bronkie_the_Bronchiasaurus'),
  ('Q4979561', 'Brunswick World: Tournament of Champions is a Super NES bowling video game that engages players in the life of an aspiring bowler who wants to make it to the top of the professional bowling world.', 'https://en.wikipedia.org/wiki/Brunswick_World:_Tournament_of_Champions'),
  ('Q4994671', 'Equinox is an action adventure puzzle video game developed by Software Creations and published by Sony Imagesoft for the Super NES. A sequel to Solstice (1990) for the Nintendo Entertainment System, Equinox depicts Glendaal saving his father Shadax, the previous game''s playable character, from the imprisonment of Sonia, Shadax''s apprentice. The player acts as Glendaal, exploring 458 rooms in eight underground dungeons. The player collects 12 blue orb tokens while solving puzzles, killing enemies, collecting keys, navigating platforms and blocks, and battling bosses. It continues Solstice''s isometric puzzle game style, with a greater emphasis on action adventure and the Mode 7 overworld map.', 'https://en.wikipedia.org/wiki/Equinox_(1993_video_game)'),
  ('Q4955774', 'Brain Lord is an action role-playing video game developed by Produce! and published by Enix for the Super NES. It was only released in Japan and North America.', 'https://en.wikipedia.org/wiki/Brain_Lord'),
  ('Q5034539', 'Capcom''s MVP Football is a sports game for the Super Nintendo Entertainment System which simulates the American football game of the NFL, released in North America.', 'https://en.wikipedia.org/wiki/Capcom%27s_MVP_Football'),
  ('Q5016060', 'Cacoma Knight in Bizyland, known in Japan as Cacoma Knight is a Super NES video game created by Datam Polystar. Seta USA created the English version of the game. The Japanese version is copyrighted in 1992, and the English version is copyrighted in 1993. The title is a pun on kakomanai to, meaning "must surround".', 'https://en.wikipedia.org/wiki/Cacoma_Knight_in_Bizyland'),
  ('Q5046338', 'Carrier Aces is a flight simulation game released for the Super Nintendo Entertainment System in 1995.', 'https://en.wikipedia.org/wiki/Carrier_Aces'),
  ('Q5095333', 'Chibi Maruko-chan is a manga series written and illustrated by Momoko Sakura. The series depicts the simple, everyday life of Momoko Sakura, a young girl everyone calls Maruko, and her family in suburban Japan in the year 1974. Maruko is a troublemaker, and every episode recounts Maruko''s trouble and how she and her friends succeed in resolving the situation.

The series is set in the former Irie District, Shimizu, now part of Shizuoka City, birthplace of its author.

The first story under the title "Chibi Maruko-chan" was published in the August 1986 edition of the manga magazine Ribon. Other semi-autobiographical stories by the author had appeared in Ribon and Ribon Original in 1984 and 1985, and were included in the first "Chibi Maruko-chan" tankōbon in 1987. The author first began writing and submitting strips in her final year of senior high school, although Shueisha (the publisher of Ribon and Ribon Original) did not decide to run them until over a year later. The author''s intent was to write "essays in manga form"; many stories are inspired by incidents from her own life, and some characters are based on her family and friends. The nostalgic, honest and thoughtful tone of the strip led to its becoming popular among a wider audience.', 'https://en.wikipedia.org/wiki/Chibi_Maruko-chan'),
  ('Q5095337', 'Chibi Maruko-chan is a manga series written and illustrated by Momoko Sakura. The series depicts the simple, everyday life of Momoko Sakura, a young girl everyone calls Maruko, and her family in suburban Japan in the year 1974. Maruko is a troublemaker, and every episode recounts Maruko''s trouble and how she and her friends succeed in resolving the situation.

The series is set in the former Irie District, Shimizu, now part of Shizuoka City, birthplace of its author.

The first story under the title "Chibi Maruko-chan" was published in the August 1986 edition of the manga magazine Ribon. Other semi-autobiographical stories by the author had appeared in Ribon and Ribon Original in 1984 and 1985, and were included in the first "Chibi Maruko-chan" tankōbon in 1987. The author first began writing and submitting strips in her final year of senior high school, although Shueisha (the publisher of Ribon and Ribon Original) did not decide to run them until over a year later. The author''s intent was to write "essays in manga form"; many stories are inspired by incidents from her own life, and some characters are based on her family and friends. The nostalgic, honest and thoughtful tone of the strip led to its becoming popular among a wider audience.', 'https://en.wikipedia.org/wiki/Chibi_Maruko-chan'),
  ('Q5129819', 'ClayFighter 2: Judgment Clay is a 1995 fighting game developed and published by Interplay Productions for the Super Nintendo Entertainment System. It is the sequel to the 1993 game ClayFighter.', 'https://en.wikipedia.org/wiki/ClayFighter_2:_Judgment_Clay'),
  ('Q5130099', 'Claymates is a platform video game developed by Visual Concepts and published by Interplay Productions for the Super Nintendo Entertainment System (SNES). It is one of Interplay''s clay animation titles which also included the ClayFighter series.', 'https://en.wikipedia.org/wiki/Claymates'),
  ('Q5104837', 'Choplifter III is a shoot ''em up video game released for the Super Nintendo Entertainment System in 1994. It was the third Choplifter title starting with the original Apple II game released in 1982.

A portable version of the game was released for the Game Gear, but this version was actually a remake of Choplifter II. This version of the game was subsequently re-released for the Game Boy.', 'https://en.wikipedia.org/wiki/Choplifter_III'),
  ('Q5174254', 'Cosmo Gang the Puzzle is a 1992 falling block puzzle video game developed and published by Namco for arcades. The third game in its Cosmo Gang series, succeeding that year''s Cosmo Gang the Video, players stack groups of blocks and aliens known as Jammers in a vertical-oriented well. The objective is to clear as many objects on the screen before they reach the top of the screen. Blocks are cleared by aligning them into complete horizontal rows, while Jammers are cleared by defeating them with blue-colored spheres.

Namco ported the game to the Super Famicom a year later in 1993. This version of the game was reworked and reskinned as Pac-Attack for North American and European markets, and was later ported to other consoles such as the Sega Genesis and Game Boy. Cosmo Gang the Puzzle was met with a mixed reception from critics, being praised for its multiplayer aspect and gameplay but criticized for its graphics.', 'https://en.wikipedia.org/wiki/Cosmo_Gang_the_Puzzle'),
  ('Q5174255', 'Cosmo Gang the Video is a 1992 fixed shooter video game developed and published by Namco for arcades. Controlling the Hyper Beat starship, the player is tasked with ridding the galaxy of the Cosmo Gang, a race of aliens that cause mischief across Earth. Gameplay involves shooting enemies and avoiding projectiles. Power-up items can be collected to grant the player additional abilities. It ran on the Namco System 2 arcade board.

Cosmo Gang the Video features characters and ideas from Cosmo Gangs, an older Namco redemption game from 1990 that was exported outside Japan by Data East. The game is heavily based on the company''s own Galaxian series, with early versions shown at tradeshows being titled Cosmo Galaxian. The arcade version of Cosmo Gang the Video was widely successful and well-received for its graphics, gameplay and music. A home conversion for the Super Famicom was released the same year, which was met with a more mixed response for its simplistic gameplay and lacking replay value. It was followed by Cosmo Gang the Puzzle later that same year. The arcade version was digitally re-released for the Japanese Wii Virtual Console in 2009. It was also re-released by Hamster Corporation for the Nintendo Switch and PlayStation 4 as part of the Arcade Archives series on April 20, 2023.', 'https://en.wikipedia.org/wiki/Cosmo_Gang_the_Video'),
  ('Q5167369', 'Cool World is an action video game developed by British studio Painting By Numbers. It was released by Ocean Software in 1993 for the Super Nintendo Entertainment System. It is loosely based on the 1992 movie of the same name. Both the European and North American versions are in English.

In contrast to the computer/Game Boy and NES versions, this version of the game plays more like an adventure game. It is the only version of the game that allows players to control Jack Deebs, who must avoid the advances of Holli Would and return home.

Cool World was first mentioned in issue #47 (April 1993) of the North American video gaming magazine Nintendo Power.', 'https://en.wikipedia.org/wiki/Cool_World_(SNES_video_game)'),
  ('Q5172106', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q5226435', 'Xardion is a platform game where the player controls robots with different skills in order to defeat the enemy and reach goals.', 'https://en.wikipedia.org/wiki/Xardion'),
  ('Q5203255', 'D-Force is a 1991 vertically scrolling shooter video game developed and published in Japan by Asmik for the Super Famicom and later localized and published in North America by Asmik Corporation of America for the Super NES. It involves an Apache helicopter set on defeating an evil Middle Eastern dictator. There are seven levels which feature six countries. Some of the levels involve switching altitudes in order to attack enemies from a different height, which uses Mode 7, one of the main features of the Super NES.', 'https://en.wikipedia.org/wiki/D-Force'),
  ('Q5275469', 'Dig & Spike Volleyball - known as Volleyball Twin in Japan - is a volleyball video game developed by TOSE. The player can choose either two variations: Men''s indoor volleyball and Women''s beach volleyball. The game was published by Nintendo, and released on the Super Nintendo Entertainment System on November 26 in Japan, and in December 1993 in North America', 'https://en.wikipedia.org/wiki/Dig_%26_Spike_Volleyball'),
  ('Q5252820', 'Dekitate High School is a Super Famicom video game that was released to an exclusively Japanese market in 1995 and was considered to be the first "high school simulation" video game to be released for the Super Famicom. Famed Japanese illustrator Nishiki Yoshimune would draw the cover art for the game, while the actual character design was done by the in-house staff at C-Lab.

The game involves going through a day of high school in Japan as a teacher while managing a star pupil to good grades and popularity. Players can even build their own high schools for the purpose of gameplay, making this game similar to SimCity. A massive amount of yen is given at the start; so players can assign all the classes and even create yards of grass for students to loiter in between classes. Socializing with an assigned student will be more than just teaching her kanji and arithmetic lessons. Menus and multiple choices are used to get through the game with a first-person perspective.', 'https://en.wikipedia.org/wiki/Dekitate_High_School'),
  ('Q5259105', 'Dennis the Menace (known as Dennis in Europe) is a platform game adaptation of the 1993 film of the same name which itself is based on the Dennis the Menace comic strip. It was released for the Game Boy, Super Nintendo Entertainment System, and Amiga. The object of the game is to defeat the antagonist from the film, Switchblade Sam, who managed to find Dennis'' town via the local railroad connection. Stages include Mr. Wilson''s house, the great outdoors, a boiler room, and eventually a boss battle with Switchblade Sam.', 'https://en.wikipedia.org/wiki/Dennis_the_Menace_(video_game)'),
  ('Q5278473', 'DinoCity is a 1992 platform video game developed and published by Irem Corporation for the Super Nintendo Entertainment System.

The game is loosely based on the 1991 made-for-television film Adventures in Dinosaur City, and borrows many of the film''s characters, settings, and basic plot while providing its own unique art direction and style. Initially released in July 1992 in Japan, the game was later made available in North America the following September. The game centers on two friends, Timmy and Jamie, young children who are accidentally transported to a world resembling prehistoric Earth populated by anthropomorphic dinosaurs. While a device which will allow them to return home exists in this environment, a critical component has been stolen by Mr. Big, leader of a gang of Neanderthals known as The Rockeys, leaving the player to guide Timmy or Jamie to his castle to retrieve it. They are assisted by Rex, a Tyrannosaurus, and Tops, a Protoceratops, each with their own play-styles.', 'https://en.wikipedia.org/wiki/DinoCity'),
  ('Q5280939', 'Dirt Racer is a Europe-exclusive video game for the Super Nintendo Entertainment System developed by British studio MotiveTime and released in 1995. This game uses the Super FX powered GSU-1 to provide enhanced graphics.', 'https://en.wikipedia.org/wiki/Dirt_Racer'),
  ('Q5280947', 'Dirt Trax FX is a racing video game developed by Sculptured Software and released by Acclaim Entertainment for the Super Nintendo Entertainment System in 1995. The 3D graphics of the game were made possible by the Super FX powered GSU-1, which was built into the cartridge.', 'https://en.wikipedia.org/wiki/Dirt_Trax_FX'),
  ('Q5305302', 'Dragon View, released in Japan as Super Drakkhen, is a 1994 action role-playing video game developed and published by Kemco for the Super Nintendo Entertainment System. It is a follow-up but not a direct sequel to Infogrames'' Drakkhen. It uses the same pseudo-3D overworld system for which the series is most famous. Other features of Dragon View are its side-view action role-playing game (RPG) hybrid gameplay (used when exploring more detailed areas such as towns and dungeons), its well translated first-person storyline, and its emphasis on player-driven undirected exploration. In 2019, the game was re-released through emulation for Windows. In 2022, a reproduction SNES cartridge was released by Limited Run Games.', 'https://en.wikipedia.org/wiki/Dragon_View'),
  ('Q5310171', 'Dual Orb II is a role-playing video game released in 1994 for the Super Famicom by I''MAX. It is the sequel of Dual Orb: Seireiju Densetsu.

It was the first game Hiroyuki Kotani, known for the Patapon series, was involved in.', 'https://en.wikipedia.org/wiki/Dual_Orb_II'),
  ('Q5306455', 'Dream TV is an action video game for the Super NES where the player has to guide two youngsters through a nightmarish land of evil television shows (using a similar plot to the campy movie Stay Tuned and Crystal Dynamics'' video game Gex). The player has to escape by defeating stereotypical television villains and finding pieces of a puzzle. The game features complex labyrinths.', 'https://en.wikipedia.org/wiki/Dream_TV_(video_game)'),
  ('Q5297127', 'Doomsday Warrior, known in Japan as Taiketsu!! Brass Numbers, is a SNES fighting game developed and published by Telenet Japan''s subsidiary Laser Soft in Japan on November 20, 1992, and later localized by Renovation Products in North America in March 1993. It was created during the fighting game trend of the 1990s that was popularized by Capcom''s Street Fighter II.

Doomsday Warrior was added to the Nintendo Classics service in February 2021.', 'https://en.wikipedia.org/wiki/Doomsday_Warrior_(video_game)'),
  ('Q5299321', 'Dossun! Ganseki Battle is a puzzle video game released in 1994 for the Super Famicom by I''MAX.', 'https://en.wikipedia.org/wiki/Dossun!_Ganseki_Battle'),
  ('Q5318930', 'Sammy Corporation is a Japanese developer and retailer of video game and gambling products and subsidiary of Sega Sammy Holdings, headquartered in Shinagawa, Tokyo. Sammy manufactures pachinko and pachislot machines, and it expanded into video game development in the 1990s with games such as Viewpoint, Survival Arts, and The Rumble Fish.

Sammy was founded as Sammy Industry on November 1, 1975 as a spin-off of the arcade division of Satomi Corporation. The company primarily dealt with slot machines and arcade cabinets in Japan. Sammy largely left the video game industry by the late 1990s to focus on its pachinko and arcade management operations. In 2004, the company merged with video game developer and publisher Sega to form Sega Sammy Holdings.', 'https://en.wikipedia.org/wiki/Sammy_Corporation'),
  ('Q5289693', 'ZOOM Inc. is a Japanese video game company based in Sapporo. The company was started by Akira Sato and initially produced a few titles for the X68000 system including Lagoon and Phalanx.

In April 1993, Zoom established a joint venture with Imagineer before it was disbanded in January 1995; together they had released a Super Famicom baseball game, Dolucky no Kusayakiu, which was slated for an American release as Zoo Ball but was cancelled. They developed a fighting game as a PlayStation launch title, Zero Divide, as well as an adaptation of Rurouni Kenshin: Ishin Gekitōhen, and later developed Mister Mosquito on PlayStation 2.', 'https://en.wikipedia.org/wiki/Zoom_(video_game_company)'),
  ('Q5303022', 'Down the World: Mervil''s Ambition is a role-playing video game (RPG) developed and published by ASCII Corporation for the Super Famicom. The plot follows the knight Gao, tasked with accompanying a hero (the player) in rescuing an ailing princess and preventing the end of all life.

Down the World contains traditional gameplay tropes from console RPGs such as exploration of dungeons, recruitment of new party members, and completion of quests to advance the plot. The game''s turn-based battles with enemies are largely automatic, where the player chooses from a set of tactical formations containing roles for characters to act out.', 'https://en.wikipedia.org/wiki/Down_the_World:_Mervil%27s_Ambition'),
  ('Q5492456', 'Frantic Flea is an action game developed by Haüs Teknikka and published in 1996 by GameTek for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Frantic_Flea'),
  ('Q5439905', 'Feda: The Emblem of Justice is a tactical role playing game developed by Max Entertainment and published by Yanoman Games that was originally released for the Super Famicom in 1994. The game centers on two soldiers forced to fight against the now-corrupted empire they used to serve. A version for the Sega Saturn, titled Feda Remake!, was released in 1996. Both versions were released exclusively in Japan.', 'https://en.wikipedia.org/wiki/Feda:_The_Emblem_of_Justice'),
  ('Q5424172', 'F1 ROC II: Race of Champions, originally released in Japan as Exhaust Heat II, is a 1993 racing video game developed and published by SETA Corporation for the Super Nintendo Entertainment System. It is the sequel to F1 ROC: Race of Champions, and similarly features Formula One licensing. Unlike that game, F1 ROC II was not released in Europe.', 'https://en.wikipedia.org/wiki/F1_ROC_II:_Race_of_Champions'),
  ('Q5449444', 'Final Stretch is a 1993 Japan-exclusive Super Famicom Formula One racing video game licensed by FOCA to Fuji Television, which is based on the 1993 Formula One season.

The game was supervised by Aguri Suzuki and can be considered as the sequel to Aguri Suzuki F-1 Super Driving. It features a DSP-1 chip. In single-player mode, there is a split screen and the player is given five views to choose from (top view, side view, turn view, camera view and back view), while controlling the car in the typical chase view. There are up to five laps on a given race and speeds can reach an average of 328 kilometres per hour (204 mph).', 'https://en.wikipedia.org/wiki/Final_Stretch_(video_game)'),
  ('Q5463439', 'Flying Hero: Bugyuru no Daibouken is a vertically scrolling shooter developed by Sting Entertainment and published by SOFEL. It was released in Japan on December 18, 1992 for the Super Famicom. The game was not released in other countries.', 'https://en.wikipedia.org/wiki/Flying_Hero'),
  ('Q5432910', 'Nintendo Research & Development No. 1 Department (commonly abbreviated as Nintendo R&D1 and formerly known as Nintendo Research & Development Department before splitting in 1978) was a division of Nintendo, and is its oldest development team. Its creation coincided with Nintendo''s entry into the video game industry, and the original R&D1 was headed by Gunpei Yokoi. The developer has created several notable Nintendo series such as Donkey Kong, Mario, and Metroid.

R&D1 developed the hugely successful Game Boy line, which was released in 1989. They developed some of the line''s most popular games, such as Super Mario Land, and created the character of Wario.', 'https://en.wikipedia.org/wiki/Nintendo_Research_%26_Development_1'),
  ('Q5485525', 'Jikkyō Power Pro Wrestling ''96: Max Voltage is a 1996 pro wrestling video game by Konami, released exclusively in Japan for the Super Famicom.', 'https://en.wikipedia.org/wiki/Jikky%C5%8D_Power_Pro_Wrestling_%2796:_Max_Voltage'),
  ('Q5452005', 'Firestriker is an overhead view action video game that was released on December 17, 1993 in Japan and in October 1994 in North America for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Firestriker'),
  ('Q5465840', 'Football Fury is a Super NES video game that was released in 1992. The game''s full Japanese name is Ultimate Football: Try Formation!.', 'https://en.wikipedia.org/wiki/Football_Fury'),
  ('Q5376904', 'Neverland Company Inc. was a Japanese video game developer founded on May 7, 1993. It has developed games for Super NES, Dreamcast, GameCube, PlayStation 2, Game Boy Color, Nintendo DS, Nintendo 3DS, PlayStation Portable, PlayStation 3 and the Wii. The most notable games this company developed were part of the Lufia and Rune Factory series of video games. By November 2013, the company ceased operations and filed for bankruptcy. The following year, many former members of the studio were hired by Marvelous, who had published many of its previous games.', 'https://en.wikipedia.org/wiki/Neverland_(company)'),
  ('Q5373594', 'Emmitt Smith Football is an American football video game released exclusively for the Super NES in North America. Its namesake is former all-pro running back Emmitt Smith of the 1994 Dallas Cowboys. There is no official use of any licenses other than the Emmitt Smith name, making the teams and players fictional.

The game received mediocre reviews from critics, most of whom remarked that the innovative play editor feature is the one thing that keeps the game from being terrible.', 'https://en.wikipedia.org/wiki/Emmitt_Smith_Football'),
  ('Q5422147', 'Extra Innings is a 1991 baseball video game released for the Super NES. The game features 12 fictional teams composed of their own fictional players, drawn in an anime style. Players can also create two custom teams, the players of which can have their names and ratings edited any number of times. For the most part, the game adhered to realistic rules of baseball; it omitted some more complex strategies such as the double switch.

Extra Innings''s controls were unlike many of the era, featuring pitches with vertical break, diving and sliding catches that could be assisted by the AI, and independent runner control (selecting the destination base with the D-pad and Y would advance the runner; the origin base on the D-pad and B would make an individual runner retreat).', 'https://en.wikipedia.org/wiki/Extra_Innings_(video_game)'),
  ('Q5508155', 'Full Throttle: All-American Racing, known in Japan as Full Power, is a racing video game released in 1994 by Gremlin Interactive for the SNES. In Japan, it was published by Coconuts Japan, in North America by Cybersoft, and in Europe by GameTek. In April 2021, it was released as part of Piko Interactive Collection 2 for the Evercade by Blaze Entertainment.', 'https://en.wikipedia.org/wiki/Full_Throttle:_All-American_Racing'),
  ('Q5514136', 'GP-1 is a motorcycle racing game developed by Genki and published by Atlus for the SNES, which was released in 1993. It was followed by a sequel, GP-1: Part II.', 'https://en.wikipedia.org/wiki/GP-1'),
  ('Q5508636', 'Fun ''n Games (Sometimes spelled Fun ''N'' Games) is a compilation video game developed by Leland Interactive Media and released for the Mega Drive/Genesis and Super NES platforms in 1993 and 1994 respectively. In 1995, an updated, redeveloped version of the game was released on the 3DO Interactive Multiplayer and MS-DOS by Williams Entertainment Inc. The North American Super NES version of the game is considered to be one of the more rare games released for the console.', 'https://en.wikipedia.org/wiki/Fun_%27n_Games'),
  ('Q5517684', 'Gakkō de Atta Kowai Hanashi is a visual novel for the Super Famicom that was released in 1995 by Banpresto in Japan. The in-game graphics make use of digitized photographs.

In 1996, a remake for the PlayStation Gakkō de Atta Kowai Hanashi S, was released. It featured improved graphics, full motion video, and an expanded story.

The game was developed by Pandora Box (game developer), a studio founded by game designer and scenario writer Takeo Iijima. The characters and setting would later be used in the Apathy franchise of Visual and Sound Novel games.', 'https://en.wikipedia.org/wiki/Gakk%C5%8D_de_Atta_Kowai_Hanashi'),
  ('Q5518147', 'Galaxy Wars is a fixed shooter arcade video game developed by Universal and published by Taito in 1979.', 'https://en.wikipedia.org/wiki/Galaxy_Wars'),
  ('Q5514138', 'GP-1: Part II, known in Japan as GP-1 RS: Rapid Stream, is a motorcycle racing game developed by Genki and published by Atlus for the SNES, which was released in 1994. It is a sequel to GP-1.', 'https://en.wikipedia.org/wiki/GP-1:_Part_II'),
  ('Q5521476', 'Gunple: Gunman''s Proof is a 1997 Japanese video game for the Super Famicom. It was developed by Lenar and published by ASCII. It was one of the latest releases for the Super Famicom, and was never released outside of Japan. It is a 2D top down action-adventure video game set in the American Wild West that incorporates some science fiction elements.', 'https://en.wikipedia.org/wiki/Gunple:_Gunman%27s_Proof'),
  ('Q5576343', 'Tengai Makyō Zero (天外魔境ゼロ) is a 1995 role-playing video game developed by Red Company and published by Hudson Soft for the Super Famicom. The game was released exclusively in Japan on December 22, 1995, and is an installment in the Tengai Makyō series.', 'https://en.wikipedia.org/wiki/Tengai_Maky%C5%8D_Zero'),
  ('Q5595760', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q5618284', 'GunForce (also known as GunForce: Battle Fire Engulfed Terror Island) is a side-scrolling run and gun video game produced by Irem for arcades in 1991. The game was ported by Bits Studios and published by Irem for the Super Nintendo Entertainment System in 1992. The sequel, GunForce II, was originally known in Japan as Geo Storm.', 'https://en.wikipedia.org/wiki/GunForce'),
  ('Q5846885', 'The Ignition Factor, known in Japan as Fire Fighting, is a video game for the Super Nintendo Entertainment System published by Jaleco. The game features firefighters in realistic situations saving civilians in burning buildings, mining incidents, and industrial accidents. It was released on the Wii Virtual Console in Japan on March 1, 2011, in the PAL region on April 29, 2011, and in North America on August 25, 2011, as well as the Nintendo Classics service on December 18, 2020.', 'https://en.wikipedia.org/wiki/The_Ignition_Factor'),
  ('Q5640683', 'HAL''s Hole in One Golf is a golf video game developed and published by HAL Laboratory for the Super Nintendo Entertainment System in 1991.', 'https://en.wikipedia.org/wiki/Hal%27s_Hole_in_One_Golf'),
  ('Q5645599', 'HammerLock Wrestling is a professional wrestling game for the Super NES that was released in 1994. In Japan, this game was called Tenryu Genichiro no Pro Wrestling Revolution.', 'https://en.wikipedia.org/wiki/HammerLock_Wrestling'),
  ('Q5648657', 'Hanna Barbera''s Turbo Toons is a 1994 racing video game developed and published by Empire Interactive in Europe for the Super Nintendo Entertainment System. Players compete in footraces featuring a choice of six Hanna-Barbera characters, including Huckleberry Hound, Quick Draw McGraw, Top Cat, Snagglepuss, Hong Kong Phooey, and Yogi Bear. During races, the players can also gather crystals that enhance their abilities or harm their opponents.

Turbo Toons was co-designed by artist Graham Rice and programmer Adrian Barritt. Barritt aimed to create a five-player game where characters interacted by knocking each other off the track, borrowing aspects from the racing game Super Sprint. The team found Hanna-Barbera difficult to work with, as the studio insisted that the characters look like "perfect" duplicates of the original cartoons. Production began in February 1994 and concluded in July 1994. Additional versions were planned for release in North America and on the Sega Mega Drive, but were never published.', 'https://en.wikipedia.org/wiki/Hanna_Barbera%27s_Turbo_Toons'),
  ('Q5888431', 'Home Improvement: Power Tool Pursuit! is a 1994 2D platform game, based on the sitcom of the same name, developed by Imagineering and published by Absolute Entertainment for the Super Nintendo Entertainment System. A Sega Genesis version was planned but never released.', 'https://en.wikipedia.org/wiki/Home_Improvement:_Power_Tool_Pursuit!'),
  ('Q5636990', 'Habu Meijin no Omoshiro Shōgi is a Shogi video game, developed by Access and published by Tomy Corporation. It was exclusively released in Japan for the Super Famicom in 1995.

This game is endorsed and supervised by Yoshiharu Habu.', 'https://en.wikipedia.org/wiki/Habu_Meijin_no_Omoshiro_Sh%C5%8Dgi'),
  ('Q5620510', 'Gourmet Sentai Barayarō is a surrealistic side-scrolling beat-''em-up developed by Winds and published by Virgin Interactive Entertainment for the Super Famicom in 1995 only in Japan.

On January 30, 2018, the game was re-released by BlazePro/ Piko Interactive. In addition, Piko Interactive created and published a US SNES cartridge in 2019, for the first time with a full official English translation, titled Gourmet Warriors.', 'https://en.wikipedia.org/wiki/Gourmet_Warriors'),
  ('Q6014096', 'Incantation is a 1996 platform video game developed and published by Titus France for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Incantation_(video_game)'),
  ('Q5994649', 'Ihatovo Monogatari is a 1993 adventure video game for the Super Famicom. It was developed and published by Hector, a small Japanese game development company. The game visually has similarities to role-playing video games of the era, but features no combat or levelling-up systems. The game adapts several fairy tales by the Children''s literature author Kenji Miyazawa and predominantly features gameplay of collecting items and talking to non-playable characters. The ultimate goal in the game is to travel to the various areas and to gather the seven notebooks hidden within them.

Contemporary critics in Japanese video game magazines Hippon Super! and Famitsu complimented the atmosphere and narrative of the game, with some reviewers saying that it may prove to be frustrating and tedious in terms of gameplay. Retrospective reviews from Hardcore Gaming 101 also complimented the game''s atmosphere, while Vícto Navarro-Remesal wrote Ihatovo Monogatari was an early precursor to games like Harvest Moon (1996) that displayed RPG-like visuals, but featured no battle gameplay.', 'https://en.wikipedia.org/wiki/Ihatovo_Monogatari'),
  ('Q5968677', 'Tuff E Nuff, known in Japan as Dead Dance, is a 1993 fighting game developed and published by Jaleco for the Super Nintendo Entertainment System (SNES).', 'https://en.wikipedia.org/wiki/Tuff_E_Nuff'),
  ('Q5957614', 'Iria: Zeiram the Animation is a six-episode original video animation (OVA) anime series produced by Ashi Productions and directed by Tetsurō Amino. The series serves as a prequel to the original live-action film Zeiram, taking place several years earlier when the female bounty hunter protagonist Iria is still a rookie and detailing the events surrounding her first encounter with the unstoppable Zeiram. This does somewhat contradict the films, which imply that Iria''s first encounter with Zeiram was in the first film.', 'https://en.wikipedia.org/wiki/Iria:_Zeiram_the_Animation'),
  ('Q6038377', 'Inspector Gadget is a 1993 side-scrolling action video game for the Super Nintendo Entertainment System based on the television show of the same title. The game was released by Hudson Soft, with developers who also worked on Hudson''s video game adaptations SWAT Kats: The Radical Squadron and An American Tail: Fievel Goes West.

The normally bumbling Gadget is portrayed as fairly competent as he must rescue his niece Penny from the clutches of Dr. Claw and his M.A.D. terrorist organization. Dr. Claw''s face makes a rare appearance in the game, unlike the cartoon, which keeps his face hidden.', 'https://en.wikipedia.org/wiki/Inspector_Gadget_(video_game)'),
  ('Q6138822', 'Pop''n TwinBee: Rainbow Bell Adventures is a 1994 platform game published and developed by Konami for the Super Nintendo Entertainment System. It is the first platformer in the TwinBee series, departing from the vertically scrolling shooter genre.', 'https://en.wikipedia.org/wiki/Pop%27n_TwinBee:_Rainbow_Bell_Adventures'),
  ('Q6072413', 'Iron Commando is a 1995 beat ''em up video game developed by French developer Arcade Zone for the Super Nintendo Entertainment System. The game was scheduled to be released in Europe by Sony Electronic Publishing (who also published Arcade Zone''s previous title, Legend) sometime between 1994 and 1995, but was cancelled after Sony discontinued its third-party publishing business on the Super NES in order to focus on the PlayStation, leaving the title orphaned without a publisher. A Japanese localization was released by Pack-In-Video''s Poppo subsidiary on February 10, 1995.

Piko Interactive ended up acquiring the international publishing rights to Iron Commando, initially releasing the game digitally on Steam in 2016, before eventually producing a reproduction cartridge for the Super NES in 2017. BlazePro also produced a reproduction cartridge for the Super Famicom version for the Japanese market during the same year.', 'https://en.wikipedia.org/wiki/Iron_Commando'),
  ('Q6120028', 'Sonic Blast Man is a 1990 arcade video game by Taito starring the titular superhero, Sonic Blastman. A SNES adaptation appeared in 1992, with much different gameplay. Both versions received a sequel.', 'https://en.wikipedia.org/wiki/Sonic_Blast_Man'),
  ('Q6104210', 'Namco was a Japanese video game developer and publisher.

Bandai Namco Entertainment is the successor of Namco and continues manufacturing and distributing video games worldwide. For Namco games released following the 2006 merger with Bandai''s video game division, see List of Bandai Namco video games. For a list of franchises owned by Bandai Namco, see List of Bandai Namco video game franchises.', 'https://en.wikipedia.org/wiki/List_of_Namco_games'),
  ('Q6104208', 'J.League Super Soccer ''95: Jikkyō Stadium is a 1995 football video game that was released by Hudson Soft exclusively in Japan. It is a sequel to J.League Super Soccer.', 'https://en.wikipedia.org/wiki/J.League_Super_Soccer_%2795_Jikky%C5%8D_Stadium'),
  ('Q6125168', 'Jaki Crush is a pinball video game developed by Compile and published by NAXAT Soft. Jaki Crush was released exclusively in Japan for the Super Famicom in 1992. The game is the third in the Crush Pinball series, and was preceded by Alien Crush and Devil''s Crush (Devil Crash on the PC Engine in Japan) on the TurboGrafx-16.', 'https://en.wikipedia.org/wiki/Jaki_Crush'),
  ('Q6135416', 'Mickey no Tokyo Disneyland Daibōken is a 1994 platform game developed by Graphic Research Co. and published by Tomy for the Super Famicom. It is set in the Tokyo Disneyland theme park and follows the player as MIckey Mouse traversing through six different attractions in order to gather his friends after Pete told them it was an off-day. With the use of water and gas balloons, the player can attack enemies and navigate environmental obstacles.', 'https://en.wikipedia.org/wiki/Mickey_no_Tokyo_Disneyland_Daib%C5%8Dken'),
  ('Q6396663', 'Kevin Keegan''s Player Manager (German title: K. H. Rummenigge''s Player Manager) is a football (soccer) video game developed by British studio Anco Software and released for the Super Nintendo Entertainment System, featuring football manager Kevin Keegan.', 'https://en.wikipedia.org/wiki/Kevin_Keegan%27s_Player_Manager'),
  ('Q6197587', 'Jim Power: The Lost Dimension in 3-D is a 1993 platform video game developed by Loriciel and published by Electro Brain for the Super Nintendo Entertainment System and MS-DOS. A Sega Genesis version was developed but never released. In 2021, Piko Interactive recovered this version and crowdfunded a release, alongside a new Nintendo Entertainment System port. A version for the Nintendo Switch and PlayStation 4 was released on June 2, 2022.', 'https://en.wikipedia.org/wiki/Jim_Power:_The_Lost_Dimension_in_3-D'),
  ('Q6387712', 'Ken Griffey Jr.''s Winning Run is a 1996 baseball video game developed by Rare and published by Nintendo for the Super Nintendo Entertainment System. It is named after the baseball player Ken Griffey Jr. It is the follow-up to Nintendo''s previous Ken Griffey Jr. Presents Major League Baseball. Two years later, Nintendo released another game featuring Griffey, Major League Baseball Featuring Ken Griffey Jr., for the Nintendo 64.

The game''s title is derived from the final play of the 1995 American League Division Series featuring the Seattle Mariners and New York Yankees. On a play that is sometimes credited with "saving baseball in Seattle", Griffey scored the game''s winning run all the way from first base, on a close play in the bottom of the 11th inning.', 'https://en.wikipedia.org/wiki/Ken_Griffey_Jr.%27s_Winning_Run'),
  ('Q6203199', 'Jissen Kyōtei is a Japan-exclusive video game for the Super Famicom.', 'https://en.wikipedia.org/wiki/Jissen_Ky%C5%8Dtei'),
  ('Q6229862', 'Vortex is a 3D shooter game developed by Argonaut Software and released by Electro Brain for the Super Nintendo Entertainment System in September 1994. Titled Citadel during development, it is one of a few games designed to use the enhanced graphics of the Super FX powered GSU-1.', 'https://en.wikipedia.org/wiki/Vortex_(video_game)'),
  ('Q6143748', 'Lufia II: Rise of the Sinistrals, known as Estpolis Denki II in Japan, and as Lufia in Europe and Australia, is a role-playing video game with puzzle elements developed by Neverland and published in Japan in 1995 by Taito, and in North America and Europe in 1996 by Natsume and Nintendo respectively, for the Super Nintendo Entertainment System. It is the second game in the Lufia series.

The game is a prequel to Lufia & the Fortress of Doom. It follows the story of the first main character''s ancestor, Maxim, and explains the origins of the war between mankind and a group of gods called the Sinistrals. Lufia II made a number of changes from the first game. Dungeons no longer have random encounters and there are hundreds of puzzles throughout the game, ranging from simple to extremely challenging. It also introduced new skills, such as a variety of weapons that could be used to stun monsters or solve puzzles, and IP attacks. In 2010, Square Enix released a re-imagining of the original game titled Lufia: Curse of the Sinistrals.', 'https://en.wikipedia.org/wiki/Lufia_II:_Rise_of_the_Sinistrals'),
  ('Q6146317', 'Treasure Hunter G is a 1996 turn-based tactical role-playing game developed by Sting Entertainment and published by Square exclusively for the Super Famicom, and in Japan.', 'https://en.wikipedia.org/wiki/Treasure_Hunter_G'),
  ('Q6379742', 'Kawasaki Caribbean Challenge is a Super NES racing game released in 1993, exclusively for the North American market.', 'https://en.wikipedia.org/wiki/Kawasaki_Caribbean_Challenge'),
  ('Q6418169', 'Kiteretsu Daihyakka is a Japanese manga series by Fujiko F. Fujio, which ran in the children''s magazine Kodomo no Hikari from April 1974 to July 1977. The manga was later made into an animated anthology television special which aired in 1987 on Fuji Television and its affiliates and a 331-episode anime television series that ran on the same channel from March 27, 1988, to June 9, 1996.', 'https://en.wikipedia.org/wiki/Kiteretsu_Daihyakka'),
  ('Q6434735', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q6434771', 'Kōtetsu no Kishi 2: Sabaku no Rommel Shōgun is a Japan-exclusive video game that was released for the Super Famicom in 1994, and to the Windows operating system in 2002.

The Super Famicom version of this video game is a sequel to Kōtetsu no Kishi and is followed by Kōtetsu no Kishi 3: Gekitotsu Europe Sensen.', 'https://en.wikipedia.org/wiki/K%C5%8Dtetsu_no_Kishi_2:_Sabaku_no_Rommel_Sh%C5%8Dgun'),
  ('Q6434772', 'Kōtetsu no Kishi 3: Gekitotsu Europe Sensen is a Super Famicom strategy video game about Europe during World War II.

The player can play as either Nazi Germany or the Allied forces. The game is mostly in Japanese, although ASCII letters can be used when typing in names. Once in the game mode, the X button is used to confirm orders. Each stage has its own individual background sound that provides additional tension to the atmosphere. It is the final game in the Kōtetsu no Kishi trilogy, following Kōtetsu no Kishi and Kōtetsu no Kishi 2: Sabaku no Rommel Shōgun.', 'https://en.wikipedia.org/wiki/K%C5%8Dtetsu_no_Kishi_3:_Gekitotsu_Europe_Sensen'),
  ('Q6451361', 'Kyle Petty''s No Fear Racing is a stock car racing video game for the Super NES that was released in 1995.', 'https://en.wikipedia.org/wiki/Kyle_Petty%27s_No_Fear_Racing'),
  ('Q6488257', 'Laplace no Ma is a horror-themed role-playing video game released in 1987 by HummingBirdSoft for the NEC PC-8801 and NEC PC-9801. The game was also ported to various Japanese computers and later to consoles with Super Famicom and PC Engine Super CD-ROM². It became the first part of the Gōsuto Hantā series which includes both Kurokishi no Kamen (1994), Paracelsus no Maken (1994), and Gōsuto Hantā Arukeringa no Ma Umi (2020).', 'https://en.wikipedia.org/wiki/Laplace_no_Ma'),
  ('Q6472552', 'Lagoon is a top-view action/adventure video game for the X68000 and Super NES, in which Nasir (Nassel in the Japanese version), Champion of Light, must investigate the source of the world''s corrupted water and return peace to Lakeland.

Lagoon is an action role-playing game with a fantasy setting, very similar to the early Ys games, combining real-time action gameplay with RPG elements such as experience levels and equipment management. The player travels through an assortment of towns, landscapes, and dungeons while battling a variety of enemies ranging from insects to giant bosses, and gaining experience and items along the way.', 'https://en.wikipedia.org/wiki/Lagoon_(video_game)'),
  ('Q6434770', 'Kōtetsu no Kishi is a Japan-exclusive video game created by General Support which was originally released for the NEC PC-9801, and later ported for the Super Famicom.

The Super Famicom version of the game received the sequels named Kōtetsu no Kishi 2: Sabaku no Rommel Shōgun and Kōtetsu no Kishi 3: Gekitotsu Europe Sensen. There was an expansion pack for the original NEC PC-9801 version titled Tetsujūji Shō - Kōtetsu no Kishi Scenario, which added a new scenario.', 'https://en.wikipedia.org/wiki/K%C5%8Dtetsu_no_Kishi'),
  ('Q6470551', 'Lady Stalker: Challenge from the Past is an action role-playing game developed by Climax Entertainment and published by Taito for the Super Famicom in 1995. It is a spinoff of Landstalker and was designed with female gamers in mind. Challenge from the Past is the only game related to Landstalker that was never released outside Japan, though the main character appeared in the Dreamcast title Time Stalkers.

A sequel, Lady Stalker 2D: The Solitary Ruler of the Calendar, was announced in 2026, with a physical Famicom release planned following a successful kickstarter.', 'https://en.wikipedia.org/wiki/Lady_Stalker:_Challenge_from_the_Past'),
  ('Q6411248', 'King Arthur & the Knights of Justice is an action-adventure game developed by Manley & Associates and published by Enix for the Super Nintendo Entertainment System in May 1995. Based on the cartoon series of the same title, which was loosely inspired by the Arthurian legend, the game was released in North America exclusively.

The player takes on the role of a team of American football players who are transported to medieval England and given the mission to save King Arthur and destroy the evil sorceress Morgana and her army. The game was the first Enix title developed by an American company, and was inspired in-part by The Legend of Zelda. It was received with reviews ranging from mediocre to extremely poor.', 'https://en.wikipedia.org/wiki/King_Arthur_%26_the_Knights_of_Justice_(video_game)'),
  ('Q6531992', 'Lester the Unlikely is a 1994 platform video game developed by Visual Concepts for the Super Nintendo Entertainment System (SNES).', 'https://en.wikipedia.org/wiki/Lester_the_Unlikely'),
  ('Q6508715', 'Leading Company is a construction-oriented strategy video game released for the Super Famicom (1993), PC-98, X68000 (1992), and FM Towns.

Both versions of this game were released only in the Japanese market, but the PC-98 version has sharper graphics and the ability to use a mouse. Instead of abstract colors (to depict control of each square of the board), buildings are used to depict a typical Japanese residential neighborhood. A theme park is shown on an island in the PC-98 version to depict recreational opportunities while the interior of the corporate headquarters is seen in the X68000 version.', 'https://en.wikipedia.org/wiki/Leading_Company'),
  ('Q6540403', 'Libble Rabble is a 1983 puzzle video game developed and published by Namco for arcades. The player is tasked with using two colored arrows, Libble and Rabble, to wrap them around pegs and surround small creatures known as Mushlins to "harvest" them under a time limit. The player can also uncover treasure chests that will have the player searching the stage for items in order to access a special bonus stage. It ran on the Namco System 16 Universal (also called Libble Rabble) hardware, one of the only games to do so.

Described by Namco as a "bashishi game", it was designed by Pac-Man creator Tōru Iwatani and composed by Nobuyuki Ohnogi. Iwatani came up with the idea for the game after an experience at a crowded disco hall, where he envisioned himself tying up people with ropes and throwing them out of the way. It was also inspired by a game he played during his childhood, where the objective was to tie ropes to short metal poles on the ground. The game was known as Potato in early development as Namco considered making the game a tie-in with a potato chip manufacturer in Japan, but these plans later fell through. Iwatani soon passed off development to Seiichi Sato due to being overwhelmed with other projects, who added additional ideas such as treasure chests as he felt the game was too simplistic. A North American release was planned by Midway Games but later cancelled.', 'https://en.wikipedia.org/wiki/Libble_Rabble'),
  ('Q6730634', 'Magic Boy is a platform game developed by Blue Turtle and published for the Amiga, Atari ST, and MS-DOS by Empire Interactive in 1993. A Super Nintendo Entertainment System version was published in 1996 in North America and Europe by JVC Musical Industries.

For the Amiga and Atari ST, Magic Boy was bundled with a bonus game Cool Croc Twins.', 'https://en.wikipedia.org/wiki/Magic_Boy_(video_game)'),
  ('Q6675669', 'Looney Tunes B-Ball (also known as Looney Tunes Basketball in some regions) is a basketball video game developed by Sculptured Software and released by Sunsoft for the Super Nintendo Entertainment System in 1995.', 'https://en.wikipedia.org/wiki/Looney_Tunes_B-Ball'),
  ('Q6798595', 'Mazinger Z is 1993 action platformer video game developed by Winkysoft and published by Bandai for the Super Famicom exclusively in Japan. It is based on the manga of the same name by Go Nagai.', 'https://en.wikipedia.org/wiki/Mazinger_Z_(1993_video_game)'),
  ('Q6943555', 'Musya is a 1992 platform game developed by Jorudan for the Super Nintendo Entertainment System. The game was released by Datam Polystar in Japan on April 21, 1992, followed by English localized version produced by SETA USA and released in North America in December 1992. The title, which translates to "Warrior", is romanized in the Kunrei-shiki style (Musya) instead of the Hepburn romanization style (Musha), likely to avoid confusion with the unrelated Sega Genesis game MUSHA.', 'https://en.wikipedia.org/wiki/Musya'),
  ('Q6747540', 'Manchester United Championship Soccer is a 1995 soccer video game developed by Krisalis Software and published by Ocean Software for the Super NES. The game was released in Germany under the title Lothar Matthäus Super Soccer. A Sega Mega Drive version was planned but never released.', 'https://en.wikipedia.org/wiki/Manchester_United_Championship_Soccer'),
  ('Q6767287', 'Mark Davis'' The Fishing Master is a fishing video game developed by Natsume for the Super Nintendo Entertainment System.

The game features Mark Davis'' voice. It became a cult video game due to its difficulty level and attention to detail about lures and weather effects. A sequel, Mark Davis Pro Bass Challenge, was released in 2003 for PlayStation 2 and 2005 for GameCube.', 'https://en.wikipedia.org/wiki/Mark_Davis%27_The_Fishing_Master'),
  ('Q6788106', 'Matsukata Hiroki no Super Trawling is a Japan-exclusive fishing video game for the Super Famicom.', 'https://en.wikipedia.org/wiki/Matsukata_Hiroki_no_Super_Trawling'),
  ('Q6822684', 'Metal Morph is a video game developed by Origin Systems and published by FCI, Inc. for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Metal_Morph'),
  ('Q6893746', 'Mohawk & Headphone Jack (alternately written as Mo Hawk & Headphone Jack) is a 1996 2D rotational game released for the Super Nintendo Entertainment System.

The game was developed by American studio Solid Software, published by THQ and distributed by Electro Source. It was programmed by industry veteran D. Scott Williamson. The game spins around and around wildly in a circle, also changing the rotation of the map, and making it difficult to continue in the right direction. Rock music plays in the background as one or two players attempt to negotiate a treacherous series of platforms throughout the game''s 14 levels. The game''s likeness was based on Sonic the Hedgehog.', 'https://en.wikipedia.org/wiki/Mohawk_%26_Headphone_Jack'),
  ('Q6924877', 'Mountain Bike Rally, also released as Cannondale Cup in North America, is a bicycle racing video game developed by Radical Entertainment and published by ASC Games for the Super Nintendo Entertainment System in 1994. The game is a simulation of real mountain biking in which the player can select between many characters and many mountain bikes ranging from mediocre to excellent in many categories. It was the first game to support the Life Fitness Entertainment System, an exercise bike peripheral for the SNES. The Cannondale Cup release has the same graphics as the Mountain Bike Rally release, but the names of the racers, bikes, and locations were all altered.', 'https://en.wikipedia.org/wiki/Mountain_Bike_Rally'),
  ('Q6804434', 'MechWarrior 3050, also known as BattleTech in its original Sega Genesis release and in Japan as BattleTech 3050, is a 1994 mech-based video game developed by Malibu. The first BattleTech based game to be released for the Sega Genesis, it was later ported to the Super NES by Activision as MechWarrior 3050. The Super NES version was localized and published in Japan by Ask Group.

The story takes place during the events of the Clan Invasion in the 3050 era. Players are assigned the role of a Clan Wolf Mechwarrior, who is sent to eliminate several Inner Sphere assets which threaten to destroy the Clan''s dominance on the battlefield, and given a Timber Wolf/MadCat mech.', 'https://en.wikipedia.org/wiki/MechWarrior_3050'),
  ('Q6822591', 'Metal Combat: Falcon''s Revenge is a 1993 light gun shooter video game developed by Intelligent Systems and published by Nintendo for the Super Nintendo Entertainment System. It is the sequel to Battle Clash (1992) and one of a small number of titles that require the Super Scope, a light gun. Taking place three years after the events of its predecessor, the player acts as the gunner of the Standing Tank (ST) Falcon piloted by Mike Anderson, fighting a group of chiefs in the Battle Game, the returning emperor Anubis, and the invading Eltorian alien race.

Metal Combat was created by Team Battle Clash, a group within Intelligent Systems made up of Nintendo R&D1 staff, which previously worked on Battle Clash. It was directed by chief graphic designer Toshitaka Muramatsu, who worked in the Fire Emblem and Paper Mario series, and produced by Gunpei Yokoi. The music was composed by Yuka Tsujiyoko, who also scored Battle Clash. The game garnered generally favorable reception from critics; praise was given to the refined gameplay, different strategies of each enemy, variety of modes, and overall improvements made over its predecessor. Some reviewers criticized the single-player campaign for its short duration, repetitive action, and difficulty.', 'https://en.wikipedia.org/wiki/Metal_Combat:_Falcon%27s_Revenge'),
  ('Q6828207', 'Michael Andretti''s Indy Car Challenge is an arcade-style racing video game that is sponsored by Michael Andretti. It was released exclusively for the SNES in North America and Japan.', 'https://en.wikipedia.org/wiki/Michael_Andretti%27s_Indy_Car_Challenge'),
  ('Q6961464', 'Tose Co., Ltd. (also called Tose Software) is a Japanese video game developer based in Kyoto. It is mostly known for developing Nintendo''s Game & Watch Gallery series, various Dragon Ball games, as well as contract work or assistance to other developers. Tose has developed or co-developed thousands of games since the company''s inception in 1979, but is virtually never credited in the games themselves. It is considered the largest non-publishing game developer in the world.

Tose maintains a policy of having no creative input in the games it works on, going so far as to refuse to put the studio''s name in the credits and employees using pseudonyms in its early days. As such, Tose has gained a reputation for being a "ghost developer." Representatives of the company have described it as a "ninja developer," because it works in the shadows, as well as the "unsung hero" of the video game industry. When talking to the press, representatives of the company ask not to be identified by name. Exceptions to this include Game & Watch Gallery 4 and The Legendary Starfy series, as Tose shares the copyright with Nintendo.', 'https://en.wikipedia.org/wiki/Tose'),
  ('Q6952900', 'NCAA Basketball, known in Europe as World League Basketball, is a basketball video game developed by Sculptured Software for the Super NES.

It was the first basketball game for a console to use a 3D perspective. The game uses the Super Nintendo''s Mode 7 to create a 3D player''s-eye view that became the standard for later basketball video games. Sculptured Software''s NHL Stanley Cup featured a similar effect.

According to the short-lived American magazine Flux, this video game was ranked the 75th-best video game of all time.', 'https://en.wikipedia.org/wiki/NCAA_Basketball_(video_game)'),
  ('Q6952668', 'NBA Give ''N Go is a 1995 Super Nintendo Entertainment System basketball video game that uses licensed teams from the National Basketball Association. The game is essentially a home version of Konami''s arcade game Run and Gun, which featured similar graphics and gameplay but no NBA license. Konami followed up Give ''N Go with Run and Gun 2 and the NBA In The Zone series.', 'https://en.wikipedia.org/wiki/NBA_Give_%27n_Go'),
  ('Q6960270', 'Koichi Nakano (born November 14, 1955) of Japan is a former professional track cyclist and ten-consecutive-time world champion in track cycling sprint.

He is among the best track sprinters of modern times. From 1977 to 1986, he won an unprecedented 10 consecutive gold medals in professional sprint events at the UCI Track World Championships.

He was one of the most successful competitors of all-time on the Japanese professional keirin circuit.', 'https://en.wikipedia.org/wiki/Koichi_Nakano'),
  ('Q6948921', 'Mystic Ark is a 1995 role-playing video game developed by Produce! and published by Enix for the Super Famicom. The video game was only released in Japan. Mystic Ark has strong similarities to the games The 7th Saga and Brain Lord, also developed by Produce and distributed by Enix. The game was being localized for a North American release under the title 7th Saga II, but the release was cancelled.', 'https://en.wikipedia.org/wiki/Mystic_Ark'),
  ('Q6954066', 'NHL Stanley Cup, known as Super Hockey in Europe, is an ice hockey video game developed by Sculptured Software for the Super NES. Unlike most hockey video games of the time, the game features movement in a pseudo-3D environment using the SNES''s Mode 7 hardware feature, similar to Sculptured''s previous NCAA Basketball.', 'https://en.wikipedia.org/wiki/NHL_Stanley_Cup_(video_game)'),
  ('Q6960189', 'Nakajima Satoru F-1 Hero ''94 is a 1994 Japan-exclusive Super Famicom Formula One arcade racing video game licensed (and also supervised) by Satoru Nakajima and by FOCA to Fuji Television. This was the sequel to Super F1 Hero and the last game endorsed by Nakajima.', 'https://en.wikipedia.org/wiki/Nakajima_Satoru_F-1_Hero_%2794'),
  ('Q7061794', 'Nosferatu is a horror-themed action platform game developed and published by SETA Corporation for the Super Nintendo Entertainment System. It was released in Japan on October 7, 1994, and in North America in October 1995.

The player controls a young man known as Kyle, who rides to the vampire Nosferatu''s castle in order to defeat him and save his beloved girlfriend Erin from his clutches.', 'https://en.wikipedia.org/wiki/Nosferatu_(video_game)'),
  ('Q7093955', 'Onita Atsushi FMW is a wrestling video game for Super Famicom. It was released on August 6, 1993, to an exclusively Japanese audience with an endorsement by Japanese professional wrestler Atsushi Onita.

The player has to fight their way through a fictionalized version of the Frontier Martial-Arts Wrestling organization; the wrestling promotion Onita owned, booked and was the star of throughout the 1990s, portrayed in this game to be more of a tournament of the Street Fighter variety than a realistic wrestling company. According to the official slogan of the game, it was considered to incorporate an entire batch of innovative ideas. The instruction manual for the game talked about the virtual pursuit of achieving the total potential of each wrestler.', 'https://en.wikipedia.org/wiki/Onita_Atsushi_FMW'),
  ('Q7038956', 'The Ninja Warriors is a beat ''em up video game developed by Natsume Co., Ltd. for the Super Nintendo Entertainment System and published by Taito in Japan and North America in 1994 and by Titus in Europe in 1995. It is a follow-up to Taito''s 1987 arcade game of the same title, and shares similar gameplay. The player can choose between playing as one of three ninja androids, each with different attributes and a unique set of moves including jumps, dashes, throws, and other attacks. The game was developed by the same team at Natsume that later developed Wild Guns (1994).

The game was generally well received by critics. They compared the quality of The Ninja Warriors to Neo Geo and arcade games, and they felt the game had tight controls and vibrant graphics. Some reviewers disagreed on the quality of several aspects including the difficulty, sound quality, and how well the game distinguished itself among the myriad of beat ''em up games. An enhanced remaster titled The Ninja Saviors: Return of the Warriors was released in 2019.', 'https://en.wikipedia.org/wiki/The_Ninja_Warriors_(1994_video_game)'),
  ('Q7093821', 'Success Corporation is a Japanese video game and online game developer and publisher, based in Shinagawa, Tokyo, and founded on 7 June 1978. It is best known for its Cotton series of shooter games, Zoo Keeper and others.', 'https://en.wikipedia.org/wiki/Success_(company)'),
  ('Q6980285', 'Natsuki Crisis Battle is a 1995 video game that was released exclusively for the Japanese Super Famicom. Based on the two-episode OVA and manga Natsuki Crisis , which was written by Hiroshi Tsuruta and serialized in the magazine Business Jump, the player can choose from eight characters and fight on locations such as inside a budō gym, outside a high school and other locations.', 'https://en.wikipedia.org/wiki/Natsuki_Crisis_Battle'),
  ('Q7001764', 'The Journey Home: Quest for the Throne, released in Japan as Neugier: Umi to Kaze no Kodō, is a 1993 action role-playing game developed by Wolf Team and published by Telenet Japan for the Super Famicom. The game was scheduled to be released in North America in late 1993 prior to being cancelled.', 'https://en.wikipedia.org/wiki/The_Journey_Home:_Quest_for_the_Throne'),
  ('Q7121840', 'Pac-In-Time is a 1995 platform game developed by Atreid Concept and published by Namco for the Super Nintendo Entertainment System and Game Boy. It is a reskinned version of the 1993 game Fury of the Furries, also developed by Atreid, modified to feature Pac-Man. It was also released for MS-DOS and Mac OS, where the original game was released.

The game is an offshoot from the normal variety of Pac-Man games, in that it does not confine Pac-Man to a maze-like board. Rather, the player controls Pac-Man through various side-scrolling levels, obtaining many different items along the way; the plot does take elements from the earlier Pac-Man games, such as the objective of collecting a certain number of pellets before exiting a level. The game allows the player to access completed levels via passwords that are given every five levels.', 'https://en.wikipedia.org/wiki/Pac-In-Time'),
  ('Q7131089', 'Panic in Nakayoshi World is a 1994 video game that was released exclusively in Japan for the Super Famicom. It features the manga series that ran in the manga magazine Nakayoshi: Sailor Moon, Goldfish Warning!, Chō Kuse ni Narisō, and Kurumi to 7 Ninnokobitotachi.', 'https://en.wikipedia.org/wiki/Panic_in_Nakayoshi_World'),
  ('Q7097243', 'Operation Logic Bomb: The Ultimate Search & Destroy, known in Japan as Ikari no Yōsai is a 1993 action video game developed and published by Jaleco for the Super NES/Famicom. It was released in Japan on April 23, 1993, and in North America in September 1993. It is the second sequel to the Game Boy game Fortified Zone, following the Japan-only Game Boy sequel Ikari no Yōsai 2. Although the Japanese version shares the same title as the original Game Boy game, it is not a remake. It was later re-released as BS Ikari no Yōsai on the Satellaview system. Operation Logic Bomb was added to the Nintendo Classics service in May 2020.', 'https://en.wikipedia.org/wiki/Operation_Logic_Bomb'),
  ('Q7108913', 'Otoboke Ninja Colosseum is a Japan-exclusive action strategic, maze-based video game, developed by Mint and published by Intec, which was released in 1995.

People who have played Bomberman will find the game structure to be similar.', 'https://en.wikipedia.org/wiki/Otoboke_Ninja_Colosseum'),
  ('Q7105842', 'Oscar is a 1993 platform game developed and published by Flair Software for the Amiga, Amiga CD32, and MS-DOS. It was later released for the Super Nintendo Entertainment System in 1996. The CD32 version was bundled with the CD32 console on the same disc as the puzzle game Diggers. A Sega Genesis version planned but never released.

The player controls a character named Oscar through seven Hollywood-themed levels collecting Oscars.', 'https://en.wikipedia.org/wiki/Oscar_(video_game)'),
  ('Q7123064', 'Packy & Marlon is an educational platform video game developed by WaveQuest and published by Raya Systems for the Super Nintendo Entertainment System. It was designed to improve self-care behavior in children with type 1 diabetes. The game achieved some success with treatment groups. It is a part of educational video game series from Raya that includes Captain Novolin, Rex Ronan: Experimental Surgeon and Bronkie the Bronchiasaurus.

In 1998, the game was released for personal computers by Kidz Health Software.', 'https://en.wikipedia.org/wiki/Packy_and_Marlon'),
  ('Q7126357', 'Paladin''s Quest, originally released as Lennus: Kodai Kikai no Kioku in Japan, is a utopian/dystopian science fantasy role-playing video game developed by Copya System and published in Japan by Asmik Corporation on November 13, 1992, for the Super Nintendo Entertainment System. It was published in North America by Enix in October 1993. It was different from other role-playing games at the time, because when the player casts magic, it takes away HP (health points) instead of MP (magic points/power).

Its sequel, Lennus II, was only released in Japan.', 'https://en.wikipedia.org/wiki/Paladin%27s_Quest'),
  ('Q7146181', 'Harvest Moon, known in Japan as Bokujō Monogatari, is a farm simulation role-playing video game developed by Amccus for the Super Nintendo Entertainment System. The game was first released in Japan by Pack-In-Video in 1996, in North America by Natsume Inc. in 1997, and in Europe by Nintendo in 1998. It is the first game in the long-running Story of Seasons series (formerly known as Harvest Moon in western territories).

Director Yasuhiro Wada conceived Harvest Moon as a leisurely country-living simulation game that contrasted from the competitive fighting games popular at the time. Development took three years, and the game was released late in the Super Nintendo''s lifespan, during the release of next-generation 32-bit hardware. Sales were initially low but increased over time, eventually becoming a commercial success. The game is considered one of the first farm life simulation games and cozy games.', 'https://en.wikipedia.org/wiki/Harvest_Moon_(video_game)'),
  ('Q7206480', 'Pocky & Rocky 2, released in Japan as Kiki Kaikai: Tsukiyo Soushi, is a shoot ''em up video game developed and published by Natsume Co., Ltd. in Japan, published by Natsume Inc. in North America, and published in PAL regions by Ocean Software for the Super NES video game console. It is the sequel to Pocky & Rocky.', 'https://en.wikipedia.org/wiki/Pocky_%26_Rocky_2'),
  ('Q7230177', 'Porky Pig''s Haunted Holiday is a 1995 side-scrolling platform video game developed by Phoenix Interactive Entertainment, published by Acclaim Entertainment, and produced by Sunsoft for the Super Nintendo Entertainment System video game console. The goal of the game is to guide the main character, Porky Pig from the Warner Bros. cartoons, through his nightmares. The game received mixed to positive reviews by critics; its graphics and animations were received well while its length and easy difficulty were not.', 'https://en.wikipedia.org/wiki/Porky_Pig%27s_Haunted_Holiday'),
  ('Q7229283', 'Popeye: Ijiwaru Majo Seahag no Maki is a video game for the Super Famicom game console based on the popular Popeye franchise. It was released by Technos Japan on August 12, 1994 exclusively in Japan.', 'https://en.wikipedia.org/wiki/Popeye:_Ijiwaru_Majo_Seahag_no_Maki'),
  ('Q7228930', 'Pop''n Twinbee (Pop''nツインビー) is a 1993 scrolling shooter video game developed and published by Konami for the Super Famicom in Japan; the game was also released for the Super Nintendo Entertainment System in the PAL region. It is the sixth game in the TwinBee series and a direct follow-up to the arcade game Detana!! TwinBee (Bells & Whistles). The European version was published by Konami''s Palcom Software division and was the first of three TwinBee games localized for the European market, followed by a Game Boy version of Pop''n TwinBee (which was actually an earlier game titled TwinBee Da!! in Japan) and the platform game Pop''n TwinBee: Rainbow Bell Adventures. It was released in North America 27 years after its Super Famicom launch through a February 2020 update to the Nintendo Classics service.', 'https://en.wikipedia.org/wiki/Pop%27n_TwinBee'),
  ('Q7246756', 'Pro Quarterback is a 1992 American football video game developed by Leland Interactive Media and published by Tradewest for the Super NES and the Sega Genesis. A port for the Atari Lynx was announced but never released.', 'https://en.wikipedia.org/wiki/Pro_Quarterback'),
  ('Q7236416', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q7191390', 'Pieces (known in Japan as Jigsaw Party is a 1994 puzzle video game for the Super NES. It was developed by Prism Kikaku and published by Hori Electric in Japan and by Atlus Software in North America. In the game, the player has to solve jigsaw puzzles. In 2002, the spiritual successor developed by the same company, Jigsaw Madness, was released for the PlayStation.', 'https://en.wikipedia.org/wiki/Pieces_(video_game)'),
  ('Q7301326', 'Realm is a platform video game with shooting elements that was released exclusively for the Super Nintendo Entertainment System in 1996.', 'https://en.wikipedia.org/wiki/Realm_(video_game)'),
  ('Q7256305', 'Psycho Dream is a platform game developed and published by Riot for the Super Famicom and released in 1992. Riot was a division of Telenet Japan.', 'https://en.wikipedia.org/wiki/Psycho_Dream'),
  ('Q7332377', 'Riddick Bowe Boxing is a boxing video game released in 1993 for the Super Nintendo Entertainment System. It was also released for the Game Boy and Game Gear consoles.

The game was released for the Super NES in Mexico and, partially, in American Southwest states, as Chavez and starred Julio César Chávez instead of Riddick Bowe. It is identical except that the Spanish language is used instead of English.', 'https://en.wikipedia.org/wiki/Riddick_Bowe_Boxing'),
  ('Q7312804', 'Rendering Ranger: R2 is a 1995 side-scrolling action video game developed by Rainbow Arts and published by Virgin Interactive for the Super Famicom. It was released only in Japan, and has gone on to be one of the rarest Super Famicom titles in existence. In June 2022, Ziggurat Interactive announced that the game would be ported to Microsoft Windows, Nintendo Switch, PlayStation 4, and PlayStation 5, with Limited Run Games set to distribute copies for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Rendering_Ranger:_R2'),
  ('Q7293799', 'Rap Jam: Volume One is a basketball video game for the Super Nintendo Entertainment System, developed by American studio 64WD Creation, in which the players are rap and hip-hop artists. The game is played on an urban basketball court, with fisticuffs and no foul calls. There is an exhibition mode and a tournament mode.

The game was released in January 1995. Despite the Volume One moniker, this was the only installment released. It is also the second and final game to be developed by Motown Software.', 'https://en.wikipedia.org/wiki/Rap_Jam:_Volume_One'),
  ('Q7262504', 'Putty Squad is a 1994 video game developed by System 3 and published by Maximum Games and Ocean Software. It was originally developed for the Amiga 1200, but that version was not released until the end of 2013; prior to that date the SNES version was the only one to be released. Sega Mega Drive and MS-DOS ports also existed, but were cancelled. It is the sequel to Putty (1992). In December 2013, the Amiga version was released as a Christmas gift on System 3''s website. In October 2015, the Mega Drive version was also released by a Sega-16 user who got a hold of a working prototype.

A remake was released in November 2013 for PlayStation 3, PlayStation 4, PlayStation Vita, Nintendo 3DS, Xbox Live Arcade, and Microsoft Windows. In November 2017, Super Putty Squad was released for Nintendo Switch.', 'https://en.wikipedia.org/wiki/Putty_Squad'),
  ('Q7277470', 'RPG Maker, known in Japan as RPG Tsukūru, is a series of programs for the development of video games generally for role-playing game (RPGs) and adventure game genres, originally created by the Japanese group ASCII. The Japanese name, Tsukūru, is a pun mixing the Japanese word tsukuru, which means "make" or "create", with tsūru, the Japanese transliteration of the English word "tool".

The RPG Maker series was originally released primarily in Japan, but it was translated by fans in Taiwan, South Korea, China, Russia, and North America with RPG Maker 2000 and RPG Maker 2003. Most of the later engines have been officially translated to English and created by successors, Enterbrain and Gotcha Gotcha Games.', 'https://en.wikipedia.org/wiki/RPG_Maker'),
  ('Q7277471', 'RPG Maker, known in Japan as RPG Tsukūru, is a series of programs for the development of video games generally for role-playing game (RPGs) and adventure game genres, originally created by the Japanese group ASCII. The Japanese name, Tsukūru, is a pun mixing the Japanese word tsukuru, which means "make" or "create", with tsūru, the Japanese transliteration of the English word "tool".

The RPG Maker series was originally released primarily in Japan, but it was translated by fans in Taiwan, South Korea, China, Russia, and North America with RPG Maker 2000 and RPG Maker 2003. Most of the later engines have been officially translated to English and created by successors, Enterbrain and Gotcha Gotcha Games.', 'https://en.wikipedia.org/wiki/RPG_Maker'),
  ('Q7311085', 'Relief Pitcher is a baseball arcade video game developed by Atari Games and released in 1992. A Super Nintendo Entertainment System port was published in 1994.', 'https://en.wikipedia.org/wiki/Relief_Pitcher_(video_game)'),
  ('Q7319308', 'Rex Ronan: Experimental Surgeon is a 1994 educational action game developed by Sculptured Software and published by Raya Systems for the Super Nintendo Entertainment System (SNES). The game teaches players about the hazards of smoking tobacco cigarettes. The initial development of the game received support from the US Agency for Healthcare Research and Quality. It is a part of educational video game series from Raya that includes Captain Novolin, Packy and Marlon and Bronkie the Bronchiasaurus.', 'https://en.wikipedia.org/wiki/Rex_Ronan:_Experimental_Surgeon'),
  ('Q7336963', 'Rival Turf!, released in Japan as Rushing Beat, is a 1992 beat''em up video game developed and published by Jaleco for the Super Nintendo Entertainment System. It was later rereleased on the Wii and Wii U''s Virtual Console and the Nintendo Classics service. The game is the first installment in the Rushing Beat trilogy, which also includes Brawl Brothers and The Peace Keepers, although the games were localized as unrelated titles in North America.', 'https://en.wikipedia.org/wiki/Rival_Turf!'),
  ('Q7392106', 'SOS, known in Japan as Septentrion, is a survival adventure video game developed and published by Human Entertainment in 1993 in Japan and published in 1994 by Vic Tokai for the Super NES in North America. A sequel to the game was later released in Japan for the PlayStation known as Septentrion: Out of the Blue.', 'https://en.wikipedia.org/wiki/SOS_(1993_video_game)'),
  ('Q7378755', 'Ruin Arm is a 1995 action role-playing video game for the Super Famicom.', 'https://en.wikipedia.org/wiki/Ruin_Arm'),
  ('Q7389506', 'SD F-1 Grand Prix is a Japan-exclusive video game based on the F1 Grand Prix series. This video game spin-off was developed for the Super Famicom by Video System.', 'https://en.wikipedia.org/wiki/SD_F-1_Grand_Prix'),
  ('Q7356001', 'Rocky Rodent is a video game for the Super Nintendo Entertainment System released by Irem in 1993. It is known as Nitropunks: Mightheads in Japan.', 'https://en.wikipedia.org/wiki/Rocky_Rodent'),
  ('Q7379529', 'Run Saber is a side-scrolling action game developed by Horisoft and published by Atlus for the Super Nintendo Entertainment System. The game was released in North America on June 8, 1993, and in Europe in 1993. Run Saber features side-scrolling fighting as the two main heroes, Allen and Sheena, the Run Sabers, fight to save the planet. The gameplay is similar to Strider, Valis and some elements of Psycho Dream.

Run Saber was not released in Japan, despite being developed by a mostly-Japanese team.', 'https://en.wikipedia.org/wiki/Run_Saber');

insert into import_summary (wikidata_id, summary, source) values
  ('Q7339386', 'Road Riot 4WD is a racing video game developed by Atari Games and released in arcades in 1991. Players control weapon-equipped dune buggies and attempt to win races around the globe. A port of the game was released for the Super NES. Versions of the game for the Atari Lynx and Genesis were developed, but never released. A sequel entitled Road Riot''s Revenge was in development and cabinets for the game were made, but the sequel never entered mass production.', 'https://en.wikipedia.org/wiki/Road_Riot_4WD'),
  ('Q7355517', 'Rocko''s Modern Life: Spunky''s Dangerous Day is a puzzle-platform game released by Viacom New Media for the Super Nintendo Entertainment System (SNES). Based on the Nickelodeon series Rocko''s Modern Life (1993–1996), it is the first project of Viacom New Media, the interactive entertainment software division of Viacom International, who owned Nickelodeon. In each of the game''s sections, the player acts as the titular character guiding his dog Spunky to a golden fire hydrant. To do this, he alters the level environment and fights enemies.

Produced by Dave Marsh, Rocko''s Modern Life: Spunky''s Dangerous Day was developed in under 12 months during the show''s creation, and the only source material to reference were rough sketches sent by artists working on the TV series. Viacom New Media published the game in North America in April 1994 to generally favorable reviews from professional critics, although some reviewers suggested the difficulty would be too much for the game''s young target demographic and was artificially increased by the difficult and unresponsive controls. The presentation was well-received for how it reflected the series.', 'https://en.wikipedia.org/wiki/Rocko%27s_Modern_Life:_Spunky%27s_Dangerous_Day'),
  ('Q7459783', 'Sgt. Saunders'' Combat! is a turn-based strategy video game based on the 1960s television series originally broadcast on the ABC Television Network. It was released for the Super Famicom exclusively in Japan.', 'https://en.wikipedia.org/wiki/Sgt._Saunders%27_Combat!'),
  ('Q7496204', 'Shien''s Revenge is a 1994 rail shooter video game developed by Almanic Corporation and originally published by Dynamic Planning for the Super Nintendo Entertainment System in Japan and later in North America by Vic Tokai. In the game, players assume the role of the titular ninja to fight against monsters coming from a time portal in order to face against an entity known as Undertaker and rescue his companion Aska. Co-designed by Takashi Shichijo and mangaka Go Nagai, the title was created by most of the same team that worked on previous projects at Almanic such as E.V.O.: Search for Eden. It was met with mixed reception from critics since its release.', 'https://en.wikipedia.org/wiki/Shien%27s_Revenge'),
  ('Q7496397', 'Shigetaka Kashiwagi''s Top Water Bassing is a Japan-exclusive Super Famicom fishing video game endorsed by the Japanese professional bass fisher Shigetaka Kashiwagi.', 'https://en.wikipedia.org/wiki/Shigetaka_Kashiwagi%27s_Top_Water_Bassing'),
  ('Q7497753', 'Shinseiki Odysselya is a role-playing video game released by Vic Tokai in Japan for the Super Famicom in 1993. An American version was scheduled in 1994 titled Lost Mission, but was canceled. A quick review of the game was published in Vol. 58 of Nintendo Power with a scheduled release date of March 1994, which criticized the game for its "poor story translation" and "standard RPG play."', 'https://en.wikipedia.org/wiki/Shinseiki_Odysselya'),
  ('Q7498911', 'Shiroi Ringu he, full title Joshi Puroresu Story: Shiroi Ringu he: Twinkle Little Star, is a professional wrestling video game for the Super Famicom that was released on December 27, 1995. Popular female Japanese professional wrestlers like Shinobu Kandori and Noriyo Tateno appear in this game.', 'https://en.wikipedia.org/wiki/Shiroi_Ringu_he'),
  ('Q7444183', 'Secret of the Stars, known as Aqutallion in Japan, is a 1993 role-playing video game developed and published by Tecmo for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Secret_of_the_Stars'),
  ('Q7497202', 'Shin Nekketsu Kōha: Kunio-tachi no Banka is a beat ''em up video game developed by Almanic Corporation and published by Technos Japan for the Super Famicom in 1994 exclusively in Japan. It was the fourth game in the Kunio-kun series released for the Super Famicom.

WayForward and Arc System Works developed an English-localized version under the title of River City Girls Zero, which was released in 2022; for Nintendo Switch on February 14 and for PlayStation, Windows, and Xbox platforms on September 21.', 'https://en.wikipedia.org/wiki/River_City_Girls_Zero'),
  ('Q7497223', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q7548022', 'Snoopy Concert is a Japan-exclusive puzzle game based on the Peanuts comic strip which was released for the Super Famicom in 1995. The game never received an official release in English-speaking territories, though unofficial fan translations have been released online.', 'https://en.wikipedia.org/wiki/Snoopy_Concert'),
  ('Q7515653', 'Silva Saga II: The Legend of Light and Darkness is a role-playing video game developed and published by SETA Corporation, which was released exclusively in Japan in 1993. It is a direct sequel to Silva Saga for the Family Computer.

The player will find similarities with Dragon Quest. Players search out the soldier of light who travels on a journey to defeat the Zolde, son of the Zuhl. Up to 12 mercenaries and deity statues can be combined as well as organized.', 'https://en.wikipedia.org/wiki/Silva_Saga_II:_The_Legend_of_Light_and_Darkness'),
  ('Q7538295', 'Sküljagger: Revolt of the Westicans is a 2D platform game released exclusively in North America for the Super Nintendo Entertainment System in 1992.', 'https://en.wikipedia.org/wiki/Sk%C3%BCljagger:_Revolt_of_the_Westicans'),
  ('Q7548338', 'Snow White: Happily Ever After is a North America-exclusive video game that was released in 1994 for the Super Nintendo Entertainment System. The game was targeted for female video game players. It is based on the 1989 animated Filmation film Happily Ever After, and not the 1937 Disney film. A Sega Genesis version was planned but never released.', 'https://en.wikipedia.org/wiki/Snow_White:_Happily_Ever_After_(video_game)'),
  ('Q7572354', 'Space Football: One on One, known in Japan as Super Linear Ball, is a video game developed by Bits Studios and released in 1992 exclusively for the Super Nintendo Entertainment System. The game takes place in the future with two athletes attempting to score goals against each other.', 'https://en.wikipedia.org/wiki/Space_Football:_One_on_One'),
  ('Q7557878', 'Solid Runner is a 1997 role-playing video game developed by Sting Entertainment and published by ASCII Corporation for the Super Famicom.', 'https://en.wikipedia.org/wiki/Solid_Runner'),
  ('Q7506203', 'Shōnin yo Taishi wo Idake!! is a 1995 Japan-exclusive board video game for the Super Famicom.', 'https://en.wikipedia.org/wiki/Sh%C5%8Dnin_yo_Taishi_wo_Idake!!'),
  ('Q7521318', 'Simulation Pro Yakyū is a Japan-exclusive video game for the Super Famicom that uses the actual ball players and teams of the 1995 Nippon Professional Baseball league and combines them into a full-blown simulator.', 'https://en.wikipedia.org/wiki/Simulation_Pro_Yaky%C5%AB'),
  ('Q7564160', 'Soul & Sword is a 1993 Japanese-only video game on Super Famicom developed by Pandora Box. It is a prequel to Traverse: Starlight & Prairie.', 'https://en.wikipedia.org/wiki/Soul_%26_Sword'),
  ('Q7605307', 'Stealth is a stealth video game released for the Super Famicom on December 18, 1992 by Hect, released in Japan.', 'https://en.wikipedia.org/wiki/Stealth_(1992_video_game)'),
  ('Q7575504', 'Speed Racer in My Most Dangerous Adventures is a racing video game developed by Radical Entertainment and published in 1994 by Accolade for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Speed_Racer_in_My_Most_Dangerous_Adventures'),
  ('Q7577489', 'Spindizzy Worlds is a puzzle video game published by Activision, released on the Amiga and Atari ST in 1990. It was later released on the Super Famicom in 1992 and the Super Nintendo Entertainment System in 1993 by Ascii Entertainment and on the X68000 and the NEC PC-9801 in 1992 by Arsys Software as Spindizzy II. The game is a sequel to the 1986 video game Spindizzy. Like its predecessor it uses an isometric view, and the player controls a spinning top-like robotic device named GERALD, a Geographical Environmental Reconnaissance And LandMapping Device, that is tasked with exploring and mapping a star system before it is destroyed.', 'https://en.wikipedia.org/wiki/Spindizzy_Worlds'),
  ('Q7580334', 'Spriggan Powered is a 1996 side-scrolling shoot ''em up video game released by Micronics for the Super Famicom and its Satellaview system. It is the sequel of Spriggan Mark 2: Re-Terraform Project.', 'https://en.wikipedia.org/wiki/Spriggan_Powered'),
  ('Q7642161', 'Super Baseball Simulator 1.000 is a 1991 sports video game by Culture Brain for the Super NES that is the sequel to the NES game Baseball Simulator 1.000. This game is called Super Ultra Baseball in Japan.

In the game, there are three baseball leagues: Atlantic, Northern, and Ultra. Each league has six teams. In the Ultra League, pitchers and batters have special power-ups that boost their abilities which gives the game a surrealistic feel that is rare in the sports genre. Players can even create their own baseball teams and assign special moves to the players that they name themselves. The game can be played in exhibition mode and season mode.', 'https://en.wikipedia.org/wiki/Super_Baseball_Simulator_1.000'),
  ('Q7611467', 'Sterling Sharpe: End 2 End is a Super Nintendo Entertainment System football video game released in 1995 exclusively for the North American market.', 'https://en.wikipedia.org/wiki/Sterling_Sharpe:_End_2_End'),
  ('Q7622860', 'Street Hockey ''95 is a roller hockey video game for the Super NES released in 1994 to an exclusively North American market.

This video game takes place in an urban environment. Instead of ice, the players play on cement and instead of ice skates, they use rollerblades. Players assemble their squads from nine hockey players who are savvy in the ways of the street. There are six different kinds of urban arenas and five different variations on the "traditional" road hockey game.

Street Hockey ''95 uses more than two thousand frames of digitized animation, making it relatively advanced for its era.', 'https://en.wikipedia.org/wiki/Street_Hockey_%2795'),
  ('Q7642145', 'Super Air Diver, also known as Lock On in North America, is a 1993 combat flight simulation video game for the Super Nintendo Entertainment System. It is the follow-up to the Sega Genesis-exclusive Air Diver.', 'https://en.wikipedia.org/wiki/Super_Air_Diver'),
  ('Q7642162', 'Super Bases Loaded is a baseball video game produced by Jaleco for the Super Nintendo Entertainment System in 1991. It is the fifth overall installment of the Bases Loaded series, and first installment of the secondary series for the Super NES. This game was originally released in Japan under the title Super Professional Baseball.

The North American version includes a sponsorship from Ryne Sandberg, like Bases Loaded 3 for the NES.', 'https://en.wikipedia.org/wiki/Super_Bases_Loaded'),
  ('Q7635142', 'Sugoi Hebereke is a 1994 fighting game developed and published by Sunsoft in Japan for the Super Famicom on March 11, 1994. It is a spin-off of the Hebereke series, as well as Sunsoft''s first attempt in the genre before they became better known for the 1995''s Galaxy Fight: Universal Warriors, the 1996''s Waku Waku 7, and the 1998''s Astra Superstars.', 'https://en.wikipedia.org/wiki/Sugoi_Hebereke'),
  ('Q7581316', 'VAP Inc. (initials of Video & Audio Project) is a Japanese entertainment company, headquartered in Chiyoda, Tokyo. It is a subsidiary of Nippon Television Holdings.', 'https://en.wikipedia.org/wiki/VAP_Inc.'),
  ('Q7573503', 'Spanky''s Quest is a 1991 puzzle-platform game developed and published by Natsume for the Game Boy and Super Nintendo Entertainment System (SNES). Known in Japan as Monkey Reflections: The Adventures of Mr. Jiro on the SNES and Lucky Monkey on the Game Boy, the player controls the monkey Spanky as they try to escape a tower created by the witch Morticia. Players are tasked with clearing rooms by using the help of a magic ball to progress. Depending on the console version, the way the player clears rooms changes.

Spanky''s Quest has received mixed reception from critics. In 2021, the SNES version of the game was added to the Nintendo Classics service.', 'https://en.wikipedia.org/wiki/Spanky%27s_Quest'),
  ('Q7642171', 'Super Batter Up, known in Japan as Super Famista, is a 1992 baseball video game developed and published by Namco for the Super Nintendo Entertainment System. The game can played with both a one- and two-player mode plus a league mode.

The North American release has an official license from the Major League Baseball Players Association and features the names of actual professional baseball players, but it does not have a license from Major League Baseball and no actual team names are used; the teams are only identified by their respective locales. While the all-star mode in the Japanese version of the game closely mimics the Nippon Professional Baseball All-Star Series, the North American version of the game emulates the MLB All-Star Game. An intrasquad mode (found only in the Japanese version) allows players on the same team to face off against each other. The only limitations are that there are only five pitchers on each team, players cannot be changed, and uniforms are limited to red and white colors.', 'https://en.wikipedia.org/wiki/Super_Batter_Up'),
  ('Q7642230', 'Super Caesars Palace is a Super Nintendo Entertainment System casino video game centered on Caesars Palace in Las Vegas, Nevada. It is the follow-up to Virgin''s previous Caesars Palace game. Super Caesars Palace was also released for the Sega Genesis and Game Gear as Caesars Palace. The Japanese version of the game was followed by a sequel, Super Casino 2.', 'https://en.wikipedia.org/wiki/Super_Caesars_Palace'),
  ('Q7642236', 'Castles is a video game developed by Quicksilver and published by Interplay Entertainment in 1991 and 1992. The game involves the construction of a series of castles in Wales and the Welsh Marches during the 13th century. Castles was quickly followed by an expansion, Castles: The Northern Campaign, and a sequel, Castles II: Siege and Conquest.', 'https://en.wikipedia.org/wiki/Castles_(video_game)'),
  ('Q7642247', 'Super Chase H.Q. is a 1992 arcade racing game developed and published by Taito. It is the third release in the Chase H.Q. series, and the sequel to Special Criminal Investigation. After the initial release in Japanese arcades under the title Super Chase: Criminal Termination, it was re-released in North America in 1993 for the Super Nintendo.', 'https://en.wikipedia.org/wiki/Super_Chase_H.Q.'),
  ('Q7642250', 'Super Chinese Fighter is a 1995 fighting game. It was developed and published by Culture Brain for the Super Famicom exclusively in Japan. It is part of the Super Chinese series, but is not in the main series of the games. Fighter allows players to fight in fighting game battles using characters from the Super Chinese games, including Jack and Ryu.

This game is the first Super Chinese Fighter game. Two others, Super Chinese Fighter GB and Super Chinese Fighter EX, were released after this game, although none of these games were released in North America.', 'https://en.wikipedia.org/wiki/Super_Chinese_Fighter'),
  ('Q7642257', 'Super Chinese World 2: Uchū Ichi Butō Taikai is a Japanese-only action RPG developed by Culture Brain. It is the second SNES Super Chinese game, being a sequel to Super Ninja Boy, which was released in North America.

Contrary to its predecessor, it doesn''t feature any traditional turn-based battles, but a couple of platforming sections still remain. Jack and Ryu are now travelling between different planets to defeat some alien invaders, who kidnapped the world leaders. The battle system was also greatly improved. Jack and Ryu now have a lot of new attacks and even a few different skills (although they still share levels and items), they can turn into giant ninjas in order to cast the most advanced spells and it is possible to use weapons or spells without going to the menu. A fighting mode has also been added, allowing to play with many other characters than the heroes.', 'https://en.wikipedia.org/wiki/Super_Chinese_World_2'),
  ('Q7642261', 'Super Chinese World 3 is a role-playing game from Culture Brain for the Super Famicom. In this game, the player lets you choose between two forms of gameplay, with one more traditional menu-based selection for RPG battles, and the other being more action-oriented.

The game was released on December 22, 1995. In Famicom Tsūshin, it was critiqued for having poor gameplay in either format of RPG and low-quality graphics.', 'https://en.wikipedia.org/wiki/Super_Chinese_World_3'),
  ('Q7642169', 'Super Battletank 2 is a 1994 tank simulation video game developed and published by Absolute Entertainment for the Super Nintendo Entertainment System. The Japanese Super Famicom version was published by Pack-In-Video.', 'https://en.wikipedia.org/wiki/Super_Battletank_2'),
  ('Q7642237', 'Super Casino 2 is a Super Nintendo Entertainment System video game that takes a player to an exclusive black tie casino known as the Casino Coconuts.

Various betting games are available like blackjack, baccarat, slot machines, roulette, and wagering bets on the horses. The game is the sequel to Super Casino - Caesars Palace (Super Caesars Palace in North America). All text in the game is in Japanese.', 'https://en.wikipedia.org/wiki/Super_Casino_2'),
  ('Q7642271', 'Super Conflict is a turn-based strategy video game released for the Super NES in March 1993. It is the sequel to Conflict for the NES.', 'https://en.wikipedia.org/wiki/Super_Conflict'),
  ('Q7642164', 'Super Bases Loaded 2 (released in Japan as Super 3D Baseball, and in South Korea as Korean Pro Baseball) is a Super Nintendo Entertainment System baseball game. The game is the sixth overall installment of the Bases Loaded series, and second installment of the secondary series for the Super NES.', 'https://en.wikipedia.org/wiki/Super_Bases_Loaded_2'),
  ('Q7642219', 'Super Bowling is a 1992 sports video game for the Super NES and the Nintendo 64. It was developed by KID and published by Athena, originally only for the SNES. It was later picked up by American Technōs and UFO Interactive and released for the N64 in 1999.

The Nintendo 64 version was a 3D remake of the SNES version. It became a rare collector''s item, with complete copies now selling for upwards of US$1,000. The game released late in the N64''s lifespan, and did not sell well, which has been attributed to its rarity.', 'https://en.wikipedia.org/wiki/Super_Bowling'),
  ('Q7642329', 'Varie was a Japanese corporation that developed and published games for the Game Boy, Famicom, the Super Famicom, and the Sega Mega Drive during the 1980s and the 1990s. It was founded in 1986 and closed in early 1997.', 'https://en.wikipedia.org/wiki/Varie'),
  ('Q7642332', 'F1 Circus is a series of Formula One-based racing video games developed and published by Nichibutsu starting on the PC Engine in 1990.', 'https://en.wikipedia.org/wiki/F1_Circus'),
  ('Q7642342', 'Super Fire Pro Wrestling: Queen''s Special is a Japan-exclusive video game based on All Japan Women''s Pro-Wrestling and is an installment of the Fire Pro Wrestling series. It was released exclusively for the Super Famicom, although an unofficial English translation exists.', 'https://en.wikipedia.org/wiki/Super_Fire_Pro_Wrestling:_Queen%27s_Special'),
  ('Q7642343', 'The following is a list of all video games in the Fire Pro Wrestling series produced by either Human Entertainment or Spike starting in 1989. Most of the titles in the series were released exclusively in Japan.', 'https://en.wikipedia.org/wiki/List_of_Fire_Pro_Wrestling_games'),
  ('Q7642347', 'The following is a list of all video games in the Fire Pro Wrestling series produced by either Human Entertainment or Spike starting in 1989. Most of the titles in the series were released exclusively in Japan.', 'https://en.wikipedia.org/wiki/List_of_Fire_Pro_Wrestling_games'),
  ('Q7642345', 'The following is a list of all video games in the Fire Pro Wrestling series produced by either Human Entertainment or Spike starting in 1989. Most of the titles in the series were released exclusively in Japan.', 'https://en.wikipedia.org/wiki/List_of_Fire_Pro_Wrestling_games'),
  ('Q7642354', 'Super Formation Soccer 96: World Club Edition is the last Super Famicom release of the original Super Formation Soccer video game. It was released exclusively in Japan in 1996.

This game featured 18 fictitious club teams from around the world, based on well-known teams of the time; there are also three hidden teams. The players names are also fictitious; for example, J. V. Pinto is spelled J. V. Minto.', 'https://en.wikipedia.org/wiki/Super_Formation_Soccer_96:_World_Club_Edition'),
  ('Q7642353', 'Super Formation Soccer 94: World Cup Edition is the third release of the original Super Formation Soccer video game, which was made specially for the 1994 FIFA World Cup.', 'https://en.wikipedia.org/wiki/Super_Formation_Soccer_94'),
  ('Q7642355', 'Super Formation Soccer II is the sequel to the original Super Formation Soccer video game (known as Super Soccer in Europe and North America), which was released exclusively in Japan in 1993. The most significant innovation over its predecessor was the introduction of a four-player mode, and a battery backup to replace the password system used in the original game.', 'https://en.wikipedia.org/wiki/Super_Formation_Soccer_II'),
  ('Q7642381', 'Super Goal! 2, known in Japan as Takeda Nobuhiro no Super Cup Soccer, is a soccer video game developed by Tose and published by Jaleco for the Super Nintendo Entertainment System. It is the sequel to Goal!.', 'https://en.wikipedia.org/wiki/Super_Goal!_2'),
  ('Q7642387', 'Kaga Create Co., Ltd., formerly Naxat Soft, was a Japan-based video game developing and publishing division of Kaga Electronics.

The company initially released games for the PC Engine (known as the TurboGrafx-16 in North America). It later released titles for a wide array of gaming systems, including the Nintendo Entertainment System, Game Boy, Super NES, Dreamcast, 3DO, PlayStation, Sega Saturn, and PC-FX. The company''s releases mostly stopped around 2005, with their final games primarily being re-releases of PC Engine titles on the Wii Virtual Console.', 'https://en.wikipedia.org/wiki/Kaga_Create'),
  ('Q7642447', 'Super Ice Hockey is a 1994 ice hockey sports video game developed by Opera House and released in Japan by Yonezawa PR21 and Europe by Sunsoft for the Super Nintendo Entertainment System. It is based on the international level of ice hockey with teams from 1994 as opposed to domestic (intra-national) ice hockey leagues.', 'https://en.wikipedia.org/wiki/Super_Ice_Hockey'),
  ('Q7642457', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q7642463', 'Super International Cricket is a cricket video game released in 1994 for the Super Nintendo Entertainment System, only in Australia and Europe. It is a sequel to International Cricket on the original Nintendo Entertainment System. The game was developed by Melbourne House (as Beam Software), with Nintendo publishing the game. Nintendo also included the game with a Super NES console bundle in Australia.', 'https://en.wikipedia.org/wiki/Super_International_Cricket'),
  ('Q7642468', 'The Game of Life, also known simply as Life, is a board game originally created in 1860 by Milton Bradley as The Checkered Game of Life, the first ever board game for his own company, the Milton Bradley Company. The game simulates a person''s travels through their life, from early adulthood to retirement, with college if chosen, jobs, marriage, and possible children along the way. Up to six players, depending on the version, can participate in a single game. Variations of the game accommodate up to ten players.

The modern version was originally published 100 years later, in 1960. It was created and co-designed by Bill Markham and Reuben Klamer, respectively, and was "heartily endorsed" by Art Linkletter. It is now part of the permanent collection of the Smithsonian''s National Museum of American History and an inductee into the National Toy Hall of Fame.', 'https://en.wikipedia.org/wiki/The_Game_of_Life'),
  ('Q7642490', 'Super Kyotei is a 1995 Japan-exclusive video game for the Super Famicom. The game allows to compete in the Kyōtei races that are held all across Japan. A sequel with a few improvements was released in 1996.', 'https://en.wikipedia.org/wiki/Super_Kyotei'),
  ('Q7642555', 'Super Mad Champ is a racing and vehicular combat video game developed by Givro Corporation and published by Tsukuda Original in Japan exclusively for the Super Famicom on 4 March 1995. The game is centered around a series of motorcycle races throughout various locations that the player must win to advance to higher-difficulty races, while using attacks to hinder the other racers.', 'https://en.wikipedia.org/wiki/Super_Mad_Champ'),
  ('Q7642636', 'Takara Co., Ltd. was a Japanese toy company founded in 1955. In March 2006, the company merged with Tomy Company, Ltd. to form Takara Tomy. The Takara motto was「遊びは文化」("playing is culture").

The company focused on traditional toys and board games. They created the Licca-chan dolls, which has been referred to as "Japan''s Barbie" in Western press. Some of the globally known toys and franchises that Takara invented include Transformers and Beyblade. Takara also held the license to localise and distribute Hasbro products in Japan including The Game of Life, Blythe dolls, Magic: The Gathering, Duel Masters trading card games. Takara was also involved in software, publishing video games based on its toys like Transformers and Choro Q / Penny Racers, porting SNK Neo Geo games to consoles, and the Battle Arena Toshinden series.', 'https://en.wikipedia.org/wiki/Takara'),
  ('Q7642645', 'Super Pinball: Behind the Mask is a pinball video game for the Super Nintendo Entertainment System that was released in 1994 in North America and Japan.', 'https://en.wikipedia.org/wiki/Super_Pinball:_Behind_the_Mask'),
  ('Q7642648', 'Super Play Action Football is an American football video game developed by Nintendo for the Super NES. It is the follow-up to NES Play Action Football.', 'https://en.wikipedia.org/wiki/Super_Play_Action_Football'),
  ('Q7642626', 'Super Ninja Boy JPN is an action role-playing game released by Culture Brain for the Super Famicom in Japan in 1991, and the Super NES in North America in 1993. It features random encounters with side-scrolling battles, although some boss battles are fought with a traditional menu-based system. There are also a few platforming sections.

In single-player mode, the main character is Jack. The game can be switched between single player and multiplayer at will, with the second player controlling Ryu. Jack and Ryu share statistics, so one character never overpowers the other.

Super Ninja Boy features a password system to record progress.', 'https://en.wikipedia.org/wiki/Super_Ninja_Boy'),
  ('Q7642610', 'Morph (also known as Super Morph on the Super Nintendo Entertainment System release) is a 1993 Super NES, Amiga and Amiga CD32 puzzle video game released by Millennium Interactive. The game''s plot is of a child who is given a temporary ability to change between states of solid, liquid, or gas coming in the forms of a cannonball, a rubber ball, a water droplet, and a cloud. The player must go through over 36 challenging levels set in four different zones collecting special cogs from each level in order to fix a machine capable of turning him back into a normal boy.', 'https://en.wikipedia.org/wiki/Morph_(video_game)'),
  ('Q7642661', 'Super Professional Baseball II is the sequel to Super Professional Baseball.', 'https://en.wikipedia.org/wiki/Super_Professional_Baseball_II'),
  ('Q7642668', 'Super R.B.I. Baseball is a baseball video game developed by Gray Matter and published by Time Warner Interactive. It was released for the Super Nintendo Entertainment System in 1995 exclusively in North America.', 'https://en.wikipedia.org/wiki/Super_R.B.I._Baseball'),
  ('Q7651153', 'Coca-Cola: Suzuka 8 Hours is a 1992 motorcycle racing arcade game developed and published by Namco. It is based on the homonymous real-world racing event. Players control a racer using a handlebar controller and must race against computer-controlled opponents while remaining in first place. It ran on the Namco System 2 arcade hardware. A direct sequel, Suzuka 8 Hours 2, was released a year later.', 'https://en.wikipedia.org/wiki/Suzuka_8_Hours_(video_game)'),
  ('Q7642774', 'Super Slam Dunk, known in its entirety as Earvin "Magic" Johnson''s Super Slam Dunk, is a Super Nintendo Entertainment System basketball video game endorsed by Magic Johnson and released in 1993.', 'https://en.wikipedia.org/wiki/Super_Slam_Dunk'),
  ('Q7642775', 'Super Slap Shot is a traditional five-on-five ice hockey video game for the Super NES/Super Famicom.', 'https://en.wikipedia.org/wiki/Super_Slap_Shot'),
  ('Q7642875', 'Super Troll Islands is a 1994 platform game, based on the license of bright-haired toys known as Troll dolls, developed by Millennium Interactive for the SNES. A Sega Genesis version was planned but never released.', 'https://en.wikipedia.org/wiki/Super_Troll_Islands'),
  ('Q7642982', 'Super Ōzumō: Netsusen Daiichiban is a sumo video game developed and published by Namcot for the Super Famicom, which was released exclusively in Japan on December 18, 1992.

Famitsu gave it 26/40.', 'https://en.wikipedia.org/wiki/Super_%C5%8Czum%C5%8D:_Netsusen_Daiichiban'),
  ('Q7670555', 'TKO Super Championship Boxing - known in Japan as Kentou-Ou World Champion - is a boxing video game, developed by Sting Entertainment and published by SOFEL, which was released in 1992.

The former professional boxer Jirō Matsushima appears in the Japanese cover art. In 1997, he became the 56th Japanese bantamweight champion.', 'https://en.wikipedia.org/wiki/TKO_Super_Championship_Boxing'),
  ('Q7674085', 'Electronic Arts Victor Inc. was a joint-venture between Electronic Arts and Victor Entertainment. It published various sports games for the Family Computer, Super Famicom, and the Mega Drive. Some other sports concepts include J-League association football, American football, and NHL hockey.

EA Victor has formerly participated in various PC World expos in the 1990s.', 'https://en.wikipedia.org/wiki/Electronic_Arts_Victor'),
  ('Q7674291', 'Tadaima Yūsha Boshūchū Okawari is a 1994 role-playing video game developed and published by Human Entertainment for the Super Famicom.', 'https://en.wikipedia.org/wiki/Tadaima_Y%C5%ABsha_Bosh%C5%ABch%C5%AB_Okawari'),
  ('Q7642789', 'Super Solitaire is a Super Nintendo Entertainment System video game that has different variations version of the classic solitaire card game.', 'https://en.wikipedia.org/wiki/Super_Solitaire'),
  ('Q7642888', 'Super Turrican is a 1993 run and gun video game released by Factor 5 for the Super Nintendo Entertainment System. The European version was published by Hudson Soft, the North American version was published by Seika Corporation, and the Japanese version was published by Tonkin House. It is the fifth game in the Turrican series.', 'https://en.wikipedia.org/wiki/Super_Turrican_(1993_video_game)'),
  ('Q7642724', 'Super SWIV (Firepower 2000 in the US) is a top-down shoot ''em up released for the Super Nintendo Entertainment System in 1992. It was released as Mega SWIV on the Mega Drive in 1995. It is the sequel to the 1991 game SWIV. It was followed by SWIV 3D in 1996.

The game''s story involves a secret underground race on an island in the Atlantic Ocean which has stolen top military vehicles and equipment from around the world and built powerful war machines from them. Military and intelligence officials of major countries detect them, but are afraid that they will be unable to prepare against an assault by this underground race. They send the player character in to infiltrate their base and destroy them.', 'https://en.wikipedia.org/wiki/Super_SWIV'),
  ('Q7642915', 'Super Wrestle Angels is a Japan-exclusive wrestling-based video game published by Imagineer in 1994, for the Super Famicom.', 'https://en.wikipedia.org/wiki/Super_Wrestle_Angels'),
  ('Q7674772', 'Taekwon-Do is a 2D Taekwondo fighting video game that attempts to capture a realistic tone of Taekwondo tournament fighting. It was developed and published by Human Entertainment, and was released in Japan and South Korea in 1994.', 'https://en.wikipedia.org/wiki/Taekwon-Do_(video_game)'),
  ('Q7706930', 'Astro Boy, known in Japan as Mighty Atom, is a Japanese manga series written and illustrated by Osamu Tezuka. It was serialized in Kobunsha''s Shōnen from 1952 to 1968, with its 112 chapters collected in 23 tankōbon volumes by Akita Shoten. Dark Horse Comics published an English translation in 2002. The story follows the eponymous Astro Boy, an android young boy with human emotions who is created by scientist Umataro Tenma in the likeness of his son Tobio after the latter''s death in an accident. Eventually, Astro is sold to a robot circus run by ringleader Hamegg, but is saved from his servitude by Professor Ochanomizu. Astro becomes a surrogate son to Ochanomizu who creates a robotic family for Astro and helps him to live a normal life like an average human boy, while accompanying him on his adventures.', 'https://en.wikipedia.org/wiki/Astro_Boy'),
  ('Q7686564', 'Tarot Mystery is a Super Famicom title that revolves around tarot divination and answering questions in Japanese. This video game would become Yasuaki Fujita''s final project as a composer for Super Famicom video games.', 'https://en.wikipedia.org/wiki/Tarot_Mystery'),
  ('Q7719821', 'The Brainies is a 1991 puzzle video game developed by Atreid Concept and published by Loriciel. It was released for Atari ST, Amiga, Apple IIgs, Macintosh, and Amstrad CPC computers. Even though its European title is Tiny Skweeks, the connection to the popular Skweek series was made late. The game is also known as The Tinies on home computers. Titus France licensed the game and released a port to the Super Nintendo Entertainment System in 1996.', 'https://en.wikipedia.org/wiki/The_Brainies'),
  ('Q7743174', 'The Jetsons: Invasion of the Planet Pirates is a 1994 platform game developed by Sting and published by Taito. Based on the animated sitcom The Jetsons, it was released for the Super Nintendo Entertainment System in North America.

In 1995, the game was modified and released in Japan as Yōkai Buster: Ruka no Daibōken, based on Kadokawa Shoten''s mascot character Ruka.', 'https://en.wikipedia.org/wiki/The_Jetsons:_Invasion_of_the_Planet_Pirates'),
  ('Q7713360', 'The Amazing Spider-Man: Lethal Foes is a 1995 platform game for the Super Famicom featuring the Marvel Comics character Spider-Man, released in Japan. The game''s name appears to have been inspired by the 1993 limited series The Lethal Foes of Spider-Man, though its plot does not resemble that of the comic beyond including multiple Spider-Man villains.

The cover art for the game was designed by comic book artists Mark Bagley, Karl Kesel, and Paul Mounts.', 'https://en.wikipedia.org/wiki/The_Amazing_Spider-Man:_Lethal_Foes'),
  ('Q7714815', 'The Atlas is a multiplatform strategy/simulation video game developed by Artdink Development. The game is set during the Age of Discovery in the 15th century. It was released in August 1991 for the NEC PC-9801, FM-TOWNS and MS-DOS, with a PC version released on March 4, 1995 and a version for the Super Nintendo Entertainment System released by Pack-In-Video on March 24 of the same year. It was also ported to Windows in September 2000. A version for Wii Virtual Console released exclusively in Japan on February 19, 2008. The sequel to The Atlas, titled The Atlas II, was released on April 26, 1993.', 'https://en.wikipedia.org/wiki/The_Atlas_(video_game)'),
  ('Q7692734', 'Tecmo Super Bowl II is an update of the previous Tecmo Super Bowl released for Super NES and Genesis.', 'https://en.wikipedia.org/wiki/Tecmo_Super_Bowl_II:_Special_Edition'),
  ('Q7692735', 'Tecmo Super Bowl III: Final Edition is a 1995 American football video game released on the Super Nintendo Entertainment System and the Sega Genesis. According to a spokesperson for the game''s developer/publisher, Tecmo, the subtitle "Final Edition" refers to it being the last football game Tecmo would make for 16-bit systems. The game features the full NFL and NFLPA licenses.', 'https://en.wikipedia.org/wiki/Tecmo_Super_Bowl_III:_Final_Edition'),
  ('Q7756422', 'The Peace Keepers, known in Japan as Rushing Beat Syura is a 1993 beat ''em up video game developed and published by Jaleco for the Super Nintendo Entertainment System in 1993. It is the third game in the Rushing Beat, following Rival Turf! and Brawl Brothers, although the three games were localized as unrelated titles in North America.

The game distinguishes itself from the rest of the series by shifting focus from the two main characters of the previous games (Douglas Bild and Rick Norton in Japan). It also adds a variety of new features including new special attacks, branching gameplay paths and multiple endings.', 'https://en.wikipedia.org/wiki/The_Peace_Keepers'),
  ('Q7760183', 'The Ren & Stimpy Show, also known simply as Ren & Stimpy, is an American animated comedy television series created by John Kricfalusi for Nickelodeon. The series follows the misadventures of Ren Höek, an emotionally unstable and psychotic chihuahua; and Stimpy, a good-natured and dimwitted Manx cat. Originally produced by Spümcø, the series was shown on Nickelodeon from August 11, 1991, to December 16, 1995, with its last episode running on MTV on October 20, 1996, spanning a total of five seasons and 52 episodes (93 segments). The third to be shown of the original three Nickelodeon animated series known as "Nicktoons", alongside Doug and Rugrats, it is one of the progenitor series of the brand.', 'https://en.wikipedia.org/wiki/The_Ren_%26_Stimpy_Show'),
  ('Q7760184', 'The Ren & Stimpy Show, also known simply as Ren & Stimpy, is an American animated comedy television series created by John Kricfalusi for Nickelodeon. The series follows the misadventures of Ren Höek, an emotionally unstable and psychotic chihuahua; and Stimpy, a good-natured and dimwitted Manx cat. Originally produced by Spümcø, the series was shown on Nickelodeon from August 11, 1991, to December 16, 1995, with its last episode running on MTV on October 20, 1996, spanning a total of five seasons and 52 episodes (93 segments). The third to be shown of the original three Nickelodeon animated series known as "Nicktoons", alongside Doug and Rugrats, it is one of the progenitor series of the brand.', 'https://en.wikipedia.org/wiki/The_Ren_%26_Stimpy_Show'),
  ('Q7746695', 'Zoku: The Legend of Bishin is a hybrid racing and beat ''em up video game that was developed and published by Magifact for the Super Famicom in 1993 only in Japan.', 'https://en.wikipedia.org/wiki/The_Legend_of_Bishin'),
  ('Q7798922', 'SimCity (also known as the retronyms Micropolis or SimCity Classic) is a city-building simulation video game developed by Will Wright, and released for several platforms from 1989 to 1991. SimCity features two-dimensional graphics and an overhead perspective. The game''s objective is to create a city, develop residential and industrial areas, build infrastructure, and collect taxes for further city development. Importance is placed on increasing the population''s standard of living, maintaining a balance between the different sectors, and monitoring the region''s environmental situations to prevent the settlement from declining and going bankrupt.', 'https://en.wikipedia.org/wiki/SimCity_(1989_video_game)'),
  ('Q7770896', 'The Twisted Tales of Spike McFang is an action role-playing video game developed by Red Company for the Super Nintendo Entertainment System. It was released by Naxat Soft in Japan and by Bullet-Proof Software in North America. The game is the sequel to the TurboGrafx-16 game Makai Prince Dorabotchan, which was only released in Japan. The characters also appeared in the Japanese Super Naxat Open golf game for Super Famicom.', 'https://en.wikipedia.org/wiki/The_Twisted_Tales_of_Spike_McFang'),
  ('Q7850387', 'Tsuyoshi Shikkari Shinasai: Taisen Puzzle-dama is a 1994 puzzle video game developed and published by Konami. It is part of the Taisen Puzzle-dama series, and is based on the anime series Tsuyoshi Shikkari Shinasai. It was released exclusively in Japan for the Super Famicom in November 18, 1994.', 'https://en.wikipedia.org/wiki/Tsuyoshi_Shikkari_Shinasai:_Taisen_Puzzle-dama'),
  ('Q7805095', 'Time Slip is a platform video game developed by The Sales Curve and published by Vic Tokai for the Super Nintendo Entertainment System. It features the adventures of Dr. Vincent Gilgamesh, a scientist attempting to foil an alien invasion to Earth by traveling to different historic ages. This game was only released to the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Time_Slip'),
  ('Q7819707', 'Tommy Moe''s Winter Extreme: Skiing and Snowboarding, known in Europe as Val d''Isère Championship, is a winter sports video game for the Super Nintendo Entertainment System that uses skiing and snowboarding as extreme sports in freestyle mode, training mode, or competition mode.', 'https://en.wikipedia.org/wiki/Tommy_Moe%27s_Winter_Extreme:_Skiing_and_Snowboarding'),
  ('Q7822966', 'Tony Meola''s Sidekicks Soccer is a 1993 soccer video game released for the Super Nintendo Entertainment System. It is named after US goalkeeper Tony Meola. It went under several names in different markets, such as Super Copa in Latin America and Ramos Ruy no World Wide Soccer in Japan (endorsed by Ruy Ramos). In Brazil, there is also a version called Worldwide Soccer, but it is not modified like Super Copa, it is just the same US version.', 'https://en.wikipedia.org/wiki/Tony_Meola%27s_Sidekicks_Soccer'),
  ('Q7824568', 'Top Management II is a multiplatform video game that emphasizes strategy and economic expansion.', 'https://en.wikipedia.org/wiki/Top_Management_II'),
  ('Q7829649', 'Crea-Tech was a Japanese video game developer based in Koto, Tokyo, Japan, which was founded by Hiroshi Miyaoka in 1988. The company was best known for developing the role-playing video game series Metal Max. They also developed many board games. The company developed console games mainly, but also had some computer games and mobile games.', 'https://en.wikipedia.org/wiki/Crea-Tech'),
  ('Q7847416', 'True Golf Classics: Waialae Country Club is a golf simulation video game developed and published by T&E Soft. This entry in the company''s long-running golf simulation series had a staggered release across multiple platforms. It simulates the sport on courses rendered using the blueprints of the Waialae Country Club in Honolulu, Hawaii. Initial reviews for its debut as a Super NES launch game praised its graphics and gameplay depth. The 3DO version later became the top-selling game for its platform in the United States in November 1994. A separate game developed by T&E Soft set on the same course is the 1998 Nintendo 64 game, Waialae Country Club: True Golf Classics.', 'https://en.wikipedia.org/wiki/True_Golf_Classics:_Waialae_Country_Club'),
  ('Q7855738', 'Turn and Burn: No-Fly Zone is a combat flight simulator from Absolute Entertainment for the Super NES, released in 1994. It is the sequel to Turn and Burn: The F-14 Dogfight Simulator, a Game Boy game which also featured the F-14 Tomcat aircraft. An enhanced port of this game was released as F-14 Tomcat on Game Boy Advance. A Sega Mega Drive version was planned but never released.', 'https://en.wikipedia.org/wiki/Turn_and_Burn:_No-Fly_Zone'),
  ('Q7876773', 'Space Knight Tekkaman Blade is a 1992 Japanese anime television series produced by Tatsunoko Production and Sotsu Agency. The series was directed by Hiroshi Negishi and written by Mayori Sekijima and Satoru Akahori. The story follows an organization called the Space Knights and their war against aliens known as the Radam. The Space Knights are assisted by Takaya Aiba, who has the ability to transform into an armored warrior known as Tekkaman Blade.

The first series, of 50 episodes (including episode 0), aired in Japan from February 18, 1992, to February 2, 1993, on TV Tokyo. This was followed by two specials. A sequel series called Tekkaman Blade II, which is set ten years after the first series and follows the events of the second Radam invasion, was a series of six Japanese original video animation (OVA) releases from July 21, 1994, to April 21, 1995. A video game based on the series, titled Uchū no Kishi: Tekkaman Blade, was released in Japan on July 30, 1993. The original series was released internationally, including North America, and was dubbed in English as Teknoman. In the English-dubbed versions, the series was heavily cut compared to the original Japanese version and shortened from 50 to 43 episodes.', 'https://en.wikipedia.org/wiki/Tekkaman_Blade'),
  ('Q7880191', 'Ultimate Fighter, known in Japan as Hiryū no Ken S: Golden Fighter, is a 1992 fighting video game developed and published by Culture Brain for the Super NES.

An updated version of it titled Hiryū no Ken S: Hyper Version was later released exclusively in Japan for the same platform on December 11, 1992, which adds a choice of turbo speed levels to increase the speed of the combat.', 'https://en.wikipedia.org/wiki/Ultimate_Fighter'),
  ('Q7876770', 'Uchū Race: Astro Go! Go! is a Japan-exclusive racing video game for the Super Famicom.', 'https://en.wikipedia.org/wiki/Uch%C5%AB_Race:_Astro_Go!_Go!'),
  ('Q7864548', 'UFO Kamen Yakisoban: Kettler no Kuroi Inbō is a 1994 beat ''em up developed by KID and published by Den’Z for the Super Famicom.', 'https://en.wikipedia.org/wiki/UFO_Kamen_Yakisoban'),
  ('Q8028769', 'Wizardry V: Heart of the Maelstrom is the fifth scenario in the Wizardry series of role-playing video games. It was published in 1988 by Sir-Tech for the Commodore 64, Apple II, and IBM PC compatibles (as a self-booting disk). A port for the Super Famicom and FM Towns was later developed and published by ASCII Entertainment in Japan. Wizardry V was released in the US for the Super NES by Capcom in 1993, and subsequently re-released for the Satellaview subsystem under the name BS Wizardry 5.', 'https://en.wikipedia.org/wiki/Wizardry_V:_Heart_of_the_Maelstrom'),
  ('Q7960738', 'Waka Taka Ōzumō: Brothers Dream Match is a sumo video game developed by Tomcat System and published by Imagineer for the Super Famicom, which was released exclusively in Japan in 1993.', 'https://en.wikipedia.org/wiki/Waka_Taka_%C5%8Czum%C5%8D:_Brothers_Dream_Match'),
  ('Q7961216', 'Waku Waku Ski Wonder Spur is a Skiing video game, developed by Human Club and published by Human Entertainment, which was released exclusively in Japan in 1995.

The game was released on January 13, 1995, for the Super Famicom system in Japan. Famitsu gave it a 21 out of 40 score.', 'https://en.wikipedia.org/wiki/Waku_Waku_Ski_Wonder_Spur'),
  ('Q7968366', 'War 3010: The Revolution is a turn-based strategy video game for the Super Nintendo Entertainment System developed and published by American studio Advanced Productions. It was released in 1996 only for North America. The story takes place in 3010 and is the sequel to War 2410.', 'https://en.wikipedia.org/wiki/War_3010:_The_Revolution'),
  ('Q7968365', 'War 2410 is a turn-based strategy video game for the Super Nintendo Entertainment System developed by American studio Advanced Productions that takes place in the year 2410.', 'https://en.wikipedia.org/wiki/War_2410'),
  ('Q8026234', 'Winter Gold is a 1996 winter sports video game developed by Funcom and published by Nintendo for the Super Nintendo Entertainment System. In the game, players participate in six winter sports disciplines across four distinct olympic venues. Its gameplay focuses on time trials in three playable modes, using a main five-button configuration. The 3D visuals are powered by the Super FX2 chip, an enhancement of Argonaut Software''s Super FX processor previously used in Doom and Yoshi''s Island.

Winter Gold garnered mixed critical reception. Praise was given to the presentation, fast pacing, 3D polygon graphics, techno-style soundtrack, and controls. Some reviewers were mixed regarding the gameplay and sound design, and criticized the lack of replay value, limited color palette, and letterboxed resolution.', 'https://en.wikipedia.org/wiki/Winter_Gold'),
  ('Q8028768', 'Wizardry VI: Bane of the Cosmic Forge (originally known as Wizardry: Bane of the Cosmic Forge) is the sixth game in the Wizardry series of role-playing video games. It was the first in the trilogy surrounding the Dark Savant, which was followed by Wizardry VII: Crusaders of the Dark Savant and Wizardry 8. The game was developed by Sir-Tech and published for the Amiga and MS-DOS in 1990 by the same company. Versions for the Super Famicom, FM Towns, and PC-98 were later released in Japan by ASCII.', 'https://en.wikipedia.org/wiki/Wizardry_VI:_Bane_of_the_Cosmic_Forge'),
  ('Q7935040', 'Virtual Soccer – known in Japan as J.League Super Soccer – is a 1994 football video game published by Hudson Soft.', 'https://en.wikipedia.org/wiki/Virtual_Soccer'),
  ('Q8042912', 'Whirlo is a side-scrolling action-platform released by Namco on July 23, 1992 in Japan for the Super Famicom video game system, and in Europe and Australia later during the same year. The game was re-released on August 1, 1998 in Nintendo Power flash RAM cartridge format.

The game is a prequel to Valkyrie no Bōken: Toki no Kagi Densetsu and features Whirlo (known as Krino Xandra in Japan), a secondary character from the first game, in a starring role. While the character designs by Hiroshi Fuji give the game the appearance of a picture book, the degree of difficulty is high, and there are many "bad ending" scenarios.', 'https://en.wikipedia.org/wiki/Whirlo'),
  ('Q8041541', 'X-Zone is a rail shooting video game released in 1992 by Kemco for the Super NES. It is played with the Super Scope light gun.', 'https://en.wikipedia.org/wiki/X-Zone'),
  ('Q8041457', 'X-Kaliber 2097 is a 1994 action game published by Activision for the Super Nintendo Entertainment System. It was co-developed by the Japanese studios Fupac and Winds.', 'https://en.wikipedia.org/wiki/X-Kaliber_2097'),
  ('Q8035815', 'World Heroes is a 1992 fighting video game developed by Alpha Denshi and published by SNK for the Neo Geo arcade and home systems. It is ADK''s first game in the fighting game genre, as well as their earliest attempt in the fighting game trend of the 1990s that was popularized by Capcom''s 1991 arcade hit Street Fighter II.

World Heroes was followed by a sequel, released less than a year later, titled World Heroes 2.', 'https://en.wikipedia.org/wiki/World_Heroes_(video_game)'),
  ('Q8034500', 'Wordtris is a Tetris offshoot designed by Sergei Utkin, Vyacheslav Tsoy and Armen Sarkissian (who later became President of Armenia) and published by Spectrum HoloByte in 1991 for MS-DOS compatible operating systems. Ports were released for the Game Boy and Super Nintendo Entertainment System in 1992, followed by a Mac version in 1993.', 'https://en.wikipedia.org/wiki/Wordtris'),
  ('Q8035916', 'World League Soccer, known as Pro Soccer in Japan, is an association football-based sports video game developed by C-Lab, and released for the Super Nintendo Entertainment System and X68000 in 1991.', 'https://en.wikipedia.org/wiki/World_League_Soccer'),
  ('Q8035948', 'World Masters Golf is a golf simulation video game for the Super NES released in Europe.', 'https://en.wikipedia.org/wiki/World_Masters_Golf'),
  ('Q8036226', 'Striker is a soccer video game series first released by Rage Software in 1992. The game was released for the Amiga, Amiga CD32, Atari ST, PC, Mega Drive, and Super Nintendo Entertainment System. It was bundled in one of the Amiga 1200 launch packs. It was one of the first soccer games to feature a 3D viewpoint, after Simulmondo''s I Play 3D Soccer.

In 1993 it was released in Japan by Coconuts Japan for the Super Famicom as World Soccer, while the French Super NES version of Striker is known as Eric Cantona Football Challenge, playing on the popularity of French forward Eric Cantona, while the North American Super NES release of Striker was known as World Soccer ''94: Road to Glory.', 'https://en.wikipedia.org/wiki/Striker_(video_game)'),
  ('Q8031770', 'Wonder Project J is a 1994 life simulation video game developed by Almanic Corporation and published by Enix for the Super Famicom. In the game, the player cares for a boy Gijin (robot) created by Dr. Geppetto named Pino. Directed by Takashi Yoneda, the title was created by most of the same personnel that worked on previous projects at Almanic such as E.V.O.: Search for Eden. It was met with positive reception from critics and sold over 1.3 million copies in Japan, making it one of the best-selling Super Famicom games. A sequel, Wonder Project J2, was released in 1996 for the Nintendo 64.', 'https://en.wikipedia.org/wiki/Wonder_Project_J'),
  ('Q8062791', 'Yūyu no Quiz de Go! Go! is a Japanese quiz video game released by Taito for the arcades in 1990, and later ported to the Super Famicom platform.

The game was featured in episode 72 (10th Season) of GameCenter CX. Yūyu no Quiz de Go! Go! (Director''s Cut) is featured in the DVD-Box Vol. 6, released on December 18, 2009.', 'https://en.wikipedia.org/wiki/Y%C5%AByu_no_Quiz_de_Go!_Go!'),
  ('Q8058309', 'Young Merlin is a video game released for the Super NES in 1993. The game follows a young Merlin as he enlists the help of the Lady of the Lake to help him defeat the evil Shadow King.', 'https://en.wikipedia.org/wiki/Young_Merlin'),
  ('Q8069495', 'Zero4 Champ RR-Z is a 1995 racing video game developed by Media Rings for the Super Famicom and the sequel to Zero4 Champ RR.', 'https://en.wikipedia.org/wiki/Zero4_Champ_RR-Z'),
  ('Q8069493', 'Zero4 Champ RR is a 1994 racing video game developed and published by Media Rings for the Super Famicom. The game is about an 18-year-old race car driver who must chase his dreams of drag racing after being turned down for university and becoming a rōnin due to his joblessness status. The game received a sequel, Zero4 Champ RR-Z.', 'https://en.wikipedia.org/wiki/Zero4_Champ_RR'),
  ('Q8189078', 'Konpeki no Kantai is a Japanese alternate history series produced by J.C.Staff. The series focuses on both a technologically advanced Imperial Japanese Navy and a radically-different World War II that were brought about by Admiral Isoroku Yamamoto''s revival by unexplained circumstances. Both the published books and the original video animation (OVA) series are also notable for using the Imperial Japanese calendar, instead of the Western calendar, in denoting the years in which the events of the series take place. It also spawned a 1997 OVA side story, Kyokujitsu no Kantai, one manga sequel, and two turn-based strategy games for the PC-FX and the Super Famicom.', 'https://en.wikipedia.org/wiki/Konpeki_no_Kantai'),
  ('Q8081824', 'This is a list of video games based on the wrestling sport of sumo.', 'https://en.wikipedia.org/wiki/List_of_sumo_video_games'),
  ('Q8062128', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q8065994', 'Namco Tales Studio Ltd., formerly known as Wolf Team (ウルフチーム, Urufu Chīmu), was a Japanese video game development company founded in 1986. The company was renamed in 2003 when Telenet Japan sold part of its stake and made Namco the majority shareholder. Namco Tales Studio was originally the primary developer of the Tales RPG series, as it had been since the series'' beginning. In November 2011, it was announced that the current Tales Studio would be dissolved and would merge with their publisher, Namco Bandai Games. In February 2012, it was announced that the 80 people of the Tales team would join Bandai Namco Studios.', 'https://en.wikipedia.org/wiki/Namco_Tales_Studio'),
  ('Q8069143', 'Zenkoku Kōkō Soccer is a soccer simulation game, developed by Affect and published by Yojigen, which was released exclusively in Japan in 1994. It features teams from the Japanese high schools. These teams are located on the islands in addition to the mainland.

Two sequels were spawned: Zenkoku Kōkō Soccer 2 and Zenkoku Kōkō Soccer Senshuken ''96.', 'https://en.wikipedia.org/wiki/Zenkoku_K%C5%8Dk%C5%8D_Soccer'),
  ('Q8069144', 'Zenkoku Kōkō Soccer 2 is a soccer simulation game, developed by Nihon Syscom and published by Yojigen, which was released exclusively in Japan in 1995. It features teams from the Japanese high schools from the islands in addition to the mainland.

This game is a sequel to Zenkoku Kōkō Soccer and a prequel to Zenkoku Kōkō Soccer Senshuken ''96.', 'https://en.wikipedia.org/wiki/Zenkoku_K%C5%8Dk%C5%8D_Soccer_2'),
  ('Q8071476', 'Zico Soccer from Electronic Arts is a football management video game released for the Super Famicom that allows players to become the head coach of an international football team; it was named after the Brazilian midfielder Zico, who at the time was playing for Japanese team Kashima Antlers. The game is mostly in the Japanese language although some words are in the English language.', 'https://en.wikipedia.org/wiki/Zico_Soccer'),
  ('Q9291443', 'Inindo: Way of the Ninja is a 1991 role-playing video game developed and published by Koei for the Super Famicom and Japanese home computers. Originally exclusive to Japan, the game later saw a release in North America for the Super Nintendo Entertainment System (SNES) in 1993. The game is a fictional account of Japan''s warring states period.', 'https://en.wikipedia.org/wiki/Inindo:_Way_of_the_Ninja'),
  ('Q9299894', 'King Arthur''s World is a 1992 strategy video game developed by Argonaut Software and published by Jaleco for the Super Nintendo Entertainment System (SNES).', 'https://en.wikipedia.org/wiki/King_Arthur%27s_World'),
  ('Q10353565', 'Prehistorik Man is a platform video game developed and published by Titus Interactive for the Super Nintendo Entertainment System. It is a sequel to Prehistorik 2, featuring similar graphics but a richer and different story, and additional non-player characters which, among other things, provide hints and a tutorial.

The game was later released for the Game Boy Advance and the Nintendo DSi (as a DSiWare release), with the latter being released in North America in February 2010. Prehistorik Man was added to the Nintendo Classics service in February 2021.

The Super NES version received positive reviews from critics with the story, sound and gameplay being praised. The Game Boy Advance and DSiware ports, however, have gotten mixed reviews.', 'https://en.wikipedia.org/wiki/Prehistorik_Man'),
  ('Q9285852', 'Timon & Pumbaa''s Jungle Games is a 1995 party video game developed by 7th Level and published by Disney Interactive Studios. The game was released on December 15, 1995, for Microsoft Windows. It was one of only two games under the Disney Gamebreak brand, the other being The Hunchback of Notre Dame: Topsy Turvy Games. A Super Nintendo Entertainment System port, developed by Tiertex and published by THQ, was released in North America and PAL territories in November 1997 and March 1998, respectively.', 'https://en.wikipedia.org/wiki/Timon_%26_Pumbaa%27s_Jungle_Games'),
  ('Q11091967', 'Dragon Slayer: The Legend of Heroes is a 1989 role-playing video game developed by Nihon Falcom. It is the sixth game in the Dragon Slayer series and the first in The Legend of Heroes franchise.

It was originally released in 1989 for the NEC PC-8801. Within the next few years, it would also be ported to the NEC PC-9801, MSX2, PC Engine CD-ROM, X68000, Mega Drive, and Super Famicom. A Dragon Slayer: The Legend of Heroes Barcode Battler card set was also released by Epoch Co. in 1992. The PC Engine version was released in the United States for the TurboGrafx-CD, and was the only game in the series released in the US until The Legend of Heroes: A Tear of Vermillion, the PlayStation Portable remake.', 'https://en.wikipedia.org/wiki/Dragon_Slayer:_The_Legend_of_Heroes'),
  ('Q10960843', 'Daikaijū Monogatari is a Japanese role-playing video game developed by Birthday and published by Hudson Soft for Super Famicom, in December 1994 in Japan. It is a sequel to the Famicom game Kaijū Monogatari.', 'https://en.wikipedia.org/wiki/Daikaij%C5%AB_Monogatari'),
  ('Q11242781', 'Compati Hero is a video game series published in Japan by Banpresto and Bandai Namco Entertainment that began in 1990 and features 16 crossover teams between Ultraman, Kamen Rider (also known as Masked Rider) and Gundam. Characters from other franchises have also been featured in some of the initial games, as well as in the Compati Sports series such as Mazinger, Getter Robo, Devilman and Godzilla.

It was the first video game series to involve a crossover between animated giant robots and live action tokusatsu heroes from different established franchises. The series makes this possible by using caricaturized versions of the characters (officially referred to as "SD" or "super deformed" characters), which allowed the different heroes and villains to co-exist and interact with each other without the need to reconcile their contrasting styles, settings, or sizes. This also made them appear cute. The first game in the series, SD Battle Ōzumō: Heisei Hero Basho for the Famicom, which mixed franchises that were originally licensed to Popy, was developed as a congratulatory present to Yukimasa Sugiura when he was promoted to president of Banpresto at the time, and was soon followed by series of spin-offs and related games featuring the same cast of characters that developed into the Compati Hero Series. The crossover was also possible due to Banpresto''s parent company Bandai holding the merchandising rights for all the properties associated with the series.', 'https://en.wikipedia.org/wiki/Compati_Hero'),
  ('Q11290849', 'Emerald Dragon is a role-playing video game developed by Glodia and released for multiple platforms in Japan. It was first launched for the NEC PC-8801 and PC-9801 home computers on December 22, 1989, followed by conversions for the X68000 (released on December 6, 1990), MSX2 (released on December 26 of the same year), and FM Towns (released on May 28, 1992). Developer Alfa System later produced console versions of the game for the PC Engine in Super CD-ROM² format (released on January 29, 1994) and the Super Famicom (released on July 28, 1995). The game features characters and locations based on Zoroastrian mythology.', 'https://en.wikipedia.org/wiki/Emerald_Dragon'),
  ('Q11309363', 'Smart Ball is a platform game developed by Game Freak and System Sacom. It was published by Epic/Sony Records and Sony Imagesoft for the Super Nintendo Entertainment System in 1991. A sequel titled Jerry Boy 2 was in production, but was not released.', 'https://en.wikipedia.org/wiki/Smart_Ball'),
  ('Q11306769', 'The Monopoly Game 2 is a 1995 video game developed by Tomcat System and published by Tomy for the Super Famicom. It was not released outside of Japan.

This game is the sequel to a 1993 Super Famicom game called Monopoly, which was published by Tomy and developed by Ape Inc. and CreamSoft (not to be confused with the 1991 Monopoly game by Sculptured Software). It was likewise Japan only.

Aside from co-developing the game, Ape also wrote a complete guidebook to it with rules and tactics. It was released in May 1995 by book publishing company Aspect (not to be confused with the game development company Aspect).', 'https://en.wikipedia.org/wiki/The_Monopoly_Game_2'),
  ('Q11304137', 'Syvalion is a 1988 multidirectional shooter video game developed and published by Taito for arcades. It was designed by Fukio Mitsuji, creator of Bubble Bobble. It was released only in Japan in October 1988. It received a port to the Super Nintendo Entertainment System in 1992, which was also released in Europe.

The game saw numerous inclusions in various compilations and digital download services: it was re-released for the PlayStation 2 in Japan as part of Taito Memories Jōkan in 2005, and then received a Western re-release as part of Taito Legends 2 in 2006. Both versions feature analog stick support to make the game easier to play. Hamster Corporation released the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4, as well as their Arcade Archives 2 series for the Nintendo Switch 2, PlayStation 5 and Xbox Series X/S in July 2026.', 'https://en.wikipedia.org/wiki/Syvalion'),
  ('Q11314000', 'Super Mahjong Taikai is a Japanese mahjong video game that was released in Japan by Koei, now Koei Tecmo, in September 1992.', 'https://en.wikipedia.org/wiki/Super_Mahjong_Taikai'),
  ('Q11321807', 'Traverse: Starlight & Prairie is a Japanese-only non-linear, turn-based role-playing video game developed by Pandora Box and published by Banpresto in 1996. It is a sequel to Soul & Sword, with a few returning characters.', 'https://en.wikipedia.org/wiki/Traverse:_Starlight_%26_Prairie'),
  ('Q11319330', 'Tetris Battle Gaiden is a puzzle video game developed and published in 1993 by Bullet-Proof Software for the Super Famicom. Released only in Japan, the game is a variant of the Tetris series involving multiplayer battles comparable to those of the Puyo Puyo and Columns series of video games. The game received its first international release via the Tetris Forever (2024) video game compilation.', 'https://en.wikipedia.org/wiki/Tetris_Battle_Gaiden'),
  ('Q11332146', 'Phalanx (full title: Phalanx: The Enforce Fighter A-144) is a 1991 horizontally scrolling shooter developed by ZOOM Inc. and Kemco for the X68000, Super Nintendo Entertainment System, and Game Boy Advance. The game was released for the X68000 in Japan in 1991, for the Super NES in Japan on August 7, 1992, in North America in October and in the same year in Europe, as well as for the Game Boy Advance in 2001 in Japan on October 26, in Europe on November 23, and in North America on December 27.

Phalanx is infamous for the incongruous box art in its American release: it displays a bearded, elderly man dressed in overalls, wearing a fedora and playing a banjo while a futuristic spaceship flies in the background. The popular media site IGN named it their fifth "Most Awesome Cover" in a top 25 countdown on their website. The advertising company responsible for the box art later admitted that they had deliberately chosen this theme in order to attract the customer with something original, considering there were many space shooters in the market that looked alike. The Game Boy Advance release used a redesigned cover with a prominent image of a spaceship.', 'https://en.wikipedia.org/wiki/Phalanx_(video_game)'),
  ('Q11326105', 'HyperZone is a rail shooter video game developed and published by HAL Laboratory for the Super Nintendo Entertainment System (SNES). It used the SNES'' Mode 7 capability.', 'https://en.wikipedia.org/wiki/HyperZone'),
  ('Q11340195', 'Magical Drop is a 1995 puzzle video game developed and released by Data East in Japanese arcades. It was later ported to Super Famicom, Sega Saturn, and PlayStation. It is the first entry in the Magical Drop series. In the game, the player takes control of one of six characters, battling against computer-controlled opponents before facing the goddess World in a final encounter. The objective is to clear the screen of constantly advancing colored ''drops'' via a character placed at the bottom of the playfield, which can grab drops and make them disappear by putting them as a column of three or more drops of the same color. Two players can also participate in a competitive versus mode. It ran on the Data East Simple 156 hardware.', 'https://en.wikipedia.org/wiki/Magical_Drop_(video_game)'),
  ('Q11340202', 'Magical Pop''n is a side-scrolling action-platform video game. It was developed by Polestar and published by Pack-In-Video exclusively for the Super Famicom in Japan on 10 March 1995. In Magical Pop''n, the Demon King''s army invades the kingdom of To''ahl and steals a magic gem that holds tremendous power from the castle. The Princess (voiced by AV idol Ai Iijima) then sets out on a journey to retrieve the stolen gem, before it can be used for the Demon King''s nefarious plans of world domination. Its gameplay consists of platforming and exploration with a main six-button configuration, featuring special moves and techniques.', 'https://en.wikipedia.org/wiki/Magical_Pop%27n'),
  ('Q11349832', 'Lennus II: Fūin no Shito is a 1996 role-playing video game for the Super Famicom. It was developed by Copya System, and published by Asmik Corporation.', 'https://en.wikipedia.org/wiki/Lennus_II'),
  ('Q11342889', 'Metal Marines, released in Japan as Militia, is a 1993 real-time strategy video game developed and published by Namco for the Super Nintendo Entertainment System. It was ported to Microsoft Windows by Mindscape. The Super NES version was re-released on the Virtual Console in Japan on July 10, 2007, for the Wii and on March 4, 2015, for the Wii U, and in North America on October 15, 2007, for the Wii.', 'https://en.wikipedia.org/wiki/Metal_Marines'),
  ('Q11359557', 'Shanghai III is a 1993 mahjong solitaire video game developed by Success and Kuusoukagaku and published by Sunsoft for arcades. A port to the Super Famicom, which uses the Super NES Mouse, was released only in Japan in 1994. It is the third installment in Sunsoft''s series of Shanghai games, released under license from Activision and separate from Activision''s own mainline series.

Hamster Corporation released the game as part of their Arcade Archives series for the PlayStation 4 in 2015 and Nintendo Switch in 2020, marking its first international release.', 'https://en.wikipedia.org/wiki/Shanghai_III'),
  ('Q11341843', 'Marvelous: Mōhitotsu no Takarajima is a 1996 video game developed and published by Nintendo for the Super Famicom. It is the first title directed by Eiji Aonuma.

Two special versions of the game, BS Marvelous: Time Athletic and BS Marvelous: Camp Arnold were released for the Satellaview.', 'https://en.wikipedia.org/wiki/Marvelous:_M%C5%8Dhitotsu_no_Takarajima'),
  ('Q11431230', 'Yakōchū is a 1995 visual novel made by Athena for the Super Famicom. The game involves players following a text-based narrative over illustrated backgrounds with sounds that play at key moments to enhance the story. Yakōchū is about a sea captain who travels on a cruise ship, where various problems happen ranging from natural disasters, deaths of the crew members, or more supernatural events. After completing the game once, the player can restart where new narrative branch options become available, allowing new stories to be available.

Yakōchū was one of the early sound novels released following the release of Chunsoft''s Otogirisō (1992) and Banshee''s Last Cry (1994). Some critics in Famicom Tsūshin found the game''s narrative too short, while the Hamamura Tsūshin listed the game as the "Best Picks of This Week" for June 12 to June 18, 1995. The game was later ported to the Game Boy Color as Yakōchū GB in 1999 and received a sequel for the Nintendo 64 titled Yakōchū II: Satsujin Kouro .', 'https://en.wikipedia.org/wiki/Yak%C5%8Dch%C5%AB'),
  ('Q11389993', 'Natsume Championship Wrestling is a 1994 Super Nintendo Entertainment System video game that was released in North America.

This game is widely based on a conversion of Zen-Nippon Pro Wrestling Dash: Sekai Saikyō Tag, a Japanese video game for the Super Famicom based on the All Japan Pro Wrestling promotion. Players must become either the Triple Crown Champion or the Triple Crown Tag Team Champions and achieve the limits of professional wrestling.

Natsume Championship Wrestling was re-released via the Wii Virtual Console in 2011, the Wii U Virtual Console in 2014, and the Nintendo Classics service in July 2020.', 'https://en.wikipedia.org/wiki/Natsume_Championship_Wrestling'),
  ('Q11514515', 'Tsukikomori is a 1996 visual novel for the Super Famicom. The game features a family gathering after the funeral of their grandmother. Each person gathered tells ghost stories. Depending on the order the player takes in choosing who to tell the story, the stories change.

Developed by Pandora Box and published by Banpresto, it is considered a companion piece to their previous game Gakkou de atta Kowai Hanashi (1995). On its release, it was not as popular as the companion release, but it grew in popularity by 2017. The game received positive commentary from three of the four reviewers in Famitsu who found it to be a proper expansion of the ideas shown in Gakkou de atta Kowai Hanashi. The game was re-released on Nintendo''s Virtual Console for the Wii U as well as being set for a re-release in Japan for the Nintendo Switch in 2026.', 'https://en.wikipedia.org/wiki/Tsukikomori'),
  ('Q11516247', 'Anubis of the Moon''s Surface is a 1995 visual novel. The game has a science fiction setting of a lunar base on the moon. Depending on the players actions in the game, the protagonist Keisuke changes his personality to move forward with the story.

The game was at at least 35% completion by late October 1995 and was published along with a similar game from Imagineer, Zakuro no Aji. Famicom Tsūshin found the game did not give enough options for the players to move the story in different directions and compared it with Zakuro no Aji. The Japanese book Perfect Guide to Nostalgic Super Famicom (2016) included it on their list of the best horror games for the Super Famicom, finding it to be a lesser known but good horror sound novel.', 'https://en.wikipedia.org/wiki/Anubis_of_the_Moon%27s_Surface'),
  ('Q11569158', 'Enix was a Japanese video game publishing company founded in September 1975 by Yasuhiro Fukushima. Initially a tabloid publisher named Eidansha Boshu Service Center, it ventured in 1982 into video game publishing for Japanese home computers such as the PC-8800 series, the X1 series, and the FM-7. Enix initially found games to release by holding contests for programming hobbyists and publishing the winners, with the first titles appearing in February 1983. Enix continued to hold contests and publish the winners through 1993. When Enix moved into traditional publishing for video game consoles in 1985, it began with ports of two of its more successful games, Door Door (1983) and The Portopia Serial Murder Case (1983). From that point onward, Enix served as a publisher for both video games developed independently by other companies as well as for titles in franchises owned by Enix and created by licensed developers. Enix''s flagship franchise was the Dragon Quest series of console games, developed primarily by Chunsoft; some of the games, such as Dragon Quest VII (2000), have sold millions of copies, and the series as a whole has sold over 85 million copies as of March 2022.', 'https://en.wikipedia.org/wiki/List_of_Enix_games'),
  ('Q11673840', 'Majūō is a 1995 Japanese action game published by KSS for the Super Famicom. The story is that of a man named Abel who must rescue his wife and child from hell. It is a 2D side scrolling game. Defeating bosses allows the player to transform into various demons. In 2024, there was an announcement of a new release from Retro-Bit.', 'https://en.wikipedia.org/wiki/Maj%C5%AB%C5%8D'),
  ('Q11660555', 'Denjinmakai, or Denjin Makai, is a 1994 side-scrolling beat ''em up developed by Winkysoft and published by Banpresto that was originally released as a coin-operated arcade game. It was later ported to the Super Famicom (known as the Super Nintendo Entertainment System in other countries) under the title Ghost Chaser Densei. The Super Famicom release is Japan-only. A sequel, Guardians, was released in 1995.', 'https://en.wikipedia.org/wiki/Denjin_Makai'),
  ('Q13218405', 'Major Title is a 1990 golf video game developed and published by Irem for arcades. A version of the game for the Super Nintendo Entertainment System and an arcade sequel, Major Title 2: Tournament Leader, were released in 1992. The SNES game and the arcade sequel were released in the United States as The Irem Skins Game.

The programmers of this game left Irem to found their own company named Nazca. The first game released by Nazca was Neo Turf Masters for Neo Geo in 1996; the game is very similar to Major Title 2.', 'https://en.wikipedia.org/wiki/Major_Title'),
  ('Q12005929', 'This is a list of The Smurfs video games that have been published by developers such as Coleco, Infogrames, and Capcom. The Smurfs (Les Schtroumpfs) are a fictional group of small sky blue creatures who live in a village in the woods. They were designed by Belgian cartoonist Peyo in 1958 and were featured in the Belgian comics magazine Spirou. They are widely known through the 1980s Hanna-Barbera animated television series of the same name.

As a franchise, the Smurfs appeared in many video games throughout the 1980s and 1990s on many consoles. They have been released for the Nintendo Entertainment System, the Super Nintendo Entertainment System, the Game Boy line, the early Atari consoles, Coleco''s ColecoVision, most of Sega''s consoles, the PlayStation, the PC, iOS, Android, Nintendo DS, Wii, Nintendo Switch, and Nintendo 3DS.', 'https://en.wikipedia.org/wiki/List_of_The_Smurfs_video_games'),
  ('Q12170990', 'Bubsy in: Claws Encounters of the Furred Kind, often shortened to Bubsy, is a 1993 platform game developed and published by Accolade for the Super Nintendo Entertainment System. A port to the Sega Genesis was released months later. It is the first entry in the Bubsy series of video games. The game''s title is a play on words in reference to the film Close Encounters of the Third Kind, with the game revolving around Bubsy defending the planet''s supply of yarn balls from alien invaders.

The game was ported to Windows in 1997 under the title Super Bubsy. A sequel, Bubsy II, was released in 1994.', 'https://en.wikipedia.org/wiki/Bubsy_in_Claws_Encounters_of_the_Furred_Kind'),
  ('Q13390015', 'Wing Commander is the first game in Chris Roberts'' space flight simulation Wing Commander franchise by Origin Systems. The game was first released for MS-DOS on September 26, 1990, and was later ported to the Amiga, CD32 (256-color), Sega CD and the Super Nintendo Entertainment System, and re-released for the PC as Wing Commander I in 1994. An enhanced remake Super Wing Commander was made for the 3DO in 1994, and later ported to the Macintosh.

Two expansion packs for the game were released: Wing Commander: The Secret Missions in November 1990 and Wing Commander: The Secret Missions 2: Crusade in March 1991.', 'https://en.wikipedia.org/wiki/Wing_Commander_(video_game)'),
  ('Q15711525', 'Skyblazer is a platform video game published by Sony Imagesoft, released in early 1994 for the Super Nintendo Entertainment System. It involves Sky, the Skyblazer hero (Garuda in the Japanese version) searching for Ashura (Asura in the Japanese version), the Lord of War, who had kidnapped the sorceress Ariana (Vishnu in the Japanese version).', 'https://en.wikipedia.org/wiki/Skyblazer'),
  ('Q15923058', 'J.R.R. Tolkien''s The Lord of the Rings, Vol. I is a 1994 action role-playing game developed and published by Interplay Productions for the Super Nintendo Entertainment System. It is an adaptation of The Fellowship of the Ring by J. R. R. Tolkien.', 'https://en.wikipedia.org/wiki/J.R.R._Tolkien%27s_The_Lord_of_the_Rings,_Vol._I_(1994_video_game)'),
  ('Q15650127', 'Dragon Slayer: The Legend of Heroes II is a 1992 role-playing video game by Nihon Falcom. It is part of the Dragon Slayer series and the second entry in The Legend of Heroes subseries. The game first released for the NEC PC-8801 before being ported to the NEC PC-9801, FM Towns, PC Engine, Mega Drive, Super Famicom and MS-DOS.', 'https://en.wikipedia.org/wiki/Dragon_Slayer:_The_Legend_of_Heroes_II'),
  ('Q15623299', 'Super Genjin 2 is a 1995 2D platform video game by Hudson Soft for Super Famicom. It is the sequel to Super Bonk and the fifth platform game in the Bonk series, and the second game in the series overall never to be released outside Japan.', 'https://en.wikipedia.org/wiki/Super_Genjin_2'),
  ('Q16258825', 'Verne World is a role-playing video game that was released for the Super Famicom exclusively for the Japanese market. The game revolves around the main character being trapped in a theme park based around the works of Jules Verne such as A Journey to the Center of the Earth and Twenty Thousand Leagues Under the Seas.', 'https://en.wikipedia.org/wiki/Verne_World'),
  ('Q16259327', 'Super Keirin is a Japanese-exclusive video game with gambling/life sim elements, where players take control of their character and make money by betting on cycle races at the local Velodrome.

Cute anime-style graphics are employed throughout the game; stating that the premise of the game is less serious than other Super NES gambling style video games.', 'https://en.wikipedia.org/wiki/Super_Keirin'),
  ('Q16267400', 'Hat Trick Hero 2 is a 1994 association football video game developed by Neverland and published by Taito for the Super Famicom. It is the sequel to Hat Trick Hero (1991). A North American release, Super Soccer Champ 2, was planned but not released.', 'https://en.wikipedia.org/wiki/Hat_Trick_Hero_2'),
  ('Q16267786', 'Power Drive is a 1994 racing video game developed by Rage Software and published by U.S. Gold. The player competes in rally driving in various countries.', 'https://en.wikipedia.org/wiki/Power_Drive_(1994_video_game)'),
  ('Q16266786', 'Motoko-chan no Wonder Kitchen or Motokochan in Wonder Kitchen is a 1993 adventure video game developed by Nintendo and published by Ajinomoto for the Super Famicom. It features minigames related to cooking. The game was a promotional item with a production run of 10,000 units which were used for a lottery contest. Consumers who mailed in two proof of purchase seals from Ajinomoto mayonnaise were entered into the contest to win the game, which was run over five months with 2,000 copies given away monthly. Due to Ajinomoto''s inexperience in video game development, Nintendo was subcontracted to develop the actual game.', 'https://en.wikipedia.org/wiki/Motoko-chan_no_Wonder_Kitchen'),
  ('Q16266999', 'Hebereke''s Popoon is a 1993 puzzle video game developed and published by Sunsoft. The game was first released for the Super Famicom in 1993 in Japan, and the SNES in Europe a year later, and was also ported to the arcades in 1994 in Japan only. It is the second game in the Hebereke series. Hebereke means drunk or untrustworthy, while Popoon is an onomatopoeia for the sound made by the game pieces when they explode.

The game is a Puyo Puyo clone where players align Popoons with others to make them explode.', 'https://en.wikipedia.org/wiki/Hebereke%27s_Popoon'),
  ('Q16267025', 'Mecarobot Golf is an arcade-style golf video game released for the Super Nintendo Entertainment System. The game was originally released in Japan as Serizawa Nobuo no Birdie Try.

The general theme of Mecarobot Golf is a near-futuristic golf course where humanoid robots are considered to be second-class citizens. A robot named Eagle is banned from participating in the world''s professional golfing tournaments due to discrimination. Eagle has the ability to play golf better than a human being, but is denied the chance to play with human individuals. A benefactor purchases Eagle and builds a golf course for him to practice on. The player''s skill determine whether humans or robots are truly better at golf. Various modes (lesson, driving range, competition) help the player practice his abilities that he will need in future matches.', 'https://en.wikipedia.org/wiki/Mecarobot_Golf'),
  ('Q16259657', 'Hiōden: Mamono-tachi tono Chikai (緋王伝 魔物達との誓い) is a video game that was published in 1992 by Telenet Japan and developed by their Wolfteam subsidiary. It was released on the NEC PC-98 in the same year. The game was later ported to the Super Famicom in 1994. Its subtitle could be translated as "Legend of the Scarlet King".

The game can be played using the SNES mouse or a normal controller.', 'https://en.wikipedia.org/wiki/Hi%C5%8Dden:_Mamono-tachi_tono_Chikai'),
  ('Q16267023', 'Tennis Cup is a 1990 tennis video game developed and published by Loriciel for the Amiga. It was ported to the Atari ST, MS-DOS and Amstrad CPC during the same year. Tennis Cup was ported to TurboGrafx-16 in 1991 as Davis Cup Tennis. Versions for the Super NES (International Tennis Tour) and Mega Drive/Genesis (Davis Cup World Tour) were released in 1993.

The Amstrad version received a sequel, Tennis Cup 2, in 1990. A 16-bit sequel, also titled Tennis Cup 2, was released in 1992 for the Amiga, Atari ST, and MS-DOS.', 'https://en.wikipedia.org/wiki/Tennis_Cup'),
  ('Q16258851', 'The Wizard of Oz is a 1993 platform video game released for the Super Nintendo Entertainment System and loosely based on the 1939 film The Wizard of Oz. Developed by Manley & Associates, it was published by SETA Corporation and released in North America in 1993 and in Europe in 1994. The player assumes the role of Dorothy, the Scarecrow, the Tin Man, or the Cowardly Lion in a series of levels containing hidden areas, mazes, and puzzles to bring Glinda''s magic ruby slippers to the Wizard of Oz.

Upon its release, it received generally positive reviews for its graphics, challenge, and playable female heroine. Retrospective coverage, however, has been negative including ranking on lists of the worst games of all time. Criticisms include poor collision detection, controls, weak character attacks, and mishandling of the source material.', 'https://en.wikipedia.org/wiki/The_Wizard_of_Oz_(1993_video_game)'),
  ('Q16205643', 'Where in the World Is Carmen Sandiego? is an educational video game released by Broderbund on April 23, 1985. It is the first product in the Carmen Sandiego franchise. The game was distributed with The World Almanac and Book of Facts, published by Pharos Books. An enhanced version of the game was released in 1989, which did not have the almanac-based copy protection and instead used disk-based copy protection. A deluxe version was released in 1990, and features additional animation and a reworked interface from the original version. Some of the bonus features include digitized photos from National Geographic, over 3200 clues, music from the Smithsonian/Folkways Recordings, 20 villains, 60 countries, and 16 maps. CD-ROM versions for MS-DOS and Mac were released in 1992. A Windows version was released in 1994.', 'https://en.wikipedia.org/wiki/Where_in_the_World_Is_Carmen_Sandiego%3F_(1985_video_game)'),
  ('Q16259167', 'Nolan Ryan''s Baseball (known in Japan as Super Stadium) is a baseball video game endorsed by then-Texas Rangers baseball player Nolan Ryan; one of the most popular baseball players of the late 20th century. It has no licensing from Major League Baseball and the Major League Baseball Players Association; meaning that Nolan Ryan is the only non-fictional ballplayer in the entire game. All the other players have names that appear to be given names while Nolan Ryan uses his surname. The game was developed by Japanese game studio Affect, and was one of their earliest productions.', 'https://en.wikipedia.org/wiki/Nolan_Ryan%27s_Baseball'),
  ('Q16677481', 'Sonic Blast Man II is a beat ''em up video game developed and published by Taito for the Super Nintendo Entertainment System in 1994.', 'https://en.wikipedia.org/wiki/Sonic_Blast_Man_II'),
  ('Q16679554', 'The Flintstones is a 1994 video game adaptation of the live-action 1994 film The Flintstones. It was released on Super NES and Game Boy, while a Sega Genesis version was distributed via Sega Channel.', 'https://en.wikipedia.org/wiki/The_Flintstones_(1994_Ocean_Software_video_game)'),
  ('Q16736412', 'Super Drift Out: World Rally Championships is a 1995 rallying video game developed by Dragnet and published by Visco Corporation for the Super Famicom. It is the third game in the Drift Out series, and was followed by Neo Drift Out: New Technology. It resembles the first Drift Out and is sometimes referred to as a port or remake.

All races in this game are based on the 1994 World Rally Championship season. Two types of background music (''normal'' and ''hard'' beats) and three racing levels (easy, normal, and hard) are available. The top six times are tracked in each of the rally legs, including the super special stage.', 'https://en.wikipedia.org/wiki/Super_Drift_Out'),
  ('Q16382836', 'Bonkers is a 1994 platform video game developed by Sun-L and published by Capcom for the Super Nintendo Entertainment System It was originally released in North America in October 1994. It is based on the animated television series Bonkers. The game was re-released for the first time as part of the Nintendo Switch and Nintendo Switch 2 versions of The Disney Afternoon Collection, released by Atari under license from Capcom and Disney in 2026.', 'https://en.wikipedia.org/wiki/Bonkers_(SNES_video_game)'),
  ('Q18149314', 'Beauty and the Beast is a 1994 platform game for the Super Nintendo Entertainment System. Based on the 1991 animated film of the same name, it was developed by Probe Entertainment and published by Hudson Soft in North America in July 1994 and Europe on February 23, 1995, respectively. The game was published by Virgin Interactive in Japan on July 8, 1994.', 'https://en.wikipedia.org/wiki/Disney%27s_Beauty_and_the_Beast_(SNES_video_game)'),
  ('Q16938346', 'Shōnen Ninja Sasuke is an action-adventure game released by Sunsoft for the Super Nintendo Entertainment System in 1994. The game was supposed to be released in English as Boy Ninja Sasuke. In October 2024, Ratalaika Games and Sunsoft announced that they would release Shōnen Ninja Sasuke in English under the name Justice Ninja Casey in 2025.', 'https://en.wikipedia.org/wiki/Sh%C5%8Dnen_Ninja_Sasuke'),
  ('Q16514315', 'Bishōjo Senshi Sailor Moon R is a side-scrolling beat ''em up video game developed by Angel and published by Bandai in Japan on December 29, 1993. It is the third game to be created by Angel based upon Naoko Takeuchi''s Sailor Moon shōjo manga and anime series, as well as the second title in the franchise for Super Famicom, serving as the sequel to Sailor Moon.

Following the second season of the anime series, which adapted the second arc of the manga, the players control one of the six Sailor Guardians and fight against enemies across several locations in order to protect Earth from both the Hell Tree aliens led by Ail and Ann as well as the Black Moon Clan led by Prince Demand, who are attempting to steal life energy from humans and the Star Points of future Crystal Tokyo. Like its predecessor, the game was met with mixed reception from critics since its release.', 'https://en.wikipedia.org/wiki/Bish%C5%8Djo_Senshi_Sailor_Moon_R_(1993_video_game)'),
  ('Q18674887', 'SWAT Kats: The Radical Squadron is a side-scrolling action video game developed by AIM and published by Hudson Soft for the Super NES. It is based on the animated series of the same name, and was released in North America in August 1995.', 'https://en.wikipedia.org/wiki/SWAT_Kats:_The_Radical_Squadron_(video_game)'),
  ('Q20725907', 'Fighter''s History: Mizoguchi Kiki Ippatsu!! is a 1995 fighting game developed and published by Data East for the Super Famicom. It is the third game in the Fighter''s History series, and the last one published by Data East. The gameplay system is largely unchanged from its predecessor, Karnov''s Revenge, but a few new additions made it to the game, including a new game mode where Mizoguchi is the protagonist, and the new character Chelnov, the hero of Data East''s action game Atomic Runner Chelnov.

The game was initially released only in Japan for the Super Famicom on February 17, 1995. In 2017, Retro-Bit published the game for the international release as part of their compilation Data East Classic Collection.', 'https://en.wikipedia.org/wiki/Fighter%27s_History:_Mizoguchi_Kiki_Ippatsu!!'),
  ('Q20712180', 'Brandish is a 1991 action role-playing game developed and published by Nihon Falcom. Originally released in 1991 for the NEC PC-9801 and FM Towns, it was later ported to the Super NES and PC Engine CD-ROM² in the mid 1990s, including an expanded re-release titled Brandish Renewal. The game was the first in the Brandish series and was followed by three sequels. A remake, Brandish: The Dark Revenant, was released for the PlayStation Portable in Japan in 2009 and worldwide in 2015.', 'https://en.wikipedia.org/wiki/Brandish_(video_game)'),
  ('Q20875653', 'Hashire Hebereke is a 1994 racing game developed and published by Sunsoft exclusively in Japan for the Super Famicom on December 22, 1994. The game is the fifth installment in the Hebereke series. It was also re-released for Project EGG (Engrossing Game Gallery) as a Windows Store title on October 11, 2011 in Japan.', 'https://en.wikipedia.org/wiki/Hashire_Hebereke'),
  ('Q19744871', 'Slayers is a role-playing video game adaptation of the Slayers light novel series developed by BEC and published by Banpresto for the Super Famicom (SNES) exclusively in Japan in 1994. Note that this game should not be confused with another "Slayers" game that was published by Banpresto for the NEC PC-9801 that same year.', 'https://en.wikipedia.org/wiki/Slayers_(video_game)'),
  ('Q25377234', 'Nightmare Busters is a 2013 run and gun action video game developed by Arcade Zone and Super Fighter Team for the Super Nintendo Entertainment System. It is the first new game for the console in North America since Frogger (1998), fourteen years after being discontinued in North America. A mobile phone version called Flynn''s Adventure was released in 2004. A revival titled Nightmare Busters Rebirth was announced in 2021 for consoles and PC. The game follows the leprechaun twin brothers Flynn and Floyd on their journey to stop Tyrant from infiltrating and turning children''s dreams into nightmares. The player is tasked with fighting off enemies by using playing cards and magic attacks across six stages, populated with an assortment of obstacles.', 'https://en.wikipedia.org/wiki/Nightmare_Busters'),
  ('Q54621340', 'The Ren & Stimpy Show: Time Warp is a beat ''em up video game developed by Sculptured Software and published by THQ for the Super Nintendo Entertainment System. An adaptation of the Nickelodeon cartoon series The Ren & Stimpy Show, the plot involves the titular duo attempting to collect 47 million Gritty Kitty proofs of purchase in order to win a time machine from Muddy Mudskipper.

The game features ten levels based on episodes early episodes of the show and cooperative multiplayer. It was released in November 1994. It received an overall lukewarm response from critics.', 'https://en.wikipedia.org/wiki/The_Ren_%26_Stimpy_Show:_Time_Warp'),
  ('Q60754687', 'Beethoven: The Ultimate Canine Caper (also known as Beethoven''s 2nd or Beethoven) is a platform game developed by Riedel Software Productions and published by Hi Tech Expressions for the Super Nintendo Entertainment System, Game Boy, and MS-DOS compatible operating systems. The game is an adaption of the 1993 film Beethoven''s 2nd. The MS-DOS conversion was developed by Rozner Labs Software. Versions of the game were developed for the Sega Genesis and Game Gear but never released.', 'https://en.wikipedia.org/wiki/Beethoven:_The_Ultimate_Canine_Caper'),
  ('Q61467449', 'Time Trax is a 1994 action-platform video game developed by Malibu Interactive and published by Malibu Games for the Super Nintendo Entertainment System. It is based on the television series of the same name, which aired from 1993 to 1994. The story follows police Captain Lambert as he tries to stop criminal fugitives from changing history and gaining control of the future, with aid from his supercomputer assistant. The player controls Lambert across eight levels, apprehending enemies using a stunner weapon capable of sending them back to the future. The player can also use martial arts to defeat enemies, or use a time ability to slow them down.', 'https://en.wikipedia.org/wiki/Time_Trax_(video_game)'),
  ('Q100152674', 'Family Feud is a video game series based on the Family Feud TV game show. It began with ShareData''s 1987 release on the Apple II and Commodore 64 consoles. In 1990, GameTek released a version on the Nintendo Entertainment System. GameTek later released four more Feud games for the Super NES, Sega Genesis, 3DO, and MS-DOS between 1993 and 1995. Hasbro Interactive, Global Star and Ubisoft have also released versions starting in 2000.', 'https://en.wikipedia.org/wiki/Family_Feud_(video_game_series)');

insert into import_summary (wikidata_id, summary, source) values
  ('Q104876516', 'Nontan to Issho: KuruKuru Puzzle is a 1994 puzzle video game. It is based on an anime series Nontan to Issho. The game was developed by Game Freak. The developer said he was satisfied with the game, as he felt it superior to the company''s earlier similar title Yoshi (1991).

The game was released on April 28, 1994 for the Game Boy and on November 25, 1994 for the Super Famicom in Japan. Both versions received generally low scores in Famicom Tsūshin.', 'https://en.wikipedia.org/wiki/Nontan_to_Issho:_KuruKuru_Puzzle'),
  ('Q104866558', 'Unholy Night: The Darkness Hunter is a 2017 fighting game developed by Foxbat Corporation with assistance from Nu-Gaia and published exclusively for the Super Nintendo Entertainment System in Japan by BlazePro, North America by Retroism and Europe by JoshProd. Set during modern times, the game follows six fighters from three groups as they face-off in a conflict to confront the vampire Katatonia. Its gameplay consists of one-on-one fights, with a main three-button configuration, featuring special moves and four playable modes.

Headed by Foxbat CEO Tatsunori Mano, Unholy Night: The Darkness Hunter was created by former SNK members who worked on several fighting game franchises, being first launched through Kickstarter but failed to meet its crowdfunding goal before Retroism acquired the publishing rights for release. The title was met with mixed reception from players and critics since its release, many of which felt divided in regards to several design aspects.', 'https://en.wikipedia.org/wiki/Unholy_Night:_The_Darkness_Hunter'),
  ('Q63049660', 'Jack Nicklaus'' Unlimited Golf & Course Design is a 1990 golf video game developed by Sculptured Software and published by Accolade for the Amiga and MS-DOS. A Super NES version with the same golf courses, titled Jack Nicklaus Golf, was released in May 1992. It is the second in a series of golf games named after golfer Jack Nicklaus, following Jack Nicklaus'' Greatest 18 Holes of Major Championship Golf (1988).

The game includes a golf course designer that allows the player to create customized courses. The computer version was praised for its graphics and course designer, although reviewers criticized the long reanimation times in each version of the game. It was followed by Jack Nicklaus Golf & Course Design: Signature Edition (1992).', 'https://en.wikipedia.org/wiki/Jack_Nicklaus%27_Unlimited_Golf_%26_Course_Design'),
  ('Q99913286', 'Puzzle''n Desu! is a puzzle video game released by Nichibutsu for the Super Famicom on April 14, 1995. It stars an unnamed gnome who has to push boxes.', 'https://en.wikipedia.org/wiki/Puzzle%27n_Desu!'),
  ('Q97656421', 'Disney''s Magical Quest is a Disney platform game trilogy released by Capcom. The games star Mickey Mouse and (depending on the game version) either Minnie Mouse or Donald Duck, who must defeat Pete. The gameplay is similar amongst all games in the series: the player must move as in a typical platform game, defeating enemies either by jumping on them or by grabbing and throwing blocks at them.

One of the most notable gameplay features of the series is the ability to change characters'' outfits, which give characters different special abilities. Other gameplay elements in the series include the ability to expand the player''s health meter by collecting special hearts, and to shop for items using coins that are scattered throughout the game.', 'https://en.wikipedia.org/wiki/Disney%27s_Magical_Quest'),
  ('Q64011134', 'The Blues Brothers: Jukebox Adventure is a video game based on the band The Blues Brothers and a sequel to The Blues Brothers. The game was released for the Super Nintendo Entertainment System in 1993 (as The Blues Brothers) and for IBM PC compatibles and Game Boy in 1994. An Amiga port was developed and even reviewed by several videogame magazines, but never released.', 'https://en.wikipedia.org/wiki/The_Blues_Brothers:_Jukebox_Adventure'),
  ('Q105615670', 'Wagyan Land is a 1989 platform video game developed by Now Production and published for the Family Computer by Namco. A port for the Game Gear was released in 1991. The game is based on the 1987 arcade game Wagyan. A sequel, Wagyan Land 2, was released in 1990.', 'https://en.wikipedia.org/wiki/Wagyan_Land'),
  ('Q108403525', 'Terminator 2: Judgment Day is a 1993 action game developed by Bits Studios for two 16-bit game consoles: the Sega Genesis and the Super Nintendo Entertainment System (SNES). It was published by Acclaim Entertainment subsidiary companies: Flying Edge for the Genesis, and LJN for the SNES. It is based on the 1991 film of the same name, and features side-scrolling and driving levels. Players act as the T-800 Terminator completing a variety of objectives at several levels with settings from the film before battling the T-1000 in a steel mill. Reviews from gaming magazines were generally negative. Although its dedication to the source material was positively covered, the gameplay, collision detection, and character sprites were frequent aspects of condemnation.', 'https://en.wikipedia.org/wiki/Terminator_2_(16-bit_video_game)'),
  ('Q108219422', 'Teenage Mutant Ninja Turtles: Turtles in Time, released as Teenage Mutant Hero Turtles: Turtles in Time in Europe, is a 1991 beat ''em up game developed and published by Konami for arcades. A sequel to the original Teenage Mutant Ninja Turtles arcade game, it is a side-scrolling game based mainly on the 1987 TMNT animated series. Originally an arcade game, Turtles in Time was ported to the Super Nintendo Entertainment System in 1992 under the title Teenage Mutant Ninja Turtles IV: Turtles in Time, continuing the numbering from the earlier Turtles games released on the original NES. That same year, a game that borrowed many elements, Teenage Mutant Ninja Turtles: The Hyperstone Heist, was released for the Sega Genesis.', 'https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles:_Turtles_in_Time'),
  ('Q105637112', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q54322', 'Super Star Wars is a 1992 run and gun video game based on the 1977 film Star Wars, developed by LucasArts and Sculptured Software and published by JVC Musical Industries for the Super Nintendo Entertainment System. The game features side-scrolling run and gun and platform gameplay, although it has stages which feature other challenges, such as driving a landspeeder or piloting an X-wing. It also features multiple playable characters with different abilities.

The game was followed by two sequels based on the subsequent Star Wars films: Super Star Wars: The Empire Strikes Back (1993) and Super Star Wars: Return of the Jedi (1994). The game was re-released in November 1996 as part of Nintendo''s Player''s Choice series. It was also released on the Wii''s Virtual Console by LucasArts in 2009. In 2015, Disney Interactive Studios re-released the game for the PlayStation 4 and PlayStation Vita, with Code Mystics developing the ports. The port features enhanced options for saving, including cross-save, leaderboards and trophies, and modern displays and controllers. The game was also made a part of a bundle with the purchase of Star Wars Battlefront for the PlayStation 4, which included Star Wars: Racer Revenge, Star Wars: Jedi Starfighter and Star Wars Bounty Hunter.', 'https://en.wikipedia.org/wiki/Super_Star_Wars'),
  ('Q54330', 'Super Star Wars: The Empire Strikes Back, also known as Super Empire Strikes Back, is a 1993 action video game developed by LucasArts and Sculptured Software and published by JVC Musical Industries for the Super Nintendo Entertainment System. It is based on the 1980 film The Empire Strikes Back and is the sequel to Super Star Wars. The game was followed by a sequel, Super Star Wars: Return of the Jedi in 1994. Unlike its predecessor, Nintendo was not involved in its publishing. The game was re-released on the Wii''s Virtual Console in North America on August 24, 2009 and in the PAL regions on October 2, 2009, alongside the other games in the Super Star Wars series.', 'https://en.wikipedia.org/wiki/Super_Star_Wars:_The_Empire_Strikes_Back'),
  ('Q54335', 'Super Star Wars: Return of the Jedi, also known as Super Return of the Jedi, is a 1994 action video game developed by Lucas Arts and Sculptured Software and published by JVC Musical Industries for the Super Nintendo Entertainment System. It is a sequel to Super Star Wars (1992) and Super Star Wars: The Empire Strikes Back (1993) and is based on the 1983 film Return of the Jedi. Ports to the Game Boy and Game Gear were developed by Realtime Associates and published by THQ in 1995. The game was re-released on the Wii Virtual Console in North America on September 7, 2009, and in PAL regions on October 16, 2009, alongside the other games in the Super Star Wars series.', 'https://en.wikipedia.org/wiki/Super_Star_Wars:_Return_of_the_Jedi'),
  ('Q117865047', 'Space Ace is an action video game developed by Oxford Digital Enterprises and published by Absolute Entertainment, Imagineer, and Empire Interactive for the Super Nintendo Entertainment System video game console in North America, Japan, and Europe respectively. It is a version of the game of the same name, which was noted for its full-motion video cutscenes. Players control the protagonist, Dexter, who is made younger and weaker by the villain Borf, through platforming-action and shooting segments. At points, players may be able to "energize" Dexter into Ace in these platforming segments, giving Dexter the ability to shoot.', 'https://en.wikipedia.org/wiki/Space_Ace_(SNES_video_game)'),
  ('Q113462786', 'Nickelodeon Guts (stylized as Nickelodeon GUTS) is an American television action sports competition series hosted by American actor/writer Mike O''Malley and officiated by British actress Moira "Mo" Quirk who also served as the show''s co-host. The series originally ran from 1992 to 1995 on Nickelodeon.

Each episode features three young athletes competing against each other in four extreme versions of athletic events culminating in a fifth and final round which set the three competitors on a race up an artificial mountain to decide the victor.', 'https://en.wikipedia.org/wiki/Nickelodeon_Guts'),
  ('Q123241950', 'Mr. Tuff is an action-platform video game developed by Sales Curve Interactive (SCi) for the Super Nintendo Entertainment System. Originally planned for a 1994 release, it was canceled until it was published by The Retro Room in 2023. Set in a future where humanity abandoned the Earth and migrated to the planet Utopia, military androids took over and enslaved the stranded domestic robots. The player controls a demolition robot named Mr. Tuff across six islands, exploring and searching each level for items and power-ups, while fighting enemies and defeating bosses.

Mr. Tuff was conceived for SCi by Darren Melbourne, based on a character named Mr. Max E. Tuff which later became Mr. Tuff. It was produced by Sean Kelly and designed by Ned Langman, who had worked on Hades Nebula and SWIV (1991), while the music was scored by Allister Brimble and Steve Blenkinsopp. The game was first announced in 1993 and shown at the 1994 ECTS Spring, and was intended to be published by Ocean Software in North America and Europe, and Sony Electronic Publishing in Australia. When it was ready, Ocean ran into financial difficulties and waived the cost of manufacturing the cartridges but paid SCi for its development.', 'https://en.wikipedia.org/wiki/Mr._Tuff'),
  ('Q111271206', 'Smash Tennis, released in Japan as Super Family Tennis, is a 1993 tennis video game developed and published by Namco for the Super Nintendo Entertainment System. It is a follow-up to Family Tennis. It was designed by Hideo Yoshizawa, a former employee of Tecmo that later created Klonoa: Door to Phantomile, Mr. Driller and R4: Ridge Racer Type 4. It did not receive a North American release until it was released on the Nintendo Classics service in February 2020.', 'https://en.wikipedia.org/wiki/Smash_Tennis'),
  ('Q113494450', 'Batman Returns is a 1993 beat ''em up video game developed and published by Konami for the Super Nintendo Entertainment System, based on the 1992 film of the same name.', 'https://en.wikipedia.org/wiki/Batman_Returns_(SNES_video_game)'),
  ('Q18940', 'Wolfenstein 3D is a 1992 first-person shooter game developed by id Software and published by Apogee Software and FormGen for MS-DOS. It was inspired by the 1981 Muse Software video game Castle Wolfenstein, and is the third installment in the Wolfenstein series. In Wolfenstein 3D, the player assumes the role of Allied spy William "B.J." Blazkowicz during World War II as he escapes from the Nazi German prison Castle Wolfenstein and carries out a series of crucial missions against the Nazis. The player traverses each of the game''s levels to find an elevator to the next level or kill a final boss, fighting Nazi soldiers, dogs, and other enemies with a knife and a variety of guns.', 'https://en.wikipedia.org/wiki/Wolfenstein_3D'),
  ('Q142107606', 'Princess Maker, commonly abbreviated in Japanese fan usage as PuriMe, is a series of raising simulation bishōjo games in which the player assumes the role of a parental figure raising a young girl. The series was produced by the video game and anime production company Gainax.

Gameplay across the series centers on scheduling the daughter''s activities over a fixed span of in-game years, from childhood to adulthood. Players allocate time and money to activities, which in turn shape her abilities. At the conclusion of the game, these accumulated choices determine one of many possible endings, ranging from royalty to ordinary professions or more troubled futures.', 'https://en.wikipedia.org/wiki/Princess_Maker'),
  ('Q131824708', 'The Super Nintendo Entertainment System has a library of 1,749 official releases, of which 717 were released in North America plus 4 championship cartridges, 532 in Europe, 1,440 in Japan, 231 on Satellaview, and 13 on SuFami Turbo. 296 releases are common to all regions, 147 were released in Japan and the US only, 165 in Europe and the US, and 27 in Japan and Europe. There are 977 Japanese exclusives, 111 US exclusives, and 35 European exclusives. The Super NES was released in North America on August 23, 1991, with its launch titles being Super Mario World, F-Zero, Pilotwings, Gradius III, and SimCity. Despite the console''s relatively late start, and the fierce competition it faced in North America and Europe from Sega''s Genesis/Mega Drive console, it was the best-selling console of its era.', 'https://en.wikipedia.org/wiki/List_of_Super_Nintendo_Entertainment_System_games'),
  ('Q128221862', 'Albert Odyssey is a tactical role-playing video game developed and published by Sunsoft and released for the Super Nintendo Entertainment System in Japan in March 1993. The game features strategy-based combat in addition to traditional role-playing game elements in two-dimensional environments. It is the first game in the Albert Odyssey series, and was followed by two sequels, Albert Odyssey 2: Jashin no Taidō in 1994, and Albert Odyssey: Legend of Eldean in 1996. Albert Odyssey was made available as a full game download on the Satellaview add-on as BS Albert Odyssey on June 12, 1996, and the original Albert Odyssey was re-released for Satellaview in March 1998 the Wii Virtual Console in October 2010, and the Wii U Virtual Console in July 2015.', 'https://en.wikipedia.org/wiki/Albert_Odyssey_(1993_video_game)'),
  ('Q48847136', 'Star Soldier is a series of scrolling shooters mainly developed by Hudson Soft. Konami has owned the rights to the series since their absorption of Hudson Soft in 2012.

The eponymous first game, Star Soldier, was released in 1986 for the MSX and NES, and lead to a series of sequels that continued on various gaming systems. Star Soldier itself was re-released with little change in the compilation Caravan Shooting Collection for the Super Famicom in 1995, received enhanced remakes for both the GameCube and PlayStation 2 in 2003, and a different remake for the PlayStation Portable in 2005. The Nintendo 64 got an exclusive release called Star Soldier: Vanishing Earth in 1998, while the latest installment of the series was released on the Wii as a WiiWare game in 2008. In addition, the TurboGrafx-16 games Super Star Soldier, Final Soldier, Soldier Blade and Star Parodier have been re-released on the Wii''s Virtual Console and on the Japanese PC Engine''s Best Collection lineup for the PSP.', 'https://en.wikipedia.org/wiki/Star_Soldier'),
  ('Q104889895', 'Super Mario All-Stars is a 1993 platform game compilation developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). It contains remakes of four Super Mario games released for the Nintendo Entertainment System (NES) and the Famicom Disk System: Super Mario Bros. (1985), Super Mario Bros.: The Lost Levels (1986; released as Super Mario Bros. 2 in Japan), Super Mario Bros. 2 (1988), and Super Mario Bros. 3 (1988). As in the original games, players control the Italian plumber Mario and his brother Luigi through themed worlds, collecting power-ups, avoiding obstacles, and finding secrets. The remakes feature updated graphics—including the addition of parallax scrolling—and music, modified game physics, a save feature, and bug fixes.', 'https://en.wikipedia.org/wiki/Super_Mario_All-Stars'),
  ('Q3519190', 'Tetris & Dr. Mario is a 1994 puzzle video game compilation published by Nintendo for the Super Nintendo Entertainment System. It contains enhanced remakes of Tetris (1989) and Dr. Mario (1990), which were originally released for both the Nintendo Entertainment System and Game Boy in North America. Both games include split-screen multiplayer and a "Mixed Match" mode that transitions between the two games.

The Japanese version of the game excludes Tetris due to Bullet-Proof Software holding the console rights to the series in Japan. The remake of Dr. Mario was also broadcast through the Satellaview, renamed BS Dr. Mario, and was the last game to be broadcast on the system. Tetris & Dr. Mario received generally positive reviews, with critics praising its controls and multiplayer, particularly the Mixed Match mode. It sold 6 million copies.', 'https://en.wikipedia.org/wiki/Tetris_%26_Dr._Mario'),
  ('Q136784104', 'Super Bombliss is a 1995 puzzle game for the Super Famicom. The Bombliss games originally featured as an addition to version of Tetris for the Japanese home market such as Tetris 2 + Bombliss (1991), with Super Bombliss for the Super Famicom and Tetris Blast for the Game Boy being the first stand-alone titles.

The game involves removing blocks that fall into a container by making them form a solid row. Additionally, the player can remove blocks through red circles that act as bombs on the playing field that cause explosions further removing lines. The game features various modes of play that involve competitive modes against computer players, human players and a timer and unique to the Super Famicom version, with puzzle modes that force you to clear a stage with only a certain amount of set blocks.', 'https://en.wikipedia.org/wiki/Super_Bombliss'),
  ('Q2818867', 'A-Train III, known internationally as A-Train, is a 1990 business simulation video game and the third game in the A-Train series. It was originally developed and published by Japanese game developer Artdink for Japan, and was later published by Maxis for the United States.', 'https://en.wikipedia.org/wiki/A-Train_III'),
  ('Q4156284', 'Art of Fighting is a 1992 fighting game developed and published by SNK for the Neo Geo arcade and home platforms. It is the first game in the Art of Fighting series. It was eventually ported to the Neo Geo AES, Neo Geo CD, PC Engine CD-ROM², Sega Genesis, and Super Nintendo Entertainment System. The game follows Kyokugenryu Karate users Ryo Sakazaki and Robert Garcia as they travel to fight criminals from South Town in order to find Ryo''s missing sister Yuri. The game employs special moves and stronger Desperation Moves that can be performed strategically by filling the player''s energy bar and removing enemies by taunting them.', 'https://en.wikipedia.org/wiki/Art_of_Fighting_(video_game)'),
  ('Q1983421', 'Chuck Rock is a 1991 platform video game developed and published by Core Design for the Atari ST and Amiga computers. A Commodore 64 port followed in 1992 and an Amiga CD32 version in 1994. The game was subsequently published by Krisalis Software for the Acorn Archimedes. Virgin Interactive published the game for the Mega Drive/Genesis, Master System, and the Game Gear. Sony Imagesoft published the game for the Mega-CD, Super NES, and Game Boy.

The character of Chuck Rock was an early mascot for Core Design before the introduction of Lara Croft in the 1996 game Tomb Raider, and Chuck Rock and his family even featured in some UK comic books of the 1990s. Chuck Rock was followed by the sequel Chuck Rock II: Son of Chuck in 1993 and the spin-off BC Racers in 1994.', 'https://en.wikipedia.org/wiki/Chuck_Rock'),
  ('Q17176439', 'College Football USA 97 is a sports video game released in 1996 by EA Sports. Its cover athlete is former Nebraska Cornhuskers quarterback Tommie Frazier.', 'https://en.wikipedia.org/wiki/College_Football_USA_97'),
  ('Q128811996', 'Deae Tonosama: Appare Ichiban is a 1995 beat ''em up video game developed and published by Sunsoft for the Super Famicom. In 2025, the game was released in English under the name Feudal Bros: Tonosama #1.', 'https://en.wikipedia.org/wiki/Deae_Tonosama:_Appare_Ichiban'),
  ('Q2301014', 'Dragon Quest VI: Realms of Revelation, known in Europe & Australia as Dragon Quest VI: Realms of Reverie, is a 1995 role-playing video game developed by Heartbeat and published by Enix for the Super Famicom as a part of the Dragon Quest series and as the last Dragon Quest game in the Zenithian Trilogy. It was released in Japan in December 1995, developed by Heartbeat; whereas the previous Dragon Quest games were developed by Chunsoft. In 2011, a remake of the game, along with Dragon Quest IV and Dragon Quest V, was released worldwide for the Nintendo DS, making this the first time the game was released in English. Another version of the game for Android and iOS devices was released in Japan in June 2015.', 'https://en.wikipedia.org/wiki/Dragon_Quest_VI'),
  ('Q86740937', 'Dual Orb: Seireiju Densetsu is a role-playing video game developed by Prism Kikaku and released in 1993 for the Super Famicom by I''MAX. It was followed by Dual Orb II.', 'https://en.wikipedia.org/wiki/Dual_Orb:_Seireiju_Densetsu'),
  ('Q7539945', 'Sleepwalker is a platform game developed by CTA Developments and published by Ocean Software for the Amiga, Amiga CD32, Commodore 64 and Atari STE in 1993. It was later ported to MS-DOS.

The game was later re-released in 1994, using the Eek! The Cat license for the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Sleepwalker_(video_game)'),
  ('Q3062970', 'F1 (released as Formula One in the USA) is a 1993 racing video game published by Domark, based on Vroom, a game developed in 1991 for the Atari ST by French company Lankhor. It was released for the IBM PC, Mega Drive/Genesis, Master System, Game Gear, and Amiga.

It spawned a sequel in 1994 titled F1: World Championship Edition, and the game engine was reused in Kawasaki Superbike Challenge. It was one of the most popular racing games for the Mega Drive/Genesis, mostly thanks to the smooth and fast game engine.

There are no major differences between the European and North American Sega versions, except naming (the European version is simply named F1), and the lack of a battery save feature in the American version.', 'https://en.wikipedia.org/wiki/F1_(video_game)'),
  ('Q7723216', 'Mystery Dungeon: Shiren the Wanderer, originally released in Japan as Fushigi no Dungeon 2: Fūrai no Shiren, is a roguelike video game developed and published by Chunsoft. It is the second entry in the Mystery Dungeon series, following 1993''s Torneko no Daibōken. It was originally released for the Super Famicom in 1995 in Japan. Sega published a Nintendo DS remake in 2006 in Japan and in 2008 internationally. The remake was later ported to iOS and Android and published by Spike Chunsoft in 2019.

The player takes the role of the rōnin Shiren, who travels through thirty areas on his way to the Land of the Golden Condor. The game is turn-based, with all enemies and characters in an area moving whenever the player performs an action, such as attacking or moving. If the player falls in battle, they lose all their progress and are forced to restart from the beginning of the game: to counter-act this, they can choose to store powerful items in warehouses, and pick them up again on further playthroughs; the Nintendo DS release also adds rescue quests, where a player can save other players who have fallen, allowing them to continue from where they left off.', 'https://en.wikipedia.org/wiki/Mystery_Dungeon:_Shiren_the_Wanderer'),
  ('Q3772779', 'Godzilla: Kaijū Daikessen is a 2D fighting video game released in 1994 for the Super Famicom. The game was developed by Alfa System and published by Toho. It was the second game based on Toho''s Godzilla franchise to be released on Super Famicom, following 1993''s Super Godzilla.

The May 1995 issue of Nintendo Power previewed a planned release of the game in North America, titled Godzilla: Destroy All Monsters, but the game was never released for unknown reasons, but most likely due to the rise of the next generation of consoles, such as the Nintendo 64 and the PlayStation. A similarly titled game, Godzilla: Destroy All Monsters Melee, was released in North America in 2002.', 'https://en.wikipedia.org/wiki/Godzilla:_Kaij%C5%AB_Daikessen'),
  ('Q1194133', 'Gradius III is a 1989 scrolling shooter video game developed and published by Konami for arcades. It was originally released only in Japan on December 11, 1989. It is the third game in the Gradius series. The game was ported to the Super Nintendo Entertainment System in Japan in 1990 and North America in 1991, and served as a launch title for the system in North America. The arcade version would never see the light of day in the West until it was included alongside Gradius IV in a two-in-one compilation (Gradius III & IV) for the PlayStation 2 and in the Gradius Collection for the PlayStation Portable.', 'https://en.wikipedia.org/wiki/Gradius_III'),
  ('Q104876802', 'Hungry Dinosaurs is a strategy game for the Super Nintendo Entertainment System. It was developed and published by Magical Company on October 19, 1994 in Japan, and was later published by Sunsoft in Europe on January 3, 1995. The game was never released in North America in any form.', 'https://en.wikipedia.org/wiki/Hungry_Dinosaurs'),
  ('Q3909665', 'Power Spikes, released in Japan as Super Volley ''91, is a 1991 volleyball video game developed and published by Video System for arcades. It is the sequel to Super Volleyball (1989). It was released in Japan in April 1991 and in North America the same year. It was ported to the Super Nintendo Entertainment System as Hyper V-Ball, which was released in Europe by Ubi Soft. It was followed by Power Spikes II in 1994.

Hamster Corporation acquired the game''s rights alongside Video System''s catalogue, releasing the game as part of their Arcade Archives series for the Nintendo Switch and PlayStation 4 in October 2024.', 'https://en.wikipedia.org/wiki/Power_Spikes'),
  ('Q3518112', 'Tennis Cup is a 1990 tennis video game developed and published by Loriciel for the Amiga. It was ported to the Atari ST, MS-DOS and Amstrad CPC during the same year. Tennis Cup was ported to TurboGrafx-16 in 1991 as Davis Cup Tennis. Versions for the Super NES (International Tennis Tour) and Mega Drive/Genesis (Davis Cup World Tour) were released in 1993.

The Amstrad version received a sequel, Tennis Cup 2, in 1990. A 16-bit sequel, also titled Tennis Cup 2, was released in 1992 for the Amiga, Atari ST, and MS-DOS.', 'https://en.wikipedia.org/wiki/Tennis_Cup'),
  ('Q55299563', 'Izzy''s Quest for the Olympic Rings is a 1995 platformer video game developed by Alexandria and published by U.S. Gold for the Sega Genesis and the Super Nintendo Entertainment System.', 'https://en.wikipedia.org/wiki/Izzy%27s_Quest_for_the_Olympic_Rings'),
  ('Q4906255', 'Big Run is a rally racing arcade video game released by Jaleco in 1989. Rendered in pseudo-3D, the game is the first to be set in the Paris-Dakar rally raid which the player drives a Porsche 959, resembling that of the 1986 winner. Opponents in the game resemble Peugeot 205 T16s, which went on to win in the 1987 Paris-Dakar rally, with Mitsubishi Pajeros also appearing occasionally.

There are two games in the series: Big Run – The Supreme 4WD Challenge – 11e Rallye (1989) and Big Run – The Supreme 4WD Challenge – 13e Rallye (1991, Super Famicom)

Big Run was also converted to the Amiga and Atari ST by The Sales Curve.', 'https://en.wikipedia.org/wiki/Big_Run_(video_game)'),
  ('Q6319542', 'Jyutei Senki is a 1993 science fiction video game for the Super Famicom. It was published by the Enix Corporation.', 'https://en.wikipedia.org/wiki/Jyutei_Senki'),
  ('Q3276899', 'Magic Sword: Heroic Fantasy is a 1990 hack and slash video game developed and published by Capcom for arcades. The player is cast as a hero who fights through a mystical tower to save the world. The player can use a sword, axe or magic, and can also rescue and recruit potential allies of various character classes, each with special abilities.', 'https://en.wikipedia.org/wiki/Magic_Sword:_Heroic_Fantasy'),
  ('Q11482386', 'Heiankyo Alien, known as Digger in North America, is a maze video game created by University of Tokyo''s Theoretical Science Group (TSG) in 1979. The game was originally developed and released as a personal computer game in 1979, and was then published by Denki Onkyō Corporation as an arcade game in November 1979. In 1980, the arcade game was released in North America as Digger by Sega-Gremlin, with minor changes in appearance.

The game was a commercial success in Japan, where it was among the top ten highest-grossing arcade games of 1979 and 1980. The game has been ported to several other gaming systems since its original release. It was an early example of a maze chase game, predating Namco''s Pac-Man (1980). It also began a genre of games about digging holes and luring enemies into traps, variously called "trap ''em up" or "digging" games, which includes titles such as Space Panic (1980) and Lode Runner (1983).', 'https://en.wikipedia.org/wiki/Heiankyo_Alien'),
  ('Q2413658', 'P.T.O. (Pacific Theater of Operations), released as Teitoku no Ketsudan in Japan, is a console strategy video game released by Koei. It was originally released for the PC-9801 in 1989 and had been ported to various platforms, such as the X68000, FM Towns, PC-8801 (1990), MSX2 (1991), Sega Genesis and the Super NES (both in 1992). Players could assume one side of the Pacific Theater of Operations during World War II, acting as naval commander, organizing fleets, building new ships, appropriating supplies and fuel, and even engaging in diplomacy with other countries. The player can choose one of several World War Two battles to simulate, or could control the entire Pacific campaign well before the Japanese attack on Pearl Harbor.', 'https://en.wikipedia.org/wiki/P.T.O._(video_game)'),
  ('Q10349861', 'Pink Goes to Hollywood is a Pink Panther themed platform game published in 1993 for the Super Nintendo Entertainment System and Genesis by TecMagik. The two releases were developed independently by different companies: the Genesis version by HeadGames and Super NES by Manley & Associates. Both are similar in theme and aesthetics, but different in layout and game mechanics.', 'https://en.wikipedia.org/wiki/Pink_Goes_to_Hollywood'),
  ('Q20723089', 'Shanghai II: Dragon''s Eye is a 1990 puzzle video game developed and published by Activision. It is a sequel to Shanghai (1986).', 'https://en.wikipedia.org/wiki/Shanghai_II:_Dragon%27s_Eye'),
  ('Q7642166', 'Super Bases Loaded 3: License to Steal (known in Japan as Super Moero!! Pro Yakyuu) is a Super Nintendo Entertainment System baseball game. It is the seventh overall installment of the Bases Loaded series, and the third installment of the secondary series for the Super NES. Super Bases Loaded 3 was licensed by the Major League Baseball Players Association (MLBPA) and uses real MLB players (the first game in the Bases Loaded series to use actual player names), but it was not licensed by Major League Baseball itself (MLB); all stats and attributes reflected the 1994 MLB season. All 28 U.S. cities that had an MLB team at the time are listed but team names and logos are not given. No real stadiums are used and the World Series is renamed the championship tournament.', 'https://en.wikipedia.org/wiki/Super_Bases_Loaded_3'),
  ('Q3411064', 'Putty (also known as Silly Putty or Look Out It''s...Putty) is a game developed by System 3 and released in 1992 for the Amiga. It was also released on the Super Nintendo Entertainment System in 1993 as Super Putty (Putty Moon in Japan) and Amiga CD32 version was published in 1994 under the same name.', 'https://en.wikipedia.org/wiki/Putty_(video_game)'),
  ('Q3747609', 'Hat Trick Hero is a 1991 association football video game developed and published by Taito for arcades. It was released for Japan in March 1991, then overseas as Football Champ for North America and Europe the same year. It was ported to multiple home consoles and personal computers. The series became one of Taito''s franchises and has seen sequels in following years, including Hat Trick Hero ''93 and Taito Power Goal.', 'https://en.wikipedia.org/wiki/Hat_Trick_Hero'),
  ('Q1543256', 'Thunder Force III is a 1990 scrolling shooter game developed by Technosoft for the Sega Genesis. It is the third chapter in the Thunder Force series. It was then retooled into an arcade game named Thunder Force AC. In 1991, Thunder Force AC was ported to the Super Nintendo Entertainment System under the title Thunder Spirits.', 'https://en.wikipedia.org/wiki/Thunder_Force_III'),
  ('Q7880463', 'Ultra League: Moero! Soccer Daikessen!! is a 1995 Japan-exclusive soccer-based video game released for the Super Famicom. The game features the Japanese super hero Ultraman, among other monsters and aliens.', 'https://en.wikipedia.org/wiki/Ultra_League'),
  ('Q124075558', 'Umihara Kawase is a 1994 platformer developed and published by Japanese company TNN. It is the inaugural game in the Umihara Kawase series. It was first released in 1994 for the Super Famicom.', 'https://en.wikipedia.org/wiki/Umihara_Kawase_(video_game)'),
  ('Q7039169', 'Nintendo World Championships ''94 was a 1994 Nintendo-promoted video game competition held during the Nintendo Powerfest ''94 tour. Most of the town competitions were held in customized trailers outside of department stores. It was based on scoring points in a special Game Pak. The three Super Nintendo Entertainment System games (Super Mario Bros.: The Lost Levels, Super Mario Kart, and Ken Griffey, Jr. Presents Major League Baseball) were played within a time limit of six minutes.', 'https://en.wikipedia.org/wiki/Nintendo_PowerFest_%2794'),
  ('Q4043571', 'Mega Apocalypse is a microcomputer video game in the genre multidirectional shooter, written by Simon Nicol for the Commodore 64 and ported to the BBC Micro, Amstrad CPC, and ZX Spectrum. It is the sequel to Crazy Comets. Both games are clones of Gottlieb''s 1983 arcade video game Mad Planets; Mega-Apocalypse adds two players simultaneous multiplayer. The music is by Rob Hubbard.', 'https://en.wikipedia.org/wiki/Mega_Apocalypse'),
  ('Q124065023', 'Dorke and Ymp is a 2015 platform video game developed and published by Piko Interactive for the Super Nintendo Entertainment System. Initially developed in the 1990s by Swedish developer Norse as an unlicensed game for the system, it failed to find a publisher and was cancelled despite nearing completion. Piko Interactive purchased the rights to the game as well as a prototype from its original developers; after artist Jim Studt''s passing, Piko redeveloped the game and added new content in his honor, releasing the game as a cartridge and on Windows in 2015.', 'https://en.wikipedia.org/wiki/Dorke_and_Ymp'),
  ('Q39058211', 'Cyber Citizen Shockman Zero is a 1997 game for the Satellaview addon for the Super Famicom. It is a side-scrolling beat-''em-up developed by Masaya and published by NCS. It is the fourth and final game in the Cyber Citizen Shockman series, and the first on the SFC. The previous entries in the series were for the PC Engine.', 'https://en.wikipedia.org/wiki/Cyber_Citizen_Shockman_Zero'),
  ('Q1229899', 'Super 3D Noah''s Ark is a non-violent Christian first-person shooter developed and published by Wisdom Tree for the Super Nintendo Entertainment System (SNES) in 1994 and MS-DOS in 1995. Its gameplay is similar to that of Wolfenstein 3D, as Wisdom Tree had licensed that game''s engine from id Software. Wisdom Tree opted not to secure a license from Nintendo for the game''s Super NES release. While not illegal, it prevented the game from being sold at most video game retailers, which were under a contractual agreement with Nintendo not to sell unlicensed games for the company''s consoles. As a result, the Super NES release of Super 3D Noah''s Ark was sold primarily via Christian bookstores.', 'https://en.wikipedia.org/wiki/Super_3D_Noah%27s_Ark'),
  ('Q3529185', 'Tinhead is a 1993 platform video game developed by MicroProse and published by Ballistic for the Sega Genesis. Piko Interactive acquired the rights to the game and released a canceled Super Nintendo Entertainment System version in 2015.', 'https://en.wikipedia.org/wiki/Tinhead');

update public.game g
set summary_en = i.summary, summary_en_source = i.source
from import_summary i
where g.wikidata_id = i.wikidata_id
  and g.summary_en is null;

drop table import_summary;
